/* OKO app css v1.97 — modules, non-blocking */

/* ===== module: core-ext ===== */
/* ===== CORE-EXT: попапы, печать, общие элементы новых модулей ===== */
#okoPopup{position:fixed;inset:0;background:rgba(0,0,0,.62);z-index:70;display:flex;align-items:center;justify-content:center;padding:22px}
#okoPopup .pop-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:24px 20px;max-width:400px;width:100%;text-align:center;box-shadow:0 18px 60px rgba(0,0,0,.5)}
#okoPopup .pop-ico{width:58px;height:58px;border-radius:50%;background:var(--lime-dim);display:flex;align-items:center;justify-content:center;margin:0 auto 14px}
#okoPopup .pop-ico svg{width:28px;height:28px;color:var(--accent)}
#okoPopup h3{font-size:24px;margin-bottom:8px}
#okoPopup .pop-body{color:var(--dim);font-size:13.5px;line-height:1.55;margin-bottom:18px}
#okoPopup .pop-actions{display:flex;flex-direction:column;gap:9px}
#okoPopup .btn{width:100%}

.balance-chip{display:inline-flex;align-items:center;gap:6px;background:var(--lime-dim);color:var(--accent);font-weight:700;font-size:12.5px;border-radius:99px;padding:6px 12px;cursor:pointer}
.balance-chip svg.i{width:15px;height:15px}

.doc-sign-block{display:flex;align-items:flex-end;gap:18px;flex-wrap:wrap;margin-top:22px}
.doc-sign-block .sig{position:relative}
.doc-sign-block .sig img{mix-blend-mode:multiply}
:root[data-theme="dark"] .doc-sign-block .sig img,
:root:not([data-theme="light"]) .doc-sign-block .sig img{filter:invert(1) hue-rotate(180deg);mix-blend-mode:screen}

/* ===== module: registration ===== */
/* ===== REGISTRATION: fullscreen-вьюха регистрации (префикс reg-) ===== */
#regView{position:fixed;inset:0;z-index:62;background:var(--bg);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .3s cubic-bezier(.3,1,.4,1);max-width:1280px;margin:0 auto}
#regView.open{transform:none}
@media(prefers-reduced-motion:reduce){#regView{transition:none}}

.reg-stepnum{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);background:var(--lime-dim);border-radius:99px;padding:4px 10px}
.reg-progress{height:3px;background:var(--border);flex-shrink:0;overflow:hidden}
.reg-progress i{display:block;height:100%;background:linear-gradient(90deg,#B9FF4D,var(--lime));box-shadow:var(--glow);transition:width .4s cubic-bezier(.3,1,.4,1)}

.reg-body{flex:1;overflow-y:auto;padding:26px 20px calc(30px + env(safe-area-inset-bottom));max-width:520px;width:100%;margin:0 auto}
.reg-step{display:none}
.reg-step.active{display:block;animation:regIn .34s cubic-bezier(.22,1,.32,1)}
.reg-step.active.reg-back{animation:regInBack .34s cubic-bezier(.22,1,.32,1)}
@keyframes regIn{from{opacity:0;transform:translateX(26px)}to{opacity:1;transform:none}}
@keyframes regInBack{from{opacity:0;transform:translateX(-26px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.reg-step.active,.reg-step.active.reg-back{animation:none}}

.reg-h{font-size:32px;margin-bottom:6px}
.reg-sub{color:var(--dim);font-size:13.5px;line-height:1.5;margin-bottom:20px}
.reg-hint{color:var(--dim);font-size:12px;margin:-2px 0 10px}

.reg-body input{width:100%;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:13px 14px;font-size:15px;color:var(--text);font-family:inherit;transition:border-color .18s,box-shadow .18s}
.reg-body input:focus{border-color:var(--lime);outline:none;box-shadow:0 0 0 3px var(--lime-dim)}
.reg-body input[type="date"]{color-scheme:dark}
:root[data-theme="light"] .reg-body input[type="date"]{color-scheme:light}
.reg-body .ep-nick input{border:none;background:none;padding:13px 2px;box-shadow:none}

/* сегмент почта/телефон */
.reg-seg{display:flex;gap:4px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:4px;margin-bottom:18px}
.reg-seg button{flex:1;display:flex;align-items:center;justify-content:center;gap:7px;padding:10px;border-radius:10px;font-size:13.5px;font-weight:600;color:var(--dim);transition:background .18s,color .18s,transform .12s}
.reg-seg button svg.i{width:16px;height:16px}
.reg-seg button:active{transform:scale(.97)}
.reg-seg button.on{background:var(--lime);color:#000;box-shadow:var(--glow)}

/* пароль */
.reg-passwrap{position:relative}
.reg-passwrap input{padding-right:46px}
.reg-eye{position:absolute;right:6px;top:50%;transform:translateY(-50%);width:36px;height:36px;display:flex;align-items:center;justify-content:center;color:var(--dim);border-radius:10px;transition:color .18s}
.reg-eye:hover,.reg-eye.on{color:var(--accent)}
.reg-eye svg.i{width:19px;height:19px}
.reg-strength{height:4px;background:var(--border);border-radius:2px;margin-top:10px;overflow:hidden}
.reg-strength i{display:block;height:100%;width:0;border-radius:2px;background:var(--danger);transition:width .3s ease,background .3s ease}
.reg-strength i.mid{background:#ffb020}
.reg-strength i.hi{background:var(--lime);box-shadow:var(--glow)}
.reg-strength-lab{font-size:11px;color:var(--dim);margin-top:6px}

.reg-err{color:var(--danger);font-size:12.5px;font-weight:600;min-height:18px;margin:10px 0 2px;opacity:0;transition:opacity .2s}
.reg-err.show{opacity:1;animation:regShake .35s ease}
@keyframes regShake{0%,100%{transform:none}20%,60%{transform:translateX(-5px)}40%,80%{transform:translateX(5px)}}

.reg-next{margin-top:10px}
.reg-next:disabled{opacity:.42;pointer-events:none;box-shadow:none}
.reg-next.loading{opacity:.7;pointer-events:none}
.reg-secure{display:flex;align-items:center;justify-content:center;gap:7px;color:var(--dim);font-size:11.5px;margin-top:16px}
.reg-secure svg.i{width:14px;height:14px;color:var(--accent)}

/* шаг 2: код */
.reg-code-ico{width:64px;height:64px;border-radius:50%;background:var(--lime-dim);display:flex;align-items:center;justify-content:center;margin:6px auto 16px;animation:regPulse 2.2s ease infinite}
.reg-code-ico svg.i{width:28px;height:28px;color:var(--accent)}
@keyframes regPulse{0%,100%{box-shadow:0 0 0 0 var(--lime-dim)}50%{box-shadow:0 0 0 12px rgba(154,255,0,0)}}
.reg-code{display:flex;gap:12px;justify-content:center;margin:8px 0 4px}
.reg-body .reg-code input{width:58px;height:66px;text-align:center;font-size:28px;font-weight:700;font-family:var(--font-display);letter-spacing:.02em;padding:0;border-radius:var(--r-md)}
.reg-code input.fill{border-color:var(--lime);box-shadow:0 0 0 3px var(--lime-dim)}
.reg-code.err input{border-color:var(--danger);animation:regShake .35s ease}
.reg-resend{display:block;margin:6px auto 14px;color:var(--accent);font-size:13.5px;font-weight:600;padding:8px 14px;border-radius:99px;transition:opacity .2s}
.reg-resend:disabled{color:var(--dim);opacity:.7;cursor:default}

/* шаг 3: ник, возраст, интересы */
.reg-nick{margin-bottom:0}
.reg-nick-st{margin-left:auto;display:flex;align-items:center}
.reg-nick-st svg.i{width:17px;height:17px}
.reg-nick-st .ok{color:var(--accent)}
.reg-nick-st .bad{color:var(--danger)}
.reg-nick-st .wait{color:var(--dim);animation:regSpin 1s linear infinite;display:inline-flex}
@keyframes regSpin{to{transform:rotate(360deg)}}
.reg-nick-msg{font-size:11.5px;font-weight:600;min-height:16px;margin:6px 2px 0}
.reg-nick-msg.ok{color:var(--accent)}
.reg-nick-msg.bad{color:var(--danger)}
.reg-nick-msg.wait{color:var(--dim)}

.reg-warn{display:none;align-items:flex-start;gap:10px;background:rgba(255,77,77,.09);border:1px solid rgba(255,77,77,.35);border-radius:var(--r-md);padding:12px 14px;font-size:12.5px;line-height:1.5;color:var(--text);margin-top:10px}
.reg-warn.show{display:flex;animation:regIn .3s ease}
.reg-warn svg.i{width:18px;height:18px;color:var(--danger);flex-shrink:0;margin-top:1px}

.reg-ints{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-bottom:6px}
.reg-int{display:flex;align-items:center;gap:9px;padding:12px 13px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);font-size:13.5px;font-weight:600;color:var(--text);text-align:left;transition:border-color .18s,background .18s,transform .12s}
.reg-int svg.i{width:18px;height:18px;color:var(--accent)}
.reg-int:active{transform:scale(.97)}
.reg-int.on{background:var(--lime);border-color:var(--lime);color:#000;box-shadow:var(--glow)}
.reg-int.on svg.i{color:#000}

.reg-terms{display:flex;align-items:flex-start;gap:11px;margin:18px 0 4px;cursor:pointer;font-size:12.5px;line-height:1.5;color:var(--dim)}
.reg-terms input{display:none;width:auto}
.reg-box{width:22px;height:22px;border-radius:7px;border:1.5px solid var(--border);background:var(--surface);display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:1px;transition:background .18s,border-color .18s}
.reg-box svg.i{width:13px;height:13px;color:#000;opacity:0;transform:scale(.4);transition:opacity .18s,transform .18s}
.reg-terms input:checked + .reg-box{background:var(--lime);border-color:var(--lime);box-shadow:var(--glow)}
.reg-terms input:checked + .reg-box svg.i{opacity:1;transform:scale(1)}
.reg-terms-txt a{color:var(--accent);font-weight:600;text-decoration:underline;text-underline-offset:2px;cursor:pointer}

@media(max-width:380px){
  .reg-body .reg-code input{width:50px;height:58px;font-size:24px}
  .reg-h{font-size:28px}
}

/* ============================================================
   ПРЕМИУМ-СЛОЙ РЕГИСТРАЦИИ (фон/анимации, поля, попапы)
   ============================================================ */

/* --- живой брендовый фон вьюхи входа --- */
#regView{background:var(--bg);isolation:isolate}
#regView::before{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;
  background:
    radial-gradient(680px 520px at 82% -8%, rgba(154,255,0,.13), transparent 62%),
    radial-gradient(560px 460px at -12% 108%, rgba(154,255,0,.09), transparent 60%),
    radial-gradient(900px 700px at 50% 130%, rgba(154,255,0,.05), transparent 70%);
  animation:regAmbient 18s ease-in-out infinite alternate}
#regView::after{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;opacity:.5;
  background-image:radial-gradient(rgba(154,255,0,.10) 1px, transparent 1.4px);
  background-size:26px 26px;
  -webkit-mask-image:radial-gradient(120% 90% at 50% 0%, #000 8%, transparent 62%);
  mask-image:radial-gradient(120% 90% at 50% 0%, #000 8%, transparent 62%);
  animation:regGrid 24s linear infinite}
#regView > .ep-head,#regView > .reg-progress,#regView > .reg-body{position:relative;z-index:1}
:root[data-theme="light"] #regView::before{
  background:
    radial-gradient(680px 520px at 82% -8%, rgba(122,204,0,.16), transparent 62%),
    radial-gradient(560px 460px at -12% 108%, rgba(122,204,0,.12), transparent 60%),
    radial-gradient(900px 700px at 50% 130%, rgba(122,204,0,.06), transparent 70%)}
:root[data-theme="light"] #regView::after{opacity:.4;background-image:radial-gradient(rgba(122,204,0,.14) 1px, transparent 1.4px)}
@keyframes regAmbient{0%{transform:translate3d(0,0,0) scale(1)}100%{transform:translate3d(-2.5%,1.8%,0) scale(1.07)}}
@keyframes regGrid{to{background-position:26px 26px}}
@media(prefers-reduced-motion:reduce){#regView::before,#regView::after{animation:none}}

/* --- прогресс-бар: живой блик + степ-пипы --- */
.reg-progress{position:relative}
.reg-progress i{position:relative}
.reg-progress i::after{content:'';position:absolute;top:0;right:0;bottom:0;width:34px;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.85));mix-blend-mode:overlay;
  animation:regBarSheen 2.4s ease-in-out infinite}
@keyframes regBarSheen{0%,100%{opacity:0}50%{opacity:.9}}
@media(prefers-reduced-motion:reduce){.reg-progress i::after{animation:none;opacity:0}}

/* --- заголовки шагов: акцент лаймом --- */
.reg-h{background:linear-gradient(92deg,var(--text) 66%,var(--accent));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
:root[data-theme="light"] .reg-h{background:linear-gradient(92deg,var(--text) 72%,#5aa300);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}

/* --- поля ввода: мягкая подложка + фокус --- */
.reg-body input{box-shadow:inset 0 1px 0 rgba(255,255,255,.02)}
.reg-body input:focus{box-shadow:0 0 0 3px var(--lime-dim),0 8px 24px -12px rgba(154,255,0,.5)}
.reg-body input::placeholder{color:var(--dim);opacity:.7}

/* --- сегмент почта/телефон: плавный лайм-переключатель --- */
.reg-seg{position:relative;overflow:hidden}
.reg-seg button{position:relative;z-index:1}
.reg-seg button.on svg.i{filter:drop-shadow(0 1px 2px rgba(0,0,0,.25))}

/* --- меры надёжности пароля: блик на «отлично» --- */
.reg-strength i.hi{position:relative;overflow:hidden}
.reg-strength i.hi::after{content:'';position:absolute;inset:0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.7),transparent);
  transform:translateX(-100%);animation:regStrSheen 1.6s ease-in-out infinite}
@keyframes regStrSheen{to{transform:translateX(100%)}}
@media(prefers-reduced-motion:reduce){.reg-strength i.hi::after{animation:none;opacity:0}}

/* --- кнопка «дальше»: подсветка при готовности --- */
.reg-next:not(:disabled){box-shadow:0 10px 30px -10px rgba(154,255,0,.55)}
.reg-next:not(:disabled):hover{transform:translateY(-1px)}
.reg-next svg.i{transition:transform .18s}
.reg-next:not(:disabled):hover svg.i{transform:translateX(3px)}

/* --- ценностная строка под шагом 1 --- */
.reg-props{display:flex;align-items:center;justify-content:center;gap:6px;flex-wrap:wrap;
  margin-top:22px;opacity:0;animation:regIn .5s .15s ease forwards}
.reg-prop{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:600;color:var(--dim);
  background:var(--surface);border:1px solid var(--border);border-radius:99px;padding:6px 11px}
.reg-prop svg.i{width:13px;height:13px;color:var(--accent)}
.reg-prop-dot{width:3px;height:3px;border-radius:50%;background:var(--border)}

/* --- шаг 2: точка-каретка в активном поле кода --- */
.reg-code input:focus{caret-color:var(--lime)}
.reg-code input.fill{animation:regCodePop .22s cubic-bezier(.3,1.4,.4,1)}
@keyframes regCodePop{0%{transform:scale(.86)}60%{transform:scale(1.08)}100%{transform:scale(1)}}
@media(prefers-reduced-motion:reduce){.reg-code input.fill{animation:none}}
.reg-code-ico::after{content:'';position:absolute;width:64px;height:64px;border-radius:50%;
  border:1.5px solid rgba(154,255,0,.35);animation:regRing 2.2s ease-out infinite}
.reg-code-ico{position:relative}
@keyframes regRing{0%{transform:scale(1);opacity:.7}100%{transform:scale(1.7);opacity:0}}
@media(prefers-reduced-motion:reduce){.reg-code-ico::after{animation:none;opacity:0}}

/* --- шаг 3: интерес-чипы появляются каскадом --- */
.reg-int{position:relative;overflow:hidden}
.reg-step.active .reg-int{animation:regChipIn .42s cubic-bezier(.2,1,.3,1) both}
.reg-step.active .reg-int:nth-child(1){animation-delay:.02s}
.reg-step.active .reg-int:nth-child(2){animation-delay:.07s}
.reg-step.active .reg-int:nth-child(3){animation-delay:.12s}
.reg-step.active .reg-int:nth-child(4){animation-delay:.17s}
.reg-step.active .reg-int:nth-child(5){animation-delay:.22s}
.reg-step.active .reg-int:nth-child(6){animation-delay:.27s}
@keyframes regChipIn{from{opacity:0;transform:translateY(10px) scale(.96)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.reg-step.active .reg-int{animation:none}}
.reg-int:hover{border-color:var(--lime);transform:translateY(-1px)}
.reg-int.on::after{content:'';position:absolute;top:0;left:-40%;width:40%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.45),transparent);
  animation:regChipSheen .6s ease}
@keyframes regChipSheen{to{left:130%}}
.reg-int.on svg.i,.reg-int.on span{position:relative;z-index:1}

/* --- никнейм: подложка-статус --- */
.ep-nick.reg-nick{transition:border-color .2s,box-shadow .2s}
.reg-nick:has(#regNick:focus){border-color:var(--lime);box-shadow:0 0 0 3px var(--lime-dim)}

/* --- дата рождения: аккуратный лайм-пикер --- */
.reg-body input[type="date"]::-webkit-calendar-picker-indicator{opacity:.6;cursor:pointer;filter:invert(.5)}
:root[data-theme="light"] .reg-body input[type="date"]::-webkit-calendar-picker-indicator{filter:none;opacity:.55}

/* ============ ПРЕМИУМ-ПОПАПЫ welcome / pro / notif ============ */
#okoPopup .reg-pop{text-align:left}
.reg-pop-lead{color:var(--dim);font-size:13px;line-height:1.55;text-align:center;margin:-4px 0 14px}
.reg-pop-lead b{color:var(--text);font-weight:700}

/* --- персональное приветствие: буквы имени появляются по очереди --- */
#okoPopup h3:has(.reg-hello){font-family:var(--font-display);font-size:26px;line-height:1.06;letter-spacing:.01em;
  margin-bottom:12px;text-align:center}
.reg-hello{display:inline-block}
.reg-hello-name{display:inline-block;background:linear-gradient(96deg,var(--text) 40%,var(--accent));
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
  filter:drop-shadow(0 4px 18px rgba(154,255,0,.22))}
:root[data-theme="light"] .reg-hello-name{background:linear-gradient(96deg,var(--text) 50%,#4d9000);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;filter:none}
.reg-let{display:inline-block;opacity:0;transform:translateY(14px) scale(.9);
  animation:regLet .55s cubic-bezier(.2,1.2,.3,1) forwards;animation-delay:calc(var(--i,0) * 55ms + 120ms)}
.reg-let.sp{width:.35em}
@keyframes regLet{to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){
  .reg-let{opacity:1;transform:none;animation:none}
}

/* --- реф-нотис: тёплая плашка «твой пригласивший получит бонус» --- */
.reg-pop-ref{display:flex;align-items:flex-start;gap:10px;padding:11px 13px;border-radius:var(--r-md);
  background:linear-gradient(135deg,rgba(154,255,0,.10),rgba(154,255,0,.02));
  border:1px solid rgba(154,255,0,.24);margin:-2px 0 12px;
  animation:regFadeUp .5s .1s cubic-bezier(.2,1,.3,1) both}
.reg-pop-ref-ico{width:26px;height:26px;border-radius:8px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:var(--lime);color:#000;margin-top:1px}
.reg-pop-ref-ico svg.i{width:14px;height:14px}
.reg-pop-ref-txt{font-size:12.5px;line-height:1.5;color:var(--text)}
.reg-pop-ref-txt b{color:var(--accent);font-weight:700}

/* --- быстрые действия: сетка 2x2 из карточек с каскадным появлением --- */
.reg-pop-qa-lab{font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--dim);
  margin:14px 2px 8px}
.reg-pop-qa{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px}
.reg-qa{display:flex;align-items:center;gap:9px;padding:11px 11px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-md);text-align:left;color:var(--text);
  cursor:pointer;overflow:hidden;position:relative;min-width:0;
  transition:border-color .18s,background .18s,transform .15s cubic-bezier(.2,1.2,.3,1),box-shadow .18s;
  opacity:0;transform:translateY(14px);
  animation:regFadeUp .5s cubic-bezier(.2,1,.3,1) forwards;
  animation-delay:calc(var(--i,0) * 90ms + 220ms)}
.reg-qa:hover{border-color:var(--lime);background:var(--raised);transform:translateY(-1px);
  box-shadow:0 10px 24px -14px rgba(154,255,0,.55)}
.reg-qa:active{transform:scale(.97)}
.reg-qa-ico{width:34px;height:34px;border-radius:11px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:var(--lime-dim);color:var(--accent);border:1px solid rgba(154,255,0,.24);
  transition:background .18s,color .18s}
.reg-qa:hover .reg-qa-ico{background:var(--lime);color:#000;border-color:var(--lime)}
.reg-qa-ico svg.i{width:17px;height:17px}
.reg-qa-txt{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;line-height:1.15}
.reg-qa-t{display:block;font-size:12.5px;font-weight:700;color:var(--text);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.reg-qa-s{display:block;font-size:10.5px;font-weight:500;color:var(--dim);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.reg-qa-arr{flex-shrink:0;color:var(--dim);opacity:.65;transition:transform .2s,color .18s,opacity .18s}
.reg-qa-arr svg.i{width:13px;height:13px}
