/* ============================================================
   АВАТАР В РЕГИСТРАЦИИ (reg-ava-) — превью инициалов на брендовом
   градиенте + выбор акцента; персистится и применяется к профилю.
   ============================================================ */
.reg-ava-row{display:flex;align-items:center;gap:14px;margin-bottom:4px}
.reg-ava-prev{width:58px;height:58px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  font-family:var(--font-display);font-size:26px;letter-spacing:.02em;color:#000;position:relative;
  box-shadow:0 8px 22px -10px rgba(154,255,0,.6);transition:background .3s ease}
.reg-ava-prev::after{content:'';position:absolute;inset:-4px;border-radius:50%;border:1.5px solid rgba(154,255,0,.35);
  opacity:0;transition:opacity .3s}
.reg-ava-prev.set::after{opacity:1;animation:regObHalo 2.4s ease-out infinite}
@keyframes regObHalo{0%{transform:scale(1);opacity:.55}100%{transform:scale(1.22);opacity:0}}
@media(prefers-reduced-motion:reduce){.reg-ava-prev.set::after{animation:none;opacity:.4}}
.reg-ava-swatches{display:flex;gap:9px;flex-wrap:wrap}
.reg-ava-sw{width:30px;height:30px;border-radius:50%;position:relative;transition:transform .14s;flex-shrink:0}
.reg-ava-sw:active{transform:scale(.9)}
.reg-ava-sw.on{transform:scale(1.08)}
.reg-ava-sw.on::after{content:'';position:absolute;inset:-4px;border-radius:50%;border:2px solid var(--text)}
:root[data-theme="light"] .reg-ava-sw.on::after{border-color:var(--accent)}

/* ============================================================
   RG2 — новый 4-шаговый регистрационный флоу внутри #authScreen.
   Полностью автономный, префикс rg2-. Живёт как оверлей над
   auth-inner (её мы скрываем на время потока).
   ============================================================ */
.rg2-shell{position:absolute;inset:0;z-index:5;display:none;flex-direction:column;
  background:var(--bg);color:var(--text);
  opacity:0;transform:translateY(12px);transition:opacity .28s ease,transform .28s ease}
.rg2-shell.open{display:flex;opacity:1;transform:none}
:root[data-theme="light"] .rg2-shell{background:var(--bg)}
/* живой брендовый фон */
.rg2-shell::before{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;
  background:
    radial-gradient(680px 520px at 82% -8%, rgba(154,255,0,.15), transparent 62%),
    radial-gradient(560px 460px at -12% 108%, rgba(154,255,0,.1), transparent 60%);
  animation:rg2Ambient 18s ease-in-out infinite alternate}
.rg2-shell::after{content:'';position:absolute;inset:0;z-index:0;pointer-events:none;opacity:.45;
  background-image:radial-gradient(rgba(154,255,0,.10) 1px, transparent 1.4px);background-size:26px 26px;
  -webkit-mask-image:radial-gradient(120% 90% at 50% 0%, #000 8%, transparent 62%);
  mask-image:radial-gradient(120% 90% at 50% 0%, #000 8%, transparent 62%);
  animation:rg2Grid 24s linear infinite}
:root[data-theme="light"] .rg2-shell::before{
  background:
    radial-gradient(680px 520px at 82% -8%, rgba(122,204,0,.18), transparent 62%),
    radial-gradient(560px 460px at -12% 108%, rgba(122,204,0,.12), transparent 60%)}
:root[data-theme="light"] .rg2-shell::after{opacity:.4;background-image:radial-gradient(rgba(122,204,0,.14) 1px, transparent 1.4px)}
@keyframes rg2Ambient{0%{transform:translate3d(0,0,0) scale(1)}100%{transform:translate3d(-2.5%,1.8%,0) scale(1.07)}}
@keyframes rg2Grid{to{background-position:26px 26px}}
@media(prefers-reduced-motion:reduce){.rg2-shell,.rg2-shell::before,.rg2-shell::after{transition:none;animation:none}}

/* --- шапка + прогресс-таймлайн (4 точки) --- */
.rg2-head{position:relative;z-index:1;display:flex;align-items:center;gap:12px;
  padding:14px 16px;padding-top:max(14px,env(safe-area-inset-top));flex-shrink:0}
.rg2-back{width:38px;height:38px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  border-radius:12px;background:var(--surface);border:1px solid var(--border);color:var(--text);
  cursor:pointer;transition:background .18s,transform .12s}
.rg2-back:hover{background:var(--raised)}
.rg2-back:active{transform:scale(.94)}
