.rg2-brand{width:38px;height:38px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  color:var(--accent);opacity:.85}
.rg2-brand .i{width:24px;height:24px}
.rg2-tl{flex:1;display:flex;align-items:center;gap:6px;min-width:0}
.rg2-tl-dot{width:26px;height:26px;flex-shrink:0;border-radius:50%;background:var(--surface);
  border:1.5px solid var(--border);display:flex;align-items:center;justify-content:center;
