  transition:background .25s,color .25s,border-color .25s,transform .25s}
.rg2-tl-dot i{font-style:normal}
.rg2-tl-dot.on{background:var(--lime);color:#000;border-color:var(--lime);
  box-shadow:0 0 0 4px var(--lime-dim);transform:scale(1.08)}
.rg2-tl-dot.done{background:var(--lime);color:#000;border-color:var(--lime)}
.rg2-tl-seg{flex:1;height:2px;background:var(--border);border-radius:2px;overflow:hidden;min-width:12px}
