.rg2-lab-dim{color:var(--dim);text-transform:none;letter-spacing:0;font-weight:500;opacity:.7;font-size:11px}

/* --- поле с иконкой + инпут --- */
.rg2-field{position:relative;display:flex;align-items:center;gap:8px;
