.rg2-check-box{width:22px;height:22px;flex-shrink:0;border-radius:7px;border:1.5px solid var(--border);
  background:var(--surface);display:flex;align-items:center;justify-content:center;margin-top:0;
  transition:background .18s,border-color .18s}
