/* ---------- шапка профиля (аватар накрывает обложку) ---------- */
.ps-top{text-align:center;position:relative}
.ps-ava-wrap{position:relative;width:92px;margin:-50px auto 12px}
.ps-ava{width:92px;height:92px;border-radius:50%;background:var(--lime-dim);border:3px solid var(--bg);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:32px;color:var(--accent);box-shadow:0 6px 22px rgba(0,0,0,.5),var(--glow);animation:psAvaIn .4s cubic-bezier(.3,1,.4,1)}
