@keyframes psAvaIn{from{opacity:0;transform:scale(.8) translateY(6px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.ps-ava{animation:none}}
/* индикатор «в сети» */
.ps-ava-on{position:absolute;right:5px;bottom:5px;width:18px;height:18px;border-radius:50%;background:#3ddc5a;border:3px solid var(--bg);box-shadow:0 0 0 0 rgba(61,220,90,.5);animation:psPulse 2s infinite}
@keyframes psPulse{0%{box-shadow:0 0 0 0 rgba(61,220,90,.5)}70%{box-shadow:0 0 0 7px rgba(61,220,90,0)}100%{box-shadow:0 0 0 0 rgba(61,220,90,0)}}
