.ps-nick .ps-dot{opacity:.5;margin:0 5px}
.ps-on{color:#3ddc5a;font-weight:600}
.ps-bio{font-size:13px;line-height:1.55;color:var(--text);opacity:.9;max-width:440px;margin:11px auto 0}

/* ---------- ачивки-лента ---------- */
.ps-ach{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:14px auto 0;max-width:520px;padding:0 2px}
.ps-badge{display:inline-flex;align-items:center;gap:6px;background:var(--surface);border:1px solid var(--border);border-radius:99px;padding:6px 12px 6px 9px;font-size:11.5px;font-weight:600;color:var(--text);white-space:nowrap;transition:border-color .2s,transform .15s,box-shadow .2s;animation:psBadgeIn .4s both}
.ps-badge:hover{border-color:var(--accent);transform:translateY(-2px);box-shadow:0 4px 14px rgba(154,255,0,.14)}
.ps-badge .ps-bi{width:22px;height:22px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--lime-dim);flex-shrink:0}
.ps-badge .ps-bi svg.i{width:13px;height:13px;color:var(--accent)}
.ps-badge.gold .ps-bi{background:linear-gradient(135deg,rgba(255,208,64,.28),rgba(255,170,0,.12))}
.ps-badge.gold .ps-bi svg.i{color:#ffcb3a}
.ps-badge.gold{border-color:rgba(255,200,60,.32)}
@keyframes psBadgeIn{from{opacity:0;transform:translateY(8px) scale(.94)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.ps-badge{animation:none}}

/* ---------- статистика: посты / подписчики / подписки ---------- */
.ps-stats{display:flex;gap:10px;margin:18px 0 14px}
.ps-stat{flex:1;text-align:center;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:13px 6px;transition:border-color .2s,transform .15s;position:relative;overflow:hidden}
.ps-stat::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(154,255,0,.06),transparent 60%);opacity:0;transition:opacity .2s}
.ps-stat:hover{border-color:var(--accent);transform:translateY(-2px)}
.ps-stat:hover::after{opacity:1}
.ps-stat b{display:block;font-family:var(--font-display);font-size:24px;line-height:1;color:var(--accent);letter-spacing:.02em;white-space:nowrap}
.ps-stat small{display:block;font-size:10px;color:var(--dim);margin-top:5px;text-transform:uppercase;letter-spacing:.08em}
.ps-bump{animation:psBump .45s ease}
@keyframes psBump{0%{transform:scale(1)}35%{transform:scale(1.24)}100%{transform:scale(1)}}

/* ---------- кнопки Подписаться / Написать ---------- */
.ps-actions{display:flex;gap:10px}
