.ps-actions .btn svg.i{width:16px;height:16px}
.ps-actions .btn:active{transform:scale(.97)}
#psFollowBtn:not(.ghost){box-shadow:var(--glow)}
:root[data-theme="light"] #psFollowBtn:not(.ghost){box-shadow:none}
/* блик-шиммер по кнопке подписки при наведении */
#psFollowBtn:not(.ghost)::after{content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.45),transparent);transform:skewX(-18deg);transition:none}
#psFollowBtn:not(.ghost):hover::after{animation:psShine .7s ease}
@keyframes psShine{from{left:-60%}to{left:130%}}
@media(prefers-reduced-motion:reduce){#psFollowBtn::after{display:none}}

/* ---------- лента постов автора ---------- */
.ps-sec{display:flex;align-items:center;gap:9px;font-family:var(--font-display);font-size:17px;letter-spacing:.07em;margin:24px 0 10px}
.ps-sec .ps-cnt{font-size:10.5px;font-family:var(--font-body);font-weight:700;background:var(--lime-dim);color:var(--accent);border-radius:99px;padding:3px 9px;letter-spacing:0}
