.ps-empty p{font-weight:700;color:var(--text);font-size:14px}
.ps-empty span{font-size:12px}

/* метки в общей ленте: чип «Подписка» у авторов, на которых подписан */
.ps-fchip{font-size:9px;padding:3px 8px;margin-left:6px;vertical-align:1px;animation:psChipIn .3s ease}
.ps-fchip svg.i{width:10px;height:10px;vertical-align:-1px;margin-right:3px}
@keyframes psChipIn{from{opacity:0;transform:translateY(-3px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.ps-fchip,.ps-bump{animation:none}}

/* точки входа: имя/аватар автора кликабельны */
