button.ps-stat-btn:active{transform:scale(.96)}
/* компактная кнопка «Поделиться» рядом с действиями */
.ps-actions .ps-share-btn{flex:0 0 auto;width:46px;padding:12px 0;display:inline-flex;align-items:center;justify-content:center}
.ps-actions .ps-share-btn svg.i{width:17px;height:17px;margin:0}
.ps-sharelink{display:flex;align-items:center;gap:8px;margin-top:12px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-sm);padding:9px 11px;font-size:12px;color:var(--text);word-break:break-all;text-align:left}
