/* ---------- соцграф: сет-лист людей ---------- */
.ps-graph-tabs{display:flex;gap:6px;background:var(--raised);border-radius:var(--r-md);padding:4px;margin:4px 0 12px}
.ps-graph-tabs button{flex:1;padding:9px 8px;border-radius:calc(var(--r-md) - 4px);font-size:13px;font-weight:700;color:var(--dim);background:transparent;transition:color .2s,background .2s;cursor:pointer}
