.ps-follow-mini{flex-shrink:0;display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:700;padding:7px 12px;border-radius:99px;background:var(--accent);color:#06210a;border:1px solid var(--accent);transition:transform .12s,background .2s,color .2s,border-color .2s;cursor:pointer}
