/* ---------- «Мои подписки» на своём профиле ---------- */
.ps-myfollows{display:flex;align-items:center;gap:12px;width:100%;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:11px 14px;margin:12px 0 2px;cursor:pointer;transition:border-color .2s,transform .12s;text-align:left}
.ps-myfollows:hover{border-color:var(--accent)}
.ps-myfollows:active{transform:scale(.99)}
.ps-mf-avas{display:flex;flex-shrink:0}
