.ps-tabs button.on::after{transform:scaleX(1)}
.ps-tabs button.on svg.i{transform:translateY(-1px)}
.ps-tabs button.on .ps-tab-cnt{background:var(--lime-dim);color:var(--accent)}
@media(prefers-reduced-motion:reduce){.ps-tabs button::after,.ps-tabs button svg.i{transition:none}}

/* ========== МЕДИА-СЕТКА (Instagram grid) ========== */
.ps-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}
.ps-mtile{position:relative;aspect-ratio:1;border-radius:var(--r-sm);overflow:hidden;cursor:pointer;background:#0a0d04;border:1px solid var(--border);transition:transform .16s,box-shadow .2s;isolation:isolate}
.ps-mtile:hover{transform:translateY(-2px);box-shadow:0 8px 20px rgba(0,0,0,.4)}
.ps-mtile:active{transform:scale(.97)}
.ps-mtile::before{content:"";position:absolute;inset:0;z-index:-1}
.ps-mtile::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(0,0,0,.55));z-index:0}
.ps-mt-ic{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:1}
.ps-mt-ic svg.i{width:30px;height:30px;color:rgba(255,255,255,.92);filter:drop-shadow(0 2px 6px rgba(0,0,0,.4));transition:transform .2s}
.ps-mtile:hover .ps-mt-ic svg.i{transform:scale(1.14)}
.ps-mt-dur{position:absolute;top:7px;right:7px;z-index:2;display:inline-flex;align-items:center;gap:3px;background:rgba(0,0,0,.55);color:#fff;font-size:9.5px;font-weight:700;border-radius:99px;padding:2px 7px 2px 5px;backdrop-filter:blur(3px)}
.ps-mt-dur svg.i{width:10px;height:10px;color:var(--accent)}
.ps-mt-stat{position:absolute;left:7px;bottom:7px;z-index:2;display:inline-flex;align-items:center;gap:4px;color:#fff;font-size:10px;font-weight:700;text-shadow:0 1px 3px rgba(0,0,0,.5)}
.ps-mt-stat svg.i{width:12px;height:12px}
/* бренд-градиенты плиток g0..g5 */
.ps-mtile.g0::before{background:radial-gradient(120% 120% at 20% 0%,rgba(154,255,0,.42),transparent 60%),linear-gradient(150deg,#101706,#070a03)}
.ps-mtile.g1::before{background:conic-gradient(from 200deg at 70% 20%,rgba(154,255,0,.4),transparent 45%,rgba(154,255,0,.14)),linear-gradient(160deg,#0d1305,#060803)}
.ps-mtile.g2::before{background:linear-gradient(120deg,rgba(154,255,0,.34) 0%,transparent 55%),linear-gradient(180deg,#0e1305,#080b03)}
.ps-mtile.g3::before{background:radial-gradient(80% 90% at 80% 90%,rgba(154,255,0,.4),transparent 62%),linear-gradient(140deg,#0c1104,#060903)}
.ps-mtile.g4::before{background:radial-gradient(70% 70% at 50% 30%,rgba(154,255,0,.36),transparent 60%),linear-gradient(200deg,#0e1405,#070a03)}
.ps-mtile.g5::before{background:repeating-linear-gradient(125deg,rgba(154,255,0,.16) 0 3px,transparent 3px 15px),linear-gradient(160deg,#0d1204,#070a03)}
:root[data-theme="light"] .ps-mtile{background:#eef7dd}
:root[data-theme="light"] .ps-mtile::after{background:linear-gradient(180deg,transparent 40%,rgba(20,40,0,.4))}
:root[data-theme="light"] .ps-mtile.g0::before{background:radial-gradient(120% 120% at 20% 0%,rgba(120,200,0,.55),transparent 62%),linear-gradient(150deg,#dcefbf,#c8e39c)}
:root[data-theme="light"] .ps-mtile.g1::before{background:conic-gradient(from 200deg at 70% 20%,rgba(120,200,0,.5),transparent 46%,rgba(154,255,0,.2)),linear-gradient(160deg,#dcefbf,#cbe49f)}
:root[data-theme="light"] .ps-mtile.g2::before{background:linear-gradient(120deg,rgba(120,200,0,.5) 0%,transparent 56%),linear-gradient(180deg,#e0f1c6,#cde59f)}
:root[data-theme="light"] .ps-mtile.g3::before{background:radial-gradient(80% 90% at 80% 90%,rgba(120,200,0,.5),transparent 62%),linear-gradient(140deg,#ddefc0,#cae49b)}
:root[data-theme="light"] .ps-mtile.g4::before{background:radial-gradient(70% 70% at 50% 30%,rgba(120,200,0,.48),transparent 62%),linear-gradient(200deg,#dfeec2,#cce49d)}
:root[data-theme="light"] .ps-mtile.g5::before{background:repeating-linear-gradient(125deg,rgba(120,200,0,.28) 0 3px,transparent 3px 15px),linear-gradient(160deg,#ddefc0,#cbe49f)}
:root[data-theme="light"] .ps-mt-ic svg.i{color:#2a4a00}
:root[data-theme="light"] .ps-mt-dur{background:rgba(20,40,0,.6)}

/* ========== ЛАЙТБОКС / СТОРИС-КАРТА (в попапе) ========== */
.ps-story{position:relative;height:150px;border-radius:var(--r-md);overflow:hidden;margin:2px 0 2px;display:flex;align-items:center;justify-content:center;isolation:isolate}
.ps-story::before{content:"";position:absolute;inset:0;z-index:-1}
.ps-story.g0::before{background:radial-gradient(120% 120% at 20% 0%,rgba(154,255,0,.42),transparent 60%),linear-gradient(150deg,#101706,#070a03)}
.ps-story.g1::before{background:conic-gradient(from 200deg at 70% 20%,rgba(154,255,0,.4),transparent 45%,rgba(154,255,0,.14)),linear-gradient(160deg,#0d1305,#060803)}
.ps-story.g2::before{background:linear-gradient(120deg,rgba(154,255,0,.34) 0%,transparent 55%),linear-gradient(180deg,#0e1305,#080b03)}
.ps-story.g3::before{background:radial-gradient(80% 90% at 80% 90%,rgba(154,255,0,.4),transparent 62%),linear-gradient(140deg,#0c1104,#060903)}
.ps-story.g4::before{background:radial-gradient(70% 70% at 50% 30%,rgba(154,255,0,.36),transparent 60%),linear-gradient(200deg,#0e1405,#070a03)}
.ps-story.g5::before{background:repeating-linear-gradient(125deg,rgba(154,255,0,.16) 0 3px,transparent 3px 15px),linear-gradient(160deg,#0d1204,#070a03)}
.ps-story-ic{width:60px;height:60px;border-radius:50%;background:rgba(0,0,0,.32);display:flex;align-items:center;justify-content:center;box-shadow:var(--glow)}
.ps-story-ic svg.i{width:30px;height:30px;color:var(--lime)}
.ps-story-tag{position:absolute;top:10px;left:10px;font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:#fff;background:rgba(0,0,0,.4);border-radius:99px;padding:3px 9px;backdrop-filter:blur(3px)}
.ps-lb-meta{position:absolute;bottom:10px;left:10px;display:flex;gap:12px;color:#fff;font-size:12px;font-weight:700}
.ps-lb-meta span{display:inline-flex;align-items:center;gap:4px;text-shadow:0 1px 3px rgba(0,0,0,.5)}
.ps-lb-meta svg.i{width:14px;height:14px;color:var(--lime)}
.ps-story-txt{font-size:13px;line-height:1.55;color:var(--text);opacity:.92;margin-top:11px;text-align:left}
:root[data-theme="light"] .ps-story.g0::before{background:radial-gradient(120% 120% at 20% 0%,rgba(120,200,0,.5),transparent 62%),linear-gradient(150deg,#dcefbf,#c8e39c)}
:root[data-theme="light"] .ps-story.g1::before{background:conic-gradient(from 200deg at 70% 20%,rgba(120,200,0,.46),transparent 46%,rgba(154,255,0,.2)),linear-gradient(160deg,#dcefbf,#cbe49f)}
:root[data-theme="light"] .ps-story.g2::before{background:linear-gradient(120deg,rgba(120,200,0,.46) 0%,transparent 56%),linear-gradient(180deg,#e0f1c6,#cde59f)}
:root[data-theme="light"] .ps-story.g3::before{background:radial-gradient(80% 90% at 80% 90%,rgba(120,200,0,.46),transparent 62%),linear-gradient(140deg,#ddefc0,#cae49b)}
:root[data-theme="light"] .ps-story.g4::before{background:radial-gradient(70% 70% at 50% 30%,rgba(120,200,0,.44),transparent 62%),linear-gradient(200deg,#dfeec2,#cce49d)}
:root[data-theme="light"] .ps-story.g5::before{background:repeating-linear-gradient(125deg,rgba(120,200,0,.26) 0 3px,transparent 3px 15px),linear-gradient(160deg,#ddefc0,#cbe49f)}
:root[data-theme="light"] .ps-story-ic{background:rgba(255,255,255,.5)}
:root[data-theme="light"] .ps-story-ic svg.i{color:#3c6b00}
:root[data-theme="light"] .ps-lb-meta{color:#1a3300}
:root[data-theme="light"] .ps-lb-meta svg.i{color:#4a8500}

/* ---------- кебаб-меню в шапке чужого профиля ---------- */
.ps-more-btn{flex-shrink:0;width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;color:var(--dim);border-radius:50%;transition:color .2s,background .2s}
.ps-more-btn svg.i{width:22px;height:22px}
.ps-more-btn:hover{color:var(--accent);background:var(--lime-dim)}
.ps-more-btn:active{transform:scale(.92)}
#okoPopup .btn.ps-btn-danger{background:var(--danger);color:#fff;border-color:var(--danger)}

/* ============================================================================
   МОЙ ПРОФИЛЬ · «социальная витрина» (mp-)
   Все инъекции живут внутри #screen-profile .pad и не трогают base.html.
   ============================================================================ */

/* ---------- ОБЛОЖКА ---------- */
.mp-cover-wrap{margin:-18px -18px 20px}
.mp-cover{position:relative;height:140px;overflow:hidden;isolation:isolate;border-bottom:1px solid var(--border)}
.mp-cover::before{content:"";position:absolute;inset:0;
  background:
    radial-gradient(120% 130% at 18% 0%, rgba(154,255,0,.30), transparent 55%),
    radial-gradient(90% 120% at 100% 100%, rgba(154,255,0,.18), transparent 60%),
    linear-gradient(160deg,#0e1305 0%, #070a03 48%, #0a0d04 100%);
}
.mp-cover::after{content:"";position:absolute;top:-40%;left:-20%;width:70%;height:180%;
  background:radial-gradient(closest-side, rgba(154,255,0,.34), transparent 70%);
  filter:blur(8px);opacity:.9;animation:mpCoverDrift 10s ease-in-out infinite;
}
@keyframes mpCoverDrift{0%{transform:translate(0,0)}50%{transform:translate(230%,14%)}100%{transform:translate(0,0)}}
.mp-cover-grid{position:absolute;inset:0;opacity:.5;mix-blend-mode:screen;
  background-image:linear-gradient(rgba(154,255,0,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(154,255,0,.08) 1px,transparent 1px);
  background-size:26px 26px;
  -webkit-mask-image:linear-gradient(180deg,#000,transparent);mask-image:linear-gradient(180deg,#000,transparent)}
.mp-cover-mark{position:absolute;right:16px;top:14px;width:36px;height:36px;color:var(--lime);opacity:.24;filter:drop-shadow(0 0 8px rgba(154,255,0,.4))}
.mp-cover-mark svg.i{width:100%;height:100%}
.mp-cover-brand{position:absolute;left:18px;bottom:12px;font-family:var(--font-display);font-size:22px;letter-spacing:.28em;color:rgba(154,255,0,.22);font-weight:800;text-shadow:0 0 12px rgba(154,255,0,.35);pointer-events:none;user-select:none}
.mp-cover.v1::before{background:radial-gradient(80% 120% at 82% 0%, rgba(154,255,0,.28), transparent 58%),conic-gradient(from 210deg at 30% 120%, rgba(154,255,0,.20), transparent 40%, transparent 70%, rgba(154,255,0,.10)),linear-gradient(150deg,#0c1205,#060803)}
.mp-cover.v2::before{background:linear-gradient(100deg, transparent 0%, rgba(154,255,0,.26) 46%, rgba(154,255,0,.05) 54%, transparent 100%),linear-gradient(180deg,#0d1204,#070a03)}
.mp-cover.v3::before{background:radial-gradient(60% 100% at 50% 130%, rgba(154,255,0,.30), transparent 60%),linear-gradient(180deg,#0b1004,#070a03)}
.mp-cover.v4::before{background:radial-gradient(90% 130% at 0% 0%, rgba(154,255,0,.26), transparent 55%),radial-gradient(70% 100% at 100% 40%, rgba(154,255,0,.14), transparent 60%),linear-gradient(140deg,#0d1305,#070a03)}
@media(prefers-reduced-motion:reduce){.mp-cover::after{animation:none}}
:root[data-theme="light"] .mp-cover::before{background:radial-gradient(120% 130% at 18% 0%, rgba(154,255,0,.34), transparent 55%),radial-gradient(90% 120% at 100% 100%, rgba(120,210,0,.20), transparent 60%),linear-gradient(160deg,#eef7dd 0%, #e7f2d4 55%, #dcecc6 100%)}
:root[data-theme="light"] .mp-cover.v1::before{background:radial-gradient(80% 120% at 82% 0%, rgba(154,255,0,.32), transparent 58%),conic-gradient(from 210deg at 30% 120%, rgba(120,210,0,.22), transparent 42%, transparent 70%, rgba(154,255,0,.12)),linear-gradient(150deg,#eef7dd,#e2eecb)}
:root[data-theme="light"] .mp-cover.v2::before{background:linear-gradient(100deg, transparent 0%, rgba(154,255,0,.30) 46%, rgba(120,210,0,.06) 54%, transparent 100%),linear-gradient(180deg,#eef7dd,#e5f0cd)}
:root[data-theme="light"] .mp-cover.v3::before{background:radial-gradient(60% 100% at 50% 130%, rgba(154,255,0,.34), transparent 60%),linear-gradient(180deg,#edf6dc,#e6f1cf)}
:root[data-theme="light"] .mp-cover.v4::before{background:radial-gradient(90% 130% at 0% 0%, rgba(154,255,0,.30), transparent 55%),radial-gradient(70% 100% at 100% 40%, rgba(120,210,0,.16), transparent 60%),linear-gradient(140deg,#eef7dd,#e4efcb)}
:root[data-theme="light"] .mp-cover::after{opacity:.55}
:root[data-theme="light"] .mp-cover-grid{mix-blend-mode:multiply;opacity:.35}
:root[data-theme="light"] .mp-cover-mark{color:#5f9e00;opacity:.35;filter:none}
:root[data-theme="light"] .mp-cover-brand{color:rgba(70,120,0,.28);text-shadow:none}

/* ---------- аватар над обложкой + стикер статуса ---------- */
#screen-profile .profile-top{margin-top:-46px;position:relative;z-index:1}
#screen-profile .profile-top .ava.mp-ava-plus{position:relative;border:3px solid var(--bg);box-shadow:0 6px 20px rgba(0,0,0,.45),var(--glow)}
:root[data-theme="light"] #screen-profile .profile-top .ava.mp-ava-plus{box-shadow:0 6px 18px rgba(60,90,10,.16)}
.mp-sticker{position:absolute;right:-3px;bottom:-3px;width:26px;height:26px;border-radius:50%;background:var(--bg);border:2.5px solid var(--bg);display:inline-flex;align-items:center;justify-content:center;box-shadow:0 3px 8px rgba(0,0,0,.35);animation:mpStickerIn .35s cubic-bezier(.3,1.4,.5,1) both}
.mp-sticker svg.i{width:14px;height:14px}
.mp-sticker.mp-tone-ok svg.i{color:#3ddc5a}
.mp-sticker.mp-tone-accent svg.i{color:var(--accent)}
.mp-sticker.mp-tone-muted svg.i{color:#a1a19a}
.mp-sticker.mp-tone-ok{background:#0f2413}
.mp-sticker.mp-tone-accent{background:#141b06}
.mp-sticker.mp-tone-muted{background:#1a1a17}
:root[data-theme="light"] .mp-sticker.mp-tone-ok{background:#e0f4dc}
:root[data-theme="light"] .mp-sticker.mp-tone-accent{background:#eef7dd}
:root[data-theme="light"] .mp-sticker.mp-tone-muted{background:#e9e9e6}
@keyframes mpStickerIn{from{opacity:0;transform:scale(.4)}to{opacity:1;transform:scale(1)}}
@media(prefers-reduced-motion:reduce){.mp-sticker{animation:none}}

/* ---------- строка статуса ---------- */
.mp-status-row{margin:10px 0 4px;display:flex}
.mp-status{display:inline-flex;align-items:center;gap:8px;padding:8px 14px 8px 8px;border-radius:99px;background:var(--surface);border:1px solid var(--border);font-size:12.5px;font-weight:700;color:var(--text);cursor:pointer;transition:border-color .2s,transform .12s,background .2s;max-width:100%}
.mp-status:hover{border-color:var(--accent)}
.mp-status:active{transform:scale(.97)}
.mp-status span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mp-status.ghost{color:var(--dim);border-style:dashed;padding:7px 14px 7px 10px}
.mp-status.ghost svg.i{width:14px;height:14px;color:var(--dim)}
.mp-status-ic{width:24px;height:24px;flex-shrink:0;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--lime-dim)}
.mp-status-ic svg.i{width:13px;height:13px;color:var(--accent)}
.mp-tone-ok .mp-status-ic{background:rgba(61,220,90,.16)}
.mp-tone-ok .mp-status-ic svg.i{color:#3ddc5a}
.mp-tone-muted .mp-status-ic{background:rgba(161,161,154,.16)}
.mp-tone-muted .mp-status-ic svg.i{color:#a1a19a}

/* пикер статуса внутри okoPopup */
.mp-pick{display:flex;flex-direction:column;gap:6px;margin:4px 0 2px}
.mp-pick-row{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:var(--r-md);border:1px solid var(--border);background:var(--surface);cursor:pointer;text-align:left;transition:border-color .2s,transform .12s,background .2s}
.mp-pick-row:hover{border-color:var(--accent)}
.mp-pick-row:active{transform:scale(.99)}
.mp-pick-row.on{border-color:var(--accent);background:var(--lime-dim)}
.mp-pick-ic{width:36px;height:36px;flex-shrink:0;border-radius:50%;background:var(--raised);display:inline-flex;align-items:center;justify-content:center;color:var(--accent)}
.mp-pick-ic svg.i{width:17px;height:17px}
.mp-pick-b{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.mp-pick-b b{font-size:13.5px;font-weight:700}
.mp-pick-b small{font-size:11.5px;color:var(--dim);line-height:1.35}
.mp-pick-ok{flex-shrink:0;width:24px;height:24px;border-radius:50%;background:var(--accent);color:#06210a;display:inline-flex;align-items:center;justify-content:center}
.mp-pick-ok svg.i{width:14px;height:14px}

/* ---------- витрина результатов ---------- */
.mp-show-wrap{margin:14px 0 4px}
.mp-show{display:grid;grid-template-columns:1fr;gap:8px}
.mp-card{display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);cursor:pointer;text-align:left;transition:border-color .2s,transform .12s,background .2s;width:100%;position:relative;overflow:hidden}
.mp-card::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:linear-gradient(180deg,var(--accent),transparent);opacity:0;transition:opacity .2s}
.mp-card:hover{border-color:var(--accent);transform:translateY(-1px)}
.mp-card:hover::before{opacity:1}
.mp-card:active{transform:scale(.99)}
.mp-card-ic{width:40px;height:40px;flex-shrink:0;border-radius:12px;background:var(--lime-dim);display:inline-flex;align-items:center;justify-content:center;color:var(--accent)}
.mp-card-ic svg.i{width:20px;height:20px}
.mp-card-b{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.mp-card-b small{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.06em;font-weight:600}
.mp-card-b b{font-size:14.5px;font-weight:800;line-height:1.15;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mp-card-s{font-size:11.5px;color:var(--dim);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mp-card-ch{flex-shrink:0;color:var(--dim);display:inline-flex}
.mp-card-ch svg.i{width:15px;height:15px}
@media(min-width:520px){.mp-show{grid-template-columns:repeat(3,1fr)}.mp-card-ch{display:none}.mp-card{flex-direction:column;align-items:flex-start;text-align:left;gap:10px}.mp-card-ic{width:36px;height:36px}}

/* ---------- sparkline: рост подписчиков ---------- */
.mp-spark-wrap{margin:8px 0 10px}
.mp-spark{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px 10px;transition:border-color .2s}
.mp-spark:hover{border-color:var(--accent)}
.mp-spark-h{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:4px}
.mp-spark-lb{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.08em;font-weight:600}
.mp-spark-v{font-family:var(--font-display);font-size:18px;color:var(--accent);letter-spacing:.02em}
.mp-spark-svg{width:100%;height:44px;display:block}

/* ---------- стрик учёбы ---------- */
.mp-streak-wrap{margin:8px 0 12px}
.mp-streak{display:flex;align-items:center;gap:12px;width:100%;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);cursor:pointer;text-align:left;transition:border-color .2s,transform .12s,background .2s;position:relative;overflow:hidden}
.mp-streak::before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,rgba(255,120,20,.10),transparent 55%);opacity:0;transition:opacity .2s;pointer-events:none}
.mp-streak:hover{border-color:var(--accent)}
.mp-streak:hover::before{opacity:1}
.mp-streak:active{transform:scale(.99)}
.mp-streak.hot{border-color:rgba(255,140,40,.35)}
.mp-streak.hot::before{opacity:1;background:linear-gradient(120deg,rgba(255,120,20,.14),transparent 60%),linear-gradient(300deg,rgba(154,255,0,.10),transparent 55%)}
.mp-streak-ic{width:46px;height:46px;flex-shrink:0;border-radius:50%;background:linear-gradient(135deg,rgba(255,180,60,.24),rgba(154,255,0,.14));display:inline-flex;align-items:center;justify-content:center;color:#ffb340;box-shadow:inset 0 0 0 1px rgba(255,180,60,.28)}
.mp-streak-ic svg.i{width:22px;height:22px;filter:drop-shadow(0 0 6px rgba(255,140,40,.5))}
.mp-streak.hot .mp-streak-ic{animation:mpStreakPulse 2s ease-in-out infinite}
@keyframes mpStreakPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.08)}}
@media(prefers-reduced-motion:reduce){.mp-streak.hot .mp-streak-ic{animation:none}}
.mp-streak-b{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.mp-streak-b b{font-family:var(--font-display);font-size:19px;letter-spacing:.02em;color:var(--text);line-height:1.1}
.mp-streak-b small{font-size:11.5px;color:var(--dim);line-height:1.4}
.mp-streak-ch{flex-shrink:0;color:var(--dim);display:inline-flex}
.mp-streak-ch svg.i{width:16px;height:16px}

/* ============================================================================
   МОИ СОЦСЕТИ (ps-soc-): fullscreen-хаб — LinkedIn + Beacons.ai + Linktree
   Точка входа — карточка .ps-soc-entry на своём профиле; открывает #psSocView.
   Всё считается детерминированно (без сети/API), персист — oko-ps-socials.
   ============================================================================ */

/* ---------- точка входа: карточка на профиле ---------- */
.ps-soc-entry-wrap{margin:12px 0 10px}
.ps-soc-entry{display:block;width:100%;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;text-align:left;cursor:pointer;transition:border-color .2s,transform .12s;position:relative;overflow:hidden}
.ps-soc-entry:hover{border-color:var(--accent);transform:translateY(-1px)}
.ps-soc-entry:active{transform:scale(.99)}
.ps-soc-entry::before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,rgba(154,255,0,.08),transparent 55%);opacity:0;transition:opacity .2s;pointer-events:none}
.ps-soc-entry:hover::before{opacity:1}
.ps-soc-entry-h{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.ps-soc-entry-h-ic{width:32px;height:32px;border-radius:10px;background:var(--lime-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}
.ps-soc-entry-h-ic svg.i{width:16px;height:16px}
.ps-soc-entry-h b{font-family:var(--font-display);font-size:16px;letter-spacing:.05em;flex:1;min-width:0}
.ps-soc-entry-h .ps-soc-entry-open{font-size:11px;color:var(--dim);display:inline-flex;align-items:center;gap:3px;font-weight:600}
.ps-soc-entry-h .ps-soc-entry-open svg.i{width:11px;height:11px}
.ps-soc-entry-row{display:flex;align-items:center;gap:8px}
.ps-soc-entry-avas{display:flex;flex-shrink:0}
.ps-soc-entry-ava{width:28px;height:28px;border-radius:50%;background:var(--raised);border:2px solid var(--surface);display:inline-flex;align-items:center;justify-content:center;color:var(--text);margin-left:-8px;flex-shrink:0;box-shadow:inset 0 0 0 1px rgba(255,255,255,.05)}
.ps-soc-entry-ava:first-child{margin-left:0}
.ps-soc-entry-ava svg.i{width:14px;height:14px}
.ps-soc-entry-ava.off{opacity:.38;filter:grayscale(1)}
.ps-soc-entry-sum{flex:1;min-width:0;font-size:12px;color:var(--dim);line-height:1.4}
.ps-soc-entry-sum b{color:var(--text);font-weight:700}
.ps-soc-entry-chev{color:var(--dim);flex-shrink:0}
.ps-soc-entry-chev svg.i{width:16px;height:16px}

/* бренд-цвета кружков в карточке-входе (детерминированные градиенты) */
.ps-soc-tone-ig{background:linear-gradient(135deg,#f58529,#dd2a7b 45%,#8134af 78%,#515bd4);color:#fff}
.ps-soc-tone-tt{background:linear-gradient(135deg,#25f4ee 0%,#111 55%,#fe2c55);color:#fff}
.ps-soc-tone-vk{background:#0077ff;color:#fff}
.ps-soc-tone-tg{background:linear-gradient(135deg,#2ea6de,#1e88c5);color:#fff}
.ps-soc-tone-yt{background:#ff0033;color:#fff}
.ps-soc-tone-th{background:linear-gradient(135deg,#101010,#333);color:#fff}
.ps-soc-tone-ru{background:linear-gradient(135deg,#000,#282828);color:#fff}
.ps-soc-tone-ig svg.i,.ps-soc-tone-tt svg.i,.ps-soc-tone-vk svg.i,.ps-soc-tone-tg svg.i,.ps-soc-tone-yt svg.i,.ps-soc-tone-th svg.i,.ps-soc-tone-ru svg.i{color:#fff}

/* ---------- fullscreen-вьюха хаба (по образцу #psView) ---------- */
#psSocView{position:fixed;inset:0;z-index:66;background:var(--bg);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .3s cubic-bezier(.3,1,.4,1);max-width:1280px;margin:0 auto;padding-left:env(safe-area-inset-left);padding-right:env(safe-area-inset-right)}
#psSocView.open{transform:none}
@media(prefers-reduced-motion:reduce){#psSocView{transition:none}}
#psSocView .sv-body{max-width:680px;width:100%;margin:0 auto}
body.ps-over-soc #sheetOverlay.open{z-index:67}
#sheet-ps-soc-connect,#sheet-ps-soc-detail,#sheet-ps-soc-post,#sheet-ps-soc-link{z-index:68}

/* ---------- секция ---------- */
.ps-soc-sec{margin:18px 0 8px;font-family:var(--font-display);font-size:15px;letter-spacing:.07em;text-transform:uppercase;color:var(--dim);display:flex;align-items:center;gap:8px}
.ps-soc-sec svg.i{width:14px;height:14px;color:var(--accent)}
.ps-soc-sec .ps-soc-sec-hint{margin-left:auto;font-family:var(--font-body);font-size:10.5px;font-weight:600;color:var(--dim);letter-spacing:0;text-transform:none}

/* ---------- совокупный дашборд (тайлы) ---------- */
.ps-soc-dash{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0 4px}
.ps-soc-tile{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 10px;position:relative;overflow:hidden;transition:border-color .2s}
.ps-soc-tile:hover{border-color:var(--accent)}
.ps-soc-tile-lb{font-size:10px;color:var(--dim);text-transform:uppercase;letter-spacing:.07em;font-weight:600;margin-bottom:4px;display:flex;align-items:center;gap:5px}
.ps-soc-tile-lb svg.i{width:11px;height:11px;color:var(--accent)}
.ps-soc-tile-v{font-family:var(--font-display);font-size:22px;line-height:1;color:var(--text);letter-spacing:.02em;white-space:nowrap}
.ps-soc-tile-v .ps-soc-tile-sub{font-family:var(--font-body);font-size:11px;color:var(--dim);margin-left:5px;font-weight:600;letter-spacing:0}
.ps-soc-tile-d{font-size:10.5px;color:#3ddc5a;margin-top:5px;display:flex;align-items:center;gap:3px;font-weight:700}
.ps-soc-tile-d.down{color:#ff6b6b}
.ps-soc-tile-d svg.i{width:10px;height:10px}
.ps-soc-tile.wide{grid-column:1/-1;padding:14px}
.ps-soc-tile.wide .ps-soc-tile-v{font-size:26px}
@media(max-width:420px){.ps-soc-dash{grid-template-columns:1fr 1fr}}

/* ---------- карточки платформ ---------- */
.ps-soc-plats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 4px}
@media(min-width:520px){.ps-soc-plats{grid-template-columns:repeat(3,1fr)}}
.ps-soc-plat{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:12px;text-align:left;cursor:pointer;transition:border-color .2s,transform .12s,background .2s;position:relative;overflow:hidden;display:flex;flex-direction:column;gap:8px;min-height:120px}
.ps-soc-plat:hover{border-color:var(--accent);transform:translateY(-2px)}
.ps-soc-plat:active{transform:scale(.98)}
.ps-soc-plat.on{border-color:rgba(154,255,0,.35);background:linear-gradient(160deg,var(--surface),rgba(154,255,0,.04))}
:root[data-theme="light"] .ps-soc-plat.on{background:linear-gradient(160deg,var(--surface),rgba(120,200,0,.06))}
.ps-soc-plat-h{display:flex;align-items:center;gap:9px}
.ps-soc-plat-ic{width:36px;height:36px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
.ps-soc-plat-ic svg.i{width:19px;height:19px}
.ps-soc-plat-name{font-weight:800;font-size:14px;line-height:1.1;flex:1;min-width:0}
.ps-soc-plat-name small{display:block;font-size:11px;color:var(--dim);font-weight:600;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-soc-plat-st{display:inline-flex;align-items:center;gap:4px;font-size:9.5px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;padding:3px 7px;border-radius:99px;background:var(--raised);color:var(--dim);white-space:nowrap;flex-shrink:0}
.ps-soc-plat-st.on{background:var(--lime-dim);color:var(--accent)}
.ps-soc-plat-st svg.i{width:9px;height:9px}
.ps-soc-plat-mini{display:grid;grid-template-columns:1fr 1fr;gap:4px 8px;font-size:11px;color:var(--dim);margin-top:auto}
.ps-soc-plat-mini b{color:var(--text);font-weight:700;font-size:12.5px}
.ps-soc-plat-mini svg.i{width:10px;height:10px;color:var(--accent);margin-right:3px;vertical-align:-1px}
.ps-soc-plat-cta{margin-top:auto;font-size:12px;color:var(--accent);font-weight:700;display:inline-flex;align-items:center;gap:5px}
.ps-soc-plat-cta svg.i{width:12px;height:12px}
.ps-soc-plat-spark{width:100%;height:22px;display:block;opacity:.9}

/* ---------- панель статистики платформы (в шите) ---------- */
.ps-soc-det-body{display:flex;flex-direction:column;gap:12px;padding-bottom:6px;max-height:min(72vh,640px);overflow-y:auto;-webkit-overflow-scrolling:touch;margin:0 -4px;padding-right:4px;padding-left:4px}
.ps-soc-det-h{display:flex;align-items:center;gap:10px;padding:2px 2px 8px;border-bottom:1px solid var(--border)}
.ps-soc-det-h .ps-soc-plat-ic{width:44px;height:44px;border-radius:12px}
.ps-soc-det-h .ps-soc-plat-ic svg.i{width:22px;height:22px}
.ps-soc-det-h-b{flex:1;min-width:0}
.ps-soc-det-h-b b{display:block;font-family:var(--font-display);font-size:18px;letter-spacing:.03em}
.ps-soc-det-h-b small{display:block;font-size:12px;color:var(--dim);margin-top:2px}
.ps-soc-det-h-actions{display:flex;gap:6px;flex-shrink:0}
.ps-soc-det-h-actions button{width:32px;height:32px;border-radius:50%;background:var(--raised);color:var(--dim);display:inline-flex;align-items:center;justify-content:center;transition:color .2s,background .2s}
.ps-soc-det-h-actions button:hover{background:var(--lime-dim);color:var(--accent)}
.ps-soc-det-h-actions button svg.i{width:14px;height:14px}
.ps-soc-det-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.ps-soc-det-stats .ps-soc-tile-v{font-size:19px}
.ps-soc-det-chart{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px}
.ps-soc-det-chart-h{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:6px}
.ps-soc-det-chart-h span{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.08em;font-weight:600}
.ps-soc-det-chart-h b{font-family:var(--font-display);font-size:18px;color:var(--accent);letter-spacing:.02em}
.ps-soc-det-chart-svg{width:100%;height:56px;display:block}

/* последние посты платформы */
.ps-soc-posts{display:flex;flex-direction:column;gap:8px}
.ps-soc-post-row{display:flex;align-items:center;gap:10px;padding:10px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);cursor:pointer;transition:border-color .2s,transform .12s}
.ps-soc-post-row:hover{border-color:var(--accent)}
.ps-soc-post-row:active{transform:scale(.99)}
.ps-soc-post-thumb{width:48px;height:48px;flex-shrink:0;border-radius:var(--r-sm);background:linear-gradient(150deg,rgba(154,255,0,.30),#0a0d04);display:inline-flex;align-items:center;justify-content:center;color:var(--accent);position:relative;overflow:hidden}
.ps-soc-post-thumb svg.i{width:20px;height:20px;filter:drop-shadow(0 1px 2px rgba(0,0,0,.4))}
.ps-soc-post-thumb.g1{background:linear-gradient(150deg,rgba(154,255,0,.34),#0d1305)}
.ps-soc-post-thumb.g2{background:linear-gradient(160deg,rgba(154,255,0,.24),#080b03)}
.ps-soc-post-thumb.g3{background:radial-gradient(80% 90% at 20% 20%,rgba(154,255,0,.36),#070a03)}
.ps-soc-post-thumb.g4{background:conic-gradient(from 210deg,rgba(154,255,0,.34),transparent 45%,#0e1305)}
:root[data-theme="light"] .ps-soc-post-thumb{background:linear-gradient(150deg,rgba(120,200,0,.44),#dcefbf)}
:root[data-theme="light"] .ps-soc-post-thumb svg.i{color:#3c6b00}
.ps-soc-post-b{flex:1;min-width:0}
.ps-soc-post-t{display:block;font-size:12.5px;font-weight:700;line-height:1.35;color:var(--text);overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.ps-soc-post-m{display:flex;gap:10px;margin-top:4px;font-size:10.5px;color:var(--dim);font-weight:600}
.ps-soc-post-m span{display:inline-flex;align-items:center;gap:3px}
.ps-soc-post-m svg.i{width:10px;height:10px;color:var(--accent)}
.ps-soc-post-er{font-family:var(--font-display);font-size:15px;color:var(--accent);letter-spacing:.02em;flex-shrink:0;min-width:44px;text-align:right}
.ps-soc-post-er small{display:block;font-family:var(--font-body);font-size:9px;color:var(--dim);text-transform:uppercase;letter-spacing:.06em;font-weight:600;margin-top:1px}
.ps-soc-post-row.best{border-color:rgba(154,255,0,.35);background:linear-gradient(140deg,var(--surface),rgba(154,255,0,.05))}
.ps-soc-post-row.best::before{content:"Лучший месяца";position:absolute}
.ps-soc-best-badge{position:absolute;top:6px;right:6px;font-size:9px;font-weight:800;padding:2px 6px;border-radius:99px;background:var(--accent);color:#06210a;letter-spacing:.03em}

.ps-soc-post-row{position:relative}

/* ---------- подключение платформы (шит) ---------- */
.ps-soc-conn-body{display:flex;flex-direction:column;gap:12px;padding-bottom:4px}
.ps-soc-conn-h{display:flex;align-items:center;gap:12px;padding:4px 2px 10px;border-bottom:1px solid var(--border)}
.ps-soc-conn-h .ps-soc-plat-ic{width:46px;height:46px;border-radius:12px}
.ps-soc-conn-h .ps-soc-plat-ic svg.i{width:22px;height:22px}
.ps-soc-conn-h b{font-family:var(--font-display);font-size:19px;letter-spacing:.03em}
.ps-soc-conn-h small{display:block;font-size:11.5px;color:var(--dim);margin-top:3px}
.ps-soc-conn-input{display:flex;flex-direction:column;gap:6px}
.ps-soc-conn-input label{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.07em;font-weight:600}
.ps-soc-conn-input input{width:100%;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-sm);padding:12px 14px;color:var(--text);font-size:14px;outline:none;transition:border-color .2s}
.ps-soc-conn-input input:focus{border-color:var(--accent)}
.ps-soc-conn-help{font-size:12px;line-height:1.5;color:var(--dim)}
.ps-soc-conn-help b{color:var(--text);font-weight:700}
.ps-soc-conn-actions{display:flex;gap:8px;padding-top:2px}
.ps-soc-conn-actions .btn{flex:1;padding:12px 8px;font-size:13.5px}

/* ---------- тренды: подсказки под соцсети ---------- */
.ps-soc-trends{display:flex;flex-direction:column;gap:8px}
.ps-soc-trend{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px;display:flex;align-items:flex-start;gap:11px;transition:border-color .2s}
.ps-soc-trend:hover{border-color:var(--accent)}
.ps-soc-trend-ic{width:34px;height:34px;flex-shrink:0;border-radius:10px;background:var(--lime-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center}
.ps-soc-trend-ic svg.i{width:16px;height:16px}
.ps-soc-trend-ic.warn{background:rgba(255,180,60,.16);color:#ffb340}
.ps-soc-trend-ic.up{background:rgba(61,220,90,.16);color:#3ddc5a}
.ps-soc-trend-b{flex:1;min-width:0}
.ps-soc-trend-t{font-size:13px;font-weight:700;line-height:1.35;margin-bottom:3px}
.ps-soc-trend-d{font-size:11.5px;color:var(--dim);line-height:1.45}
.ps-soc-trend-d b{color:var(--text);font-weight:700}

/* ---------- медиа-кит: превью PDF-макета ---------- */
.ps-soc-mediakit{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;display:flex;gap:12px;align-items:center;position:relative;overflow:hidden}
.ps-soc-mediakit::before{content:"";position:absolute;inset:0;background:linear-gradient(120deg,rgba(154,255,0,.10),transparent 55%);opacity:.6;pointer-events:none}
.ps-soc-mk-doc{position:relative;width:66px;height:86px;flex-shrink:0;border-radius:6px;background:linear-gradient(160deg,#0f1706,#070a03);border:1px solid var(--border);display:flex;flex-direction:column;padding:8px 6px 6px;box-shadow:0 4px 14px rgba(0,0,0,.35);overflow:hidden}
:root[data-theme="light"] .ps-soc-mk-doc{background:linear-gradient(160deg,#f7fbec,#e9f2d1);box-shadow:0 4px 12px rgba(60,90,10,.14)}
.ps-soc-mk-doc::after{content:"";position:absolute;right:0;top:0;width:14px;height:14px;background:var(--bg);clip-path:polygon(0 0,100% 100%,100% 0)}
.ps-soc-mk-logo{width:20px;height:20px;color:var(--accent);margin-bottom:5px}
.ps-soc-mk-logo svg.i{width:100%;height:100%}
.ps-soc-mk-lines{display:flex;flex-direction:column;gap:3px;flex:1}
.ps-soc-mk-lines i{display:block;height:3px;border-radius:2px;background:rgba(154,255,0,.32)}
.ps-soc-mk-lines i:nth-child(1){width:80%}
.ps-soc-mk-lines i:nth-child(2){width:60%}
.ps-soc-mk-lines i:nth-child(3){width:70%}
.ps-soc-mk-lines i:nth-child(4){width:45%}
.ps-soc-mk-lines i:nth-child(5){width:65%}
.ps-soc-mk-lines i:nth-child(6){width:50%}
.ps-soc-mk-b{flex:1;min-width:0;position:relative;z-index:1}
.ps-soc-mk-t{font-family:var(--font-display);font-size:15px;letter-spacing:.04em;color:var(--text);margin-bottom:4px}
.ps-soc-mk-d{font-size:11.5px;color:var(--dim);line-height:1.45;margin-bottom:10px}
.ps-soc-mk-btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;font-size:12px;font-weight:700;border-radius:99px;background:var(--accent);color:#06210a;transition:transform .12s,box-shadow .2s;cursor:pointer;border:1px solid var(--accent)}
.ps-soc-mk-btn:hover{box-shadow:0 6px 18px rgba(154,255,0,.24)}
.ps-soc-mk-btn:active{transform:scale(.97)}
.ps-soc-mk-btn svg.i{width:12px;height:12px}
:root[data-theme="light"] .ps-soc-mk-btn{color:#0a2a00}

/* ---------- публичная ссылка + QR ---------- */
.ps-soc-pub{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;display:flex;gap:14px;align-items:center}
.ps-soc-qr{width:96px;height:96px;flex-shrink:0;border-radius:10px;background:#fff;padding:6px;box-shadow:0 4px 14px rgba(0,0,0,.28)}
:root[data-theme="light"] .ps-soc-qr{box-shadow:0 4px 12px rgba(60,90,10,.14);border:1px solid var(--border)}
.ps-soc-qr svg{width:100%;height:100%;display:block}
.ps-soc-pub-b{flex:1;min-width:0}
.ps-soc-pub-lb{font-size:10.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.07em;font-weight:600;margin-bottom:3px}
.ps-soc-pub-url{display:flex;align-items:center;gap:5px;font-family:var(--font-display);font-size:14px;letter-spacing:.02em;color:var(--text);word-break:break-all;line-height:1.25;margin-bottom:9px}
.ps-soc-pub-url svg.i{width:14px;height:14px;color:var(--accent);flex-shrink:0}
.ps-soc-pub-actions{display:flex;gap:6px;flex-wrap:wrap}
.ps-soc-pub-actions button{display:inline-flex;align-items:center;gap:5px;padding:7px 12px;background:var(--raised);border:1px solid var(--border);border-radius:99px;font-size:11.5px;font-weight:700;color:var(--text);cursor:pointer;transition:border-color .2s,color .2s,background .2s}
.ps-soc-pub-actions button:hover{border-color:var(--accent);color:var(--accent)}
.ps-soc-pub-actions button svg.i{width:12px;height:12px;color:var(--accent)}

/* ---------- автопостинг ---------- */
.ps-soc-auto{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px}
.ps-soc-auto-h{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.ps-soc-auto-h .ps-soc-plat-ic{width:36px;height:36px;border-radius:10px;background:var(--lime-dim);color:var(--accent)}
.ps-soc-auto-h .ps-soc-plat-ic svg.i{width:18px;height:18px}
.ps-soc-auto-h b{font-family:var(--font-display);font-size:15px;letter-spacing:.05em;flex:1}
.ps-soc-auto-h button{font-size:11.5px;font-weight:700;padding:7px 12px;border-radius:99px;background:var(--accent);color:#06210a;border:1px solid var(--accent);display:inline-flex;align-items:center;gap:4px;cursor:pointer;transition:transform .12s,box-shadow .2s}
.ps-soc-auto-h button:hover{box-shadow:0 4px 14px rgba(154,255,0,.24)}
.ps-soc-auto-h button:active{transform:scale(.96)}
.ps-soc-auto-h button svg.i{width:11px;height:11px}
.ps-soc-auto-list{display:flex;flex-direction:column;gap:6px}
.ps-soc-auto-row{display:flex;align-items:center;gap:11px;padding:8px 10px;border:1px solid var(--border);border-radius:var(--r-sm);background:var(--raised)}
.ps-soc-auto-time{font-family:var(--font-display);font-size:16px;letter-spacing:.02em;color:var(--accent);width:48px;flex-shrink:0}
.ps-soc-auto-time small{display:block;font-family:var(--font-body);font-size:9.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.06em;font-weight:600;margin-top:1px}
.ps-soc-auto-b{flex:1;min-width:0}
.ps-soc-auto-b span{display:block;font-size:12.5px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-soc-auto-b small{display:block;font-size:10.5px;color:var(--dim);margin-top:2px}
.ps-soc-auto-plats{display:inline-flex;gap:4px;flex-shrink:0}
.ps-soc-auto-plats span{width:20px;height:20px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center}
.ps-soc-auto-plats span svg.i{width:11px;height:11px;color:#fff}
.ps-soc-auto-del{width:26px;height:26px;border-radius:50%;color:var(--dim);display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;transition:color .2s,background .2s;cursor:pointer}
.ps-soc-auto-del:hover{color:#ff6b6b;background:rgba(255,107,107,.1)}
.ps-soc-auto-del svg.i{width:12px;height:12px}
.ps-soc-auto-empty{padding:14px 4px;text-align:center;font-size:12px;color:var(--dim);line-height:1.5}
.ps-soc-auto-empty svg.i{width:22px;height:22px;color:var(--accent);opacity:.6;display:block;margin:0 auto 6px}

/* --- форма планирования поста --- */
.ps-soc-post-body{display:flex;flex-direction:column;gap:14px}
.ps-soc-post-body textarea{width:100%;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-sm);padding:12px 14px;color:var(--text);font:inherit;font-size:14px;outline:none;transition:border-color .2s;resize:vertical;min-height:80px}
.ps-soc-post-body textarea:focus{border-color:var(--accent)}
.ps-soc-post-time-row{display:flex;gap:8px}
.ps-soc-post-time-row input{flex:1;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-sm);padding:12px 14px;color:var(--text);font:inherit;font-size:14px;outline:none;transition:border-color .2s;color-scheme:dark}
:root[data-theme="light"] .ps-soc-post-time-row input{color-scheme:light}
.ps-soc-post-time-row input:focus{border-color:var(--accent)}
.ps-soc-post-plats{display:flex;flex-wrap:wrap;gap:6px}
.ps-soc-post-plats button{display:inline-flex;align-items:center;gap:5px;padding:7px 11px;border-radius:99px;border:1px solid var(--border);background:var(--raised);font-size:11.5px;font-weight:700;color:var(--dim);cursor:pointer;transition:border-color .2s,color .2s,background .2s}
.ps-soc-post-plats button.on{border-color:var(--accent);color:var(--accent);background:var(--lime-dim)}
.ps-soc-post-plats button svg.i{width:11px;height:11px}
.ps-soc-post-plats button .ps-soc-plat-ic{width:16px;height:16px;border-radius:5px}
.ps-soc-post-plats button .ps-soc-plat-ic svg.i{width:9px;height:9px}
.ps-soc-post-plats button.off{opacity:.5;cursor:not-allowed}
.ps-soc-post-actions{display:flex;gap:8px}
.ps-soc-post-actions .btn{flex:1;padding:12px 8px;font-size:13.5px}

/* ---------- ссылки-агрегатор (Linktree) ---------- */
.ps-soc-links{display:flex;flex-direction:column;gap:6px}
.ps-soc-link-row{display:flex;align-items:center;gap:11px;padding:11px 12px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);cursor:pointer;transition:border-color .2s,transform .12s}
.ps-soc-link-row:hover{border-color:var(--accent);transform:translateY(-1px)}
.ps-soc-link-row:active{transform:scale(.99)}
.ps-soc-link-ic{width:36px;height:36px;flex-shrink:0;border-radius:10px;background:var(--lime-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center}
.ps-soc-link-ic svg.i{width:17px;height:17px}
.ps-soc-link-b{flex:1;min-width:0}
.ps-soc-link-b b{display:block;font-size:13px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-soc-link-b small{display:block;font-size:11px;color:var(--dim);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-soc-link-stat{font-size:10.5px;color:var(--dim);font-weight:700;flex-shrink:0;text-align:right}
.ps-soc-link-stat b{color:var(--accent);font-family:var(--font-display);font-size:13px;display:block}
.ps-soc-link-edit{width:28px;height:28px;border-radius:50%;color:var(--dim);display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;transition:color .2s,background .2s}
.ps-soc-link-edit:hover{color:var(--accent);background:var(--lime-dim)}
.ps-soc-link-edit svg.i{width:13px;height:13px}
.ps-soc-link-add{width:100%;padding:11px;border-radius:var(--r-md);border:1px dashed var(--border);background:transparent;color:var(--text);font-size:13px;font-weight:600;cursor:pointer;transition:border-color .2s,color .2s;display:inline-flex;align-items:center;justify-content:center;gap:8px;margin-top:2px}
.ps-soc-link-add:hover{border-color:var(--accent);color:var(--accent)}
.ps-soc-link-add svg.i{width:14px;height:14px}

.ps-soc-link-body{display:flex;flex-direction:column;gap:10px}
.ps-soc-link-body label{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.07em;font-weight:600;margin-bottom:-4px}
.ps-soc-link-body input,.ps-soc-link-body select{width:100%;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-sm);padding:11px 14px;color:var(--text);font:inherit;font-size:14px;outline:none;transition:border-color .2s}
.ps-soc-link-body input:focus,.ps-soc-link-body select:focus{border-color:var(--accent)}
.ps-soc-link-actions{display:flex;gap:8px;padding-top:4px}
.ps-soc-link-actions .btn{flex:1;padding:12px 8px;font-size:13.5px}

/* ---------- утилиты ---------- */
.ps-soc-hint{font-size:12px;color:var(--dim);line-height:1.5;margin:6px 2px 0}
.ps-soc-hint b{color:var(--text)}
.ps-soc-empty-body{padding:14px 8px;text-align:center;color:var(--dim);font-size:12.5px;line-height:1.6}
.ps-soc-empty-body svg.i{width:34px;height:34px;color:var(--accent);opacity:.55;display:block;margin:0 auto 8px}
.ps-soc-inline-ic{display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:5px;vertical-align:-4px;margin-right:2px}
.ps-soc-inline-ic svg.i{width:11px;height:11px;color:#fff}

/* ================================================================
   PP2 · Компактный профиль (Telegram + iOS Settings)
   ---------------------------------------------------------------
   Полностью переопределяет содержимое #screen-profile .pad после
   ядра renderMyProfile и старых чейнов (mp-, ps-soc-). Никаких
   эмодзи — только SVG (#i-*). Обе темы. Свой nav-стек подстраниц.
   ================================================================ */

/* убираем всё, что рисуют предыдущие чейны в шапке своего профиля */
#screen-profile .pad .mp-cover-wrap,
#screen-profile .pad .mp-status-row,
#screen-profile .pad .mp-show-wrap,
#screen-profile .pad .mp-spark-wrap,
#screen-profile .pad .mp-streak-wrap,
#screen-profile .pad .ps-soc-entry-wrap,
#screen-profile .pad .ps-myfollows,
#screen-profile #st2MyCover{display:none!important}

/* контейнер компактного профиля — единственный визуальный ребёнок .pad */
#screen-profile.pp2-on>.pad{padding:0}
.pp2-wrap{padding:14px 16px calc(28px + env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:14px;max-width:640px;margin:0 auto;width:100%}

/* ---------- top-block: аватар + имя + био ---------- */
.pp2-top{display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;padding:14px 8px 6px}
.pp2-ava{width:88px;height:88px;border-radius:50%;background:var(--lime-dim);color:var(--accent);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:34px;letter-spacing:-.02em;background-size:cover;background-position:center;border:2px solid var(--bg);box-shadow:0 6px 22px rgba(0,0,0,.35);position:relative;flex-shrink:0}
:root[data-theme="light"] .pp2-ava{box-shadow:0 6px 18px rgba(60,90,10,.14)}
.pp2-ava.has-photo{color:transparent}
.pp2-name{font-family:var(--font-display),Bebas Neue,Impact,sans-serif;font-size:30px;line-height:1;letter-spacing:.01em;font-weight:700;color:var(--text);margin-top:4px;display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap;justify-content:center}
.pp2-name svg.i{width:18px;height:18px;color:var(--accent)}
.pp2-nick{font-size:13px;color:var(--dim);margin-top:-2px}
.pp2-nick .pp2-online{color:#3ddc5a;font-weight:600}
.pp2-nick .pp2-dot{opacity:.5;margin:0 5px}
.pp2-bio{font-size:13.5px;line-height:1.5;color:var(--text);opacity:.9;max-width:440px;margin:6px auto 0;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis}
.pp2-chips{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin-top:4px}
.pp2-chip{display:inline-flex;align-items:center;gap:5px;font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent);background:var(--lime-dim);border-radius:99px;padding:5px 11px;line-height:1}
.pp2-chip svg.i{width:11px;height:11px}
.pp2-chip.gold{background:linear-gradient(135deg,rgba(255,208,64,.22),rgba(255,170,0,.10));color:#f5c53a;border:1px solid rgba(255,200,60,.28)}
.pp2-chip.owner{background:transparent;border:1px solid var(--border);color:var(--dim)}
.pp2-chip.disc{background:transparent;border:1px dashed var(--border);color:var(--text)}
.pp2-edit{margin:8px auto 0;display:inline-flex;align-items:center;gap:7px;padding:8px 18px;border-radius:99px;border:1px solid var(--border);background:var(--surface);color:var(--text);font-size:13px;font-weight:600;cursor:pointer;transition:border-color .18s,transform .12s,background .18s}
.pp2-edit:hover{border-color:var(--accent);color:var(--accent)}
.pp2-edit:active{transform:scale(.97)}
.pp2-edit svg.i{width:13px;height:13px}

/* ---------- быстрые действия (Telegram-style row) ---------- */
.pp2-quick{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:2px 0 4px}
.pp2-qbtn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:12px 4px;background:var(--surface);border:1px solid var(--border);border-radius:14px;color:var(--text);font-size:10.5px;font-weight:600;cursor:pointer;transition:transform .12s,border-color .18s,background .18s;min-height:64px;position:relative;overflow:hidden}
.pp2-qbtn:hover{border-color:var(--accent);color:var(--accent)}
.pp2-qbtn:active{transform:scale(.96)}
.pp2-qbtn svg.i{width:20px;height:20px;color:var(--accent)}
.pp2-qbtn span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
@media(max-width:360px){.pp2-qbtn{font-size:10px;padding:11px 3px;min-height:58px}.pp2-qbtn svg.i{width:18px;height:18px}}

/* ---------- iOS-style list-group ---------- */
.pp2-group{background:var(--surface);border:1px solid var(--border);border-radius:14px;overflow:hidden;margin:0}
.pp2-group-h{font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--dim);padding:6px 14px 6px;margin:0}
.pp2-row{display:flex;align-items:center;gap:12px;width:100%;padding:12px 14px;background:transparent;color:var(--text);font-size:14.5px;font-weight:500;text-align:left;cursor:pointer;border:0;border-bottom:1px solid var(--border);transition:background .12s}
.pp2-row:last-child{border-bottom:0}
.pp2-row:hover{background:var(--raised)}
.pp2-row:active{background:var(--lime-dim)}
.pp2-row-ic{width:30px;height:30px;border-radius:8px;background:var(--lime-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center;flex-shrink:0}
.pp2-row-ic svg.i{width:16px;height:16px}
.pp2-row-ic.blue{background:rgba(64,158,255,.15);color:#4aa3ff}
.pp2-row-ic.pink{background:rgba(255,86,145,.14);color:#ff6b9a}
.pp2-row-ic.gold{background:rgba(255,196,64,.18);color:#f5c53a}
.pp2-row-ic.violet{background:rgba(148,110,255,.16);color:#a488ff}
.pp2-row-ic.teal{background:rgba(45,200,180,.16);color:#3fd4bf}
.pp2-row-ic.gray{background:var(--raised);color:var(--dim)}
.pp2-row-ic.danger{background:rgba(255,90,90,.14);color:#ff6b6b}
.pp2-row-b{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.pp2-row-t{font-size:14.5px;font-weight:600;color:var(--text);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pp2-row-s{font-size:11.5px;color:var(--dim);line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pp2-row-r{display:inline-flex;align-items:center;gap:8px;flex-shrink:0}
.pp2-row-r .pp2-chip{font-size:9.5px;padding:4px 8px}
.pp2-row-chev{color:var(--dim);display:inline-flex}
.pp2-row-chev svg.i{width:14px;height:14px}
.pp2-row.danger .pp2-row-t{color:#ff6b6b}

/* ---------- отдельная кнопка (типа «Выйти») ---------- */
.pp2-btn-plain{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:14px;background:var(--surface);border:1px solid var(--border);border-radius:14px;color:var(--text);font-size:14.5px;font-weight:700;cursor:pointer;transition:border-color .18s,color .18s}
.pp2-btn-plain.danger{color:#ff6b6b}
.pp2-btn-plain.danger:hover{border-color:#ff6b6b}
.pp2-btn-plain svg.i{width:17px;height:17px}

/* ---------- футер с версией и подписью ---------- */
.pp2-foot{text-align:center;padding:14px 0 4px;color:var(--dim);font-size:11px;line-height:1.55}
.pp2-foot b{color:var(--text);font-weight:700}
.pp2-foot a{color:var(--accent)}

/* ================================================================
   NAV-стек: полноэкранные подстраницы (slide-in справа)
   ================================================================ */
#pp2Nav{position:fixed;inset:0;z-index:67;pointer-events:none}
.pp2-page{position:absolute;inset:0;background:var(--bg);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .28s cubic-bezier(.3,1,.4,1);max-width:1280px;margin:0 auto;padding-left:env(safe-area-inset-left);padding-right:env(safe-area-inset-right);pointer-events:auto;overflow:hidden}
.pp2-page.pp2-in{transform:none}
.pp2-page.pp2-out{transform:translateX(-24%);opacity:.6;filter:brightness(.7)}
@media(prefers-reduced-motion:reduce){.pp2-page{transition:none}}
.pp2-head{display:flex;align-items:center;gap:10px;padding:14px 16px;padding-top:max(14px,env(safe-area-inset-top));border-bottom:1px solid var(--border);flex-shrink:0;background:var(--bg);position:sticky;top:0;z-index:2}
.pp2-back{width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;background:transparent;border:0;color:var(--text);cursor:pointer;padding:0;border-radius:50%;transition:background .15s}
.pp2-back:hover{background:var(--raised)}
.pp2-back svg.i{width:20px;height:20px}
.pp2-title{flex:1;font-size:16px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pp2-head-r{display:inline-flex;gap:6px;flex-shrink:0}
.pp2-head-r button{width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;background:transparent;border:0;color:var(--dim);cursor:pointer;border-radius:50%;transition:color .15s,background .15s}
.pp2-head-r button:hover{color:var(--accent);background:var(--raised)}
.pp2-head-r button svg.i{width:18px;height:18px}
.pp2-body{flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:14px;max-width:640px;width:100%;margin:0 auto}

/* ---------- подстраница «Тарифы OKO» ---------- */
.pp2-tier-hero{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:16px 18px;display:flex;flex-direction:column;gap:6px}
.pp2-tier-hero h3{font-size:20px;font-weight:700;color:var(--text);margin:0}
.pp2-tier-hero p{font-size:12.5px;color:var(--dim);line-height:1.5;margin:0}
.pp2-tier-hero .pp2-chips{justify-content:flex-start;margin-top:6px}
.pp2-tiers{display:flex;flex-direction:column;gap:10px}
.pp2-tier-card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:14px 16px;display:flex;flex-direction:column;gap:8px;position:relative;overflow:hidden;transition:border-color .18s,transform .12s;cursor:pointer}
.pp2-tier-card:hover{border-color:var(--accent);transform:translateY(-1px)}
.pp2-tier-card.on{border-color:var(--accent);background:linear-gradient(180deg,var(--lime-dim),var(--surface))}
.pp2-tier-card .pp2-tier-flag{position:absolute;top:10px;right:12px;font-size:9.5px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#000;background:var(--lime);padding:3px 8px;border-radius:99px}
.pp2-tier-card.free .pp2-tier-flag{background:var(--raised);color:var(--dim)}
.pp2-tier-card.max .pp2-tier-flag{background:linear-gradient(135deg,#ffd664,#ff9800);color:#1a1200}
.pp2-tier-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.pp2-tier-name{font-family:var(--font-display),Bebas Neue,Impact,sans-serif;font-size:24px;letter-spacing:.02em;color:var(--text);line-height:1;font-weight:700}
.pp2-tier-price{font-size:14px;color:var(--accent);font-weight:700}
.pp2-tier-price small{color:var(--dim);font-weight:500;font-size:11px;margin-left:2px}
.pp2-tier-feats{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:5px}
.pp2-tier-feats li{font-size:12.5px;color:var(--text);opacity:.86;line-height:1.4;padding-left:18px;position:relative}
.pp2-tier-feats li::before{content:"";position:absolute;left:2px;top:8px;width:8px;height:8px;border-radius:50%;background:var(--lime-dim);border:1.5px solid var(--accent)}
.pp2-tier-cta{margin-top:6px}
.pp2-tier-cta .btn{padding:11px 14px;font-size:13px}

/* ---------- подстраница «Внешние ссылки» ---------- */
.pp2-links-empty{padding:24px 12px;text-align:center;color:var(--dim);font-size:12.5px;line-height:1.55}
.pp2-links-empty svg.i{width:34px;height:34px;color:var(--accent);opacity:.55;display:block;margin:0 auto 8px}

/* ---------- подстраница «QR / Ссылка» ---------- */
.pp2-qr-wrap{display:flex;flex-direction:column;align-items:center;gap:14px;padding:8px}
.pp2-qr-box{width:220px;height:220px;background:#fff;border-radius:22px;padding:14px;display:flex;align-items:center;justify-content:center;box-shadow:0 12px 34px rgba(0,0,0,.18)}
:root[data-theme="light"] .pp2-qr-box{box-shadow:0 12px 30px rgba(60,90,10,.12);border:1px solid var(--border)}
.pp2-qr-box svg{width:100%;height:100%;display:block}
.pp2-qr-link{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:10px 14px;font-size:13.5px;font-weight:600;color:var(--text);word-break:break-all;text-align:center;width:100%;max-width:360px}
.pp2-qr-actions{display:flex;gap:8px;width:100%;max-width:360px}
.pp2-qr-actions .btn{flex:1;padding:12px 10px;font-size:13px}

/* ---------- подстраница «Устройства» / служебные списки ---------- */
.pp2-item{display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--surface);border:1px solid var(--border);border-radius:12px}
.pp2-item .pp2-row-ic{margin-right:2px}
.pp2-item-b{flex:1;min-width:0}
.pp2-item-b b{display:block;font-size:13.5px;font-weight:700;color:var(--text)}
.pp2-item-b small{display:block;font-size:11.5px;color:var(--dim);margin-top:2px}
.pp2-item .pp2-chip{margin-left:auto}

.pp2-help-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.pp2-help-cards .pp2-row{border-radius:14px;border:1px solid var(--border);flex-direction:column;align-items:flex-start;gap:6px;padding:14px}
.pp2-help-cards .pp2-row-ic{margin-bottom:2px}

/* ---------- статистика профиля (компактно) ---------- */
.pp2-stat-row{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:12px}
.pp2-stat{display:flex;flex-direction:column;align-items:center;gap:3px}
.pp2-stat b{font-family:var(--font-display),Bebas Neue,Impact,sans-serif;font-size:20px;color:var(--text);letter-spacing:.02em;line-height:1}
.pp2-stat small{font-size:10.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.05em;text-align:center;line-height:1.2}

/* «О приложении» — красивая карточка */
.pp2-about{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:20px 18px;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center}
.pp2-about-logo{width:56px;height:56px;border-radius:16px;background:var(--lime-dim);color:var(--accent);display:inline-flex;align-items:center;justify-content:center}
.pp2-about-logo svg.i{width:34px;height:34px}
.pp2-about h4{font-family:var(--font-display),Bebas Neue,Impact,sans-serif;font-size:26px;color:var(--text);letter-spacing:.03em;margin:0}
.pp2-about small{color:var(--dim);font-size:11.5px}
.pp2-about p{font-size:12.5px;color:var(--dim);line-height:1.55;margin:6px 0 0}


/* ===== module: stories-plus ===== */
/* ===== STORIES-PLUS (sp-): редактор сторис, просмотры, реакции, мультисторис ===== */

/* ---------- редактор текст-сторис (fullscreen поверх приложения) ---------- */
#spEditor{position:fixed;inset:0;z-index:66;background:var(--bg);display:flex;flex-direction:column;transform:translateY(102%);transition:transform .3s cubic-bezier(.3,1,.4,1);max-width:640px;margin:0 auto}
#spEditor.open{transform:none}
@media(prefers-reduced-motion:reduce){#spEditor{transition:none}}
.sp-ed-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 16px 8px}
.sp-ed-head b{font-family:var(--font-display);font-size:22px;letter-spacing:.05em}
.sp-ed-ic{width:38px;height:38px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--text);background:var(--surface);border:1px solid var(--border);transition:border-color .2s,transform .15s;flex-shrink:0}
.sp-ed-ic:hover{border-color:var(--accent)}
.sp-ed-ic:active{transform:scale(.92)}
.sp-ed-ic svg.i{width:19px;height:19px}
.sp-ed-stage{flex:1;display:flex;align-items:center;justify-content:center;min-height:0;padding:6px 16px}
.sp-ed-card{position:relative;aspect-ratio:9/16;height:100%;max-height:56dvh;max-width:min(86vw,320px);border-radius:20px;border:1px solid rgba(154,255,0,.28);box-shadow:0 14px 48px rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;overflow:hidden;transition:background .25s ease}
:root[data-theme="light"] .sp-ed-card{box-shadow:0 10px 34px rgba(30,50,0,.22)}
#spEdText{width:100%;max-height:100%;overflow-y:auto;padding:18px 16px;outline:none;font-weight:600;line-height:1.45;word-break:break-word;font-family:var(--font-body)}
#spEdText:empty::before{content:attr(data-ph);color:currentColor;opacity:.45;font-weight:500}
.sp-sz-s #spEdText{font-size:12.5px}
.sp-sz-m #spEdText{font-size:16px}
.sp-sz-l #spEdText{font-size:21px;line-height:1.3}
.sp-al-left #spEdText{text-align:left}
.sp-al-center #spEdText{text-align:center}
.sp-al-right #spEdText{text-align:right}
.sp-ed-sticker{position:absolute;width:34px;height:34px;border-radius:10px;background:rgba(0,0,0,.4);border:1px solid rgba(154,255,0,.55);display:none;align-items:center;justify-content:center;color:#9AFF00;z-index:2;transition:top .2s,left .2s,right .2s,bottom .2s}
.sp-ed-sticker svg.i{width:20px;height:20px}
.sp-ed-card.sp-stk .sp-ed-sticker{display:flex;animation:spPop .25s ease}
@keyframes spPop{from{opacity:0;transform:scale(.55)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.sp-ed-card.sp-stk .sp-ed-sticker{animation:none}}

/* панель инструментов редактора */
.sp-ed-swatches{display:flex;gap:10px;justify-content:center;align-items:center;padding:6px 16px 10px}
.sp-sw{width:34px;height:34px;border-radius:50%;border:2px solid var(--border);cursor:pointer;transition:transform .15s,border-color .15s,box-shadow .15s;flex-shrink:0}
.sp-sw:hover{transform:scale(1.08)}
.sp-sw.on{border-color:var(--lime);transform:scale(1.14);box-shadow:var(--glow)}
:root[data-theme="light"] .sp-sw.on{box-shadow:0 0 12px rgba(110,200,0,.4)}
/* выбор бренд-стикера */
.sp-ed-stickers{display:flex;gap:8px;justify-content:center;align-items:center;padding:0 16px 10px;flex-wrap:wrap}
.sp-stk-pick{width:38px;height:38px;border-radius:12px;background:var(--surface);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--dim);transition:transform .15s,border-color .15s,color .15s;flex-shrink:0}
.sp-stk-pick:hover{transform:scale(1.08);border-color:var(--accent)}
.sp-stk-pick.on{color:var(--accent);border-color:var(--lime);box-shadow:var(--glow)}
:root[data-theme="light"] .sp-stk-pick.on{box-shadow:0 0 10px rgba(110,200,0,.35)}
.sp-stk-pick svg.i{width:19px;height:19px}
.sp-ed-row{display:flex;align-items:center;justify-content:center;gap:10px;padding:0 16px 12px;flex-wrap:wrap}
.sp-seg-group{display:flex;background:var(--surface);border:1px solid var(--border);border-radius:99px;padding:3px;gap:2px}
.sp-seg-group button{width:38px;height:32px;border-radius:99px;display:flex;align-items:center;justify-content:center;color:var(--dim);font-weight:800;transition:background .15s,color .15s}
.sp-seg-group button.on{background:var(--lime-dim);color:var(--accent)}
.sp-seg-group button svg.i{width:17px;height:17px}
.sp-stk-toggle{width:44px;height:38px;border-radius:99px;background:var(--surface);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;color:var(--dim);transition:border-color .15s,color .15s,box-shadow .15s}
.sp-stk-toggle.on{color:var(--accent);border-color:var(--lime);box-shadow:var(--glow)}
:root[data-theme="light"] .sp-stk-toggle.on{box-shadow:none}
.sp-stk-toggle svg.i{width:20px;height:20px}
.sp-ed-pub{margin:0 16px calc(16px + env(safe-area-inset-bottom));padding:14px;font-size:15px}

/* ---------- вьювер: прогресс-сегменты (всегда через модуль → transform-based) ---------- */
/* бар ядра гасим — модуль рисует свой сегментный бар для любого числа историй */
#storyViewer .sv-bar{display:none}
.sp-bars{position:absolute;top:10px;left:50%;transform:translateX(-50%);width:min(calc(100% - 32px),460px);display:flex;gap:5px;z-index:3;pointer-events:none}
.sp-seg{flex:1;height:16px;display:flex;align-items:center;cursor:pointer;background:none;padding:0;pointer-events:auto}
.sp-seg i{display:block;width:100%;height:3px;border-radius:2px;background:rgba(255,255,255,.22);overflow:hidden}
/* заливка — transform:scaleX (не layout): плавно и без reflow */
.sp-seg i b{display:block;height:100%;width:100%;background:#9AFF00;border-radius:2px;transform:scaleX(0);transform-origin:left center;will-change:transform}
.sp-seg.done i b{transform:scaleX(1)}
.sp-seg.act i b{animation:spFill var(--sp-dur,4s) linear forwards}
@keyframes spFill{from{transform:scaleX(0)}to{transform:scaleX(1)}}
#storyViewer.sp-paused .sp-seg.act i b{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){.sp-seg.act i b{animation-duration:.01s}}

/* ---------- вьювер: низ (строка ответа + реакции / счётчик просмотров) ---------- */
.sp-foot{position:absolute;left:0;right:0;bottom:calc(18px + env(safe-area-inset-bottom));display:flex;justify-content:center;z-index:3;pointer-events:none;padding:0 14px}
.sp-eye{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.18);color:#fff;border-radius:99px;padding:9px 16px;font-size:13.5px;font-weight:700;backdrop-filter:blur(6px);pointer-events:auto;transition:transform .15s,border-color .15s;animation:spPop .25s ease}
.sp-eye:hover{border-color:#9AFF00}
.sp-eye:active{transform:scale(.95)}
.sp-eye svg.i{width:17px;height:17px;color:#9AFF00}
.sp-eye svg.i:last-child{width:13px;height:13px;color:#bbb;transform:rotate(90deg)}
/* строка ответа + быстрые реакции (чужие сторис) */
.sp-foot-bar{display:flex;align-items:center;gap:10px;width:min(100%,460px);pointer-events:auto;animation:spPop .25s ease}
.sp-reply{flex:1;display:flex;align-items:center;gap:6px;min-width:0;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.22);border-radius:99px;padding:4px 4px 4px 16px;backdrop-filter:blur(8px);transition:border-color .18s,box-shadow .18s}
.sp-reply:focus-within{border-color:#9AFF00;box-shadow:0 0 0 1px rgba(154,255,0,.4)}
.sp-reply-in{flex:1;min-width:0;background:none;border:none;outline:none;color:#fff;font-size:14px;font-family:var(--font-body);padding:8px 0}
.sp-reply-in::placeholder{color:rgba(255,255,255,.6)}
.sp-reply-send{width:36px;height:36px;flex-shrink:0;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#0b1400;background:#9AFF00;transition:transform .15s,opacity .15s}
.sp-reply-send:active{transform:scale(.9)}
.sp-reply-send svg.i{width:17px;height:17px}
.sp-reacts{display:flex;gap:8px;pointer-events:auto;flex-shrink:0}
.sp-react{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.18);display:flex;align-items:center;justify-content:center;color:#fff;backdrop-filter:blur(6px);transition:transform .15s,border-color .15s,color .15s}
.sp-react:hover{border-color:#9AFF00}
.sp-react:active{transform:scale(1.18)}
.sp-react.on{background:rgba(154,255,0,.18);border-color:#9AFF00;color:#9AFF00}
.sp-react svg.i{width:20px;height:20px}
@media(max-width:360px){.sp-react{width:40px;height:40px}.sp-reacts{gap:6px}}
@media(prefers-reduced-motion:reduce){.sp-eye,.sp-foot-bar{animation:none}}

/* летящая реакция */
.sp-fly{position:fixed;z-index:79;color:#9AFF00;pointer-events:none;opacity:0;animation:spFly 1s ease-out forwards}
.sp-fly svg.i{width:26px;height:26px}
@keyframes spFly{0%{opacity:0;transform:translate(0,10px) scale(.55)}18%{opacity:1}100%{opacity:0;transform:translate(var(--dx,0px),-140px) scale(1.3)}}

/* двойной-тап → крупное сердце в точке касания */
.sp-biglike{position:fixed;z-index:81;transform:translate(-50%,-50%);pointer-events:none;color:#9AFF00;filter:drop-shadow(0 0 16px rgba(154,255,0,.55));animation:spBigLike 1s cubic-bezier(.2,1.2,.4,1) forwards}
.sp-biglike svg.i{width:96px;height:96px}
@keyframes spBigLike{0%{opacity:0;transform:translate(-50%,-50%) scale(.3) rotate(-12deg)}22%{opacity:1;transform:translate(-50%,-50%) scale(1.16) rotate(5deg)}42%{transform:translate(-50%,-50%) scale(.94) rotate(0)}70%{opacity:1;transform:translate(-50%,-55%) scale(1)}100%{opacity:0;transform:translate(-50%,-50%) scale(1.05) translateY(-72px)}}

/* вау-открытие вьювера: подсветка фона + вылет карточки */
#storyViewer.sp-open-anim{animation:spViewerIn .34s ease}
#storyViewer.sp-open-anim .sv-card{animation:spCardIn .46s cubic-bezier(.25,1.1,.4,1)}
@keyframes spViewerIn{from{opacity:.25}to{opacity:1}}
@keyframes spCardIn{0%{opacity:0;transform:translateY(16px) scale(.85)}55%{opacity:1}100%{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){#storyViewer.sp-open-anim,#storyViewer.sp-open-anim .sv-card,.sp-biglike{animation:none}}

/* потяни-вниз-закрыть: чрому вьювера гасим по мере протяжки, карточка едет за пальцем */
#storyViewer.sp-dragging .sv-card{will-change:transform}
#storyViewer.sp-dragging .sp-bars,
#storyViewer.sp-dragging .sp-foot,
#storyViewer.sp-dragging .sv-close{opacity:var(--sp-fade,1)}

/* стикер-глаз OKO в карточке сторис */
.sp-sticker{position:absolute;width:44px;height:44px;border-radius:12px;background:rgba(0,0,0,.42);border:1px solid rgba(154,255,0,.6);display:flex;align-items:center;justify-content:center;color:#9AFF00;box-shadow:0 0 18px rgba(154,255,0,.3);z-index:2;animation:spPop .3s ease}
.sp-sticker svg.i{width:26px;height:26px}
.sp-pos-tl{top:12px;left:12px}
.sp-pos-tr{top:12px;right:12px}
.sp-pos-bl{bottom:12px;left:12px}
.sp-pos-br{bottom:12px;right:12px}
@media(prefers-reduced-motion:reduce){.sp-sticker{animation:none}}

/* счётчик историй на кружке автора в ленте */
.sp-cnt{position:absolute;right:-3px;bottom:-2px;min-width:19px;height:19px;border-radius:10px;background:#000;border:1.5px solid var(--lime);color:var(--lime);font-size:10px;font-weight:800;display:flex;align-items:center;justify-content:center;padding:0 4px;font-style:normal}
:root[data-theme="light"] .sp-cnt{background:#fff;color:var(--accent);border-color:var(--accent)}

/* ---------- шторка «кто посмотрел» (поверх вьювера, z 80 > 76) ---------- */
#spVwWrap{position:fixed;inset:0;z-index:80;background:rgba(0,0,0,.55);display:none;align-items:flex-end;justify-content:center}
#spVwWrap.open{display:flex}
.sp-vw{width:100%;max-width:480px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg) var(--r-lg) 0 0;padding:8px 18px calc(18px + env(safe-area-inset-bottom));max-height:62dvh;overflow-y:auto;animation:spVwUp .28s cubic-bezier(.3,1,.4,1)}
@keyframes spVwUp{from{transform:translateY(55%);opacity:.4}to{transform:none;opacity:1}}
@media(prefers-reduced-motion:reduce){.sp-vw{animation:none}}
.sp-vw-grip{width:38px;height:4px;border-radius:2px;background:var(--border);margin:4px auto 14px}
.sp-vw h3{font-size:20px;display:flex;align-items:center;gap:9px;margin-bottom:8px}
.sp-vw h3 svg.i{width:19px;height:19px;color:var(--accent)}
.sp-vw h3 span{margin-left:auto;font-family:var(--font-display);font-size:23px;color:var(--accent);letter-spacing:.03em}
.sp-vw-item{display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--border);animation:fade .3s ease both}
.sp-vw-item:last-child{border-bottom:none}
.sp-vw-item .ava{width:40px;height:40px;font-size:15px}
.sp-vw-item b{font-size:14px;display:block}
.sp-vw-item small{color:var(--dim);font-size:11.5px;display:block;margin-top:1px}
.sp-vw-re{margin-left:auto;color:var(--accent);display:flex}
.sp-vw-re svg.i{width:18px;height:18px}
.sp-vw-empty{color:var(--dim);font-size:13px;text-align:center;padding:18px 0 10px}

/* ---------- вьювер: экшены сверху (поделиться + звук) ---------- */
.sp-actions{position:absolute;top:34px;right:14px;z-index:5;display:flex;gap:8px;pointer-events:auto}
.sp-act-btn{width:36px;height:36px;border-radius:50%;background:rgba(0,0,0,.42);border:1px solid rgba(255,255,255,.22);color:#fff;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(6px);transition:transform .15s,border-color .15s,color .15s}
.sp-act-btn:hover{border-color:#9AFF00;color:#9AFF00}
.sp-act-btn:active{transform:scale(.9)}
.sp-act-btn svg.i{width:16px;height:16px}
#storyViewer.sp-dragging .sp-actions{opacity:var(--sp-fade,1)}

/* ---------- опрос / викторина в сторис ---------- */
.sp-poll{position:absolute;left:14px;right:14px;bottom:96px;z-index:2;background:rgba(0,0,0,.42);border:1px solid rgba(255,255,255,.18);border-radius:16px;padding:12px 14px;backdrop-filter:blur(10px);animation:spPop .3s ease}
.sp-poll-q{color:#fff;font-size:14px;font-weight:700;text-align:center;margin-bottom:10px;line-height:1.35}
.sp-poll-opts{display:flex;flex-direction:column;gap:6px}
.sp-poll-opt{position:relative;overflow:hidden;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);color:#fff;border-radius:99px;padding:10px 14px;font-size:13.5px;font-weight:600;text-align:left;transition:border-color .15s,background .18s}
.sp-poll-opt:hover{border-color:#9AFF00}
.sp-poll-opt:active{transform:scale(.98)}
.sp-poll-opt .sp-poll-bar{position:absolute;inset:0;background:linear-gradient(90deg,rgba(154,255,0,.35),rgba(154,255,0,.18));border-radius:99px;transform:scaleX(0);transform-origin:left center;transition:transform .55s cubic-bezier(.3,1,.4,1);z-index:0}
.sp-poll-opt .sp-poll-lb,.sp-poll-opt .sp-poll-pc{position:relative;z-index:1;display:inline-flex;align-items:center}
.sp-poll-opt .sp-poll-pc{float:right;color:#9AFF00;font-family:var(--font-display);letter-spacing:.03em;font-size:15px;margin-left:8px}
.sp-poll.voted .sp-poll-opt{cursor:default;pointer-events:none;background:rgba(255,255,255,.06)}
.sp-poll.voted .sp-poll-opt.picked{border-color:#9AFF00;box-shadow:0 0 0 1px rgba(154,255,0,.4)}
.sp-poll.quiz.voted .sp-poll-opt.correct{border-color:#9AFF00;box-shadow:0 0 0 1px rgba(154,255,0,.55);color:#9AFF00}
.sp-poll.quiz.voted .sp-poll-opt.wrong{border-color:#ff5757;box-shadow:0 0 0 1px rgba(255,87,87,.4);color:#ffb3b3}
.sp-poll.quiz.voted .sp-poll-opt.correct .sp-poll-bar{background:linear-gradient(90deg,rgba(154,255,0,.38),rgba(154,255,0,.16))}
.sp-poll.quiz.voted .sp-poll-opt.wrong .sp-poll-bar{background:linear-gradient(90deg,rgba(255,87,87,.28),rgba(255,87,87,.1))}
.sp-poll-mark{display:inline-flex;width:16px;height:16px;margin-right:8px;color:#9AFF00;align-items:center;justify-content:center;opacity:0;transition:opacity .2s}
.sp-poll.voted .sp-poll-opt.picked .sp-poll-mark,
.sp-poll.quiz.voted .sp-poll-opt.correct .sp-poll-mark{opacity:1}
.sp-poll-mark svg.i{width:14px;height:14px}
@media(prefers-reduced-motion:reduce){.sp-poll{animation:none}.sp-poll-opt .sp-poll-bar{transition:none}}

/* ---------- панель быстрых реакций (свайп-вверх) ---------- */
#spQuickReact{position:fixed;left:50%;bottom:calc(96px + env(safe-area-inset-bottom));transform:translate(-50%,120%);z-index:79;display:flex;gap:8px;background:rgba(10,10,10,.72);border:1px solid rgba(255,255,255,.2);border-radius:99px;padding:8px 10px;backdrop-filter:blur(14px);box-shadow:0 12px 40px rgba(0,0,0,.55);pointer-events:none;opacity:0;transition:transform .3s cubic-bezier(.3,1,.4,1),opacity .2s ease}
#spQuickReact.open{transform:translate(-50%,0);opacity:1;pointer-events:auto}
.sp-qr-btn{width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);display:flex;align-items:center;justify-content:center;color:#fff;transition:transform .12s,border-color .15s,color .15s,background .15s}
.sp-qr-btn:hover{border-color:#9AFF00;color:#9AFF00}
.sp-qr-btn:active{transform:scale(1.22)}
.sp-qr-btn svg.i{width:22px;height:22px}
@media(prefers-reduced-motion:reduce){#spQuickReact{transition:opacity .01s}}

/* ---------- видео-сторис (fallback, если st.video задан) ---------- */
.sv-video{width:100%;height:100%;object-fit:cover;display:block;background:#000}
#storyViewer .sv-card.video{text-align:left;padding:0}

/* ===== module: settings-plus ===== */
/* ===== SETTINGS-PLUS (st2-): полноэкранный раздел «Настройки» ===== */

/* вьюха: справа-налево, как psView/editProfile; z 66 — попапы (70) поверх */
#st2View{position:fixed;inset:0;z-index:66;background:var(--bg);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .3s cubic-bezier(.3,1,.4,1);max-width:1280px;margin:0 auto}
#st2View.open{transform:none}
@media(prefers-reduced-motion:reduce){#st2View{transition:none}}
#st2View .sv-body{max-width:640px;width:100%;margin:0 auto}

/* секции-карточки со стаггер-появлением */
.st2-sec{margin-bottom:22px;animation:st2In .45s ease both}
.st2-sec:nth-of-type(2){animation-delay:.045s}
.st2-sec:nth-of-type(3){animation-delay:.09s}
.st2-sec:nth-of-type(4){animation-delay:.135s}
.st2-sec:nth-of-type(5){animation-delay:.18s}
.st2-sec:nth-of-type(6){animation-delay:.225s}
.st2-sec:nth-of-type(7){animation-delay:.27s}
.st2-sec:nth-of-type(8){animation-delay:.315s}
.st2-sec:nth-of-type(9){animation-delay:.36s}
@keyframes st2In{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){.st2-sec{animation:none}}
.st2-h{display:flex;align-items:center;gap:8px;font-family:var(--font-display);font-size:16px;letter-spacing:.09em;color:var(--dim);margin:0 2px 8px;text-transform:uppercase}
.st2-h svg.i{width:15px;height:15px;color:var(--accent)}
.st2-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:2px 14px;transition:border-color .25s,box-shadow .25s}
.st2-card .prow:last-child{border-bottom:none}
.st2-card:hover{border-color:color-mix(in srgb,var(--accent) 34%,var(--border))}

/* строки-настройки: живой ховер/пресс, скруглённая подсветка, ровные иконки */
#st2View .prow{border-radius:12px;padding-left:10px;padding-right:8px;transition:background .18s,transform .12s}
#st2View .prow[onclick]:hover{background:var(--lime-dim)}
#st2View .prow[onclick]:active{transform:scale(.985)}
#st2View .prow>svg.i{flex-shrink:0}

/* красивый switch: плавная пружина, свечение включённого, отклик на нажатие */
#st2View .switch{transition:background .28s cubic-bezier(.3,1.4,.5,1),box-shadow .28s}
#st2View .switch i{transition:left .28s cubic-bezier(.3,1.6,.5,1),background .2s,transform .12s}
#st2View .switch.on{box-shadow:0 0 0 1px var(--lime),0 0 14px rgba(154,255,0,.4)}
:root[data-theme="light"] #st2View .switch.on{box-shadow:0 0 0 1px var(--lime),0 2px 8px rgba(90,150,10,.28)}
#st2View .prow:active .switch i{transform:scale(.9)}
@media(prefers-reduced-motion:reduce){#st2View .switch,#st2View .switch i{transition:none}}

/* значение справа в строке (почта, размер кэша…) */
.st2-card .prow .st2-val{margin-left:auto;color:var(--dim);font-size:12.5px;font-weight:600;max-width:46%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .2s}
.st2-card .prow .st2-val~.chev,.st2-card .prow .st2-val~.switch{margin-left:8px}
.st2-clearing .st2-val{color:var(--accent);font-variant-numeric:tabular-nums}
.st2-chip{font-size:9px;padding:3px 8px;margin-left:8px;flex-shrink:0}
.st2-chip svg.i{width:10px!important;height:10px!important;vertical-align:-1.5px;margin-right:3px;color:var(--accent)}

/* сегмент-переключатель (2 и 3 варианта) */
.st2-seg{display:flex;gap:4px;background:var(--raised);border:1px solid var(--border);border-radius:99px;padding:4px;margin-left:auto;flex-shrink:0}
.st2-seg button{padding:6px 12px;border-radius:99px;font-size:11px;font-weight:700;color:var(--dim);transition:all .2s;white-space:nowrap;position:relative}
.st2-seg button.on{background:var(--lime);color:#000;box-shadow:var(--glow)}
:root[data-theme="light"] .st2-seg button.on{box-shadow:none}
.st2-seg button:active{transform:scale(.95)}
.st2-seg3{width:100%;margin-left:0}
.st2-seg3 button{flex:1;text-align:center;padding:8px 4px}

/* строка настройки в колонку: подпись сверху, сегмент во всю ширину снизу */
.st2-prow-col{flex-direction:column;align-items:stretch;gap:9px}
.st2-prow-col .st2-prow-lbl{display:flex;align-items:center;gap:14px;width:100%;font-size:14.5px;font-weight:500}
.st2-prow-col .st2-prow-lbl svg.i{flex-shrink:0;color:var(--accent)}

/* аккаунты */
.st2-acc{display:flex;align-items:center;gap:12px;padding:11px 4px;border-bottom:1px solid var(--border);border-radius:12px;transition:background .18s}
.st2-acc:last-of-type{border-bottom:none}
.st2-acc-on{background:var(--lime-dim)}
.st2-acc-flash{animation:st2Flash .35s ease}
@keyframes st2Flash{0%{background:var(--lime-dim)}40%{background:color-mix(in srgb,var(--lime) 30%,transparent)}100%{background:var(--lime-dim)}}
.st2-acc-av{width:40px;height:40px;border-radius:12px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-family:var(--font-display);font-size:16px;letter-spacing:.03em;color:#fff;background:linear-gradient(135deg,hsl(var(--h,90) 68% 44%),hsl(var(--h,90) 70% 30%));box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
.st2-acc-b{flex:1;min-width:0}
.st2-acc-b b{display:flex;align-items:center;font-size:14px}
.st2-acc-b small{display:block;color:var(--dim);font-size:11.5px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st2-acc-sw{color:var(--accent);font-size:12px;font-weight:700;padding:7px 14px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--border));border-radius:99px;transition:all .2s;flex-shrink:0}
.st2-acc-sw:hover{background:var(--lime);color:#000;border-color:var(--lime)}
.st2-acc-sw:active{transform:scale(.94)}
.st2-acc-rm{flex-shrink:0;padding:6px;border-radius:9px;color:var(--dim);transition:color .2s,background .2s}
.st2-acc-rm:hover{color:var(--danger);background:color-mix(in srgb,var(--danger) 10%,transparent)}
.st2-acc-rm svg.i{width:15px;height:15px}
.st2-add-acc{color:var(--accent);font-weight:600}
.st2-add-acc>svg.i:first-child{color:var(--accent)}

/* включённый статус-чип (2FA / активный аккаунт) */
.st2-chip-on{color:var(--accent);border:1px solid color-mix(in srgb,var(--accent) 40%,var(--border))}
.st2-chip-on svg.i{color:var(--accent)!important}

/* 2FA: ключ + честная пометка */
.st2-2fa-key{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:15px;letter-spacing:.14em;background:var(--raised);border:1px dashed color-mix(in srgb,var(--accent) 45%,var(--border));border-radius:var(--r-md);padding:13px 10px;text-align:center;color:var(--accent);word-break:break-word;line-height:1.6}
.st2-note{font-size:11.5px;color:var(--dim);line-height:1.55;margin-top:12px;padding:10px 12px;border-radius:var(--r-md);background:color-mix(in srgb,var(--accent) 6%,transparent);border:1px solid var(--border)}
.st2-note b{color:var(--text)}

/* сессии */
.st2-ses{display:flex;align-items:center;gap:12px;padding:13px 4px;border-bottom:1px solid var(--border);transition:opacity .28s,transform .28s}
.st2-ses:last-of-type{border-bottom:none}
.st2-ses.st2-out{opacity:0;transform:translateX(46px)}
.st2-ses-ico{width:38px;height:38px;border-radius:12px;background:var(--raised);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.st2-ses-ico svg.i{width:19px;height:19px;color:var(--accent)}
.st2-ses-b{flex:1;min-width:0}
.st2-ses-b b{display:flex;align-items:center;font-size:13.5px;gap:2px}
.st2-ses-b small{display:block;color:var(--dim);font-size:11px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st2-dot{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 8px var(--lime);display:inline-block;margin-right:6px;animation:st2Pulse 2s infinite;flex-shrink:0}
@keyframes st2Pulse{50%{opacity:.45}}
@media(prefers-reduced-motion:reduce){.st2-dot{animation:none}}
.st2-kill{color:var(--danger);font-size:11px;font-weight:700;padding:7px 11px;border:1px solid rgba(255,80,80,.4);border-radius:99px;transition:all .2s;flex-shrink:0}
.st2-kill:hover{background:var(--danger);color:#fff;border-color:var(--danger)}
.st2-kill:active{transform:scale(.94)}
.st2-killall{display:block;width:100%;text-align:center;color:var(--danger);font-size:12px;font-weight:700;padding:12px 4px;border-top:1px solid var(--border);transition:opacity .2s}
.st2-killall:hover{opacity:.75}
.st2-empty{text-align:center;color:var(--dim);font-size:12px;padding:16px 4px}

/* опасная зона */
.st2-danger{border-color:rgba(255,80,80,.45);padding:16px 14px;background:var(--surface)}
@supports (background:color-mix(in srgb,red 5%,transparent)){
  .st2-danger{background:color-mix(in srgb,var(--danger) 5%,var(--surface))}
}
.st2-danger h4{font-size:14px;font-weight:800;color:var(--danger);display:flex;align-items:center;gap:8px;margin-bottom:6px}
.st2-danger h4 svg.i{width:16px;height:16px}
.st2-danger p{font-size:12px;line-height:1.55;color:var(--dim)}
.st2-del{width:100%;margin-top:13px;background:none;border:1px solid var(--danger);color:var(--danger);border-radius:var(--r-md);padding:12px;font-weight:800;font-size:13.5px;transition:all .2s}
.st2-del:hover{background:var(--danger);color:#fff;box-shadow:0 6px 24px rgba(255,60,60,.3)}
.st2-del:active{transform:scale(.98)}
#okoPopup .btn.st2-btn-danger{background:var(--danger);color:#fff;border-color:var(--danger)}

/* инпут внутри попапа (ник / почта / подтверждение удаления) */
.st2-pin{margin:2px 0}
.st2-pin input{width:100%;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px;font-size:15px;color:var(--text);font-family:inherit;text-align:center}
.st2-pin input:focus{border-color:var(--lime);outline:none}
.st2-perr{color:var(--danger);font-size:12px;font-weight:700;margin-top:9px;animation:st2Shake .35s}
@keyframes st2Shake{0%,100%{transform:none}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}

/* подпись внизу вьюхи */
.st2-foot{text-align:center;color:var(--dim);font-size:10.5px;letter-spacing:.04em;padding:2px 0 8px;opacity:.75}

/* ---------- выход из аккаунта ---------- */
.st2-logout-acc{color:var(--danger)}
.st2-logout-acc>svg.i:first-child{color:var(--danger)}
#st2View .st2-logout-acc[onclick]:hover{background:color-mix(in srgb,var(--danger) 9%,transparent)}

/* ================= ПРОФИЛЬ: аватар-фото + обложка ================= */
/* аватар с загруженным фото (ядро #profAva / #epAva и account-аватары) */
.ava.st2-has-photo,#profAva.st2-has-photo,#epAva.st2-has-photo{background-size:cover!important;background-position:center!important;background-repeat:no-repeat;color:transparent}
#epAva.st2-has-photo{box-shadow:0 6px 22px rgba(0,0,0,.4),var(--glow)}
:root[data-theme="light"] #epAva.st2-has-photo{box-shadow:0 6px 18px rgba(60,90,10,.16)}
.st2-acc-av.has{background-image:none}
.st2-acc-av.has[style*="background-image"]{background-size:cover;background-position:center}
.st2-acc-av.has{color:transparent;font-size:0}

/* собственная обложка над profile-top (#screen-profile) */
.st2-mycover{position:relative;display:block;width:100%;height:120px;margin:0 0 -30px;border-radius:var(--r-lg);overflow:hidden;border:1px solid var(--border);background:var(--surface);background-size:cover;background-position:center;cursor:pointer;transition:border-color .2s,transform .12s;isolation:isolate}
.st2-mycover:hover{border-color:color-mix(in srgb,var(--accent) 40%,var(--border))}
.st2-mycover:active{transform:scale(.995)}
.st2-mycover::before{content:"";position:absolute;inset:0;z-index:0;background:radial-gradient(120% 140% at 12% 0%,rgba(154,255,0,.30),transparent 55%),radial-gradient(90% 120% at 100% 100%,rgba(154,255,0,.14),transparent 60%),linear-gradient(160deg,#0e1305,#070a03)}
.st2-mycover.has::before{background:linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.42))}
:root[data-theme="light"] .st2-mycover::before{background:radial-gradient(120% 140% at 12% 0%,rgba(154,255,0,.34),transparent 55%),radial-gradient(90% 120% at 100% 100%,rgba(120,210,0,.18),transparent 60%),linear-gradient(160deg,#eef7dd,#dcecc6)}
:root[data-theme="light"] .st2-mycover.has::before{background:linear-gradient(180deg,rgba(0,0,0,.02),rgba(0,0,0,.28))}
.st2-mycover-grid{position:absolute;inset:0;z-index:1;opacity:.5;mix-blend-mode:screen;background-image:linear-gradient(rgba(154,255,0,.10) 1px,transparent 1px),linear-gradient(90deg,rgba(154,255,0,.08) 1px,transparent 1px);background-size:26px 26px;-webkit-mask-image:linear-gradient(180deg,#000,transparent);mask-image:linear-gradient(180deg,#000,transparent);pointer-events:none}
.st2-mycover.has .st2-mycover-grid{opacity:0}
:root[data-theme="light"] .st2-mycover-grid{mix-blend-mode:multiply;opacity:.32}
.st2-mycover-mark{position:absolute;left:14px;top:11px;z-index:2;width:30px;height:30px;color:var(--lime);opacity:.24;filter:drop-shadow(0 0 8px rgba(154,255,0,.4));pointer-events:none}
.st2-mycover.has .st2-mycover-mark{color:#fff;opacity:.85;filter:drop-shadow(0 1px 4px rgba(0,0,0,.5))}
.st2-mycover-mark svg.i{width:100%;height:100%}
.st2-mycover-edit{position:absolute;right:10px;top:10px;bottom:auto;z-index:2;display:inline-flex;align-items:center;gap:5px;font-size:10px;font-weight:700;color:var(--text);background:color-mix(in srgb,var(--surface) 82%,transparent);border:1px solid var(--border);border-radius:99px;padding:4px 9px;backdrop-filter:blur(6px);transition:color .2s,border-color .2s}
.st2-mycover.has .st2-mycover-edit{color:#fff;background:rgba(0,0,0,.42);border-color:rgba(255,255,255,.22)}
.st2-mycover:hover .st2-mycover-edit{color:var(--accent);border-color:var(--accent)}
.st2-mycover.has:hover .st2-mycover-edit{color:var(--lime)}
.st2-mycover-edit svg.i{width:13px;height:13px}
/* аватар в profile-top поднимается над обложкой */
#screen-profile .st2-mycover~.profile-top{position:relative;z-index:1}
#screen-profile .st2-mycover~.profile-top .ava{border:3px solid var(--bg);box-shadow:0 4px 16px rgba(0,0,0,.4)}
:root[data-theme="light"] #screen-profile .st2-mycover~.profile-top .ava{box-shadow:0 4px 14px rgba(60,90,10,.14)}

/* контрол обложки в редакторе профиля (#editProfile) */
.ep-cover{position:relative;display:block;width:100%;height:104px;border-radius:var(--r-md);overflow:hidden;border:1px solid var(--border);background:var(--surface);background-size:cover;background-position:center;cursor:pointer;transition:border-color .2s;isolation:isolate}
.ep-cover:hover{border-color:var(--accent)}
.ep-cover::before{content:"";position:absolute;inset:0;z-index:0;background:radial-gradient(120% 140% at 12% 0%,rgba(154,255,0,.28),transparent 55%),linear-gradient(160deg,#0e1305,#070a03)}
.ep-cover.has::before{background:linear-gradient(180deg,rgba(0,0,0,.04),rgba(0,0,0,.4))}
:root[data-theme="light"] .ep-cover::before{background:radial-gradient(120% 140% at 12% 0%,rgba(154,255,0,.32),transparent 55%),linear-gradient(160deg,#eef7dd,#dcecc6)}
.ep-cover-mark{position:absolute;left:12px;top:10px;z-index:2;width:26px;height:26px;color:var(--lime);opacity:.24;pointer-events:none}
.ep-cover.has .ep-cover-mark{color:#fff;opacity:.8}
.ep-cover-mark svg.i{width:100%;height:100%}
.ep-cover-hint{position:absolute;right:11px;bottom:10px;z-index:2;display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:var(--text);background:color-mix(in srgb,var(--surface) 82%,transparent);border:1px solid var(--border);border-radius:99px;padding:5px 11px}
.ep-cover.has .ep-cover-hint{color:#fff;background:rgba(0,0,0,.42);border-color:rgba(255,255,255,.22)}
.ep-cover-hint svg.i{width:13px;height:13px;color:var(--accent)}
.ep-cover.has .ep-cover-hint svg.i{color:var(--lime)}

/* ================= ЧЁРНЫЙ СПИСОК (шит) ================= */
/* над #st2View (z66), но ниже попапов/тоста (z70) */
#sheet-st2-blocked{z-index:68}
body.st2-over #sheetOverlay.open{z-index:67}
.st2-bl-body{max-height:min(64vh,520px);overflow-y:auto;-webkit-overflow-scrolling:touch;margin:2px -4px 0;padding:0 4px}
.st2-bl-cap{font-size:11px;color:var(--dim);text-transform:uppercase;letter-spacing:.06em;font-weight:700;margin:4px 2px 8px}
.st2-bl-list{display:flex;flex-direction:column;gap:4px;margin-bottom:8px}
.st2-bl-row{display:flex;align-items:center;gap:11px;padding:8px 8px;border-radius:var(--r-md);transition:background .15s}
.st2-bl-row:hover{background:var(--surface)}
.st2-bl-av{width:40px;height:40px;flex-shrink:0;border-radius:50%;background:var(--raised);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:15px;color:var(--accent)}
.st2-bl-av svg.i{width:52%;height:52%;color:var(--accent)}
.st2-bl-b{flex:1;min-width:0}
.st2-bl-b b{display:block;font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st2-bl-b small{display:block;font-size:11.5px;color:var(--dim);margin-top:1px}
.st2-bl-un{flex-shrink:0;font-size:11.5px;font-weight:700;color:var(--accent);padding:7px 13px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--border));border-radius:99px;transition:all .2s}
.st2-bl-un:hover{background:var(--lime);color:#000;border-color:var(--lime)}
.st2-bl-un:active{transform:scale(.94)}
.st2-bl-do{flex-shrink:0;display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:700;color:var(--danger);padding:7px 12px;border:1px solid rgba(255,80,80,.4);border-radius:99px;transition:all .2s}
.st2-bl-do svg.i{width:12px;height:12px}
.st2-bl-do:hover{background:var(--danger);color:#fff;border-color:var(--danger)}
.st2-bl-do:hover svg.i{color:#fff}
.st2-bl-do:active{transform:scale(.94)}
.st2-bl-add{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;border:1px dashed var(--border);border-radius:var(--r-md);color:var(--accent);font-size:13.5px;font-weight:700;margin:2px 0 8px;transition:border-color .2s,background .2s}
.st2-bl-add svg.i{width:15px;height:15px;color:var(--accent)}
.st2-bl-add:hover{border-color:var(--accent);background:var(--lime-dim)}
.st2-bl-empty{text-align:center;color:var(--dim);padding:26px 14px 20px}
.st2-bl-empty svg.i{width:38px;height:38px;opacity:.5;margin-bottom:10px;color:var(--danger)}
.st2-bl-empty p{font-weight:700;color:var(--text);font-size:14px}
.st2-bl-empty span{font-size:12px;display:block;margin-top:4px;max-width:280px;margin-left:auto;margin-right:auto;line-height:1.5}

/* ================= ЖИВОЙ ПОИСК ПО НАСТРОЙКАМ ================= */
/* липкая строка поиска: моментально фильтрует секции/строки по названию */
.st2-search{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:9px;background:var(--surface);border:1px solid var(--border);border-radius:99px;padding:0 6px 0 15px;height:44px;margin:0 0 18px;transition:border-color .2s,box-shadow .2s}
/* капот: закрывает контент, уезжающий под липкую строку (padding sv-body) */
.st2-search::before{content:"";position:absolute;left:-18px;right:-18px;top:-22px;height:22px;background:var(--bg);pointer-events:none}
.st2-search:focus-within{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime),0 0 14px rgba(154,255,0,.20)}
:root[data-theme="light"] .st2-search:focus-within{box-shadow:0 0 0 1px var(--lime),0 2px 8px rgba(90,150,10,.16)}
.st2-search-ic{display:flex;flex-shrink:0;color:var(--dim);transition:color .2s}
.st2-search:focus-within .st2-search-ic{color:var(--accent)}
.st2-search-ic svg.i{width:17px;height:17px}
.st2-search input{flex:1;min-width:0;background:none;border:none;outline:none;color:var(--text);font-family:inherit;font-size:14.5px;height:100%;padding:0}
.st2-search input::placeholder{color:var(--dim)}
.st2-search input::-webkit-search-cancel-button,.st2-search input::-webkit-search-decoration{-webkit-appearance:none;display:none}
.st2-search-x{flex-shrink:0;width:32px;height:32px;border-radius:50%;display:none;align-items:center;justify-content:center;color:var(--dim);transition:color .2s,background .2s}
.st2-search.has .st2-search-x{display:flex}
.st2-search-x:hover{color:var(--text);background:var(--raised)}
.st2-search-x:active{transform:scale(.9)}
.st2-search-x svg.i{width:12px;height:12px}
.st2-search-empty{display:none;text-align:center;color:var(--dim);padding:34px 14px 10px}
.st2-search-empty svg.i{width:34px;height:34px;opacity:.5;margin-bottom:10px;color:var(--accent)}
.st2-search-empty p{font-weight:700;color:var(--text);font-size:14px}
.st2-search-empty span{display:block;font-size:12px;margin-top:4px}

/* ================= ТИХИЕ ЧАСЫ / НЕ БЕСПОКОИТЬ ================= */
/* плавно раскрывающийся блок с двумя тайм-пикерами (grid 0fr->1fr) */
.st2-quiet{display:grid;grid-template-rows:0fr;transition:grid-template-rows .32s cubic-bezier(.3,1,.4,1)}
.st2-quiet.open{grid-template-rows:1fr}
.st2-quiet>.st2-quiet-in{overflow:hidden;min-height:0}
@media(prefers-reduced-motion:reduce){.st2-quiet{transition:none}}
.st2-quiet-times{display:flex;align-items:center;gap:10px;padding:6px 2px 2px}
.st2-time{flex:1;display:flex;align-items:center;gap:10px;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);padding:9px 13px;transition:border-color .2s}
.st2-time:focus-within{border-color:var(--lime)}
.st2-time>span{font-size:10.5px;font-weight:700;color:var(--dim);text-transform:uppercase;letter-spacing:.08em}
.st2-time input{flex:1;min-width:0;background:none;border:none;outline:none;color:var(--text);font-family:var(--font-display);font-size:20px;letter-spacing:.04em;color-scheme:dark}
:root[data-theme="light"] .st2-time input{color-scheme:light}
.st2-time input::-webkit-calendar-picker-indicator{opacity:.45;cursor:pointer;transition:opacity .2s;filter:invert(1)}
.st2-time input::-webkit-calendar-picker-indicator:hover{opacity:.9}
:root[data-theme="light"] .st2-time input::-webkit-calendar-picker-indicator{filter:none}
.st2-quiet-arrow{flex-shrink:0;color:var(--dim);opacity:.55;display:flex}
.st2-quiet-arrow svg.i{width:16px;height:16px}
.st2-quiet-note{display:flex;align-items:flex-start;gap:8px;font-size:11.5px;color:var(--dim);line-height:1.5;padding:9px 4px 11px}
.st2-quiet-note svg.i{width:14px;height:14px;flex-shrink:0;margin-top:1px;color:var(--accent)}

/* ================= NAV-STACK: полноэкранные саб-панели ================= */
#st2View .sv-body{position:relative;flex:1;overflow:hidden;padding:0}
.st2-panel{position:absolute;inset:0;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:14px 18px 40px;background:var(--bg);transition:transform .32s cubic-bezier(.3,1,.4,1),opacity .32s ease}
.st2-panel-inner{max-width:640px;width:100%;margin:0 auto}
.st2-panel.st2-in{transform:translateX(100%)}
.st2-panel.st2-out-left{transform:translateX(-24%);opacity:.35;pointer-events:none}
.st2-panel.st2-out-right{transform:translateX(100%);opacity:1;pointer-events:none}
.st2-panel.st2-back-behind{transform:translateX(-24%);opacity:.35;pointer-events:none}
@media(prefers-reduced-motion:reduce){.st2-panel{transition:none}}
#st2Back svg.i{transition:transform .3s cubic-bezier(.3,1,.4,1)}

/* группированные строки как в iOS Settings */
.st2-grouped{display:flex;flex-direction:column;gap:22px}
.st2-grp{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:2px 14px;overflow:hidden;transition:border-color .25s}
.st2-grp:hover{border-color:color-mix(in srgb,var(--accent) 30%,var(--border))}
.st2-grp .prow:last-child{border-bottom:none}
.st2-grp-cap{font-family:var(--font-display);font-size:11.5px;letter-spacing:.14em;color:var(--dim);margin:0 6px 8px;text-transform:uppercase;display:flex;align-items:center;gap:7px}
.st2-grp-cap svg.i{width:13px;height:13px;color:var(--accent)}
.st2-grp .prow{border-radius:12px;padding-left:10px;padding-right:8px;transition:background .18s,transform .12s}
.st2-grp .prow[onclick]:hover{background:var(--lime-dim)}
.st2-grp .prow[onclick]:active{transform:scale(.985)}
.st2-grp .prow>svg.i{flex-shrink:0}

/* пункт-навигатор в корне: иконка в квадратной плашке, как в iOS */
.st2-nav-ico{width:30px;height:30px;flex:none;display:inline-flex;align-items:center;justify-content:center;border-radius:8px;background:var(--raised);border:1px solid var(--border);transition:all .2s}
.st2-nav-ico svg.i{width:17px;height:17px;color:var(--accent)}
.st2-grp .prow[onclick]:hover .st2-nav-ico{background:var(--lime-dim);border-color:transparent}
.st2-nav-ico.st2-nav-danger{background:color-mix(in srgb,var(--danger) 12%,var(--raised))}
.st2-nav-ico.st2-nav-danger svg.i{color:var(--danger)}
.st2-nav-sum{margin-left:auto;color:var(--dim);font-size:12.5px;font-weight:600;max-width:44%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .2s}
.st2-nav-sum.on{color:var(--accent)}
.st2-nav-sum~.chev{margin-left:8px}

/* pie chart для «Данные и хранилище» */
.st2-storage{display:flex;align-items:center;gap:22px;padding:18px 4px}
.st2-pie{width:140px;height:140px;flex:none;filter:drop-shadow(0 3px 14px rgba(154,255,0,.16))}
.st2-pie circle.st2-pie-bg{stroke:var(--raised)}
.st2-pie text.st2-pie-cx{font-family:var(--font-display);font-size:20px;fill:var(--text);letter-spacing:.02em}
.st2-pie text.st2-pie-cu{font-size:9px;font-weight:700;fill:var(--dim);letter-spacing:.14em;text-transform:uppercase}
.st2-pie-anim circle{stroke-dashoffset:0;animation:st2PieDraw .8s ease both}
@keyframes st2PieDraw{from{stroke-dasharray:0 999}}
@media(prefers-reduced-motion:reduce){.st2-pie-anim circle{animation:none}}
.st2-pie-legend{flex:1;min-width:0;display:flex;flex-direction:column;gap:10px}
.st2-pie-row{display:flex;align-items:center;gap:10px;font-size:12.5px;font-weight:600}
.st2-pie-row .st2-pie-dot{width:10px;height:10px;border-radius:3px;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.14) inset}
.st2-pie-row b{margin-left:auto;font-family:ui-monospace,Menlo,Consolas,monospace;font-weight:700;color:var(--text)}

/* range-слайдер (шрифт, лимит кэша) */
.st2-range{display:flex;flex-direction:column;gap:9px;padding:8px 2px}
.st2-range-h{display:flex;align-items:center;gap:9px;font-size:14.5px;font-weight:500}
.st2-range-h svg.i{width:18px;height:18px;color:var(--accent);flex:none}
.st2-range-h .st2-range-v{margin-left:auto;color:var(--accent);font-variant-numeric:tabular-nums;font-weight:700;font-size:13px}
.st2-range input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:6px;background:linear-gradient(90deg,var(--lime) 0 var(--st2-fill,50%),var(--raised) var(--st2-fill,50%) 100%);border-radius:99px;outline:none;border:1px solid var(--border)}
.st2-range input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:22px;height:22px;border-radius:50%;background:var(--lime);border:2px solid var(--bg);box-shadow:0 2px 8px rgba(154,255,0,.4),0 0 0 1px var(--border);cursor:pointer;transition:transform .12s}
.st2-range input[type=range]::-moz-range-thumb{width:22px;height:22px;border-radius:50%;background:var(--lime);border:2px solid var(--bg);box-shadow:0 2px 8px rgba(154,255,0,.4);cursor:pointer}
.st2-range input[type=range]:active::-webkit-slider-thumb{transform:scale(1.15)}
.st2-range-ticks{display:flex;justify-content:space-between;font-size:10.5px;color:var(--dim);padding:0 2px}

/* каналы уведомлений в списке */
.st2-notch{display:flex;align-items:center;gap:12px;padding:12px 2px;border-radius:12px;cursor:pointer;transition:background .18s}
.st2-notch:hover{background:var(--lime-dim)}
.st2-notch-ico{width:34px;height:34px;flex:none;display:flex;align-items:center;justify-content:center;border-radius:9px;background:var(--raised);border:1px solid var(--border)}
.st2-notch-ico svg.i{width:18px;height:18px;color:var(--accent)}
.st2-notch-b{flex:1;min-width:0}
.st2-notch-b b{display:block;font-size:14.5px;font-weight:600}
.st2-notch-b small{display:block;color:var(--dim);font-size:11.5px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st2-notch-state{font-size:11px;font-weight:700;color:var(--dim);text-transform:uppercase;letter-spacing:.06em;padding:4px 10px;border-radius:99px;background:var(--raised);border:1px solid var(--border);flex:none}
.st2-notch-state.on{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 45%,var(--border))}
.st2-notch~.chev{margin-left:8px}

/* auto-download матрица Wi-Fi/mobile */
.st2-dl-grid{display:grid;grid-template-columns:1fr auto auto;gap:6px 12px;align-items:center;padding:10px 4px 4px}
.st2-dl-grid .st2-dl-head{font-family:var(--font-display);font-size:10.5px;letter-spacing:.12em;color:var(--dim);text-transform:uppercase;text-align:center}
.st2-dl-grid .st2-dl-row-h{display:flex;align-items:center;gap:10px;font-size:14px}
.st2-dl-grid .st2-dl-row-h svg.i{width:16px;height:16px;color:var(--accent);flex:none}
.st2-dl-grid .switch{transform:scale(.85)}

/* radio-строка (тема авто-часы, форматы даты) */
.st2-radio{display:flex;align-items:center;gap:12px;padding:11px 2px;cursor:pointer;border-radius:12px;transition:background .18s}
.st2-radio:hover{background:var(--lime-dim)}
.st2-radio-mark{width:20px;height:20px;flex:none;border-radius:50%;border:2px solid var(--border);position:relative;transition:border-color .2s,box-shadow .2s}
.st2-radio.on .st2-radio-mark{border-color:var(--lime);box-shadow:0 0 0 3px rgba(154,255,0,.14)}
.st2-radio-mark::after{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--lime);transform:scale(0);transition:transform .2s cubic-bezier(.3,1.5,.5,1)}
.st2-radio.on .st2-radio-mark::after{transform:scale(1)}
.st2-radio-b{flex:1;min-width:0}
.st2-radio-b b{display:block;font-size:14px;font-weight:600}
.st2-radio-b small{display:block;color:var(--dim);font-size:11.5px;margin-top:2px}
.st2-radio-tag{font-family:var(--font-display);font-size:11px;letter-spacing:.08em;color:var(--dim);padding:3px 9px;border:1px solid var(--border);border-radius:99px;flex:none;text-transform:uppercase}
.st2-radio.on .st2-radio-tag{color:var(--accent);border-color:color-mix(in srgb,var(--accent) 45%,var(--border))}

/* помощь / документы */
.st2-help-hero{background:linear-gradient(135deg,rgba(154,255,0,.14),transparent 60%),var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:18px 16px;margin-bottom:16px}
.st2-help-hero h4{font-family:var(--font-display);font-size:22px;letter-spacing:.02em;margin:0 0 6px;display:flex;align-items:center;gap:9px}
.st2-help-hero h4 svg.i{width:22px;height:22px;color:var(--accent)}
.st2-help-hero p{font-size:12.5px;color:var(--dim);line-height:1.55}
.st2-help-btn{margin-top:12px;display:inline-flex;align-items:center;gap:7px;font-size:12.5px;font-weight:700;color:#000;background:var(--lime);padding:9px 14px;border-radius:99px;box-shadow:var(--glow);transition:transform .12s}
.st2-help-btn:active{transform:scale(.96)}
:root[data-theme="light"] .st2-help-btn{box-shadow:none}
.st2-help-btn svg.i{width:13px;height:13px}

.st2-faq{margin:0}
.st2-faq details{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:8px;overflow:hidden;transition:border-color .2s}
.st2-faq details[open]{border-color:color-mix(in srgb,var(--accent) 40%,var(--border))}
.st2-faq summary{list-style:none;padding:13px 14px;cursor:pointer;display:flex;align-items:center;gap:10px;font-size:13.5px;font-weight:600;transition:background .18s}
.st2-faq summary::-webkit-details-marker{display:none}
.st2-faq summary::after{content:"";width:8px;height:8px;border-right:2px solid var(--dim);border-bottom:2px solid var(--dim);transform:rotate(-45deg);margin-left:auto;transition:transform .25s,border-color .2s}
.st2-faq details[open] summary::after{transform:rotate(45deg);border-color:var(--accent)}
.st2-faq summary:hover{background:var(--lime-dim)}
.st2-faq-body{padding:0 14px 14px;color:var(--dim);font-size:12.5px;line-height:1.6}
.st2-faq-body b{color:var(--text)}

/* удаление с задержкой */
.st2-del-status{margin-top:12px;padding:12px 14px;background:color-mix(in srgb,var(--danger) 8%,transparent);border:1px solid color-mix(in srgb,var(--danger) 40%,var(--border));border-radius:var(--r-md);font-size:12px;line-height:1.55;color:var(--danger)}
.st2-del-status b{display:block;font-family:var(--font-display);font-size:14px;letter-spacing:.06em;margin-bottom:4px}
.st2-del-status .st2-del-cancel{display:block;width:100%;margin-top:10px;background:var(--surface);border:1px solid var(--border);color:var(--text);padding:9px;border-radius:var(--r-md);font-weight:700;font-size:13px;transition:background .18s}
.st2-del-status .st2-del-cancel:hover{background:var(--lime-dim)}

/* поисковой результат: чип с секцией */
.st2-search-res{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-lg);padding:2px 14px;margin-top:12px}
.st2-search-res .prow{border-radius:12px;padding-left:10px;padding-right:8px;transition:background .18s}
.st2-search-res .prow:hover{background:var(--lime-dim)}
.st2-search-res-tag{margin-left:auto;font-size:10.5px;font-weight:700;color:var(--accent);padding:3px 9px;border-radius:99px;border:1px solid color-mix(in srgb,var(--accent) 40%,var(--border));text-transform:uppercase;letter-spacing:.06em}
.st2-search-res-tag~.chev{margin-left:8px}

/* заголовок под-панели */
.st2-panel-h{font-family:var(--font-display);font-size:12px;letter-spacing:.14em;color:var(--dim);text-transform:uppercase;margin:6px 6px 10px;display:flex;align-items:center;gap:7px}
.st2-panel-h svg.i{width:13px;height:13px;color:var(--accent)}
.st2-panel-desc{color:var(--dim);font-size:12.5px;line-height:1.55;margin:0 6px 14px}
.st2-panel-sec{margin-bottom:22px}
.st2-panel-sec:last-child{margin-bottom:0}

/* ================= A11Y: применение флагов к корню ================= */
:root.st2-a-motion *,:root.st2-a-motion *::before,:root.st2-a-motion *::after{animation-duration:.001ms!important;transition-duration:.001ms!important;animation-iteration-count:1!important}
:root.st2-a-contrast{--dim:#c9d2df;--border:#3d4757}
:root[data-theme="light"].st2-a-contrast{--dim:#212936;--border:#7f8ea3;--text:#000}
:root.st2-a-opacity{--glass-opacity:1}
:root.st2-a-opacity .glass,:root.st2-a-opacity [class*="blur"]{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}
:root.st2-a-tap .prow{min-height:56px}
:root.st2-a-tap .switch{transform:scale(1.15)}
:root.st2-a-tap button,:root.st2-a-tap .chip{min-height:40px}



/* ===== module: notifs-plus ===== */
/* ===== NOTIFS-PLUS: центр уведомлений уровня TG + iOS/Android system =====
   Префиксы: np-, nt-. Не трогает base.html — только chain-патчи ядра.
   Механики:
     1) Категории-чипы: Всё / Чаты / Партнёрка / Игры / Академия / Система
     2) Группировка одинаковых (5 новых лайков → тап раскрывает список)
     3) Inline-действия: Ответить (textarea), Принять/Отклонить, Оплатить, Открыть
     4) Свайпы: влево → Отклонить (danger), вправо → Прочитано (accent)
     5) Live-toast стек сверху экрана (slide-in-out 4s, до 3, крестик «закрыть все»)
     6) Расписание "Не беспокоить" (22:00–08:00) с иконкой луны
     7) Приоритеты: Все / Только важные / Тишина — bell-иконка меняется
     8) Бейдж с числом непрочитанных (>99 → «99+»)
     9) Настройки каналов (звук/вибро/превью/бейдж) с localStorage-persist
    10) Демо-поток: реалистичные примеры «5 мин назад», разные авторы */

/* ------------------------------------------------------------------ */
/*  Шапка экрана: DND, приоритет, настройки                            */
/* ------------------------------------------------------------------ */
.np-headx{display:inline-flex;align-items:center;gap:6px}
.np-hb{
  width:36px;height:36px;border-radius:10px;
  display:inline-flex;align-items:center;justify-content:center;
  background:transparent;border:1px solid transparent;
  transition:background .18s,border-color .18s,color .18s,transform .12s;
  color:var(--dim);
}
.np-hb svg.i{width:20px;height:20px;transition:color .18s,filter .18s;color:inherit}
.np-hb:hover{background:var(--lime-dim)}
.np-hb:active{transform:scale(.94)}
.np-hb.on{background:var(--lime-dim);border-color:var(--lime);color:var(--accent)}
.np-hb.on svg.i{filter:drop-shadow(0 0 5px rgba(154,255,0,.55))}
.np-hb.danger.on{background:rgba(255,77,77,.12);border-color:var(--danger);color:var(--danger)}
.np-hb.danger.on svg.i{filter:drop-shadow(0 0 5px rgba(255,77,77,.5))}

/* ------------------------------------------------------------------ */
/*  Чипы фильтра                                                       */
/* ------------------------------------------------------------------ */
.np-chips{
  display:flex;gap:8px;overflow-x:auto;overflow-y:hidden;
  padding:10px 18px 12px;border-bottom:1px solid var(--border);
  flex-shrink:0;background:var(--bg);scrollbar-width:none;
}
.np-chips::-webkit-scrollbar{display:none}
.np-chip{
  padding:7px 14px;border-radius:100px;
  background:var(--surface);border:1px solid var(--border);
  color:var(--dim);font-size:12.5px;font-weight:600;
  white-space:nowrap;flex-shrink:0;opacity:.75;position:relative;
  transition:background .18s,color .18s,opacity .18s,border-color .18s,transform .12s;
  font-family:var(--font-body);
}
.np-chip.on{background:var(--lime);color:#0a0a0a;border-color:var(--lime);opacity:1}
.np-chip:active{transform:scale(.97)}
.np-chip .np-chip-c{
  display:inline-block;margin-left:6px;font-size:10.5px;font-weight:800;
  padding:1px 6px;border-radius:99px;background:rgba(0,0,0,.18);color:inherit;
  min-width:16px;text-align:center;
}
.np-chip:not(.on) .np-chip-c{background:var(--raised);color:var(--accent)}

/* Плашка «тихий режим» / «расписание» — над чипами */
.np-modehint{
  padding:8px 18px;font-size:11.5px;font-weight:600;
  color:var(--accent);background:var(--lime-dim);
  border-bottom:1px solid var(--border);
  display:none;align-items:center;gap:8px;flex-shrink:0;
}
.np-modehint svg.i{width:14px;height:14px;flex-shrink:0}
#notifsView.np-hint-on .np-modehint{display:flex}
#notifsView.np-mode-silent .np-modehint{color:var(--danger);background:rgba(255,77,77,.1)}

/* ------------------------------------------------------------------ */
/*  Строка (row) уведомления: обёртка со свайпом                       */
/* ------------------------------------------------------------------ */
.np-row{position:relative;border-radius:var(--r-md);overflow:hidden;margin:2px 0;isolation:isolate}
.np-swipe{
  position:relative;background:var(--bg);
  transition:transform .28s cubic-bezier(.3,1,.4,1);
  will-change:transform;touch-action:pan-y;z-index:1;
}
.np-row.np-open .np-swipe{transform:translateX(-140px)}
.np-row.np-open-r .np-swipe{transform:translateX(140px)}

/* левый край (за свайпом влево) — Отклонить */
.np-actions{position:absolute;top:0;right:0;bottom:0;width:140px;display:flex;pointer-events:none;z-index:0}
.np-row.np-open .np-actions{pointer-events:auto}
.np-act{
  flex:1;display:flex;align-items:center;justify-content:center;gap:6px;
  font-size:12px;font-weight:700;color:#fff;user-select:none;
  text-align:center;padding:0 6px;cursor:pointer;letter-spacing:.01em;
  font-family:var(--font-body);white-space:nowrap;
}
.np-act svg.i{width:14px;height:14px;color:#fff}
.np-act.del{background:#e64545}
.np-act:active{opacity:.85}

/* правый край (за свайпом вправо) — Прочитано */
.np-actions-r{position:absolute;top:0;left:0;bottom:0;width:140px;display:flex;pointer-events:none;z-index:0}
.np-row.np-open-r .np-actions-r{pointer-events:auto}
.np-act.read{background:#37a0ff}

/* ------------------------------------------------------------------ */
/*  Inline quick-actions под текстом уведомления                       */
/* ------------------------------------------------------------------ */
.np-quick{display:inline-flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center}
.np-q{
  display:inline-flex;align-items:center;gap:5px;
  padding:6px 12px;border-radius:100px;
  background:var(--lime-dim);color:var(--accent);
  font-size:11.5px;font-weight:700;border:1px solid var(--border);
  cursor:pointer;white-space:nowrap;letter-spacing:.01em;
  transition:background .16s,color .16s,border-color .16s,transform .12s;
  font-family:var(--font-body);
}
.np-q svg.i{width:12px;height:12px}
.np-q:hover{background:var(--lime);color:#0a0a0a;border-color:var(--lime)}
.np-q:active{transform:scale(.96)}
.np-q.ghost{background:transparent;color:var(--dim);border-color:var(--border)}
.np-q.ghost:hover{background:var(--surface);color:var(--text)}
.np-q.danger{background:rgba(255,77,77,.1);color:var(--danger);border-color:rgba(255,77,77,.35)}
.np-q.danger:hover{background:var(--danger);color:#fff;border-color:var(--danger)}
.np-q.primary{background:var(--lime);color:#0a0a0a;border-color:var(--lime)}
.np-q.primary:hover{filter:brightness(1.05)}

/* Inline reply area */
.np-reply{
  display:none;margin-top:10px;padding:10px 12px;
  border-radius:var(--r-md);background:var(--surface);border:1px solid var(--border);
  gap:8px;flex-direction:column;
}
.np-row.np-reply-on .np-reply{display:flex}
.np-reply textarea{
  width:100%;min-height:56px;resize:none;border:none;
  background:transparent;color:var(--text);font-family:var(--font-body);font-size:13px;
  line-height:1.4;padding:0;outline:none;
}
.np-reply textarea::placeholder{color:var(--dim)}
.np-reply .np-reply-row{display:flex;gap:6px;justify-content:flex-end}

/* ------------------------------------------------------------------ */
/*  Группировка (стек одинаковых уведомлений — iOS-стиль)              */
/* ------------------------------------------------------------------ */
.np-stack{position:relative}
.np-stack .np-swipe{
  box-shadow:0 -6px 0 -3px var(--raised), 0 -12px 0 -6px var(--surface);
  border-radius:var(--r-md);
}
.np-stack .np-stack-more{
  display:inline-flex;align-items:center;gap:4px;
  margin-left:6px;padding:2px 8px;border-radius:99px;
  background:var(--lime-dim);color:var(--accent);
  font-size:10.5px;font-weight:800;letter-spacing:.02em;
  vertical-align:middle;
}
.np-stack.np-expanded .np-swipe{box-shadow:none}
.np-substack{display:none;padding:0 0 4px 12px;border-left:2px solid var(--lime-dim);margin-left:22px}
.np-stack.np-expanded + .np-substack{display:block}
.np-substack .np-row{margin:4px 0}
.np-substack .nt-item{padding:8px 10px}
.np-substack .nt-ic,.np-substack .nt-ava{width:32px;height:32px}
.np-substack .nt-ic svg.i{width:16px;height:16px}
.np-substack .nt-b span{font-size:12.5px}
.np-substack .nt-b small{font-size:10.5px}

/* ------------------------------------------------------------------ */
/*  Анимация появления новых уведомлений                               */
/* ------------------------------------------------------------------ */
.np-bounce{animation:npBounce .7s cubic-bezier(.3,1.5,.4,1)}
@keyframes npBounce{
  0%{transform:translateY(-14px);opacity:0}
  55%{transform:translateY(3px);opacity:1}
  100%{transform:none;opacity:1}
}

/* ------------------------------------------------------------------ */
/*  Бейдж-счётчик в шапке приложения (поверх notif-dot из base)        */
/* ------------------------------------------------------------------ */
.notif-dot.np-count{
  top:2px;right:2px;
  width:auto;height:16px;min-width:16px;
  padding:0 5px;border-radius:99px;
  background:var(--danger);border:1.5px solid var(--surface);
  color:#fff;font-family:var(--font-body);font-size:10px;font-weight:800;
  line-height:14px;letter-spacing:0;text-align:center;
  display:none;box-shadow:0 2px 6px rgba(230,69,69,.4);
}
.notif-dot.np-count.on{display:inline-block}
.notif-dot.np-count.np-only-imp{background:var(--accent);color:#0a0a0a;box-shadow:0 2px 6px rgba(154,255,0,.35)}
.notif-dot.np-count.np-silent{background:var(--dim);color:var(--bg);box-shadow:none}
/* иконка колокольчика при разных приоритетах */
.notif-btn.np-mode-silent svg.i{opacity:.6}
.notif-btn.np-mode-important svg.i{color:var(--accent);filter:drop-shadow(0 0 4px rgba(154,255,0,.4))}

/* ------------------------------------------------------------------ */
/*  Панель настроек (внутри экрана уведомлений, слайд сверху)          */
/* ------------------------------------------------------------------ */
.np-settings{
  display:none;flex-direction:column;gap:12px;
  padding:16px 18px;border-bottom:1px solid var(--border);
  background:linear-gradient(180deg,var(--surface),var(--bg));
  flex-shrink:0;animation:npSlide .28s cubic-bezier(.3,1,.4,1);
}
#notifsView.np-settings-on .np-settings{display:flex}
@keyframes npSlide{from{transform:translateY(-8px);opacity:0}to{transform:none;opacity:1}}
.np-sec-title{
  font-size:10.5px;font-weight:800;color:var(--dim);
  text-transform:uppercase;letter-spacing:.08em;margin:2px 0 -4px;
}
.np-seg{
  display:flex;background:var(--raised);border-radius:100px;padding:3px;
  border:1px solid var(--border);
}
.np-seg button{
  flex:1;padding:8px 10px;font-size:11.5px;font-weight:700;
  border-radius:99px;color:var(--dim);letter-spacing:.01em;
  transition:background .18s,color .18s,transform .12s;font-family:var(--font-body);
  display:inline-flex;align-items:center;justify-content:center;gap:5px;
}
.np-seg button svg.i{width:12px;height:12px}
.np-seg button.on{background:var(--lime);color:#0a0a0a;box-shadow:0 1px 4px rgba(154,255,0,.35)}
.np-seg button.on.danger{background:var(--danger);color:#fff;box-shadow:0 1px 4px rgba(230,69,69,.4)}
.np-seg button.on.warn{background:#ffcf33;color:#0a0a0a;box-shadow:0 1px 4px rgba(255,207,51,.4)}
.np-seg button:active{transform:scale(.97)}

.np-dnd-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.np-dnd-times{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dim);font-weight:600}
.np-dnd-times input[type="time"]{
  background:var(--raised);color:var(--text);border:1px solid var(--border);
  border-radius:8px;padding:5px 8px;font-family:var(--font-body);font-size:12px;
  color-scheme:dark;
}
:root[data-theme="light"] .np-dnd-times input[type="time"]{color-scheme:light}

.np-toggles{display:flex;flex-direction:column;gap:8px}
.np-toggle{
  display:flex;align-items:center;justify-content:space-between;
  padding:10px 12px;border-radius:var(--r-md);
  background:var(--raised);border:1px solid var(--border);
}
.np-toggle-l{display:flex;align-items:center;gap:10px;min-width:0;flex:1}
.np-toggle-l svg.i{width:16px;height:16px;color:var(--dim);flex-shrink:0}
.np-toggle-t{display:flex;flex-direction:column;min-width:0}
.np-toggle-t b{font-size:12.5px;font-weight:700;color:var(--text);letter-spacing:.005em}
.np-toggle-t small{font-size:10.5px;color:var(--dim);font-weight:500}
.np-sw{
  position:relative;width:38px;height:22px;border-radius:99px;
  background:var(--surface);border:1px solid var(--border);
  cursor:pointer;flex-shrink:0;transition:background .2s,border-color .2s;
}
.np-sw::after{
  content:'';position:absolute;top:2px;left:2px;
  width:16px;height:16px;border-radius:50%;background:var(--dim);
  transition:transform .22s cubic-bezier(.3,1.5,.4,1),background .2s;
}
.np-sw.on{background:var(--lime);border-color:var(--lime)}
.np-sw.on::after{transform:translateX(16px);background:#0a0a0a}

/* ------------------------------------------------------------------ */
/*  Live-toast стек (в реальном времени, поверх всего)                 */
/* ------------------------------------------------------------------ */
#np-live-stack{
  position:fixed;left:50%;transform:translateX(-50%);
  top:max(12px, env(safe-area-inset-top));
  z-index:9200;pointer-events:none;
  display:flex;flex-direction:column;gap:8px;align-items:center;
  width:min(96%, 420px);
}
.np-live{
  pointer-events:auto;width:100%;
  background:var(--surface);border:1px solid var(--border);
  border-radius:var(--r-md);padding:11px 12px 11px 12px;
  box-shadow:0 10px 30px rgba(0,0,0,.35),0 0 0 1px rgba(154,255,0,.05);
  display:flex;align-items:center;gap:11px;
  transform:translateY(-24px);opacity:0;
  transition:transform .3s cubic-bezier(.3,1.5,.4,1),opacity .22s;
  cursor:pointer;position:relative;
}
.np-live.show{transform:none;opacity:1}
.np-live.hide{transform:translateY(-24px);opacity:0}
.np-live-ic{
  width:36px;height:36px;border-radius:11px;
  background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;
  border:1px solid var(--border);
}
.np-live-ic svg.i{width:18px;height:18px}
.np-live-ic.tone-heart{background:rgba(255,90,122,.12);color:#ff5a7a;border-color:rgba(255,90,122,.3)}
.np-live-ic.tone-star{background:rgba(255,207,51,.15);color:#ffcf33;border-color:rgba(255,207,51,.35)}
.np-live-ic.tone-comment{background:rgba(55,160,255,.13);color:#37a0ff;border-color:rgba(55,160,255,.3)}
.np-live-ic.tone-money{background:rgba(154,255,0,.14);color:var(--accent);border-color:var(--lime)}
.np-live-b{flex:1;min-width:0}
.np-live-b b{display:block;font-size:12.5px;font-weight:700;color:var(--text);line-height:1.25;letter-spacing:.005em;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np-live-b span{display:block;font-size:11.5px;color:var(--dim);line-height:1.35;margin-top:2px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np-live-x{
  width:24px;height:24px;border-radius:8px;
  display:inline-flex;align-items:center;justify-content:center;
  color:var(--dim);flex-shrink:0;transition:background .18s,color .18s;
}
.np-live-x svg.i{width:12px;height:12px}
.np-live-x:hover{background:var(--raised);color:var(--text)}

.np-live-all{
  pointer-events:auto;font-size:10.5px;font-weight:700;
  color:var(--dim);background:var(--surface);
  padding:4px 10px;border-radius:99px;border:1px solid var(--border);
  cursor:pointer;letter-spacing:.02em;text-transform:uppercase;
  transition:background .18s,color .18s,transform .12s;
}
.np-live-all:hover{background:var(--raised);color:var(--text)}
.np-live-all:active{transform:scale(.96)}

/* ------------------------------------------------------------------ */
/*  Пустое состояние                                                   */
/* ------------------------------------------------------------------ */
.np-empty{padding:36px 22px;text-align:center;color:var(--dim);font-size:13px;line-height:1.55}
.np-empty svg.i{width:44px;height:44px;color:var(--accent);opacity:.5;margin-bottom:10px}
.np-empty b{display:block;font-size:15px;font-weight:700;color:var(--text);margin-bottom:6px}

/* ------------------------------------------------------------------ */
/*  Светлая тема — точечные правки                                     */
/* ------------------------------------------------------------------ */
:root[data-theme="light"] .np-swipe{background:var(--bg)}
:root[data-theme="light"] .np-chips{background:var(--bg)}
:root[data-theme="light"] .np-live{box-shadow:0 10px 30px rgba(0,40,10,.09),0 0 0 1px rgba(154,255,0,.06)}
:root[data-theme="light"] .notif-dot.np-count.np-silent{color:#fff}

/* ===== module: tour ===== */
/* ===== TOUR (tr-) — интерактивный тур: мягкий спотлайт + карточки-подсказки ===== */
#trOverlay{position:fixed;inset:0;z-index:65;opacity:0;transition:opacity .34s ease;
  overscroll-behavior:contain;-webkit-tap-highlight-color:transparent}
#trOverlay.tr-on{opacity:1}

/* --- мягкий спотлайт: прозрачная «дыра», тьма — гигантским РАЗМЫТЫМ box-shadow --- */
/* blur-радиус 26px даёт feather-край (плавный переход тьма→элемент), а не резкий вырез.
   translateZ(0) изолирует слой компоновки: дыра репейнтится в свой слой, а не всю страницу. */
.tr-hole{position:absolute;border-radius:16px;pointer-events:none;
  box-shadow:0 0 26px 200vmax rgba(0,0,0,.76);
  transform:translateZ(0);
  will-change:top,left,width,height;
  transition:top .5s cubic-bezier(.4,.82,.24,1),left .5s cubic-bezier(.4,.82,.24,1),
             width .5s cubic-bezier(.4,.82,.24,1),height .5s cubic-bezier(.4,.82,.24,1),
             border-radius .5s ease}
.tr-hole.tr-jump{transition:none}
/* мягкая лаймовая аура вокруг спотлайта — глубина, бренд-акцент (статична, без анимации) */
.tr-hole::before{content:'';position:absolute;inset:-10px;border-radius:inherit;pointer-events:none;
  box-shadow:0 0 44px 4px rgba(154,255,0,.12)}
/* точный лаймовый контур + дышащая пульсация.
   ВАЖНО (перф): пульсируем ТОЛЬКО opacity (композитится на GPU, ноль per-frame repaint),
   box-shadow/border статичны — прежняя анимация box-shadow репейнтила контур каждый кадр. */
.tr-hole::after{content:'';position:absolute;inset:-3px;border:2px solid var(--lime);
  border-radius:inherit;pointer-events:none;
  box-shadow:0 0 22px rgba(154,255,0,.55),inset 0 0 14px rgba(154,255,0,.2);
  will-change:opacity;animation:trPulse 2.4s ease-in-out infinite}
@keyframes trPulse{0%,100%{opacity:1}50%{opacity:.45}}

/* --- карточка шага --- */
.tr-card{position:absolute;left:50%;transform:translateX(-50%) translateZ(0);width:calc(100% - 28px);
  max-width:352px;background:var(--surface);border:1px solid var(--border);
  border-radius:var(--r-lg);padding:16px 16px 13px;overflow:hidden;
  box-shadow:0 20px 64px rgba(0,0,0,.58),0 0 0 1px rgba(154,255,0,.06);
  will-change:top;transition:top .5s cubic-bezier(.4,.82,.24,1)}
.tr-card.tr-jump{transition:none}
/* тонкая лаймовая grad-полоса сверху карточки */
.tr-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;
  background:linear-gradient(90deg,transparent,var(--lime),transparent);opacity:.55}
.tr-arr{position:absolute;width:14px;height:14px;background:var(--surface);transform:rotate(45deg);
  transition:left .5s cubic-bezier(.4,.82,.24,1)}
.tr-arr.up{top:-8px;border-left:1px solid var(--border);border-top:1px solid var(--border)}
.tr-arr.down{bottom:-8px;border-right:1px solid var(--border);border-bottom:1px solid var(--border)}
.tr-arr.hide{display:none}

.tr-body{animation:trIn .38s cubic-bezier(.3,.9,.3,1) both}
@keyframes trIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.tr-step-chip{display:inline-flex;align-items:center;gap:7px;font-size:9.5px;font-weight:700;
  letter-spacing:.14em;text-transform:uppercase;color:var(--lime);margin-bottom:7px}
.tr-step-chip svg.i{width:13px;height:13px}
.tr-card h3{font-family:var(--font-display);font-size:23px;letter-spacing:.02em;line-height:1;margin:0 0 6px;overflow-wrap:break-word}
.tr-card p{color:var(--dim);font-size:12.8px;line-height:1.55;margin:0;overflow-wrap:break-word}

.tr-foot{display:flex;align-items:center;gap:10px;margin-top:14px}
/* точки-прогресс: активная вытягивается в пилюлю */
.tr-dots{display:flex;align-items:center;gap:6px}
.tr-dots span{width:7px;height:7px;border-radius:50%;background:var(--border);cursor:pointer;
  transition:width .38s cubic-bezier(.4,.82,.24,1),background .28s ease,box-shadow .28s ease,transform .2s ease}
.tr-dots span.on{width:20px;border-radius:5px;background:var(--lime);
  box-shadow:0 0 9px rgba(154,255,0,.7)}
.tr-dots span:not(.on):hover{transform:scale(1.35);background:var(--dim)}
.tr-btns{display:flex;align-items:center;gap:6px;margin-left:auto}
.tr-skip{background:none;border:none;color:var(--dim);font-size:12px;font-weight:600;
  padding:9px 10px;cursor:pointer;border-radius:var(--r-sm);transition:color .2s,background .2s}
.tr-skip:hover{color:var(--text);background:var(--raised)}
.tr-next{width:auto;padding:10px 18px;font-size:13px}
.tr-next:active{transform:scale(.95)}
.tr-next svg.i{width:14px;height:14px}

/* --- светлая тема: мягче затемнение, тень без лайм-ореола --- */
:root[data-theme="light"] .tr-hole{box-shadow:0 0 30px 200vmax rgba(16,22,8,.62)}
:root[data-theme="light"] .tr-hole::before{box-shadow:0 0 44px 4px rgba(120,200,0,.16)}
:root[data-theme="light"] .tr-card{box-shadow:0 20px 54px rgba(20,30,8,.28)}

@media (prefers-reduced-motion:reduce){
  .tr-hole,.tr-card,.tr-arr,.tr-dots span{transition-duration:.01ms}
  .tr-hole::after{animation:none}
  .tr-body{animation-duration:.01ms}
}

/* ===== TOUR STORIES (ts-) — Instagram-like сторис Даниэля, первый заход ===== */
#trStories{position:fixed;inset:0;z-index:70;display:flex;flex-direction:column;
  background:#0a0f04;opacity:0;transition:opacity .32s ease;overscroll-behavior:contain;
  -webkit-tap-highlight-color:transparent;color:#f4fff2}
#trStories.ts-on{opacity:1}

/* --- полоски-прогресс сверху (5 сегментов, живая заполняется по времени) --- */
.ts-bars{position:absolute;top:calc(env(safe-area-inset-top,0px) + 10px);left:12px;right:12px;
  display:flex;gap:5px;z-index:3;pointer-events:none}
.ts-bar{flex:1;height:3px;border-radius:3px;background:rgba(255,255,255,.22);overflow:hidden}
.ts-bar > i{display:block;height:100%;width:0%;background:#fff;border-radius:3px}
.ts-bar.done > i{width:100%}
.ts-bar.live > i{box-shadow:0 0 8px rgba(255,255,255,.55)}
#trStories.ts-paused .ts-bar.live > i{filter:brightness(.85)}

/* --- шапка: автор + крест --- */
.ts-head{position:absolute;top:calc(env(safe-area-inset-top,0px) + 22px);left:14px;right:14px;
  display:flex;align-items:center;gap:10px;z-index:3}
.ts-author{display:flex;align-items:center;gap:10px;min-width:0}
.ts-ava{width:34px;height:34px;border-radius:50%;background:var(--lime,#9AFF00);
  display:flex;align-items:center;justify-content:center;color:#001400;
  box-shadow:0 0 0 2px rgba(255,255,255,.18),0 6px 18px rgba(154,255,0,.35)}
.ts-ava svg.i{width:18px;height:18px}
.ts-author-b{min-width:0;line-height:1.15}
.ts-author-b b{font-size:13.5px;font-weight:800;letter-spacing:.01em;color:#fff}
.ts-author-b small{display:block;font-size:11px;color:rgba(255,255,255,.7);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:60vw}
.ts-close{margin-left:auto;width:36px;height:36px;border-radius:50%;border:none;
  background:rgba(255,255,255,.08);color:#fff;cursor:pointer;display:flex;
  align-items:center;justify-content:center;transition:background .2s,transform .1s}
.ts-close:hover{background:rgba(255,255,255,.18)}
.ts-close:active{transform:scale(.94)}
.ts-close svg.i{width:14px;height:14px}

/* --- сцена и слайд --- */
.ts-stage{position:absolute;inset:0;overflow:hidden;isolation:isolate}
.ts-tone-lime{background:radial-gradient(120% 80% at 15% 20%,#3b6f00 0%,#1a2d05 55%,#050803 100%)}
.ts-tone-dark{background:radial-gradient(120% 80% at 85% 20%,#0f150b 0%,#050603 55%,#000 100%)}
.ts-slide{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;
  padding:0 24px calc(env(safe-area-inset-bottom,0px) + 128px);
  animation:tsIn .5s cubic-bezier(.3,.9,.3,1) both}
@keyframes tsIn{from{opacity:0;transform:scale(.985)}to{opacity:1;transform:none}}

/* тонкая грид-сетка на фоне, характерный OKO-паттерн */
.ts-grid{position:absolute;inset:0;pointer-events:none;opacity:.14;
  background-image:linear-gradient(rgba(154,255,0,.6) 1px,transparent 1px),
                    linear-gradient(90deg,rgba(154,255,0,.6) 1px,transparent 1px);
  background-size:56px 56px;mask-image:radial-gradient(65% 60% at 50% 42%,#000 0%,transparent 90%)}
.ts-tone-dark .ts-grid{opacity:.08}

/* лаймовое сияние-глаз в центре-сверху */
.ts-halo{position:absolute;left:50%;top:22%;width:520px;height:520px;transform:translate(-50%,-50%);
  background:radial-gradient(closest-side,rgba(154,255,0,.55),rgba(154,255,0,.08) 55%,transparent 72%);
  filter:blur(4px);pointer-events:none;
  animation:tsHalo 6.4s ease-in-out infinite}
@keyframes tsHalo{0%,100%{opacity:.85;transform:translate(-50%,-50%) scale(1)}
                   50%{opacity:1;transform:translate(-50%,-50%) scale(1.06)}}
.ts-tone-dark .ts-halo{opacity:.55;background:radial-gradient(closest-side,rgba(154,255,0,.35),transparent 70%)}

/* большая брендовая иконка над контентом */
.ts-ico-big{position:absolute;left:50%;top:calc(env(safe-area-inset-top,0px) + 92px);
  transform:translateX(-50%);width:96px;height:96px;border-radius:28px;
  background:linear-gradient(135deg,#9AFF00,#4d9c00);color:#001400;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 20px 60px rgba(154,255,0,.35),inset 0 0 0 1px rgba(255,255,255,.25);
  animation:tsIcoPop .7s cubic-bezier(.3,1.3,.4,1) both}
.ts-ico-big svg.i{width:52px;height:52px}
.ts-tone-dark .ts-ico-big{background:linear-gradient(135deg,#151b0f,#0a0e07);color:#9AFF00;
  box-shadow:0 20px 60px rgba(0,0,0,.5),inset 0 0 0 1px rgba(154,255,0,.35)}
@keyframes tsIcoPop{from{opacity:0;transform:translateX(-50%) translateY(14px) scale(.9)}
                     to{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}}

.ts-content{position:relative;z-index:2;text-align:left}
.ts-tag{display:inline-flex;align-items:center;padding:5px 10px;border-radius:999px;
  background:rgba(154,255,0,.16);color:#c6ff5e;font-size:10.5px;font-weight:800;
  letter-spacing:.16em;text-transform:uppercase;margin-bottom:12px}
.ts-title{font-family:var(--font-display,'Bebas Neue',Impact,sans-serif);
  font-size:38px;line-height:1.02;letter-spacing:.015em;margin:0 0 12px;color:#fff;
  text-shadow:0 8px 30px rgba(0,0,0,.6)}
.ts-text{font-size:14.5px;line-height:1.55;color:rgba(255,255,255,.86);margin:0;
  max-width:34ch}

.ts-foot{position:absolute;left:24px;right:24px;
  bottom:calc(env(safe-area-inset-bottom,0px) + 78px);
  display:flex;align-items:center;gap:8px;color:rgba(255,255,255,.6);
  font-size:11.5px;z-index:2}
.ts-dot{width:5px;height:5px;border-radius:50%;background:var(--lime,#9AFF00);
  box-shadow:0 0 8px var(--lime,#9AFF00)}

/* невидимые «зоны» для тапов: левая — назад, правая — вперёд */
.ts-nav{position:absolute;inset:0;display:flex;z-index:2}
.ts-hit{flex:1;background:none;border:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
.ts-hit-l{flex:0 0 32%}
.ts-hit-r{flex:1}

/* CTA внизу — «Пропустить сторис» / «Начать тур по OKO» */
.ts-cta{position:absolute;left:0;right:0;bottom:0;
  padding:14px 20px calc(env(safe-area-inset-bottom,0px) + 18px);
  z-index:4;
  background:linear-gradient(to top,rgba(0,0,0,.55),transparent);
  pointer-events:none}
.ts-cta .btn{pointer-events:auto;width:100%;height:48px;border-radius:14px;
  font-size:14px;font-weight:800;letter-spacing:.02em;
  background:#fff;color:#0a0f04;border:none;cursor:pointer;
  box-shadow:0 12px 30px rgba(0,0,0,.35);transition:transform .12s,background .2s}
.ts-cta .btn:hover{background:#eaffbf}
.ts-cta .btn:active{transform:scale(.98)}

/* --- светлая тема (для консистентности, если пользователь переключил): более мягкий фон --- */
:root[data-theme="light"] #trStories{background:#111a08}

/* --- планшет / широкий экран --- */
@media (min-width:640px){
  .ts-slide{padding-left:8%;padding-right:8%}
  .ts-title{font-size:46px;max-width:20ch}
  .ts-text{font-size:15.5px;max-width:38ch}
}

@media (prefers-reduced-motion:reduce){
  .ts-slide,.ts-ico-big{animation-duration:.01ms}
  .ts-halo{animation:none}
  .ts-bar > i{transition:none !important}
}

/* ===== module: pwa ===== */
/* ===== PWA module: установка, offline, обновление, sync ===== */

/* --- баннер «Установить OKO» (Android/desktop) --- */
#pwa-install{position:fixed;left:12px;right:12px;bottom:calc(74px + env(safe-area-inset-bottom));z-index:9800;
  display:none;flex-direction:column;gap:12px;padding:16px 16px 14px;border-radius:18px;
  background:linear-gradient(180deg,rgba(154,255,0,.06),transparent 70%),var(--surface);
  border:1px solid var(--border);box-shadow:0 18px 44px rgba(0,0,0,.5),0 0 0 1px rgba(154,255,0,.14);
  transform:translateY(24px);opacity:0;transition:transform .32s cubic-bezier(.22,.9,.36,1),opacity .28s ease}
#pwa-install.pwa-show{display:flex;opacity:1;transform:translateY(0)}
:root[data-theme="light"] #pwa-install{box-shadow:0 12px 32px rgba(10,30,0,.14),0 0 0 1px rgba(83,168,0,.18)}

.pwa-row{display:flex;align-items:center;gap:12px;min-width:0}
.pwa-ico{width:44px;height:44px;flex:none;border-radius:12px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center}
.pwa-ico svg{width:24px;height:24px;stroke:currentColor;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;fill:none}
.pwa-txt{min-width:0;flex:1}
.pwa-title{font-family:var(--font-display);font-size:16px;letter-spacing:.05em;text-transform:uppercase;line-height:1.1;color:var(--text)}
.pwa-sub{margin-top:4px;font-size:12.5px;line-height:1.45;color:var(--dim)}
.pwa-close{width:32px;height:32px;flex:none;border-radius:10px;border:1px solid var(--border);background:transparent;
  color:var(--dim);display:flex;align-items:center;justify-content:center;cursor:pointer;
  transition:color .18s,border-color .18s,transform .12s}
.pwa-close:hover{color:var(--text);border-color:var(--accent)}
.pwa-close:active{transform:scale(.94)}
.pwa-close svg{width:14px;height:14px;stroke:currentColor;stroke-width:8;stroke-linecap:round;fill:none}

.pwa-actions{display:flex;gap:10px}
.pwa-btn{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:8px;
  padding:12px 14px;border-radius:12px;font-weight:700;font-size:14px;letter-spacing:.02em;cursor:pointer;
  border:1px solid transparent;transition:box-shadow .2s,transform .12s,background .2s,border-color .2s;
  -webkit-tap-highlight-color:transparent}
.pwa-btn.pwa-primary{background:var(--lime);color:#000;border-color:var(--lime)}
.pwa-btn.pwa-primary:hover{box-shadow:var(--glow)}
.pwa-btn.pwa-ghost{background:transparent;color:var(--dim);border-color:var(--border)}
.pwa-btn.pwa-ghost:hover{color:var(--text);border-color:var(--accent)}
.pwa-btn:active{transform:scale(.97)}
.pwa-btn svg{width:14px;height:14px;stroke:currentColor;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;fill:none}

/* --- iOS-подсказка: «Поделиться → На главный экран» --- */
#pwa-ios{position:fixed;left:12px;right:12px;bottom:calc(74px + env(safe-area-inset-bottom));z-index:9800;
  display:none;padding:14px 14px 16px;border-radius:18px;background:var(--surface);
  border:1px solid var(--border);box-shadow:0 16px 36px rgba(0,0,0,.5),0 0 0 1px rgba(154,255,0,.14);
  transform:translateY(24px);opacity:0;transition:transform .32s cubic-bezier(.22,.9,.36,1),opacity .28s ease}
#pwa-ios.pwa-show{display:block;opacity:1;transform:translateY(0)}
#pwa-ios .pwa-row{margin-bottom:10px}
.pwa-ios-step{display:flex;align-items:flex-start;gap:10px;padding:8px 0;font-size:13px;color:var(--text);line-height:1.4}
.pwa-ios-num{width:22px;height:22px;flex:none;border-radius:50%;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center;font-weight:800;font-size:12px}
.pwa-ios-step svg{width:16px;height:16px;color:var(--accent);flex:none;margin-top:2px;
  stroke:currentColor;stroke-width:6;stroke-linecap:round;stroke-linejoin:round;fill:none}
.pwa-ios-step b{color:var(--text);font-weight:700}
#pwa-ios .pwa-close{position:absolute;top:10px;right:10px}
#pwa-ios{position:fixed} /* сохраняем позиционирование */

/* --- офлайн-плашка сверху --- */
#pwa-offline{position:fixed;top:0;left:0;right:0;z-index:9900;
  display:none;align-items:center;justify-content:center;gap:10px;
  padding:8px 14px;padding-top:max(8px,env(safe-area-inset-top));
  background:#ff4d4d;color:#fff;font-size:13px;font-weight:600;letter-spacing:.02em;
  box-shadow:0 6px 18px rgba(255,77,77,.35);
  transform:translateY(-100%);transition:transform .32s cubic-bezier(.22,.9,.36,1)}
#pwa-offline.pwa-show{display:flex;transform:translateY(0)}
#pwa-offline svg{width:14px;height:14px;stroke:currentColor;stroke-width:8;stroke-linecap:round;stroke-linejoin:round;fill:none;flex:none}
#pwa-offline .pwa-off-dot{width:7px;height:7px;border-radius:50%;background:#fff;
  box-shadow:0 0 0 0 rgba(255,255,255,.6);animation:pwa-puls 2.4s ease-in-out infinite;flex:none}
@keyframes pwa-puls{0%,100%{box-shadow:0 0 0 0 rgba(255,255,255,.6)}50%{box-shadow:0 0 0 8px rgba(255,255,255,0)}}
body.pwa-offline-shift #app{padding-top:38px}
body.pwa-offline-shift header{padding-top:calc(10px + max(8px,env(safe-area-inset-top)) + 30px)}

/* --- toast «Новая версия готова» --- */
#pwa-update{position:fixed;left:12px;right:12px;bottom:calc(74px + env(safe-area-inset-bottom));z-index:9850;
  display:none;align-items:center;gap:12px;padding:12px 14px;border-radius:14px;
  background:var(--surface);border:1px solid rgba(154,255,0,.35);
  box-shadow:0 14px 32px rgba(0,0,0,.45),0 0 0 1px rgba(154,255,0,.12);
  transform:translateY(24px);opacity:0;transition:transform .32s cubic-bezier(.22,.9,.36,1),opacity .28s ease}
#pwa-update.pwa-show{display:flex;opacity:1;transform:translateY(0)}
#pwa-update .pwa-ico{width:36px;height:36px;border-radius:10px}
#pwa-update .pwa-ico svg{width:20px;height:20px}
#pwa-update .pwa-txt{flex:1;min-width:0}
#pwa-update .pwa-title{font-size:14px}
#pwa-update .pwa-sub{margin-top:2px;font-size:12px}
#pwa-update .pwa-btn{flex:none;padding:10px 14px;font-size:13px}

/* --- offline-toast «синхронизируем...» --- */
#pwa-sync-toast{position:fixed;left:50%;bottom:calc(80px + env(safe-area-inset-bottom));transform:translateX(-50%) translateY(20px);
  z-index:9860;display:none;opacity:0;transition:opacity .25s,transform .25s;
  background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:99px;
  padding:8px 16px;font-size:12.5px;font-weight:600;box-shadow:0 10px 24px rgba(0,0,0,.35);
  align-items:center;gap:8px}
#pwa-sync-toast.pwa-show{display:inline-flex;opacity:1;transform:translateX(-50%) translateY(0)}
#pwa-sync-toast .pwa-spin{width:12px;height:12px;border-radius:50%;border:2px solid var(--border);border-top-color:var(--accent);animation:pwa-spin 1s linear infinite}
@keyframes pwa-spin{to{transform:rotate(360deg)}}

/* --- когда установлено standalone: чуть-чуть safe-area внизу --- */
@media all and (display-mode: standalone){
  body{padding-bottom:env(safe-area-inset-bottom)}
}
@media all and (display-mode: window-controls-overlay){
  body{padding-top:env(titlebar-area-height,0)}
}

/* ===== module: paywall ===== */
/* ============ PAYWALL (pw-) — монетизация, паволлы, тарифы ============ */

/* ---- Замочки на сервис-тайлах ---- */
.svc{position:relative}
.pw-lock{position:absolute;top:7px;right:7px;height:19px;border-radius:99px;
  display:inline-flex;align-items:center;gap:3px;padding:0 7px 0 5px;
  background:rgba(0,0,0,.62);border:1px solid rgba(154,255,0,.55);
  box-shadow:0 2px 10px rgba(0,0,0,.35);z-index:2;backdrop-filter:blur(4px)}
.pw-lock svg{width:10px;height:10px;color:var(--lime);flex:none}
.pw-lock i{font-style:normal;font-size:8px;font-weight:800;letter-spacing:.06em;color:var(--lime)}
:root[data-theme="light"] .pw-lock{background:rgba(255,255,255,.82);border-color:rgba(83,168,0,.5)}
:root[data-theme="light"] .pw-lock svg,:root[data-theme="light"] .pw-lock i{color:var(--accent)}
.svc.pw-locked .svc-ic{filter:saturate(.55) brightness(.92)}

/* ---- Паволл-попап ---- */
#pwPop{position:fixed;inset:0;z-index:80;display:flex;align-items:flex-end;justify-content:center;
  background:rgba(0,0,0,.66);backdrop-filter:blur(3px);animation:pwFade .22s ease}
@media(min-width:560px){#pwPop{align-items:center}}
@keyframes pwFade{from{opacity:0}to{opacity:1}}
.pw-card{position:relative;width:100%;max-width:460px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-lg) var(--r-lg) 0 0;overflow:hidden;
  box-shadow:0 -20px 70px rgba(0,0,0,.6);animation:pwUp .34s cubic-bezier(.25,1,.4,1);
  max-height:94dvh;overflow-y:auto}
@media(min-width:560px){.pw-card{border-radius:var(--r-lg);animation:pwPop .34s cubic-bezier(.25,1,.4,1)}}
@keyframes pwUp{from{transform:translateY(60px)}to{transform:translateY(0)}}
@keyframes pwPop{from{transform:scale(.94);opacity:.4}to{transform:scale(1);opacity:1}}

.pw-hero{position:relative;height:186px;overflow:hidden;background:#0a0a0a}
.pw-hero-media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.pw-hero-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
  transform:scale(1.04);animation:pwKen 14s ease-in-out infinite alternate}
@keyframes pwKen{from{transform:scale(1.02) translate(0,0)}to{transform:scale(1.12) translate(-2%,-3%)}}
.pw-hero::after{content:'';position:absolute;inset:0;
  background:linear-gradient(180deg,rgba(10,10,10,.15) 0%,rgba(10,10,10,.55) 55%,var(--surface) 100%)}
:root[data-theme="light"] .pw-hero::after{
  background:linear-gradient(180deg,rgba(10,10,10,.05) 0%,rgba(10,10,10,.28) 45%,var(--surface) 100%)}
.pw-hero-top{position:absolute;top:0;left:0;right:0;z-index:2;display:flex;justify-content:space-between;
  align-items:flex-start;padding:14px 16px}
.pw-lock-badge{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;
  background:rgba(0,0,0,.42);border:1.5px solid var(--lime);box-shadow:var(--glow);backdrop-filter:blur(6px)}
.pw-lock-badge svg{width:20px;height:20px;color:var(--lime)}
.pw-close{width:34px;height:34px;border-radius:50%;background:rgba(0,0,0,.42);backdrop-filter:blur(6px);
  display:flex;align-items:center;justify-content:center;color:#fff;transition:transform .15s,background .2s}
.pw-close:active{transform:scale(.9)}
.pw-close svg{width:16px;height:16px;transform:rotate(45deg)}
.pw-hero-cap{position:absolute;left:16px;right:16px;bottom:12px;z-index:2}
.pw-hero-cap .k{font-size:10.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--lime)}
.pw-hero-cap h2{font-family:var(--font-display);font-size:34px;line-height:.96;letter-spacing:.01em;color:#fff;margin-top:2px}
:root[data-theme="light"] .pw-hero-cap h2{color:#0d110a}
:root[data-theme="light"] .pw-hero-cap .k{color:var(--accent)}

.pw-body{padding:16px 18px calc(18px + env(safe-area-inset-bottom))}
.pw-reason{font-size:13.5px;line-height:1.55;color:var(--dim);margin-bottom:14px}
.pw-reason b{color:var(--text)}
.pw-benefits{display:flex;flex-direction:column;gap:9px;margin-bottom:16px}
.pw-benefit{display:flex;gap:11px;align-items:flex-start;opacity:0;transform:translateY(6px);
  animation:pwIn .4s ease forwards}
.pw-benefit:nth-child(1){animation-delay:.06s}.pw-benefit:nth-child(2){animation-delay:.13s}
.pw-benefit:nth-child(3){animation-delay:.2s}.pw-benefit:nth-child(4){animation-delay:.27s}
@keyframes pwIn{to{opacity:1;transform:translateY(0)}}
.pw-benefit .pw-b-ic{flex:none;width:26px;height:26px;border-radius:8px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center;margin-top:1px}
.pw-benefit .pw-b-ic svg{width:14px;height:14px;color:var(--accent);fill:none;stroke:currentColor;stroke-width:9}
.pw-benefit b{font-size:13.5px;font-weight:700;display:block}
.pw-benefit small{font-size:12px;color:var(--dim);line-height:1.45}

.pw-price{display:flex;align-items:baseline;justify-content:space-between;
  background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);
  padding:13px 16px;margin-bottom:13px}
.pw-price .pw-p-l{font-size:11.5px;color:var(--dim);font-weight:600}
.pw-price .pw-p-v{font-family:var(--font-display);font-size:30px;letter-spacing:.01em;color:var(--text)}
.pw-price .pw-p-v small{font-family:var(--font-body);font-size:12.5px;color:var(--dim);font-weight:600;letter-spacing:0}
.pw-price .pw-p-note{font-size:11px;color:var(--accent);font-weight:700;text-align:right}
.pw-cta{width:100%;margin-bottom:9px}
.pw-cta svg{width:16px;height:16px}
.pw-later{width:100%}
.pw-guarant{text-align:center;font-size:11px;color:var(--dim);margin-top:11px;display:flex;
  align-items:center;justify-content:center;gap:6px}
.pw-guarant svg{width:13px;height:13px;color:var(--accent)}

/* ---- Ambient nudge (мягкий тост-баннер) ---- */
#pwNudge{position:fixed;left:12px;right:12px;bottom:calc(74px + env(safe-area-inset-bottom));z-index:60;
  max-width:456px;margin:0 auto;display:flex;gap:12px;align-items:center;
  background:var(--surface);border:1px solid var(--lime);border-radius:var(--r-md);
  padding:12px 14px;box-shadow:0 12px 40px rgba(0,0,0,.45),var(--glow);
  animation:pwNudgeIn .4s cubic-bezier(.25,1,.4,1)}
@keyframes pwNudgeIn{from{transform:translateY(24px);opacity:0}to{transform:translateY(0);opacity:1}}
#pwNudge.pw-out{animation:pwNudgeOut .3s ease forwards}
@keyframes pwNudgeOut{to{transform:translateY(24px);opacity:0}}
#pwNudge .pw-n-ic{flex:none;width:38px;height:38px;border-radius:10px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center}
#pwNudge .pw-n-ic svg{width:19px;height:19px;color:var(--accent)}
#pwNudge .pw-n-tx{flex:1;min-width:0}
#pwNudge .pw-n-tx b{font-size:13px;font-weight:700;display:block}
#pwNudge .pw-n-tx small{font-size:11.5px;color:var(--dim);line-height:1.4}
#pwNudge .pw-n-go{flex:none;font-size:12px;font-weight:800;color:#000;background:var(--lime);
  padding:8px 13px;border-radius:99px}
#pwNudge .pw-n-x{flex:none;color:var(--dim);width:22px;height:22px;display:flex;align-items:center;justify-content:center}
#pwNudge .pw-n-x svg{width:13px;height:13px;transform:rotate(45deg)}

/* ---- Редизайн тарифов (в #payView) ---- */
.pw-pay-head{text-align:center;margin:2px 0 14px}
.pw-pay-head h3{font-family:var(--font-display);font-size:30px;letter-spacing:.02em}
.pw-pay-head p{font-size:12px;color:var(--dim);margin-top:2px}
.pw-tiers{display:flex;flex-direction:column;gap:11px;margin-bottom:16px}
.pw-tier{position:relative;border:1.5px solid var(--border);border-radius:var(--r-lg);overflow:hidden;
  cursor:pointer;transition:border-color .22s,transform .15s,box-shadow .22s;background:var(--raised)}
.pw-tier:active{transform:scale(.99)}
.pw-tier.on{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime),0 10px 34px rgba(154,255,0,.14)}
.pw-tier-bg{position:relative;height:98px;overflow:hidden;background:#0a0a0a}
.pw-tier-bg .pw-tier-vid,.pw-tier-bg .pw-tier-im{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.pw-tier-bg .pw-tier-im{transform:scale(1.05);animation:pwKen 16s ease-in-out infinite alternate}
.pw-tier-bg::after{content:'';position:absolute;inset:0;
  background:linear-gradient(90deg,rgba(10,10,10,.72) 0%,rgba(10,10,10,.35) 55%,rgba(10,10,10,.15) 100%)}
:root[data-theme="light"] .pw-tier-bg::after{
  background:linear-gradient(90deg,rgba(10,10,10,.6) 0%,rgba(10,10,10,.3) 55%,rgba(10,10,10,.08) 100%)}
.pw-tier-cap{position:absolute;left:14px;bottom:9px;z-index:2}
.pw-tier-cap .n{font-family:var(--font-display);font-size:26px;line-height:.9;color:#fff;letter-spacing:.02em}
.pw-tier-cap .s{font-size:11px;color:rgba(255,255,255,.82);font-weight:600;margin-top:2px}
.pw-flag{position:absolute;top:9px;right:9px;z-index:3;font-size:9.5px;font-weight:800;letter-spacing:.08em;
  text-transform:uppercase;color:#000;background:var(--lime);padding:4px 9px;border-radius:99px;box-shadow:var(--glow)}
.pw-tier-sel{position:absolute;top:9px;left:9px;z-index:3;width:22px;height:22px;border-radius:50%;
  border:2px solid rgba(255,255,255,.7);background:rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;transition:.2s}
.pw-tier.on .pw-tier-sel{border-color:var(--lime);background:var(--lime)}
.pw-tier.on .pw-tier-sel svg{width:12px;height:12px;color:#000;fill:currentColor;opacity:1}
.pw-tier-sel svg{opacity:0;transition:.2s}
.pw-tier-price{display:flex;align-items:baseline;gap:6px;padding:10px 14px 4px}
.pw-tier-price b{font-family:var(--font-display);font-size:24px;letter-spacing:.01em}
.pw-tier-price span{font-size:11.5px;color:var(--dim);font-weight:600}
.pw-tier-price .pw-perday{margin-left:auto;font-size:11px;color:var(--accent);font-weight:700}
.pw-tier-feats{list-style:none;padding:2px 14px 13px;display:flex;flex-direction:column;gap:6px}
.pw-tier-feats li{display:flex;gap:8px;align-items:flex-start;font-size:12px;line-height:1.4;color:var(--text)}
.pw-tier-feats li svg{flex:none;width:13px;height:13px;color:var(--accent);fill:none;stroke:currentColor;stroke-width:9;margin-top:2px}
.pw-tier-feats li.pw-more{color:var(--dim);font-weight:600}

.pw-cmp-toggle{width:100%;font-size:12.5px;font-weight:700;color:var(--accent);background:var(--lime-dim);
  border-radius:var(--r-md);padding:11px;margin-bottom:14px;display:flex;align-items:center;justify-content:center;gap:7px}
.pw-cmp-toggle svg{width:14px;height:14px;transition:transform .25s}
.pw-cmp-toggle.on svg{transform:rotate(180deg)}
.pw-cmp-wrap{overflow-x:auto;margin-bottom:16px;-webkit-overflow-scrolling:touch;
  border:1px solid var(--border);border-radius:var(--r-md);
  /* правый край подтаивает — сигнал «листай, есть ещё BUSINESS и MAX» */
  -webkit-mask-image:linear-gradient(90deg,#000 89%,rgba(0,0,0,.35) 100%);
          mask-image:linear-gradient(90deg,#000 89%,rgba(0,0,0,.35) 100%)}
/* подпись-подсказка над таблицей */
.pw-cmp-hint{font-size:11px;color:var(--dim);text-align:right;margin:-6px 2px 6px;letter-spacing:.02em}
.pw-cmp{border-collapse:collapse;width:100%;min-width:452px;font-size:12px}
.pw-cmp th,.pw-cmp td{padding:9px 8px;text-align:center;border-bottom:1px solid var(--border)}
.pw-cmp thead th{position:sticky;top:0;background:var(--surface);font-family:var(--font-display);font-size:15px;
  letter-spacing:.03em;font-weight:400}
.pw-cmp thead th.pw-c-pro{color:var(--accent)}
.pw-cmp tbody th{text-align:left;font-weight:600;color:var(--dim);font-size:11.5px;white-space:nowrap}
.pw-cmp td svg{width:14px;height:14px}
.pw-cmp td.pw-yes svg{color:var(--accent);fill:none;stroke:currentColor;stroke-width:9}
.pw-cmp td.pw-no{color:var(--border)}
.pw-cmp td.pw-no svg{color:var(--border)}
.pw-cmp td.pw-val{font-weight:700;color:var(--text);font-size:11.5px}
.pw-cmp tbody tr:last-child td,.pw-cmp tbody tr:last-child th{border-bottom:none}
.pw-cmp col.pw-col-pro,.pw-cmp .pw-c-pro-cell{background:var(--lime-dim)}

/* Live-цифры воронки */
.pw-live{display:flex;gap:9px;margin:0 0 16px}
.pw-live-cell{flex:1;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);
  padding:11px 8px;text-align:center}
.pw-live-cell .v{font-family:var(--font-display);font-size:23px;letter-spacing:.01em;color:var(--accent);
  transition:color .3s}
.pw-live-cell .l{font-size:10px;color:var(--dim);line-height:1.3;margin-top:2px}

/* ---- Инфографика-кольца в продающем попапе ---- */
.pw-info{display:flex;gap:10px;margin:0 0 15px}
.pw-info-cell{flex:1;display:flex;flex-direction:column;align-items:center;gap:6px}
.pw-ring{--pwp:0;position:relative;width:58px;height:58px;border-radius:50%;
  background:conic-gradient(var(--lime) calc(var(--pwp)*1%),var(--border) 0);
  display:flex;align-items:center;justify-content:center;
  transition:background .1s;filter:drop-shadow(0 0 8px rgba(154,255,0,.18))}
.pw-anim .pw-ring{animation:pwRingSpin .9s cubic-bezier(.3,1,.4,1) both}
@keyframes pwRingSpin{from{transform:rotate(-24deg) scale(.85);opacity:.3}to{transform:none;opacity:1}}
.pw-ring::after{content:'';position:absolute;inset:5px;border-radius:50%;background:var(--surface)}
.pw-ring b{position:relative;z-index:1;font-family:var(--font-display);font-size:16px;color:var(--text);letter-spacing:.01em}
.pw-info-cell small{font-size:10px;color:var(--dim);text-align:center;line-height:1.25}
:root[data-theme="light"] .pw-ring::after{background:var(--surface)}

/* ---- Кнопка «Что входит» на карточке тарифа ---- */
.pw-tier-more{width:calc(100% - 28px);margin:0 14px 13px;padding:9px;border-radius:var(--r-md);
  display:flex;align-items:center;justify-content:center;gap:7px;font-size:12px;font-weight:700;
  color:var(--accent);background:var(--lime-dim);border:1px solid transparent;
  transition:background .18s,border-color .18s,transform .12s}
.pw-tier-more:hover{border-color:rgba(154,255,0,.4)}
.pw-tier-more:active{transform:scale(.98)}
.pw-tier-more svg{width:13px;height:13px;color:var(--accent)}

/* ---- Тариф MAX: премиальный акцент ---- */
.pw-flag-max{background:linear-gradient(90deg,var(--lime),#d8ff7a);color:#0a0a0a}
.pw-tier-max.on{box-shadow:0 0 0 1px var(--lime),0 12px 40px rgba(154,255,0,.22)}
.pw-tier-max .pw-tier-cap .n{background:linear-gradient(90deg,#fff,#dfffb0);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}

/* ---- Реклама: доступна на любом тарифе ---- */
.pw-ads-note{display:flex;gap:12px;align-items:center;background:var(--raised);
  border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px;margin:0 0 12px}
.pw-ads-ic{flex:none;width:38px;height:38px;border-radius:10px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center}
.pw-ads-ic svg{width:19px;height:19px;color:var(--accent)}
.pw-ads-note b{font-size:13px;font-weight:700;display:block}
.pw-ads-note small{font-size:11.5px;color:var(--dim);line-height:1.4;display:block;margin-top:2px}

/* ---- Партнёрская программа (отдельный блок) ---- */
.pw-partner{background:var(--raised);border:1px solid var(--border);border-radius:var(--r-lg);
  padding:15px 15px 14px;margin:0 0 18px;position:relative;overflow:hidden}
.pw-partner::before{content:'';position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(120% 80% at 100% 0%,rgba(154,255,0,.1),transparent 60%)}
.pw-partner-h{display:flex;gap:11px;align-items:center;margin-bottom:12px;position:relative}
.pw-partner-ic{flex:none;width:40px;height:40px;border-radius:11px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center}
.pw-partner-ic svg{width:20px;height:20px;color:var(--accent)}
.pw-partner-h b{font-size:14px;font-weight:800;display:block}
.pw-partner-h small{font-size:11px;color:var(--dim);line-height:1.35;display:block;margin-top:2px}
.pw-partner-rows{display:flex;flex-direction:column;gap:8px;margin-bottom:13px;position:relative}
.pw-pr{display:flex;align-items:baseline;gap:11px;padding:9px 12px;border-radius:var(--r-md);
  background:var(--surface);border:1px solid var(--border)}
.pw-pr b{flex:none;min-width:52px;font-family:var(--font-display);font-size:22px;color:var(--accent);letter-spacing:.01em}
.pw-pr span{font-size:12px;color:var(--text);line-height:1.35}
.pw-pr-max{border-color:rgba(154,255,0,.5);box-shadow:0 0 0 1px rgba(154,255,0,.14)}
.pw-partner-cta{width:100%;display:flex;align-items:center;justify-content:center;gap:8px;
  padding:11px;border-radius:99px;font-size:13px;font-weight:800;color:#0a0a0a;
  background:var(--lime);box-shadow:var(--glow);position:relative;transition:transform .12s,filter .18s}
.pw-partner-cta:hover{filter:brightness(1.05)}
.pw-partner-cta:active{transform:scale(.98)}
.pw-partner-cta svg{width:15px;height:15px;color:#0a0a0a}

/* партнёрка внутри showPopup */
.pw-partner-pop .pw-pr{margin-top:8px}
.pw-partner-pop p{font-size:13px;line-height:1.5}

/* ---- Сравнительная таблица: колонка MAX ---- */
.pw-cmp{min-width:540px}
.pw-cmp thead th.pw-c-max{color:var(--accent)}

/* ---- Рекомендованный тариф (PRO): якорь выбора ---- */
.pw-tier-rec{border-color:rgba(154,255,0,.42)}
.pw-tier-rec:not(.on){box-shadow:0 6px 26px rgba(154,255,0,.09)}

/* ---- «хит» над колонкой PRO в сравнении ---- */
.pw-c-tag{display:block;font-style:normal;font-family:var(--font-body);font-size:8px;font-weight:800;
  letter-spacing:.08em;text-transform:uppercase;color:#000;background:var(--lime);border-radius:99px;
  padding:1px 5px;margin:3px auto 0;width:fit-content}

/* ---- Лента недавней активности (соц-доказательство) ---- */
.pw-tick{background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);padding:9px 12px 8px;margin:0 0 16px}
.pw-tick-h{display:flex;align-items:center;gap:6px;font-size:10px;font-weight:800;letter-spacing:.07em;
  text-transform:uppercase;color:var(--dim);margin-bottom:4px}
.pw-tick-h svg{width:12px;height:12px;color:var(--accent)}
.pw-tick-view{height:38px;overflow:hidden;position:relative;
  -webkit-mask:linear-gradient(180deg,transparent,#000 24%,#000 76%,transparent);
  mask:linear-gradient(180deg,transparent,#000 24%,#000 76%,transparent)}
.pw-tick-track{display:flex;flex-direction:column;animation:pwTickScroll 22s linear infinite;will-change:transform}
@keyframes pwTickScroll{from{transform:translateY(0)}to{transform:translateY(-50%)}}
.pw-tick-row{height:19px;display:flex;align-items:center;gap:7px;font-size:12px;line-height:19px}
.pw-tick-row b{font-weight:700;color:var(--text)}
.pw-tick-row>span:not(.pw-tick-dot){color:var(--dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pw-tick-dot{flex:none;width:6px;height:6px;border-radius:50%;background:var(--lime);
  box-shadow:0 0 6px var(--lime);animation:pwDotPulse 1.6s ease-in-out infinite}
@keyframes pwDotPulse{0%,100%{opacity:1}50%{opacity:.4}}

/* ---- Честный обратный отсчёт годовой скидки ---- */
.pw-count{border:1px solid rgba(154,255,0,.4);border-radius:var(--r-md);padding:11px 12px;margin:0 0 12px;text-align:center;
  background:radial-gradient(120% 120% at 50% 0%,rgba(154,255,0,.1),transparent 70%),var(--raised)}
.pw-count-t{font-size:11px;font-weight:700;color:var(--accent);display:flex;align-items:center;
  justify-content:center;gap:6px;margin-bottom:8px}
.pw-count-t svg{width:13px;height:13px}
.pw-count-segs{display:flex;align-items:center;justify-content:center;gap:5px}
.pw-count-seg{min-width:46px;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:5px 4px}
.pw-count-seg b{font-family:var(--font-display);font-size:22px;line-height:1;color:var(--text);
  letter-spacing:.01em;display:block;font-variant-numeric:tabular-nums}
.pw-count-seg i{font-style:normal;font-size:8.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.04em}
.pw-count-sep{font-family:var(--font-display);font-size:18px;color:var(--dim);opacity:.6}

/* ---- Ценностное обрамление (экономия / цена-в-день / ROI) ---- */
.pw-value{display:flex;flex-direction:column;gap:7px;margin:0 0 4px}
.pw-value-i{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--text);font-weight:600;line-height:1.35}
.pw-value-i span{flex:none;width:20px;height:20px;border-radius:6px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center}
.pw-value-i span svg{width:12px;height:12px;color:var(--accent)}

/* ---- Гарантия / снятие риска ---- */
.pw-guar-band{display:flex;align-items:center;gap:8px;justify-content:center;text-align:center;
  font-size:11px;color:var(--dim);background:var(--raised);border:1px solid var(--border);
  border-radius:var(--r-md);padding:10px 12px;margin-top:10px;line-height:1.4}
.pw-guar-band svg{flex:none;width:14px;height:14px;color:var(--accent)}

/* ---- FAQ / возражения ---- */
.pw-faq{margin:16px 0 4px}
.pw-faq-h{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:800;margin-bottom:9px}
.pw-faq-h svg{width:15px;height:15px;color:var(--accent)}
.pw-faq-i{border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:8px;background:var(--raised);overflow:hidden}
.pw-faq-i summary{list-style:none;cursor:pointer;padding:12px 14px;font-size:13px;font-weight:700;
  display:flex;align-items:center;justify-content:space-between;gap:10px}
.pw-faq-i summary::-webkit-details-marker{display:none}
.pw-faq-x{flex:none;width:20px;height:20px;display:flex;align-items:center;justify-content:center;transition:transform .22s}
.pw-faq-x svg{width:13px;height:13px;color:var(--dim)}
.pw-faq-i[open] .pw-faq-x{transform:rotate(180deg)}
.pw-faq-i[open] .pw-faq-x svg{color:var(--accent)}
.pw-faq-i p{padding:0 14px 13px;font-size:12.5px;line-height:1.55;color:var(--dim)}

/* ---- Партнёрский пример начисления ---- */
.pw-pr-eg{display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--dim);margin:2px 2px 0;line-height:1.35;position:relative}
.pw-pr-eg svg{flex:none;width:13px;height:13px;color:var(--accent)}
.pw-pr-eg b{color:var(--accent);font-weight:800}

/* ---- Партнёрский шэр-кит (ссылка + кнопки шэра) ---- */
.pw-share{margin-top:12px;display:flex;flex-direction:column;gap:9px;position:relative}
.pw-share-link{display:flex;align-items:center;gap:8px;background:var(--surface);
  border:1px dashed rgba(154,255,0,.5);border-radius:var(--r-md);padding:8px 8px 8px 11px}
.pw-share-link span{flex:1;min-width:0;font-size:12px;color:var(--text);font-weight:600;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pw-share-copy{flex:none;width:32px;height:32px;border-radius:8px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center;transition:filter .18s,transform .12s}
.pw-share-copy:active{transform:scale(.92)}
.pw-share-copy svg{width:15px;height:15px;color:var(--accent)}
.pw-share-row{display:flex;gap:8px}
.pw-share-btn{flex:1;display:flex;align-items:center;justify-content:center;gap:6px;padding:9px 4px;
  border-radius:var(--r-md);background:var(--surface);border:1px solid var(--border);
  font-size:12px;font-weight:700;color:var(--text);transition:border-color .18s,transform .12s}
.pw-share-btn:hover{border-color:rgba(154,255,0,.45)}
.pw-share-btn:active{transform:scale(.97)}
.pw-share-btn svg{flex:none;width:14px;height:14px;color:var(--accent)}

/* ---- Ценностный якорь: «заменяет команду за X» (anchoring, ясность выгоды) ---- */
.pw-anchor{display:flex;align-items:center;gap:12px;background:var(--raised);
  border:1px solid var(--border);border-radius:var(--r-md);padding:12px 14px;margin:0 0 12px;
  position:relative;overflow:hidden;opacity:0;transform:translateY(8px);
  animation:pwAnchorIn .45s cubic-bezier(.25,1,.4,1) forwards}
@keyframes pwAnchorIn{to{opacity:1;transform:translateY(0)}}
.pw-anchor::before{content:'';position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(130% 90% at 100% 0%,rgba(154,255,0,.12),transparent 62%)}
.pw-anchor-l{flex:1;min-width:0;position:relative}
.pw-anchor-k{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:var(--dim);line-height:1.3}
.pw-anchor-k svg{flex:none;width:13px;height:13px;color:var(--accent)}
.pw-anchor-k b{color:var(--text);font-weight:800}
.pw-anchor-cmp{margin-top:5px;font-size:12.5px;line-height:1.4}
.pw-anchor-cmp s{color:var(--dim);text-decoration-thickness:1.5px;margin-right:5px}
.pw-anchor-cmp b{color:var(--accent);font-weight:800}
.pw-anchor-x{flex:none;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-width:58px;padding:8px 6px;border-radius:12px;background:var(--lime);box-shadow:var(--glow)}
.pw-anchor-x b{font-family:var(--font-display);font-size:24px;line-height:.9;color:#0a0a0a;letter-spacing:.01em}
.pw-anchor-x i{font-style:normal;font-size:8.5px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#0a0a0a;margin-top:2px}
:root[data-theme="light"] .pw-anchor::before{background:radial-gradient(130% 90% at 100% 0%,rgba(110,200,0,.14),transparent 62%)}

/* ---- Премиальный блик на CTA-кнопке (микро-вау в момент решения) ---- */
.pw-shine{position:relative;overflow:hidden}
.pw-shine::after{content:'';position:absolute;top:0;bottom:0;left:0;width:38%;pointer-events:none;
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.55),transparent);
  transform:translateX(-160%) skewX(-18deg);animation:pwShine 4.2s ease-in-out infinite}
@keyframes pwShine{0%,64%{transform:translateX(-160%) skewX(-18deg)}82%,100%{transform:translateX(430%) skewX(-18deg)}}
:root[data-theme="light"] .pw-shine::after{background:linear-gradient(100deg,transparent,rgba(255,255,255,.7),transparent)}
@media(prefers-reduced-motion:reduce){.pw-shine::after{display:none}}

/* Крупные суммы вроде «Оплатить 1 439 040 ₽» не должны обрезаться в узком экране.
   Разрешаем перенос и лёгкое сжатие внутренностей — единой строкой на широких. */
.btn.pw-shine{white-space:normal;word-break:normal;overflow-wrap:anywhere;line-height:1.2;min-width:0;max-width:100%;padding:14px 16px;text-align:center;text-overflow:ellipsis}
.btn.pw-shine svg.i{flex:none}

/* ==========================================================================
   PW 2.0 — тарифы без видео: CSS-анимации на GPU, компакт-карточки, свайпер
   ========================================================================== */

/* профиль: компактная строка вместо длинных карточек всех тарифов */
.pw-prof-band{display:flex;gap:10px;align-items:center;background:var(--raised);
  border:1px solid var(--border);border-radius:var(--r-md);
  padding:12px 14px;margin:6px 0 2px;position:relative;overflow:hidden}
.pw-prof-band::before{content:'';position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(140% 90% at 100% 0%,rgba(154,255,0,.10),transparent 62%)}
.pw-prof-ic{flex:none;width:38px;height:38px;border-radius:10px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center;position:relative;z-index:1}
.pw-prof-ic svg{width:19px;height:19px;color:var(--accent)}
.pw-prof-tx{flex:1;min-width:0;position:relative;z-index:1}
.pw-prof-tx b{font-size:13.5px;font-weight:800;display:block;letter-spacing:.01em}
.pw-prof-tx small{font-size:11.5px;color:var(--dim);line-height:1.35}
.pw-prof-btn{flex:none;font-family:var(--font-body);font-size:12px;font-weight:800;color:#0a0a0a;
  background:var(--lime);border-radius:99px;padding:9px 14px;box-shadow:var(--glow);
  position:relative;z-index:1;transition:transform .12s,filter .18s;display:flex;align-items:center;gap:6px}
.pw-prof-btn:active{transform:scale(.96)}
.pw-prof-btn svg{width:13px;height:13px;color:#0a0a0a}
:root[data-theme="light"] .pw-prof-band::before{background:radial-gradient(140% 90% at 100% 0%,rgba(110,200,0,.14),transparent 62%)}

/* горизонтальный свайпер тарифов */
.pw-swiper-wrap{position:relative;margin:0 -18px 14px}
.pw-swiper{display:flex;gap:12px;overflow-x:auto;scroll-snap-type:x mandatory;
  padding:6px 18px 10px;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.pw-swiper::-webkit-scrollbar{display:none}
.pw-swiper .pw-tier{scroll-snap-align:center;flex:0 0 82%;min-width:250px;max-width:296px;margin:0}
@media(min-width:520px){.pw-swiper .pw-tier{flex:0 0 62%}}

/* переопределяем прежнюю pw-tier — убираем видео-фон */
.pw-tier{position:relative;border:1.5px solid var(--border);border-radius:var(--r-lg);overflow:hidden;
  cursor:pointer;transition:border-color .22s,transform .22s,box-shadow .22s;background:var(--raised);
  display:flex;flex-direction:column}
.pw-tier:active{transform:scale(.985)}
.pw-tier.on{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime),0 14px 40px rgba(154,255,0,.18);transform:translateY(-2px)}
.pw-tier .pw-tier-bg{position:relative;height:110px;overflow:hidden;background:#0e0f0d;isolation:isolate}
:root[data-theme="light"] .pw-tier .pw-tier-bg{background:#f4f6f0}

/* точки-индикаторы под свайпером */
.pw-dots{display:flex;justify-content:center;gap:6px;margin:-2px 0 12px}
.pw-dots span{width:6px;height:6px;border-radius:50%;background:var(--border);transition:.2s}
.pw-dots span.on{background:var(--lime);width:20px;border-radius:99px;box-shadow:0 0 6px rgba(154,255,0,.4)}

/* «Твой тариф» — вместо кнопки «Выбрать» */
.pw-tier-btn{margin:0 12px 12px;padding:10px;border-radius:99px;font-size:12.5px;font-weight:800;
  color:#0a0a0a;background:var(--lime);display:flex;align-items:center;justify-content:center;gap:6px;
  transition:filter .18s,transform .12s}
.pw-tier-btn:active{transform:scale(.97)}
.pw-tier-btn svg{width:13px;height:13px;color:#0a0a0a}
.pw-tier-btn.ghost{background:transparent;color:var(--accent);border:1.5px solid rgba(154,255,0,.4)}
.pw-tier-btn.ghost svg{color:var(--accent)}
.pw-tier-btn:disabled,.pw-tier-btn.is-current{background:var(--surface);color:var(--dim);border:1.5px solid var(--border);cursor:default}
.pw-tier-btn.is-current svg{color:var(--accent)}

/* ---- субэкран деталей тарифа (полноэкранный слайд поверх свайпера) ---- */
.pw-details{position:absolute;inset:0;background:var(--surface);z-index:5;
  transform:translateX(100%);transition:transform .32s cubic-bezier(.3,1,.4,1);
  overflow-y:auto;padding:14px 18px 22px;display:flex;flex-direction:column}
.pw-details.on{transform:translateX(0)}
.pw-det-top{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.pw-det-back{width:34px;height:34px;border-radius:50%;background:var(--raised);
  display:flex;align-items:center;justify-content:center;color:var(--text);
  border:1px solid var(--border);transition:background .18s}
.pw-det-back:active{background:var(--surface)}
.pw-det-back svg{width:14px;height:14px;transform:rotate(180deg)}
.pw-det-top h3{font-family:var(--font-display);font-size:26px;letter-spacing:.02em;flex:1;min-width:0}
.pw-det-hero{height:150px;border-radius:var(--r-md);overflow:hidden;margin-bottom:14px;position:relative;background:#0e0f0d}
:root[data-theme="light"] .pw-det-hero{background:#f4f6f0}
.pw-det-price{display:flex;align-items:baseline;gap:8px;margin-bottom:14px}
.pw-det-price b{font-family:var(--font-display);font-size:32px;letter-spacing:.01em}
.pw-det-price span{font-size:12px;color:var(--dim);font-weight:600}
.pw-det-price em{margin-left:auto;font-style:normal;font-size:11.5px;color:var(--accent);font-weight:800}
.pw-det-feats{list-style:none;padding:0;margin:0 0 16px;display:flex;flex-direction:column;gap:10px}
.pw-det-feats li{display:flex;gap:11px;align-items:flex-start;font-size:13.5px;line-height:1.45}
.pw-det-feats li .pw-df-ic{flex:none;width:26px;height:26px;border-radius:8px;background:var(--lime-dim);
  display:flex;align-items:center;justify-content:center;margin-top:1px}
.pw-det-feats li .pw-df-ic svg{width:13px;height:13px;color:var(--accent)}
.pw-det-feats li b{font-weight:700;display:block;margin-bottom:2px}
.pw-det-feats li small{font-size:12px;color:var(--dim);line-height:1.4;display:block}

/* ============ АНИМАЦИИ ФОНОВ КАРТОЧЕК (только transform + opacity + filter) ============ */
.pw-tbg{position:absolute;inset:0;overflow:hidden}
.pw-tbg::after{content:'';position:absolute;inset:0;pointer-events:none;
  background:linear-gradient(180deg,transparent 40%,rgba(10,10,10,.55) 100%)}
:root[data-theme="light"] .pw-tbg::after{background:linear-gradient(180deg,transparent 40%,rgba(230,238,215,.75) 100%)}

/* FREE — плавающие пузыри мессенджера */
.pw-tbg-free{background:radial-gradient(120% 100% at 30% 20%,rgba(154,255,0,.10),transparent 60%),#0e120a}
:root[data-theme="light"] .pw-tbg-free{background:radial-gradient(120% 100% at 30% 20%,rgba(154,255,0,.16),transparent 60%),#f0f6e0}
.pw-tbg-free .pw-bub{position:absolute;border-radius:14px;background:rgba(154,255,0,.22);
  border:1px solid rgba(154,255,0,.4);will-change:transform,opacity;animation:pwBubFloat 5.4s ease-in-out infinite}
.pw-tbg-free .pw-bub:nth-child(1){width:42%;height:22px;top:22%;left:10%;animation-delay:-.6s}
.pw-tbg-free .pw-bub:nth-child(2){width:26%;height:18px;top:48%;left:56%;animation-delay:-2.3s;background:rgba(154,255,0,.14)}
.pw-tbg-free .pw-bub:nth-child(3){width:34%;height:22px;top:70%;left:14%;animation-delay:-4s}
@keyframes pwBubFloat{0%,100%{transform:translate3d(0,0,0);opacity:.55}50%{transform:translate3d(0,-8px,0);opacity:1}}

/* START — ракета взлетает по кривой */
.pw-tbg-start{background:radial-gradient(120% 100% at 20% 90%,rgba(154,255,0,.12),transparent 55%),#0d1210}
:root[data-theme="light"] .pw-tbg-start{background:radial-gradient(120% 100% at 20% 90%,rgba(154,255,0,.16),transparent 55%),#eaf3df}
.pw-tbg-start svg{position:absolute;inset:0;width:100%;height:100%}
.pw-tbg-start .pw-trail{stroke:rgba(154,255,0,.55);stroke-width:1.6;fill:none;stroke-dasharray:3 5;stroke-linecap:round;animation:pwTrailDrift 3.2s linear infinite}
@keyframes pwTrailDrift{to{stroke-dashoffset:-16}}
.pw-tbg-start .pw-rocket{transform-box:fill-box;transform-origin:center;
  offset-path:path('M-10 92 Q 60 82 100 55 T 220 8');offset-rotate:auto;
  animation:pwRocketRun 4.8s cubic-bezier(.45,.1,.6,.9) infinite;will-change:transform}
@keyframes pwRocketRun{
  0%{offset-distance:0%;opacity:0}
  10%{opacity:1}
  92%{opacity:1}
  100%{offset-distance:100%;opacity:0}
}
.pw-tbg-start .pw-spark{position:absolute;left:8%;bottom:12%;width:6px;height:6px;border-radius:50%;
  background:var(--lime);box-shadow:0 0 12px var(--lime);animation:pwSpark 1.4s ease-out infinite}
@keyframes pwSpark{0%{transform:scale(.4);opacity:.8}100%{transform:scale(1.8);opacity:0}}

/* PRO — крутящиеся шестерёнки (transform:rotate infinite) */
.pw-tbg-pro{background:radial-gradient(110% 100% at 70% 40%,rgba(154,255,0,.14),transparent 60%),#0d1211}
:root[data-theme="light"] .pw-tbg-pro{background:radial-gradient(110% 100% at 70% 40%,rgba(154,255,0,.18),transparent 60%),#e8f2dc}
.pw-tbg-pro .pw-gear{position:absolute;color:rgba(154,255,0,.6);will-change:transform}
.pw-tbg-pro .pw-gear svg{width:100%;height:100%;display:block}
.pw-tbg-pro .pw-gear-a{width:70px;height:70px;left:18%;top:12%;animation:pwGearSpin 9s linear infinite}
.pw-tbg-pro .pw-gear-b{width:46px;height:46px;left:44%;top:44%;color:rgba(154,255,0,.4);animation:pwGearSpin 6s linear infinite reverse}
.pw-tbg-pro .pw-gear-c{width:36px;height:36px;left:66%;top:18%;color:rgba(154,255,0,.35);animation:pwGearSpin 12s linear infinite}
@keyframes pwGearSpin{to{transform:rotate(360deg)}}

/* BUSINESS — график и колонки, линия «рисуется» */
.pw-tbg-biz{background:radial-gradient(120% 100% at 100% 0%,rgba(154,255,0,.15),transparent 60%),#0d1210}
:root[data-theme="light"] .pw-tbg-biz{background:radial-gradient(120% 100% at 100% 0%,rgba(154,255,0,.20),transparent 60%),#e9f2db}
.pw-tbg-biz svg{position:absolute;inset:0;width:100%;height:100%}
.pw-tbg-biz .pw-bar{fill:rgba(154,255,0,.42);opacity:0;transform-origin:bottom;transform-box:fill-box;
  animation:pwBarRise 3.6s ease-in-out infinite;will-change:transform,opacity}
.pw-tbg-biz .pw-bar:nth-child(1){animation-delay:.05s}
.pw-tbg-biz .pw-bar:nth-child(2){animation-delay:.35s}
.pw-tbg-biz .pw-bar:nth-child(3){animation-delay:.65s}
.pw-tbg-biz .pw-bar:nth-child(4){animation-delay:.95s}
.pw-tbg-biz .pw-bar:nth-child(5){animation-delay:1.25s}
@keyframes pwBarRise{0%,15%{transform:scaleY(.2);opacity:0}30%,80%{transform:scaleY(1);opacity:1}95%,100%{transform:scaleY(.2);opacity:0}}
.pw-tbg-biz .pw-line{fill:none;stroke:var(--lime);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;
  stroke-dasharray:260;stroke-dashoffset:260;filter:drop-shadow(0 0 4px rgba(154,255,0,.6));
  animation:pwLineDraw 3.6s ease-in-out infinite}
@keyframes pwLineDraw{0%{stroke-dashoffset:260}45%,80%{stroke-dashoffset:0}100%{stroke-dashoffset:-260}}
.pw-tbg-biz .pw-dot{fill:var(--lime);opacity:0;animation:pwDotPop 3.6s ease infinite}
.pw-tbg-biz .pw-dot:nth-child(6){animation-delay:.4s}
.pw-tbg-biz .pw-dot:nth-child(7){animation-delay:.8s}
.pw-tbg-biz .pw-dot:nth-child(8){animation-delay:1.2s}
.pw-tbg-biz .pw-dot:nth-child(9){animation-delay:1.6s}
@keyframes pwDotPop{0%,20%{opacity:0;transform:scale(.4)}45%,80%{opacity:1;transform:scale(1)}95%,100%{opacity:0;transform:scale(.4)}}

/* BUSINESS PRO — студийный свет: пульсирующие цветные орбы + мягкие «колбы» */
.pw-tbg-bizpro{background:radial-gradient(90% 80% at 20% 20%,rgba(154,255,0,.12),transparent 60%),
  radial-gradient(90% 80% at 90% 90%,rgba(154,255,0,.10),transparent 60%),#0b100d}
:root[data-theme="light"] .pw-tbg-bizpro{background:radial-gradient(90% 80% at 20% 20%,rgba(154,255,0,.20),transparent 60%),
  radial-gradient(90% 80% at 90% 90%,rgba(154,255,0,.16),transparent 60%),#e6efd8}
.pw-tbg-bizpro .pw-orb{position:absolute;border-radius:50%;filter:blur(14px);opacity:.75;will-change:transform,opacity;mix-blend-mode:screen}
.pw-tbg-bizpro .pw-orb-a{width:80px;height:80px;left:12%;top:14%;background:radial-gradient(closest-side,rgba(154,255,0,.9),rgba(154,255,0,0));animation:pwOrbPulse 4.4s ease-in-out infinite}
.pw-tbg-bizpro .pw-orb-b{width:64px;height:64px;left:52%;top:44%;background:radial-gradient(closest-side,rgba(255,255,255,.6),rgba(255,255,255,0));animation:pwOrbPulse 5.6s ease-in-out infinite -1.4s}
.pw-tbg-bizpro .pw-orb-c{width:100px;height:100px;left:64%;top:8%;background:radial-gradient(closest-side,rgba(154,255,0,.55),rgba(154,255,0,0));animation:pwOrbPulse 6.8s ease-in-out infinite -2.8s}
@keyframes pwOrbPulse{0%,100%{transform:scale(.85);opacity:.5}50%{transform:scale(1.15);opacity:.95}}
.pw-tbg-bizpro .pw-ray{position:absolute;left:50%;top:-15%;width:60%;height:150%;
  background:linear-gradient(180deg,rgba(154,255,0,.28),transparent 70%);
  transform-origin:top center;transform:translateX(-50%) rotate(0deg);filter:blur(6px);
  animation:pwRaySweep 8s ease-in-out infinite;will-change:transform;opacity:.6}
@keyframes pwRaySweep{0%,100%{transform:translateX(-50%) rotate(-14deg)}50%{transform:translateX(-50%) rotate(14deg)}}

/* MAX — звёздное небо (radial-gradient + твинкл, без canvas) */
.pw-tbg-max{background:radial-gradient(120% 100% at 50% 50%,#12160f,#050603 90%)}
:root[data-theme="light"] .pw-tbg-max{background:radial-gradient(120% 100% at 50% 50%,#1a1f14,#0a0d05 90%)}
.pw-tbg-max .pw-stars{position:absolute;inset:0;background-image:
  radial-gradient(1.4px 1.4px at 12% 22%,#fff,transparent 55%),
  radial-gradient(1px 1px at 28% 68%,#fff,transparent 55%),
  radial-gradient(1.6px 1.6px at 44% 34%,var(--lime),transparent 55%),
  radial-gradient(1px 1px at 62% 12%,#fff,transparent 55%),
  radial-gradient(1.2px 1.2px at 74% 74%,#fff,transparent 55%),
  radial-gradient(1.6px 1.6px at 88% 26%,var(--lime),transparent 55%),
  radial-gradient(1px 1px at 8% 78%,#fff,transparent 55%),
  radial-gradient(1.4px 1.4px at 36% 88%,#fff,transparent 55%),
  radial-gradient(1px 1px at 56% 58%,#fff,transparent 55%),
  radial-gradient(1.2px 1.2px at 82% 62%,var(--lime),transparent 55%),
  radial-gradient(1px 1px at 20% 46%,#fff,transparent 55%),
  radial-gradient(1.4px 1.4px at 70% 40%,#fff,transparent 55%),
  radial-gradient(1px 1px at 96% 82%,#fff,transparent 55%),
  radial-gradient(1px 1px at 4% 8%,#fff,transparent 55%);
  animation:pwStarTwinkle 3.4s ease-in-out infinite alternate;will-change:opacity}
.pw-tbg-max .pw-stars.b{animation-duration:4.8s;animation-delay:-1.6s;
  background-image:
  radial-gradient(1px 1px at 18% 12%,#fff,transparent 55%),
  radial-gradient(1.2px 1.2px at 50% 22%,var(--lime),transparent 55%),
  radial-gradient(1px 1px at 82% 44%,#fff,transparent 55%),
  radial-gradient(1.4px 1.4px at 66% 68%,#fff,transparent 55%),
  radial-gradient(1px 1px at 30% 58%,#fff,transparent 55%),
  radial-gradient(1px 1px at 46% 82%,#fff,transparent 55%),
  radial-gradient(1.2px 1.2px at 78% 88%,var(--lime),transparent 55%),
  radial-gradient(1px 1px at 90% 12%,#fff,transparent 55%)}
@keyframes pwStarTwinkle{0%{opacity:.4}100%{opacity:1}}
.pw-tbg-max .pw-comet{position:absolute;top:24%;left:-20%;width:60%;height:2px;
  background:linear-gradient(90deg,transparent,var(--lime),transparent);
  filter:blur(.5px);animation:pwCometFly 6.2s ease-in infinite;transform:rotate(-12deg);opacity:0;will-change:transform,opacity}
@keyframes pwCometFly{0%{transform:translate3d(-40%,-10%,0) rotate(-12deg);opacity:0}
  10%{opacity:1}40%,100%{transform:translate3d(220%,180%,0) rotate(-12deg);opacity:0}}

/* при выборе — фон карточки чуть ярче */
.pw-tier.on .pw-tbg{filter:saturate(1.15) brightness(1.06)}

/* уважение reduced-motion — статичный кадр */
@media(prefers-reduced-motion:reduce){
  .pw-tbg-free .pw-bub,
  .pw-tbg-start .pw-rocket,.pw-tbg-start .pw-trail,.pw-tbg-start .pw-spark,
  .pw-tbg-pro .pw-gear,
  .pw-tbg-biz .pw-bar,.pw-tbg-biz .pw-line,.pw-tbg-biz .pw-dot,
  .pw-tbg-bizpro .pw-orb,.pw-tbg-bizpro .pw-ray,
  .pw-tbg-max .pw-stars,.pw-tbg-max .pw-comet{animation:none!important}
  .pw-tbg-biz .pw-line{stroke-dashoffset:0}
  .pw-tbg-start .pw-rocket{offset-distance:60%}
}

/* пометка «сейчас у тебя» на карточке текущего тарифа */
.pw-tier-cur-badge{position:absolute;top:9px;left:9px;z-index:3;font-size:9px;font-weight:800;
  letter-spacing:.08em;text-transform:uppercase;color:#0a0a0a;background:rgba(255,255,255,.9);
  padding:4px 8px;border-radius:99px;box-shadow:0 4px 10px rgba(0,0,0,.35)}
:root[data-theme="light"] .pw-tier-cur-badge{background:var(--surface);color:var(--text);border:1px solid var(--border)}

/* фикс: центрируем «MAX-флаг» повыше, чтоб не наезжал на анимацию */
.pw-tier .pw-flag{top:9px;right:9px}

/* компакт-цена в карточке — тонкий разделитель */
.pw-tier-price{border-top:1px solid var(--border);padding:11px 14px 4px}
.pw-tier-price b{font-size:23px}
.pw-tier-price .pw-per{margin-left:auto;font-size:11px;color:var(--accent);font-weight:800}
.pw-tier .pw-tier-cap .n{font-size:24px}
.pw-tier .pw-tier-cap .s{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* «Скидочные чипы» строкой над свайпером */
.pw-disc-row{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:0 0 12px}
.pw-disc-row .chip{font-size:11px;font-weight:700;padding:6px 11px;border-radius:99px;
  background:var(--raised);border:1px solid var(--border);color:var(--text);cursor:pointer;transition:.18s}
.pw-disc-row .chip.on{background:var(--lime-dim);border-color:var(--lime);color:var(--accent)}
.pw-disc-row .chip i{font-style:normal;color:var(--accent);font-weight:800;margin-left:4px}

/* ============================================================
   PAYWALL EXTRAS: универсальная модалка + trial + cross-sell +
   bundles + micro-subs + LTV + 14-day guarantee
   ============================================================ */

/* ------- Универсальная модалка (bottom-sheet + center на десктопе) ------- */
.pw-modal{position:fixed;inset:0;z-index:120;display:flex;align-items:flex-end;justify-content:center;
  background:rgba(0,0,0,.66);backdrop-filter:blur(4px);opacity:0;transition:opacity .22s ease}
@media(min-width:560px){.pw-modal{align-items:center}}
.pw-modal.on{opacity:1}
.pw-modal-card{position:relative;width:100%;max-width:460px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-lg) var(--r-lg) 0 0;overflow:hidden;
  box-shadow:0 -20px 70px rgba(0,0,0,.6);max-height:94dvh;overflow-y:auto;
  transform:translateY(40px);transition:transform .32s cubic-bezier(.25,1,.4,1)}
@media(min-width:560px){.pw-modal-card{border-radius:var(--r-lg);transform:scale(.96)}}
.pw-modal.on .pw-modal-card{transform:translateY(0)}
@media(min-width:560px){.pw-modal.on .pw-modal-card{transform:scale(1)}}
.pw-modal-x{position:absolute;top:12px;right:12px;z-index:5;width:34px;height:34px;border-radius:50%;
  background:rgba(0,0,0,.42);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;
  color:#fff;transition:transform .15s,background .2s}
.pw-modal-x svg{width:16px;height:16px;transform:rotate(45deg)}
.pw-modal-x:active{transform:scale(.9)}
:root[data-theme="light"] .pw-modal-x{background:rgba(0,0,0,.55)}

/* ------- FREE-TRIAL PRO ------- */
.pw-trial{padding:0}
.pw-trial-hero{position:relative;padding:28px 20px 22px;text-align:center;overflow:hidden;
  background:linear-gradient(160deg,#0a0a0a 0%,#1a2810 55%,#0a0a0a 100%)}
.pw-trial-ray{position:absolute;inset:auto -20% -60% -20%;height:220%;
  background:radial-gradient(ellipse at 50% 50%, rgba(154,255,0,.28) 0%, transparent 55%);pointer-events:none;
  animation:pwTrialPulse 4.5s ease-in-out infinite alternate}
@keyframes pwTrialPulse{from{transform:scale(.9);opacity:.65}to{transform:scale(1.1);opacity:1}}
.pw-trial-badge{position:relative;width:60px;height:60px;margin:0 auto 12px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  background:rgba(0,0,0,.42);border:2px solid var(--lime);box-shadow:0 0 32px rgba(154,255,0,.4)}
.pw-trial-badge svg{width:28px;height:28px;color:var(--lime)}
.pw-trial-days{position:relative;display:inline-flex;align-items:baseline;gap:8px;margin-bottom:6px}
.pw-trial-days b{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:82px;line-height:.9;
  color:var(--lime);letter-spacing:.02em;text-shadow:0 0 24px rgba(154,255,0,.5)}
.pw-trial-days span{font-size:16px;font-weight:800;color:#fff;letter-spacing:.06em;text-transform:uppercase}
.pw-trial-h1{position:relative;font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:36px;
  color:#fff;letter-spacing:.02em;line-height:1;margin-bottom:6px}
:root[data-theme="light"] .pw-trial-hero{background:linear-gradient(160deg,#0f1608 0%,#1b2810 55%,#0f1608 100%)}
.pw-trial-sub{position:relative;font-size:13.5px;color:rgba(255,255,255,.72);line-height:1.45;
  max-width:340px;margin:0 auto}
.pw-trial-body{padding:16px 18px calc(18px + env(safe-area-inset-bottom))}
.pw-trial-list{list-style:none;padding:0;margin:0 0 14px;display:flex;flex-direction:column;gap:10px}
.pw-trial-list li{display:flex;gap:10px;align-items:flex-start;font-size:13.5px;line-height:1.45;color:var(--dim)}
.pw-trial-list li b{color:var(--text)}
.pw-trial-list li svg{width:16px;height:16px;color:var(--lime);flex:none;margin-top:2px}
.pw-trial-note{display:flex;gap:8px;align-items:flex-start;font-size:11.5px;color:var(--dim);
  background:var(--raised);border:1px solid var(--border);border-radius:10px;padding:9px 11px;margin-bottom:12px;line-height:1.45}
.pw-trial-note svg{width:13px;height:13px;color:var(--accent);flex:none;margin-top:1px}
.pw-trial-cta{margin-bottom:8px}
.pw-trial-skip{opacity:.7}

/* индикатор Trial PRO в pw-prof-band */
.pw-trial-badge-inline{display:inline-flex;align-items:center;gap:4px;margin-left:6px;
  background:var(--lime-dim);color:var(--accent);border:1px solid var(--lime);
  border-radius:99px;padding:2px 8px;font-size:10.5px;font-weight:800;letter-spacing:.04em}
.pw-trial-badge-inline svg{width:10px;height:10px;color:var(--accent)}

/* «Продли со скидкой» — цена в попапе */
.pw-trial-renew-box{position:relative;display:flex;align-items:center;gap:12px;padding:14px 16px;
  background:var(--raised);border:1px solid var(--border);border-radius:14px;margin-bottom:6px}
.pw-trial-renew-old{font-size:14px;color:var(--dim);text-decoration:line-through}
.pw-trial-renew-new b{font-size:26px;color:var(--accent);font-weight:800;letter-spacing:-.01em}
.pw-trial-renew-new span{display:block;font-size:11px;color:var(--dim);margin-top:1px}
.pw-trial-renew-tag{margin-left:auto;background:var(--lime);color:#0a0a0a;font-size:12px;font-weight:800;
  border-radius:99px;padding:4px 10px;letter-spacing:.03em}

/* ------- CROSS-SELL ------- */
.pw-cross{padding:22px 18px calc(18px + env(safe-area-inset-bottom))}
.pw-cross-top{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.pw-cross-ic{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;
  background:var(--lime-dim);color:var(--accent)}
.pw-cross-ic svg{width:20px;height:20px}
.pw-cross-pill{margin-left:auto;background:var(--lime);color:#0a0a0a;font-size:11px;font-weight:800;
  border-radius:99px;padding:5px 10px;letter-spacing:.03em}
.pw-cross-h{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:26px;line-height:1;
  letter-spacing:.01em;margin:4px 0 4px}
.pw-cross-sub{font-size:13.5px;color:var(--dim);line-height:1.5;margin-bottom:12px}
.pw-cross-list{list-style:none;padding:0;margin:0 0 14px;display:flex;flex-direction:column;gap:8px}
.pw-cross-list li{display:flex;gap:9px;align-items:flex-start;font-size:13px;line-height:1.45;color:var(--text)}
.pw-cross-list li svg{width:14px;height:14px;color:var(--accent);flex:none;margin-top:3px}
.pw-cross-price{display:flex;align-items:baseline;gap:10px;padding:12px 14px;background:var(--raised);
  border:1px solid var(--border);border-radius:14px;margin-bottom:12px}
.pw-cross-old{font-size:15px;color:var(--dim);text-decoration:line-through}
.pw-cross-new{font-size:28px;font-weight:800;color:var(--accent);letter-spacing:-.01em}
.pw-cross-save{margin-left:auto;background:var(--lime-dim);color:var(--accent);font-size:12px;font-weight:800;
  border-radius:99px;padding:4px 10px;border:1px solid var(--lime)}
.pw-cross-cta{margin-bottom:8px}

/* ------- BUNDLES / MICRO-SUBS ------- */
.bnd-sheet{padding:22px 18px calc(20px + env(safe-area-inset-bottom))}
.bnd-head{margin-bottom:14px;padding-right:36px}
.bnd-head-k{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);font-weight:800;
  display:flex;align-items:center;gap:6px}
.bnd-head-k svg{width:12px;height:12px}
.bnd-head h2{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:26px;line-height:1;
  letter-spacing:.01em;margin:6px 0 4px}
.bnd-head p{font-size:13px;color:var(--dim);line-height:1.5}
.bnd-list{display:flex;flex-direction:column;gap:12px}
.bnd-card{position:relative;background:var(--raised);border:1px solid var(--border);border-radius:16px;
  padding:14px 14px 12px;overflow:hidden}
.bnd-card::before{content:'';position:absolute;inset:auto -30% -60% -30%;height:120px;
  background:radial-gradient(ellipse at 50% 50%, rgba(154,255,0,.14) 0%, transparent 60%);pointer-events:none}
.bnd-card-top{display:flex;align-items:center;gap:8px;margin-bottom:8px;position:relative}
.bnd-card-ic{width:34px;height:34px;border-radius:10px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center}
.bnd-card-ic svg{width:16px;height:16px}
.bnd-card-tag{font-size:11px;color:var(--dim);font-weight:700;letter-spacing:.03em}
.bnd-card-disc{margin-left:auto;background:var(--lime);color:#0a0a0a;font-size:11px;font-weight:800;
  border-radius:99px;padding:4px 9px;letter-spacing:.03em}
.bnd-card-h{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:24px;line-height:1;
  letter-spacing:.01em;margin:2px 0 8px;position:relative}
.bnd-card-list{list-style:none;padding:0;margin:0 0 12px;display:flex;flex-direction:column;gap:6px;position:relative}
.bnd-card-list li{display:flex;gap:8px;align-items:flex-start;font-size:12.5px;color:var(--text);line-height:1.4}
.bnd-card-list li svg{width:12px;height:12px;color:var(--accent);flex:none;margin-top:3px}
.bnd-card-price{display:flex;align-items:baseline;gap:8px;padding:10px 12px;background:var(--surface);
  border:1px solid var(--border);border-radius:12px;margin-bottom:10px;position:relative}
.bnd-old{font-size:13px;color:var(--dim);text-decoration:line-through}
.bnd-new{margin-left:auto}
.bnd-new b{font-size:22px;font-weight:800;color:var(--accent);letter-spacing:-.01em}
.bnd-new span{font-size:11px;color:var(--dim);margin-left:2px}
.bnd-cta{position:relative}
.bnd-note{margin-top:14px;font-size:11.5px;color:var(--dim);text-align:center;
  display:flex;gap:6px;align-items:center;justify-content:center}
.bnd-note svg{width:12px;height:12px;color:var(--accent)}

/* Микро-подписки — компакт-строка */
.bnd-micro-list{display:flex;flex-direction:column;gap:10px}
.bnd-micro-card{display:grid;grid-template-columns:40px 1fr auto;gap:10px;align-items:flex-start;
  background:var(--raised);border:1px solid var(--border);border-radius:14px;padding:12px}
.bnd-micro-ic{width:40px;height:40px;border-radius:10px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center}
.bnd-micro-ic svg{width:18px;height:18px}
.bnd-micro-body{min-width:0}
.bnd-micro-h{font-size:14px;font-weight:800;color:var(--text)}
.bnd-micro-sub{font-size:12px;color:var(--dim);margin-top:1px;line-height:1.4}
.bnd-micro-feats{list-style:none;padding:0;margin:8px 0 0;display:flex;flex-direction:column;gap:4px}
.bnd-micro-feats li{display:flex;gap:6px;align-items:flex-start;font-size:11.5px;color:var(--dim);line-height:1.35}
.bnd-micro-feats li svg{width:10px;height:10px;color:var(--accent);flex:none;margin-top:3px}
.bnd-micro-price{text-align:right;display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.bnd-micro-price b{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:24px;color:var(--accent);line-height:1;letter-spacing:.01em}
.bnd-micro-price span{font-size:10.5px;color:var(--dim);margin-top:-3px}
.bnd-micro-cta{padding:8px 12px;font-size:12px;white-space:nowrap;min-width:104px}
.bnd-micro-cta svg{width:11px;height:11px}

/* Entry-кнопки в профиле (Комбо-пакеты / Микро-подписки) */
.bnd-entry{display:flex;flex-direction:column;gap:8px;margin:10px 0 6px}
.bnd-entry-btn{display:grid;grid-template-columns:40px 1fr 18px;gap:12px;align-items:center;
  background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:11px 13px;
  cursor:pointer;text-align:left;transition:border-color .18s,transform .12s,background .18s}
.bnd-entry-btn:active{transform:scale(.99)}
.bnd-entry-btn:hover{border-color:var(--lime);background:var(--raised)}
.bnd-entry-ic{width:40px;height:40px;border-radius:12px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center}
.bnd-entry-ic-alt{background:linear-gradient(135deg,#9AFF00 0%,#7bcf00 100%);color:#0a0a0a}
.bnd-entry-ic svg{width:18px;height:18px}
.bnd-entry-tx{min-width:0}
.bnd-entry-tx b{display:block;font-size:14px;font-weight:800;color:var(--text)}
.bnd-entry-tx small{display:block;font-size:11.5px;color:var(--dim);margin-top:2px;line-height:1.4}
.bnd-entry-chev{color:var(--dim);display:flex;align-items:center;justify-content:center}
.bnd-entry-chev svg{width:14px;height:14px;transform:rotate(-90deg)}

/* ------- LTV report card ------- */
.pw-ltv{margin:14px 0 6px;padding:16px 16px 14px;background:var(--surface);border:1px solid var(--border);
  border-radius:16px;position:relative;overflow:hidden}
.pw-ltv::before{content:'';position:absolute;inset:auto -20% -60% -20%;height:180px;
  background:radial-gradient(ellipse at 30% 50%, rgba(154,255,0,.18) 0%, transparent 60%);pointer-events:none}
.pw-ltv-head{display:flex;gap:11px;align-items:flex-start;margin-bottom:8px;position:relative}
.pw-ltv-ic{width:38px;height:38px;border-radius:11px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center;flex:none}
.pw-ltv-ic svg{width:18px;height:18px}
.pw-ltv-cap b{display:block;font-size:14px;font-weight:800;color:var(--text)}
.pw-ltv-cap small{display:block;font-size:11.5px;color:var(--dim);margin-top:2px;line-height:1.4}
.pw-ltv-big{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:46px;line-height:1;
  letter-spacing:.01em;color:var(--accent);margin:8px 0 6px;position:relative;
  text-shadow:0 2px 20px rgba(154,255,0,.35)}
.pw-ltv-hours{font-size:12px;color:var(--dim);display:flex;align-items:center;gap:5px;margin-bottom:12px;position:relative}
.pw-ltv-hours svg{width:12px;height:12px;color:var(--accent)}
.pw-ltv-split{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;position:relative}
.pw-ltv-cell{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:10px 11px}
.pw-ltv-c-l{font-size:10.5px;color:var(--dim);font-weight:700;letter-spacing:.03em;text-transform:uppercase}
.pw-ltv-c-v{font-size:17px;font-weight:800;color:var(--text);letter-spacing:-.01em;margin:3px 0 6px}
.pw-ltv-bar{height:5px;border-radius:99px;background:var(--border);overflow:hidden}
.pw-ltv-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--lime) 0%,#c4ff5c 100%);
  border-radius:99px;transition:width .8s ease}
.pw-ltv-share{position:relative;padding:9px 12px;font-size:12.5px;width:100%}
.pw-ltv-share svg{width:12px;height:12px}

/* ------- 14-day guarantee banner на checkout ------- */
.pw-14d-guar{display:flex;gap:10px;align-items:flex-start;background:var(--lime-dim);
  border:1px solid var(--lime);border-radius:12px;padding:10px 12px;margin:12px 0 10px}
.pw-14d-ic{width:26px;height:26px;border-radius:8px;background:var(--lime);color:#0a0a0a;
  display:flex;align-items:center;justify-content:center;flex:none}
.pw-14d-ic svg{width:13px;height:13px}
.pw-14d-tx b{display:block;font-size:13px;color:var(--accent);font-weight:800}
.pw-14d-tx small{display:block;font-size:11.5px;color:var(--dim);margin-top:2px;line-height:1.4}
:root[data-theme="light"] .pw-14d-guar{background:rgba(154,255,0,.12)}


/* ===== module: partner-plus ===== */
/* ===== PARTNER-PLUS: усиленный партнёрский кабинет ===== */

/* ----------- HERO-дашборд ----------- */
.pp-hero{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:18px 16px;margin-top:14px;position:relative;overflow:hidden}
.pp-hero::before{content:"";position:absolute;inset:0;background:radial-gradient(900px 220px at 0% -20%, var(--lime-dim), transparent 65%);pointer-events:none}
.pp-hero-lbl{font-size:12px;color:var(--dim);font-weight:600;letter-spacing:.02em;position:relative;display:flex;align-items:center;gap:8px}
.pp-hero-lbl .pp-hero-tag{display:inline-flex;align-items:center;gap:4px;background:var(--lime-dim);color:var(--accent);border-radius:99px;padding:3px 8px;font-size:10.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase}
.pp-hero-lbl .pp-hero-tag svg.i{width:11px;height:11px}
.pp-hero-num{font-family:var(--font-display, 'Bebas Neue', sans-serif);font-size:44px;font-weight:800;letter-spacing:-.01em;line-height:1;margin-top:6px;color:var(--text);position:relative}
.pp-hero-num .pp-hero-cur{font-size:24px;color:var(--accent);margin-left:6px;vertical-align:top;font-family:inherit}
.pp-hero-delta{font-size:12.5px;font-weight:700;color:var(--accent);margin-top:6px;position:relative;display:flex;align-items:center;gap:6px}
.pp-hero-delta svg.i{width:12px;height:12px}
.pp-hero-delta.down{color:var(--danger,#ff6b6b)}
.pp-hero-spark{position:relative;margin-top:12px;height:56px;width:100%}
.pp-hero-spark svg{display:block;width:100%;height:100%;overflow:visible}
.pp-hero-cta{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:6px;margin-top:14px;position:relative}
.pp-hero-cta .btn{padding:12px 10px;font-size:13px;white-space:nowrap;width:auto;min-width:0;text-overflow:ellipsis;overflow:hidden;max-width:100%}
.pp-hero-cta .btn.icon-only{padding:12px;min-width:44px;flex:0 0 auto}
.pp-hero-cta .btn.icon-only svg.i{margin:0}
@media(max-width:400px){.pp-hero-cta .btn:not(.icon-only) svg.i{margin-right:4px}}

/* Микро-статы под hero */
.pp-microstat{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-top:12px;position:relative}
.pp-microstat > div{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:10px 8px;text-align:center;min-width:0}
.pp-microstat .v{font-size:16px;font-weight:800;letter-spacing:-.01em;color:var(--text);line-height:1.1}
.pp-microstat .l{font-size:10.5px;color:var(--dim);margin-top:3px;font-weight:600;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}
.pp-microstat .v.lime{color:var(--accent)}

/* Топ-3 источника */
.pp-sources{margin-top:12px;position:relative}
.pp-sources-h{font-size:12.5px;color:var(--dim);font-weight:700;margin-bottom:8px;display:flex;justify-content:space-between}
.pp-src-row{display:grid;grid-template-columns:22px 1fr auto;gap:10px;align-items:center;padding:7px 0;font-size:13px}
.pp-src-ico{width:22px;height:22px;border-radius:6px;display:flex;align-items:center;justify-content:center;color:#000}
.pp-src-ico svg.i{width:13px;height:13px}
.pp-src-ico.s-ig{background:linear-gradient(135deg,#f77b3f,#c73dab)}
.pp-src-ico.s-tg{background:linear-gradient(135deg,#2ba9f2,#005eaa);color:#fff}
.pp-src-ico.s-yt{background:#ff2c2c;color:#fff}
.pp-src-ico.s-vk{background:#3f7cbf;color:#fff}
.pp-src-ico.s-dir{background:var(--lime);color:#000}
.pp-src-name{font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pp-src-name .dim{font-weight:500;margin-left:4px}
.pp-src-sum{font-weight:800;color:var(--accent);font-size:13px;white-space:nowrap}
.pp-src-bar{grid-column:2 / 4;height:5px;background:var(--raised);border-radius:99px;overflow:hidden;margin-top:2px}
.pp-src-bar i{display:block;height:100%;background:linear-gradient(90deg,#7ACC00,var(--lime));border-radius:99px;transition:width .6s ease}

/* ----------- Turnover-лестница ----------- */
.pp-tier{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:16px;margin-top:12px;position:relative;overflow:hidden}
.pp-tier::before{content:"";position:absolute;inset:0;background:radial-gradient(1200px 220px at -10% -50%, var(--lime-dim), transparent 60%);pointer-events:none}
.pp-tier-row{display:flex;align-items:center;justify-content:space-between;gap:12px;position:relative}
.pp-tier-name{display:flex;align-items:center;gap:10px;font-weight:800;font-size:15px}
.pp-tier-badge{width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;color:#000;flex-shrink:0}
.pp-tier-badge.junior{background:linear-gradient(135deg,#4a5568,#2d3748);color:#fff}
.pp-tier-badge.middle{background:linear-gradient(135deg,#c98a5a,#8a5230)}
.pp-tier-badge.senior{background:linear-gradient(135deg,#e6e6e6,#8f8f8f);color:#111}
.pp-tier-badge.pro{background:linear-gradient(135deg,#ffd93a,#c98a10);color:#111}
.pp-tier-badge.legend{background:radial-gradient(circle at 30% 30%,#c8ff5a,#9AFF00 50%,#3f7000);color:#000;box-shadow:0 0 22px rgba(154,255,0,.5)}
.pp-tier-badge svg.i{width:18px;height:18px}
.pp-tier-percent{background:var(--lime-dim);color:var(--accent);border-radius:99px;padding:5px 10px;font-size:11.5px;font-weight:800;letter-spacing:.04em;display:inline-flex;align-items:center;gap:4px}
.pp-tier-sales{font-weight:800;font-size:14px;color:var(--dim)}
.pp-tier-sales b{color:var(--text)}
.pp-tier-bar{height:10px;background:var(--raised);border-radius:99px;margin-top:12px;position:relative;overflow:hidden}
.pp-tier-bar i{position:absolute;left:0;top:0;bottom:0;background:linear-gradient(90deg,#7ACC00,var(--lime));border-radius:99px;transition:width .5s ease;box-shadow:0 0 12px rgba(154,255,0,.4)}
.pp-tier-sub{display:flex;justify-content:space-between;font-size:11.5px;color:var(--dim);margin-top:8px;font-weight:600}
.pp-tier-note{font-size:12.5px;color:var(--dim);margin-top:10px;line-height:1.5;position:relative}
.pp-tier-note b{color:var(--accent)}

/* Лестница уровней */
.pp-ladder{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-top:12px;position:relative}
.pp-ladder-cell{background:var(--raised);border:1px solid var(--border);border-radius:10px;padding:9px 6px;text-align:center;font-size:10px;font-weight:700;color:var(--dim);line-height:1.15;transition:all .2s;cursor:default;min-width:0}
.pp-ladder-cell.on{background:var(--lime);color:#000;border-color:var(--lime);box-shadow:0 4px 12px rgba(154,255,0,.25)}
.pp-ladder-cell.done{background:var(--lime-dim);color:var(--accent);border-color:var(--accent)}
.pp-ladder-cell .lv-name{font-size:11px;font-weight:800;letter-spacing:.02em;display:block;margin-bottom:2px;text-transform:uppercase}
.pp-ladder-cell .lv-pct{font-size:9.5px;opacity:.85;letter-spacing:.02em}

/* ----------- Мульти-tier калькулятор ----------- */
.pp-calc{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:16px;margin-top:12px}
.pp-calc-h{font-weight:800;font-size:15px;margin-bottom:2px}
.pp-calc-sub{font-size:12px;color:var(--dim);margin-bottom:14px;line-height:1.5}
.pp-calc-prod{display:flex;gap:6px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none;margin-bottom:14px;padding-bottom:2px}
.pp-calc-prod::-webkit-scrollbar{display:none}
.pp-calc-prod button{flex:0 0 auto;background:var(--raised);border:1px solid var(--border);color:var(--text);font-size:12px;font-weight:700;padding:8px 12px;border-radius:99px;white-space:nowrap;cursor:pointer;transition:all .15s}
.pp-calc-prod button.on{background:var(--lime);color:#000;border-color:var(--lime)}
.pp-calc-row{display:flex;align-items:center;justify-content:space-between;padding:8px 0}
.pp-calc-label{font-size:13px;color:var(--dim);font-weight:600}
.pp-calc-stepper{display:inline-flex;align-items:center;background:var(--raised);border:1px solid var(--border);border-radius:12px;overflow:hidden}
.pp-calc-stepper button{background:transparent;border:none;color:var(--text);width:36px;height:36px;font-size:20px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1}
.pp-calc-stepper button:active{background:var(--lime-dim)}
.pp-calc-stepper .val{min-width:44px;text-align:center;font-weight:800;font-size:16px;padding:0 6px;color:var(--text)}
.pp-calc-slider{width:100%;margin-top:8px;-webkit-appearance:none;background:var(--raised);height:6px;border-radius:99px;outline:none}
.pp-calc-slider::-webkit-slider-thumb{-webkit-appearance:none;width:22px;height:22px;background:var(--lime);border-radius:50%;box-shadow:0 2px 8px rgba(154,255,0,.5);cursor:pointer}
.pp-calc-slider::-moz-range-thumb{width:22px;height:22px;background:var(--lime);border-radius:50%;box-shadow:0 2px 8px rgba(154,255,0,.5);cursor:pointer;border:none}
.pp-calc-result{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:14px;margin-top:12px}
.pp-calc-result-line{display:flex;justify-content:space-between;font-size:13px;padding:5px 0;color:var(--dim)}
.pp-calc-result-line b{color:var(--text);font-weight:700}
.pp-calc-result-total{display:flex;justify-content:space-between;align-items:baseline;padding-top:10px;margin-top:6px;border-top:1px solid var(--border);font-size:14px;font-weight:700}
.pp-calc-result-total b{color:var(--accent);font-size:22px;font-weight:800}
.pp-calc-hint{font-size:11.5px;color:var(--dim);margin-top:10px;text-align:center;line-height:1.5}

/* ----------- Реф-ссылки ----------- */
.pp-deep{margin-top:12px}
.pp-deep-tabs{display:flex;gap:6px;margin-bottom:10px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.pp-deep-tabs::-webkit-scrollbar{display:none}
.pp-deep-tabs button{flex:0 0 auto;background:var(--raised);border:1px solid var(--border);color:var(--text);font-size:12px;font-weight:700;padding:8px 12px;border-radius:99px;white-space:nowrap;cursor:pointer;transition:all .15s;display:inline-flex;align-items:center;gap:5px}
.pp-deep-tabs button.on{background:var(--lime);color:#000;border-color:var(--lime)}
.pp-deep-tabs button .dot{width:6px;height:6px;border-radius:50%;background:var(--accent)}
.pp-deep-tabs button.on .dot{background:#000}
.pp-ref-actions{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;margin-top:10px}
.pp-ref-actions .btn{padding:11px 12px;font-size:13px;white-space:nowrap;width:auto;min-width:0;text-overflow:ellipsis;overflow:hidden;max-width:100%}
.pp-ref-actions .btn.icon-only{padding:11px 12px;min-width:44px;flex:0 0 auto}
.pp-ref-actions .btn.icon-only svg.i{margin:0}
.pp-ref-hint{font-size:11.5px;color:var(--dim);margin-top:8px;line-height:1.5}
.pp-ref-badge{display:inline-block;background:var(--lime-dim);color:var(--accent);border-radius:6px;padding:2px 6px;font-size:11px;font-weight:800;letter-spacing:.02em;margin-left:6px}

/* QR-модалка */
.pp-qr-wrap{display:flex;flex-direction:column;align-items:center;padding:12px 0 4px}
.pp-qr{background:#fff;padding:16px;border-radius:16px;box-shadow:0 8px 32px rgba(0,0,0,.4)}
.pp-qr svg{display:block;width:220px;height:220px}
.pp-qr-url{margin-top:14px;font-size:12.5px;color:var(--dim);text-align:center;word-break:break-all;padding:0 8px;line-height:1.5}
.pp-qr-tip{font-size:12px;color:var(--dim);text-align:center;margin-top:8px}

/* ----------- Промо-материалы ----------- */
.pp-promo-tabs{display:flex;gap:6px;margin:10px 0;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.pp-promo-tabs::-webkit-scrollbar{display:none}
.pp-promo-tabs button{flex:0 0 auto;background:var(--raised);border:1px solid var(--border);color:var(--text);font-size:12px;font-weight:700;padding:7px 12px;border-radius:99px;white-space:nowrap;cursor:pointer}
.pp-promo-tabs button.on{background:var(--lime);color:#000;border-color:var(--lime)}
.pp-promo-grid{display:grid;grid-template-columns:repeat(2, 1fr);gap:10px}
.pp-promo-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;overflow:hidden;cursor:pointer;transition:transform .15s, border-color .15s;position:relative}
.pp-promo-card:active{transform:scale(.98)}
.pp-promo-card:hover{border-color:var(--accent)}
.pp-promo-thumb{aspect-ratio:1/1;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;color:#fff;text-align:center;padding:14px;font-weight:800;line-height:1.15}
.pp-promo-thumb.g1{background:linear-gradient(135deg,#000 0%,#1a1a1a 50%,#0d2100 100%)}
.pp-promo-thumb.g2{background:linear-gradient(135deg,#9AFF00 0%,#5aa000 100%);color:#000}
.pp-promo-thumb.g3{background:radial-gradient(circle at 30% 30%,#9AFF00,transparent 60%),#111;color:#fff}
.pp-promo-thumb.g4{background:linear-gradient(180deg,#111 0%,#000 100%);color:#fff;border:1px solid var(--lime-dim)}
.pp-promo-thumb.g5{background:linear-gradient(135deg,#2a2a2a 0%,#000 100%);color:var(--lime)}
.pp-promo-thumb.g6{background:linear-gradient(45deg,#9AFF00 0%,#000 100%);color:#fff}
.pp-promo-thumb.g7{background:linear-gradient(135deg,#0057ff,#001a4c);color:#fff}
.pp-promo-thumb.g8{background:linear-gradient(135deg,#ff8a00,#c73dab);color:#fff}
.pp-promo-thumb.g9{background:linear-gradient(135deg,#111 0%,#9AFF00 200%);color:#fff}
.pp-promo-thumb .pp-promo-h{font-size:15px;letter-spacing:-.01em}
.pp-promo-thumb .pp-promo-sub{font-size:10.5px;font-weight:600;opacity:.75;margin-top:6px;letter-spacing:.03em;text-transform:uppercase}
.pp-promo-thumb .pp-promo-logo{position:absolute;left:8px;bottom:8px;font-weight:800;font-size:11px;opacity:.85;letter-spacing:.1em}
.pp-promo-thumb .pp-promo-fmt{position:absolute;right:8px;top:8px;font-size:9px;font-weight:800;background:rgba(0,0,0,.55);color:#fff;padding:3px 6px;border-radius:6px;letter-spacing:.04em}
.pp-promo-meta{padding:10px 12px;display:flex;justify-content:space-between;align-items:center;font-size:11.5px;font-weight:600}
.pp-promo-meta .dim{color:var(--dim)}
.pp-promo-kind-tag{display:inline-block;font-size:9.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;padding:2px 6px;border-radius:5px;background:var(--lime-dim);color:var(--accent)}
.pp-promo-kind-tag.reels{background:rgba(255,42,42,.14);color:#ff5a5a}
.pp-promo-kind-tag.banner{background:rgba(0,120,255,.14);color:#3f8bff}

/* Промо-сит: копирование текста */
.pp-promo-view h3{margin-bottom:4px}
.pp-promo-preview{margin:8px 0 14px;border-radius:14px;overflow:hidden;height:200px;display:flex;align-items:center;justify-content:center;text-align:center;padding:20px;font-weight:800;color:#fff;position:relative}
.pp-promo-preview .pp-promo-logo{position:absolute;left:14px;bottom:14px;font-weight:800;font-size:13px;opacity:.85;letter-spacing:.1em}
.pp-promo-copy{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:12px;font-size:13px;line-height:1.55;white-space:pre-wrap;color:var(--text);margin-bottom:12px;max-height:280px;overflow-y:auto}
.pp-promo-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.pp-promo-actions .btn{width:auto}

/* Reels-сценарий: разметка сцен */
.pp-scene{background:var(--raised);border:1px solid var(--border);border-radius:10px;padding:10px 12px;margin-bottom:8px}
.pp-scene-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px;margin-bottom:4px}
.pp-scene-h .n{font-weight:800;font-size:12px;color:var(--accent);letter-spacing:.02em}
.pp-scene-h .t{font-size:11px;color:var(--dim);font-weight:700}
.pp-scene-txt{font-size:13px;line-height:1.5;color:var(--text)}
.pp-scene-vo{font-size:12px;color:var(--dim);margin-top:6px;line-height:1.5;padding-top:6px;border-top:1px dashed var(--border)}

/* ----------- Wall of Fame ----------- */
.pp-lb{margin-top:0}
.pp-lb-row{display:grid;grid-template-columns:32px 1fr auto;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--border);font-size:13.5px}
.pp-lb-row:last-child{border-bottom:none}
.pp-lb-row.you{background:var(--lime-dim);border-radius:10px;margin:6px 0;border-bottom:none;position:relative}
.pp-lb-row.you::after{content:"ты";display:inline-block;font-size:9.5px;font-weight:800;background:var(--accent);color:#000;padding:3px 8px;border-radius:99px;margin-left:6px;letter-spacing:.06em;text-transform:uppercase}
.pp-lb-place{font-weight:800;font-size:15px;text-align:center;color:var(--dim);font-family:var(--font-display, sans-serif)}
.pp-lb-row.top1 .pp-lb-place{color:#ffd93a}
.pp-lb-row.top2 .pp-lb-place{color:#e0e0e0}
.pp-lb-row.top3 .pp-lb-place{color:#c98a5a}
.pp-lb-nick{font-weight:700;display:flex;align-items:center;gap:8px;min-width:0}
.pp-lb-ava{width:26px;height:26px;border-radius:50%;background:var(--raised);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:12px;flex-shrink:0;color:var(--accent);border:1px solid var(--border)}
.pp-lb-nick span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
.pp-lb-tier{font-size:9.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;padding:2px 6px;border-radius:5px;background:var(--raised);color:var(--dim)}
.pp-lb-tier.pro,.pp-lb-tier.legend{background:var(--lime-dim);color:var(--accent)}
.pp-lb-sum{font-weight:800;color:var(--accent);font-size:13.5px;white-space:nowrap;font-family:var(--font-display, sans-serif)}

/* ----------- Выплаты ----------- */
.pp-payout-hero{background:linear-gradient(135deg,rgba(154,255,0,.14),transparent 65%),var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.pp-payout-hero .lbl{font-size:12px;color:var(--dim);font-weight:700}
.pp-payout-hero .sum{font-size:28px;font-weight:800;color:var(--text);letter-spacing:-.01em;line-height:1.05;margin-top:2px;font-family:var(--font-display, sans-serif)}
.pp-payout-hero .sum b{color:var(--accent)}
.pp-payout-hero .cta{flex:1 1 auto;max-width:160px}
.pp-payout-hero .cta .btn{width:100%;padding:12px}
.pp-payout-hero .cta .btn:disabled{opacity:.5;pointer-events:none;background:var(--raised);color:var(--dim)}
.pp-payout-hero .cta .btn.ghost:disabled{background:transparent;border-color:var(--border)}
.pp-payout-hint{font-size:11.5px;color:var(--dim);margin-top:8px;display:flex;align-items:center;gap:6px}
.pp-payout-hint svg.i{width:12px;height:12px;color:var(--accent);flex-shrink:0}

.pp-hist-filters{display:flex;gap:6px;margin:10px 0 8px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.pp-hist-filters::-webkit-scrollbar{display:none}
.pp-hist-filters button{flex:0 0 auto;background:var(--raised);border:1px solid var(--border);color:var(--text);font-size:12px;font-weight:700;padding:7px 12px;border-radius:99px;white-space:nowrap;cursor:pointer}
.pp-hist-filters button.on{background:var(--lime);color:#000;border-color:var(--lime)}
.pp-hist-row{display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px;padding:11px 0;border-bottom:1px solid var(--border);font-size:13px}
.pp-hist-row:last-child{border-bottom:none}
.pp-hist-t{font-weight:700}
.pp-hist-m{display:flex;gap:8px;font-size:11.5px;color:var(--dim);margin-top:3px;flex-wrap:wrap;align-items:center}
.pp-hist-st{font-size:9.5px;font-weight:800;padding:2px 7px;border-radius:99px;letter-spacing:.06em;text-transform:uppercase}
.pp-hist-st.paid{background:var(--lime-dim);color:var(--accent)}
.pp-hist-st.hold{background:rgba(255,180,0,.15);color:#e0a700}
.pp-hist-st.can{background:rgba(255,77,77,.14);color:var(--danger,#ff6b6b)}
:root[data-theme="light"] .pp-hist-st.hold{color:#9a6f00}
.pp-hist-sum{font-weight:800;color:var(--accent);font-size:14px;white-space:nowrap;font-family:var(--font-display, sans-serif)}
.pp-hist-empty{padding:24px 0;text-align:center;color:var(--dim);font-size:13px}

/* Кнопка «Запросить выплату» внутри sheet */
.pp-payout-method{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin:12px 0}
.pp-payout-method button{background:var(--raised);border:1px solid var(--border);color:var(--text);padding:12px 6px;border-radius:12px;font-weight:700;font-size:12px;cursor:pointer;transition:all .15s;display:flex;flex-direction:column;align-items:center;gap:6px}
.pp-payout-method button svg.i{width:20px;height:20px;color:var(--accent)}
.pp-payout-method button.on{background:var(--lime-dim);border-color:var(--accent);color:var(--text)}
.pp-payout-summary{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:12px;margin:12px 0;display:flex;justify-content:space-between;align-items:baseline}
.pp-payout-summary .lb{font-size:12px;color:var(--dim);font-weight:600}
.pp-payout-summary .sm{font-size:22px;font-weight:800;color:var(--accent);font-family:var(--font-display, sans-serif)}

/* ----------- Инструкции (3-шаговый гайд) ----------- */
.pp-guide{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:0}
.pp-guide-step{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:12px 10px;position:relative;text-align:left;min-width:0}
.pp-guide-num{position:absolute;top:8px;right:10px;font-size:22px;font-weight:800;color:var(--lime-dim);line-height:1;font-family:var(--font-display, sans-serif);letter-spacing:-.02em}
:root[data-theme="light"] .pp-guide-num{color:rgba(154,255,0,.4)}
.pp-guide-ic{width:28px;height:28px;border-radius:8px;background:var(--lime-dim);color:var(--accent);display:flex;align-items:center;justify-content:center;margin-bottom:6px}
.pp-guide-ic svg.i{width:15px;height:15px}
.pp-guide-h{font-size:12.5px;font-weight:800;letter-spacing:-.01em;line-height:1.2;margin-bottom:3px}
.pp-guide-t{font-size:10.5px;color:var(--dim);line-height:1.35;font-weight:500}

/* ----------- Live-уведомление (toast slide-in) ----------- */
.pp-live{position:fixed;left:50%;transform:translateX(-50%) translateY(-140%);top:calc(env(safe-area-inset-top, 0px) + 10px);z-index:60;background:var(--surface);border:1px solid var(--accent);color:var(--text);border-radius:16px;padding:10px 14px 10px 12px;display:flex;align-items:center;gap:10px;box-shadow:0 8px 32px rgba(0,0,0,.4),0 0 24px rgba(154,255,0,.25);max-width:calc(100% - 24px);width:auto;pointer-events:auto;transition:transform .5s cubic-bezier(.2,.9,.3,1.1)}
.pp-live.on{transform:translateX(-50%) translateY(0)}
.pp-live-ico{width:32px;height:32px;border-radius:10px;background:var(--lime);color:#000;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.pp-live-ico svg.i{width:16px;height:16px}
.pp-live-body{min-width:0;flex:1 1 auto}
.pp-live-t{font-size:13px;font-weight:800;letter-spacing:-.01em;line-height:1.15;color:var(--text)}
.pp-live-t b{color:var(--accent)}
.pp-live-s{font-size:11px;color:var(--dim);font-weight:600;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:190px}
.pp-live-x{background:transparent;border:none;color:var(--dim);width:26px;height:26px;display:flex;align-items:center;justify-content:center;border-radius:8px;cursor:pointer;flex-shrink:0;font-size:18px;line-height:1;padding:0}
.pp-live-x:hover{background:var(--raised);color:var(--text)}

/* ----------- Onboarding welcome ----------- */
.pp-welcome{padding:6px 0 2px;text-align:center}
.pp-welcome-hero{background:radial-gradient(circle at 50% 20%, rgba(154,255,0,.4), transparent 60%),linear-gradient(180deg,var(--raised),var(--surface));border:1px solid var(--border);border-radius:18px;padding:22px 18px 20px;margin-bottom:14px;position:relative;overflow:hidden}
.pp-welcome-hero::before{content:"";position:absolute;inset:-40%;background:conic-gradient(from 0deg at 50% 0%, transparent, rgba(154,255,0,.06), transparent 30%);animation:ppWelSpin 12s linear infinite;pointer-events:none}
@keyframes ppWelSpin{to{transform:rotate(360deg)}}
.pp-welcome-badge{display:inline-flex;align-items:center;gap:6px;background:var(--lime-dim);color:var(--accent);font-size:11px;font-weight:800;padding:5px 10px;border-radius:99px;letter-spacing:.08em;text-transform:uppercase;position:relative;z-index:1}
.pp-welcome-num{font-family:var(--font-display, sans-serif);font-size:64px;font-weight:800;line-height:1;letter-spacing:-.02em;margin:8px 0 4px;color:var(--accent);text-shadow:0 0 24px rgba(154,255,0,.4);position:relative;z-index:1}
.pp-welcome-h{font-size:20px;font-weight:800;letter-spacing:-.01em;line-height:1.2;position:relative;z-index:1}
.pp-welcome-list{text-align:left;padding:0;margin:14px 0;display:grid;gap:8px}
.pp-welcome-list li{list-style:none;display:grid;grid-template-columns:28px 1fr;gap:10px;align-items:start;font-size:13px;line-height:1.4;padding:8px 10px;background:var(--raised);border:1px solid var(--border);border-radius:10px}
.pp-welcome-list li b{color:var(--accent)}
.pp-welcome-list li .pp-w-ic{width:28px;height:28px;border-radius:8px;background:var(--lime);color:#000;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.pp-welcome-list li .pp-w-ic svg.i{width:14px;height:14px}
.pp-welcome-actions{display:grid;grid-template-columns:1fr;gap:8px;margin-top:8px}
.pp-welcome-actions .btn{width:100%}
.pp-welcome-actions .btn.ghost{color:var(--dim);border-color:var(--border)}

/* Общие мелочи */
.pp-section-h{display:flex;justify-content:space-between;align-items:baseline;padding:0 0 8px}
.pp-section-h.padded{padding:0 14px 8px}
.pp-section-h p{font-weight:700;font-size:15px;letter-spacing:-.01em;margin:0}
.pp-section-h .chip{font-size:10.5px}

/* заголовок «Партнёрская программа» + чип-процент справа: чип не должен ужиматься */
#ppRoot > h2.section-h{gap:8px;flex-wrap:wrap}
#ppRoot > h2.section-h > .chip{flex:0 0 auto;max-width:100%;white-space:nowrap}

/* Sparkline точки — вид ховер-подсказки */
.pp-hero-spark .spot{fill:var(--lime);filter:drop-shadow(0 0 6px rgba(154,255,0,.6))}

/* ============================================================
   REFERRAL SQUARED — цели «приведи N клиентов → бонус»
   ============================================================ */
.pp-goals{padding:14px 14px 12px;margin-top:12px;background:var(--surface);
  border:1px solid var(--border);border-radius:16px;position:relative;overflow:hidden}
.pp-goals::before{content:'';position:absolute;inset:auto -25% -70% -25%;height:180px;
  background:radial-gradient(ellipse at 50% 50%, rgba(154,255,0,.14) 0%, transparent 60%);pointer-events:none}
.pp-goals-h{display:flex;gap:12px;align-items:flex-start;position:relative;margin-bottom:8px}
.pp-goals-title{display:flex;gap:10px;align-items:flex-start;flex:1;min-width:0}
.pp-goals-title-ic{width:36px;height:36px;border-radius:11px;background:var(--lime-dim);color:var(--accent);
  display:flex;align-items:center;justify-content:center;flex:none}
.pp-goals-title-ic svg.i{width:16px;height:16px}
.pp-goals-title b{display:block;font-size:14px;font-weight:800;color:var(--text)}
.pp-goals-title small{display:block;font-size:11.5px;color:var(--dim);margin-top:2px;line-height:1.4}
.pp-goals-count{text-align:right;flex:none}
.pp-goals-count b{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:28px;color:var(--accent);line-height:1;letter-spacing:.01em}
.pp-goals-count span{display:block;font-size:10.5px;color:var(--dim);margin-top:1px;font-weight:600}
.pp-goals-overall{position:relative;height:6px;border-radius:99px;background:var(--border);overflow:hidden;margin-bottom:12px}
.pp-goals-overall i{display:block;height:100%;background:linear-gradient(90deg,var(--lime) 0%,#c4ff5c 100%);border-radius:99px;transition:width .8s ease}
.pp-goals-list{display:flex;flex-direction:column;gap:10px;position:relative}
.pp-goal{background:var(--raised);border:1px solid var(--border);border-radius:12px;padding:10px 12px;transition:border-color .2s}
.pp-goal.done{border-color:var(--lime);background:linear-gradient(180deg,rgba(154,255,0,.08) 0%,var(--raised) 100%)}
.pp-goal-row{display:grid;grid-template-columns:32px 1fr auto;gap:10px;align-items:center;margin-bottom:8px}
.pp-goal-ic{width:32px;height:32px;border-radius:9px;background:var(--surface);border:1px solid var(--border);
  color:var(--accent);display:flex;align-items:center;justify-content:center}
.pp-goal-ic svg.i{width:15px;height:15px}
.pp-goal.done .pp-goal-ic{background:var(--lime);color:#0a0a0a;border-color:var(--lime)}
.pp-goal-body{min-width:0}
.pp-goal-h{font-size:13px;color:var(--text);font-weight:600;line-height:1.3}
.pp-goal-h b{color:var(--accent);font-weight:800}
.pp-goal-r{margin-top:3px}
.pp-goal-tag{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.03em;
  background:var(--lime-dim);color:var(--accent);border-radius:99px;padding:2px 8px}
.pp-goal-count{text-align:right}
.pp-goal-count b{font-family:var(--font-display,'Bebas Neue',sans-serif);font-size:20px;color:var(--text);line-height:1}
.pp-goal-count span{display:block;font-size:10.5px;color:var(--dim);margin-top:1px}
.pp-goal.done .pp-goal-count b{color:var(--accent)}
.pp-goal-bar{height:5px;border-radius:99px;background:var(--border);overflow:hidden;margin-bottom:6px}
.pp-goal-bar i{display:block;height:100%;background:linear-gradient(90deg,var(--lime) 0%,#c4ff5c 100%);border-radius:99px;transition:width .8s ease}
.pp-goal-status{font-size:11.5px;line-height:1.4}
.pp-goal-left{color:var(--dim)}
.pp-goal-left b{color:var(--accent);font-weight:800}
.pp-goal-done{color:var(--accent);font-weight:700;display:inline-flex;align-items:center;gap:5px}
.pp-goal-done svg.i{width:12px;height:12px}
.pp-goals-actions{margin-top:12px;position:relative}
.pp-goals-actions .btn{width:100%;font-size:12.5px;padding:10px 12px}
.pp-goals-actions .btn svg.i{width:12px;height:12px}

/* Награда — попап после достижения */
.pp-goal-reward-box{display:flex;gap:10px;align-items:center;padding:10px 12px;background:var(--lime-dim);
  border:1px solid var(--lime);border-radius:12px;margin-top:6px}
.pp-goal-reward-ic{width:36px;height:36px;border-radius:10px;background:var(--lime);color:#0a0a0a;
  display:flex;align-items:center;justify-content:center;flex:none}
.pp-goal-reward-ic svg.i{width:16px;height:16px}
.pp-goal-reward-tx b{display:block;font-size:13.5px;font-weight:800;color:var(--accent)}
.pp-goal-reward-tx small{display:block;font-size:11px;color:var(--dim);margin-top:2px}


/* ===== module: channels ===== */
/* ================= CHANNELS: платные каналы / курсы + управление (префикс ch-) ================= */
#chView{position:fixed;inset:0;z-index:67;background:var(--bg);display:flex;flex-direction:column;
  transform:translateX(100%);transition:transform .32s cubic-bezier(.3,1,.4,1);
  max-width:1280px;margin:0 auto;padding-left:env(safe-area-inset-left);padding-right:env(safe-area-inset-right)}
#chView.open{transform:none}
@media(prefers-reduced-motion:reduce){#chView{transition:none}}

/* заголовок вьюхи */
.ch-head{display:flex;align-items:center;gap:10px;padding:14px 16px;
  padding-top:max(14px,env(safe-area-inset-top));border-bottom:1px solid var(--border);flex-shrink:0}
.ch-head .ch-back{color:var(--dim);display:inline-flex;padding:2px;flex-shrink:0}
.ch-head .ch-back svg.i{width:22px;height:22px}
.ch-head b{font-size:16.5px;font-weight:800;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-head .ch-htools{display:inline-flex;gap:4px;flex-shrink:0}
.ch-head .ch-htools button{color:var(--dim);padding:5px;border-radius:var(--r-sm)}
.ch-head .ch-htools button:hover{color:var(--text);background:var(--raised)}
.ch-head .ch-htools svg.i{width:20px;height:20px}
.ch-body{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;
  padding:16px 16px calc(30px + env(safe-area-inset-bottom))}

/* ---- общие ---- */
.ch-sec-h{font:700 11px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--dim);
  margin:22px 4px 11px;display:flex;align-items:center;gap:7px}
.ch-sec-h:first-child{margin-top:4px}
.ch-sec-h svg.i{width:15px;height:15px;color:var(--lime)}
.ch-empty{text-align:center;color:var(--dim);font-size:13px;padding:26px 14px;border:1px dashed var(--border);border-radius:var(--r-md)}

/* карточка канала в списке */
.ch-card{display:flex;align-items:center;gap:12px;padding:12px 13px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:9px;cursor:pointer;
  transition:transform .16s,border-color .2s,background .2s;position:relative;overflow:hidden}
.ch-card:hover{border-color:var(--lime-dim);background:var(--raised);transform:translateY(-1px)}
.ch-card:active{transform:scale(.985)}
.ch-av{width:52px;height:52px;border-radius:15px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  font:800 21px/1 var(--font-display);letter-spacing:.02em;position:relative;overflow:hidden;
  background:var(--av-g,linear-gradient(135deg,#141414,#2a2a2a));color:var(--av-c,#0a0a0a)}
.ch-av svg.i{width:26px;height:26px;color:inherit}
.ch-av.mini{width:40px;height:40px;border-radius:12px;font-size:16px}
.ch-av.big{width:84px;height:84px;border-radius:24px;font-size:34px}
.ch-av .ch-avlock{position:absolute;right:-2px;bottom:-2px;width:20px;height:20px;border-radius:50%;
  background:var(--surface);display:flex;align-items:center;justify-content:center;box-shadow:0 0 0 2px var(--surface)}
.ch-av .ch-avlock svg.i{width:12px;height:12px;color:var(--lime)}
.ch-cbody{flex:1;min-width:0}
.ch-cname{font-weight:700;font-size:14.5px;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-cname .vs-badge svg,.ch-cname svg.i{flex-shrink:0}
.ch-csub{color:var(--dim);font-size:12px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:5px}
.ch-csub svg.i{width:12px;height:12px}
.ch-tag{font:800 9px/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;padding:4px 7px;border-radius:6px;flex-shrink:0}
.ch-tag.paid{background:var(--lime);color:#0a0a0a}
.ch-tag.course{background:linear-gradient(120deg,#9AFF00,#6fd400);color:#0a0a0a}
.ch-tag.free{background:var(--raised);color:var(--dim)}
.ch-price-pill{margin-left:auto;flex-shrink:0;font-weight:800;font-size:13px;color:var(--lime);white-space:nowrap}

/* CTA создать */
.ch-create-cta{display:flex;align-items:center;gap:12px;width:100%;padding:15px 14px;border-radius:var(--r-md);
  background:linear-gradient(120deg,rgba(154,255,0,.14),rgba(154,255,0,.03));border:1px solid var(--lime-dim);
  color:var(--text);cursor:pointer;transition:transform .16s,box-shadow .2s;margin-bottom:6px}
.ch-create-cta:hover{transform:translateY(-1px);box-shadow:var(--glow)}
.ch-create-cta .ch-cc-ic{width:44px;height:44px;border-radius:13px;background:var(--lime);color:#0a0a0a;
  display:flex;align-items:center;justify-content:center;flex-shrink:0}
.ch-create-cta .ch-cc-ic svg.i{width:23px;height:23px}
.ch-create-cta b{display:block;font-size:14.5px}
.ch-create-cta small{color:var(--dim);font-size:11.5px}

/* ---- создание: тип ---- */
.ch-type-grid{display:grid;gap:10px;margin-bottom:6px}
.ch-type-card{display:flex;align-items:center;gap:13px;padding:14px;border-radius:var(--r-md);
  background:var(--surface);border:1.5px solid var(--border);cursor:pointer;text-align:left;transition:all .18s}
.ch-type-card:hover{border-color:var(--lime-dim)}
.ch-type-card.on{border-color:var(--lime);background:var(--raised);box-shadow:0 0 0 3px rgba(154,255,0,.1)}
.ch-type-card .ch-tc-ic{width:46px;height:46px;border-radius:14px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:var(--raised);color:var(--lime);transition:all .18s}
.ch-type-card.on .ch-tc-ic{background:var(--lime);color:#0a0a0a}
.ch-type-card .ch-tc-ic svg.i{width:24px;height:24px}
.ch-type-card b{font-size:14.5px;display:block}
.ch-type-card small{color:var(--dim);font-size:12px;display:block;margin-top:2px;line-height:1.35}
.ch-type-card .ch-tc-check{margin-left:auto;flex-shrink:0;width:22px;height:22px;border-radius:50%;border:2px solid var(--border);
  display:flex;align-items:center;justify-content:center;transition:all .18s}
.ch-type-card.on .ch-tc-check{background:var(--lime);border-color:var(--lime)}
.ch-type-card .ch-tc-check svg.i{width:13px;height:13px;color:#0a0a0a;opacity:0;transition:opacity .18s}
.ch-type-card.on .ch-tc-check svg.i{opacity:1}

/* форма */
.ch-lab{font:700 12px/1 var(--font-body);color:var(--dim);margin:16px 4px 8px;display:block}
.ch-input,.ch-ta{width:100%;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-sm);
  color:var(--text);font:400 14px/1.4 var(--font-body);padding:12px 13px;transition:border-color .2s}
.ch-input:focus,.ch-ta:focus{outline:none;border-color:var(--lime)}
.ch-ta{resize:none;line-height:1.5}
.ch-price-row{display:flex;align-items:center;gap:8px}
.ch-price-row .ch-input{flex:1}
.ch-price-row .ch-unit{color:var(--dim);font-size:13px;font-weight:600;white-space:nowrap}
.ch-price-chips{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}
.ch-price-chips button{background:var(--surface);border:1px solid var(--border);border-radius:20px;color:var(--text);
  font-size:12.5px;font-weight:600;padding:7px 13px;cursor:pointer;transition:all .16s}
.ch-price-chips button:hover{border-color:var(--lime-dim)}
.ch-price-chips button.on{background:var(--lime);color:#0a0a0a;border-color:var(--lime)}

/* аватар + фон пикеры */
.ch-appear-prev{border-radius:var(--r-md);overflow:hidden;position:relative;height:130px;display:flex;align-items:flex-end;
  padding:14px;margin-bottom:14px;border:1px solid var(--border)}
.ch-appear-prev .ch-ap-ava{width:64px;height:64px;border-radius:19px;display:flex;align-items:center;justify-content:center;
  font:800 26px/1 var(--font-display);background:var(--av-g,linear-gradient(135deg,#141414,#2a2a2a));color:var(--av-c,#0a0a0a);
  box-shadow:0 6px 18px rgba(0,0,0,.35);border:2.5px solid rgba(255,255,255,.85)}
.ch-appear-prev .ch-ap-name{color:#fff;font-weight:800;font-size:16px;margin-left:12px;text-shadow:0 1px 6px rgba(0,0,0,.5)}
.ch-swatches{display:grid;grid-template-columns:repeat(auto-fill,minmax(56px,1fr));gap:9px}
.ch-sw{aspect-ratio:1;border-radius:14px;cursor:pointer;border:2.5px solid transparent;transition:transform .14s,border-color .16s;position:relative}
.ch-sw:hover{transform:scale(1.05)}
.ch-sw.on{border-color:var(--lime)}
.ch-sw.on::after{content:'';position:absolute;inset:0;border-radius:11px;box-shadow:inset 0 0 0 2px rgba(0,0,0,.25)}
.ch-letter-row{display:flex;gap:8px;flex-wrap:wrap;margin-top:9px}
.ch-letter-row .ch-lt{width:42px;height:42px;border-radius:12px;display:flex;align-items:center;justify-content:center;
  background:var(--surface);border:2px solid var(--border);cursor:pointer;color:var(--lime);transition:all .16s}
.ch-letter-row .ch-lt:hover{border-color:var(--lime-dim)}
.ch-letter-row .ch-lt.on{border-color:var(--lime);background:var(--raised)}
.ch-letter-row .ch-lt svg.i{width:21px;height:21px;color:var(--lime)}

/* ---- просмотр канала ---- */
.ch-cover{border-radius:var(--r-lg);overflow:hidden;position:relative;padding:20px 16px 16px;margin-bottom:14px;
  display:flex;flex-direction:column;align-items:center;text-align:center}
.ch-cover::before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.05),rgba(0,0,0,.42))}
.ch-cover>*{position:relative;z-index:1}
.ch-cover .ch-av.big{border:3px solid rgba(255,255,255,.9);box-shadow:0 8px 24px rgba(0,0,0,.4)}
.ch-cv-name{color:#fff;font:800 22px/1.1 var(--font-display);letter-spacing:.02em;margin-top:12px;text-shadow:0 2px 8px rgba(0,0,0,.5);
  display:flex;align-items:center;gap:7px;justify-content:center;flex-wrap:wrap;max-width:100%;word-break:break-word}
.ch-cv-sub{color:rgba(255,255,255,.85);font-size:12.5px;margin-top:5px;font-weight:600;text-shadow:0 1px 4px rgba(0,0,0,.5)}
.ch-cv-stats{display:flex;gap:18px;margin-top:12px}
.ch-cv-stats div{color:#fff;text-align:center}
.ch-cv-stats b{display:block;font:800 17px/1 var(--font-display)}
.ch-cv-stats small{color:rgba(255,255,255,.8);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em}
.ch-desc{font-size:13.5px;line-height:1.55;color:var(--text);background:var(--surface);border:1px solid var(--border);
  border-radius:var(--r-md);padding:13px 14px;margin-bottom:14px}

/* paywall */
.ch-paywall{border-radius:var(--r-lg);border:1px solid var(--lime-dim);overflow:hidden;margin-bottom:8px;
  background:linear-gradient(180deg,rgba(154,255,0,.08),var(--surface))}
.ch-pw-blur{position:relative;padding:16px;filter:blur(3px);opacity:.5;pointer-events:none;user-select:none;max-height:150px;overflow:hidden}
.ch-pw-body{padding:18px 16px 16px;text-align:center}
.ch-pw-lock{width:52px;height:52px;border-radius:50%;background:var(--lime);color:#0a0a0a;display:inline-flex;
  align-items:center;justify-content:center;margin-bottom:12px;box-shadow:var(--glow)}
.ch-pw-lock svg.i{width:26px;height:26px}
.ch-pw-body h3{font-size:17px;font-weight:800;margin-bottom:5px}
.ch-pw-body p{color:var(--dim);font-size:12.5px;line-height:1.5;margin-bottom:14px}
.ch-pw-price{font:800 30px/1 var(--font-display);color:var(--lime);margin-bottom:2px}
.ch-pw-price span{font-size:14px;color:var(--dim)}
.ch-pw-benefits{text-align:left;max-width:320px;margin:0 auto 16px}
.ch-pw-benefits li{display:flex;gap:9px;align-items:flex-start;font-size:12.5px;color:var(--text);padding:5px 0}
.ch-pw-benefits svg.i{width:16px;height:16px;color:var(--lime);flex-shrink:0;margin-top:1px}

/* посты канала */
.ch-post{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:13px 14px;margin-bottom:10px;animation:chFade .4s both}
.ch-post-h{display:flex;align-items:center;gap:8px;margin-bottom:8px}
.ch-post-h .ch-av.mini{border-radius:11px}
.ch-post-h b{font-size:13px;font-weight:700}
.ch-post-h b.ch-ph-name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-post-h small{color:var(--dim);font-size:11px;margin-left:auto;flex-shrink:0;padding-left:8px}
.ch-post-txt{font-size:13.5px;line-height:1.55;color:var(--text)}
.ch-post-media{margin-top:10px;border-radius:var(--r-sm);height:150px;display:flex;align-items:center;justify-content:center;
  color:var(--lime);position:relative;overflow:hidden}
.ch-post-media svg.i{width:44px;height:44px;position:relative;z-index:1;filter:drop-shadow(0 2px 8px rgba(0,0,0,.4))}
.ch-post-acts{display:flex;gap:16px;margin-top:11px;color:var(--dim);font-size:12px;font-weight:600;align-items:center}
.ch-post-acts button{display:inline-flex;align-items:center;gap:5px;color:var(--dim);transition:color .16s}
.ch-post-acts button:hover{color:var(--lime)}
.ch-post-acts button.on{color:var(--lime)}
.ch-post-acts button svg.i{width:16px;height:16px}
.ch-post-acts .ch-views{margin-left:auto;display:inline-flex;gap:5px;align-items:center}
.ch-post-acts .ch-views svg.i{width:15px;height:15px}

/* курс: уроки */
.ch-prog-top{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;margin-bottom:14px}
.ch-prog-top .ch-pt-row{display:flex;align-items:center;justify-content:space-between;margin-bottom:9px}
.ch-prog-top b{font-size:14px;font-weight:800}
.ch-prog-top .ch-pt-pct{color:var(--lime);font:800 15px/1 var(--font-display)}
.ch-prog-bar{height:8px;border-radius:5px;background:var(--raised);overflow:hidden}
.ch-prog-bar i{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,#6fd400,#9AFF00);
  transition:width .6s cubic-bezier(.3,1,.4,1);box-shadow:0 0 10px rgba(154,255,0,.5)}
.ch-lesson{display:flex;align-items:center;gap:12px;background:var(--surface);border:1px solid var(--border);
  border-radius:var(--r-md);padding:11px 13px;margin-bottom:8px;cursor:pointer;transition:all .16s}
.ch-lesson:hover{border-color:var(--lime-dim);background:var(--raised)}
.ch-lesson .ch-ls-n{width:34px;height:34px;border-radius:10px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  background:var(--raised);color:var(--lime);font:800 14px/1 var(--font-display);position:relative}
.ch-lesson.done .ch-ls-n{background:var(--lime);color:#0a0a0a}
.ch-lesson .ch-ls-n svg.i{width:17px;height:17px}
.ch-lesson .ch-ls-b{flex:1;min-width:0}
.ch-lesson .ch-ls-b b{font-size:13.5px;font-weight:700;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-lesson .ch-ls-b small{color:var(--dim);font-size:11.5px;display:flex;align-items:center;gap:5px;margin-top:2px}
.ch-lesson .ch-ls-b small svg.i{width:12px;height:12px}
.ch-lesson .ch-ls-play{color:var(--lime);flex-shrink:0}
.ch-lesson .ch-ls-play svg.i{width:26px;height:26px}
.ch-lesson.locked{opacity:.6;cursor:default}
.ch-lesson.locked:hover{border-color:var(--border);background:var(--surface)}

/* урок-плеер */
.ch-player{border-radius:var(--r-md);height:220px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;margin-bottom:14px}
.ch-player::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 45%,rgba(0,0,0,.05),rgba(0,0,0,.55))}
.ch-player .ch-play-btn{position:relative;z-index:1;width:70px;height:70px;border-radius:50%;background:rgba(154,255,0,.95);
  color:#0a0a0a;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 28px rgba(0,0,0,.4);cursor:pointer;transition:transform .18s}
.ch-player .ch-play-btn:hover{transform:scale(1.07)}
.ch-player .ch-play-btn svg.i{width:32px;height:32px;margin-left:3px}

/* ---- управление ---- */
.ch-manage-hub .ch-av.big{margin:0 auto 10px;display:flex}
.ch-mrow{display:flex;align-items:center;gap:13px;width:100%;padding:14px 13px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:8px;cursor:pointer;text-align:left;transition:all .16s}
.ch-mrow:hover{border-color:var(--lime-dim);background:var(--raised);transform:translateX(2px)}
.ch-mrow .ch-mr-ic{width:38px;height:38px;border-radius:11px;background:var(--raised);color:var(--lime);
  display:flex;align-items:center;justify-content:center;flex-shrink:0}
.ch-mrow:hover .ch-mr-ic{background:var(--lime-dim)}
.ch-mrow .ch-mr-ic svg.i{width:20px;height:20px}
.ch-mrow .ch-mr-b{flex:1;min-width:0}
.ch-mrow .ch-mr-b b{font-size:14px;font-weight:700;display:block}
.ch-mrow .ch-mr-b small{color:var(--dim);font-size:11.5px;display:block;margin-top:1px}
.ch-mrow .ch-mr-val{color:var(--dim);font-size:12.5px;font-weight:600;flex-shrink:0;display:flex;align-items:center;gap:6px}
.ch-mrow .ch-mr-val svg.i{width:16px;height:16px}
.ch-mrow.danger .ch-mr-ic{color:var(--danger)}
.ch-mrow.danger .ch-mr-b b{color:var(--danger)}

/* переключатель-строка */
.ch-toggle-row{display:flex;align-items:center;gap:12px;width:100%;padding:13px;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-md);margin-bottom:8px;text-align:left;cursor:pointer}
.ch-toggle-row .ch-tr-ic{color:var(--lime);flex-shrink:0;display:inline-flex}
.ch-toggle-row .ch-tr-ic svg.i{width:20px;height:20px}
.ch-toggle-row .ch-tr-b{flex:1;min-width:0}
.ch-toggle-row .ch-tr-b b{font-size:13.5px;font-weight:700;display:block}
.ch-toggle-row .ch-tr-b small{color:var(--dim);font-size:11.5px;display:block;margin-top:1px;line-height:1.35}

/* сегментированный выбор типа */
.ch-seg{display:grid;gap:9px;margin-bottom:6px}
.ch-owner-note{font-size:11.5px;color:var(--dim);line-height:1.5;padding:6px 4px 2px}

/* доход владельца */
.ch-earn{border-radius:var(--r-md);padding:16px;margin-bottom:14px;border:1px solid var(--lime-dim);
  background:linear-gradient(135deg,rgba(154,255,0,.1),var(--surface))}
.ch-earn small.ch-earn-lab{font:700 10px/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--dim)}
.ch-earn .ch-earn-sum{font:800 30px/1 var(--font-display);color:var(--lime);margin:7px 0 3px}
.ch-earn .ch-earn-sum span{font-size:15px;color:var(--text)}
.ch-earn .ch-earn-calc{margin:10px 0 12px}
.ch-earn .ch-earn-calc div{display:flex;justify-content:space-between;font-size:12.5px;padding:4px 0;color:var(--dim)}
.ch-earn .ch-earn-calc div b{color:var(--text);font-weight:700}
.ch-earn .ch-earn-calc div.fee b{color:var(--danger)}
.ch-earn .ch-earn-calc div.total{border-top:1px solid var(--border);margin-top:5px;padding-top:8px}
.ch-earn .ch-earn-calc div.total b{color:var(--lime)}

/* KPI + статистика */
.ch-kpi{display:grid;grid-template-columns:repeat(2,1fr);gap:9px;margin-bottom:14px}
.ch-kpi-t{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:13px;text-align:center}
.ch-kpi-t svg.i{width:19px;height:19px;color:var(--lime);margin-bottom:5px}
.ch-kpi-t b{display:block;font:800 22px/1 var(--font-display)}
.ch-kpi-t small{color:var(--dim);font-size:11px;display:block;margin-top:3px}
.ch-canvas-wrap{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;margin-bottom:14px}
.ch-canvas-wrap .ch-cw-h{font-size:12.5px;font-weight:700;color:var(--text);margin-bottom:4px;display:flex;justify-content:space-between;align-items:baseline}
.ch-canvas-wrap .ch-cw-h span{color:var(--lime);font-weight:800;font-size:13px}
.ch-canvas-wrap canvas{width:100%;height:130px;display:block}
.ch-donut{display:flex;align-items:center;gap:16px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;margin-bottom:14px}
.ch-donut canvas{width:96px;height:96px;flex-shrink:0}
.ch-donut-leg{flex:1;min-width:0}
.ch-donut-leg div{display:flex;align-items:center;gap:8px;font-size:12.5px;padding:3px 0}
.ch-donut-leg i{width:11px;height:11px;border-radius:3px;flex-shrink:0}
.ch-donut-leg b{margin-left:auto;font-weight:700}

/* участники / админы / чс */
.ch-member{display:flex;align-items:center;gap:11px;padding:9px 4px;border-bottom:1px solid var(--border)}
.ch-member:last-child{border-bottom:none}
.ch-member .ch-av.mini{border-radius:12px}
.ch-member .ch-m-b{flex:1;min-width:0}
.ch-member .ch-m-b b{font-size:13.5px;font-weight:700;display:flex;align-items:center;gap:5px}
.ch-member .ch-m-b small{color:var(--dim);font-size:11.5px;display:block}
.ch-member .ch-m-role{font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;
  padding:3px 8px;border-radius:6px;background:var(--lime-dim);color:var(--accent);flex-shrink:0}
.ch-member .ch-m-role.owner{background:var(--lime);color:#0a0a0a}
.ch-member .ch-m-act{color:var(--dim);padding:5px;flex-shrink:0;border-radius:8px;transition:all .16s}
.ch-member .ch-m-act:hover{color:var(--danger);background:var(--raised)}
.ch-member .ch-m-act svg.i{width:18px;height:18px}
.ch-add-btn{display:flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:12px;margin-top:10px;
  border:1px dashed var(--lime-dim);border-radius:var(--r-md);color:var(--lime);font-weight:700;font-size:13px;cursor:pointer;transition:all .16s}
.ch-add-btn:hover{background:var(--lime-dim)}
.ch-add-btn svg.i{width:18px;height:18px}

@keyframes chFade{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}

/* профиль: строка «Мои каналы» */
#chProwCount{margin-left:auto;background:var(--lime);color:#0a0a0a;font:800 10px/1 var(--font-body);
  padding:3px 7px;border-radius:9px}

/* @id на обложке + кнопка редактирования обложки */
.ch-cv-id{color:rgba(255,255,255,.82);font:600 12px/1 var(--font-body);margin-top:5px;text-shadow:0 1px 4px rgba(0,0,0,.5)}
.ch-cover .ch-cv-edit{position:absolute;top:12px;right:12px;z-index:2;width:34px;height:34px;border-radius:50%;
  background:rgba(0,0,0,.42);backdrop-filter:blur(4px);color:#fff;display:flex;align-items:center;justify-content:center;
  border:1px solid rgba(255,255,255,.25);cursor:pointer;transition:all .16s}
.ch-cover .ch-cv-edit:hover{background:var(--lime);color:#0a0a0a;border-color:var(--lime)}
.ch-cover .ch-cv-edit svg.i{width:17px;height:17px}

/* панель действий владельца/подписчика на странице канала */
.ch-owner-bar{display:flex;gap:9px;margin-bottom:14px}
.ch-owner-bar .btn{flex:1;margin:0}

/* фото в посте + метка видео */
.ch-post-media.photo{background-size:cover;background-position:center;color:transparent}
.ch-post-media .ch-pm-dur{position:absolute;bottom:8px;right:9px;z-index:1;background:rgba(0,0,0,.6);color:#fff;
  font:700 10px/1 var(--font-body);letter-spacing:.05em;text-transform:uppercase;padding:4px 8px;border-radius:6px}

/* опрос */
.ch-poll{margin-top:11px;background:var(--raised);border:1px solid var(--border);border-radius:var(--r-md);padding:12px}
.ch-poll-q{font-size:13px;font-weight:700;margin-bottom:10px;display:flex;align-items:center;gap:7px}
.ch-poll-q svg.i{width:15px;height:15px;color:var(--lime)}
.ch-poll-opt{position:relative;display:flex;align-items:center;width:100%;background:var(--surface);
  border:1px solid var(--border);border-radius:var(--r-sm);padding:10px 12px;margin-bottom:7px;cursor:pointer;
  overflow:hidden;text-align:left;transition:border-color .16s}
.ch-poll-opt:last-of-type{margin-bottom:0}
.ch-poll-opt:not(.voted):hover{border-color:var(--lime)}
.ch-poll-opt .ch-po-fill{position:absolute;left:0;top:0;bottom:0;background:var(--lime-dim);
  transition:width .6s cubic-bezier(.3,1,.4,1);z-index:0}
.ch-poll-opt.mine .ch-po-fill{background:rgba(154,255,0,.28)}
.ch-poll-opt .ch-po-t{position:relative;z-index:1;font-size:12.5px;font-weight:600;flex:1;min-width:0}
.ch-poll-opt.mine .ch-po-t{color:var(--accent)}
.ch-poll-opt .ch-po-p{position:relative;z-index:1;font:800 12.5px/1 var(--font-display);color:var(--text);margin-left:8px;flex-shrink:0}
.ch-poll-opt.voted{cursor:default}
.ch-poll-total{color:var(--dim);font-size:11px;margin-top:8px;text-align:center}

/* композер публикации */
.ch-compose-head{display:flex;align-items:center;gap:11px;margin-bottom:12px}
.ch-compose-head b{font-size:14px;font-weight:800;display:block}
.ch-compose-head small{color:var(--dim);font-size:11.5px}
.ch-compose-kinds{display:flex;gap:8px;margin-top:11px;flex-wrap:wrap}
.ch-ck{flex:1;min-width:70px;display:flex;flex-direction:column;align-items:center;gap:5px;padding:11px 6px;border-radius:var(--r-sm);
  background:var(--surface);border:1.5px solid var(--border);color:var(--dim);cursor:pointer;transition:all .16s;font-size:11.5px;font-weight:600}
.ch-ck:hover{border-color:var(--lime-dim)}
.ch-ck.on{border-color:var(--lime);background:var(--raised);color:var(--text)}
.ch-ck svg.i{width:20px;height:20px;color:var(--lime)}
.ch-compose-photo{margin-top:12px;height:170px;border-radius:var(--r-md);border:1.5px dashed var(--lime-dim);
  background-color:var(--surface);background-size:cover;background-position:center;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:8px;color:var(--lime);cursor:pointer;position:relative;overflow:hidden;transition:border-color .16s}
.ch-compose-photo:hover{border-color:var(--lime)}
.ch-compose-photo small{color:var(--dim);font-size:12px}
.ch-compose-photo svg.i{width:30px;height:30px}
.ch-compose-photo .ch-cp-change{position:absolute;bottom:10px;right:10px;background:rgba(0,0,0,.6);color:#fff;
  padding:6px 11px;border-radius:20px;font-size:11.5px;font-weight:600;display:inline-flex;align-items:center;gap:6px}
.ch-compose-photo .ch-cp-change svg.i{width:15px;height:15px;color:#fff}

/* загрузка фото в оформлении */
.ch-photo-row{display:flex;gap:8px;margin-bottom:9px}
.ch-photo-btn{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;padding:12px;border-radius:var(--r-md);
  background:var(--surface);border:1px solid var(--border);color:var(--text);font-size:13px;font-weight:600;cursor:pointer;transition:all .16s}
.ch-photo-btn:hover{border-color:var(--lime-dim);background:var(--raised)}
.ch-photo-btn svg.i{width:18px;height:18px;color:var(--lime)}
.ch-photo-btn.del{flex:0 0 46px}
.ch-photo-btn.del svg.i{color:var(--danger)}
.ch-photo-btn.del:hover{border-color:var(--danger)}
.ch-ap-id{font:600 11px/1 var(--font-body);color:rgba(255,255,255,.8);margin-left:9px;text-shadow:0 1px 4px rgba(0,0,0,.5)}

/* DM-кнопка у участника */
.ch-member .ch-m-act.send:hover{color:var(--lime)}

/* ===== оси ДОСТУП (открытый/закрытый) + ОПЛАТА (бесплатно/платно) ===== */
.ch-tag{display:inline-flex;align-items:center;gap:4px}
.ch-tag svg.i{width:11px;height:11px}
.ch-tag.closed{background:var(--raised);color:var(--text);border:1px solid var(--border)}
.ch-tag.closed svg.i{color:var(--lime)}
.ch-tag.club{background:var(--lime-dim);color:var(--accent);border:1px solid var(--lime-dim)}
.ch-tag.club svg.i{color:var(--accent)}
.ch-tag.course svg.i{color:#0a0a0a}
.ch-cbadges{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}
.ch-cbadges:empty{display:none}
.ch-price-pill.dim-pill{color:var(--dim);display:inline-flex;align-items:center;gap:4px;font-size:12px}
.ch-price-pill.dim-pill svg.i{width:13px;height:13px}

/* сегмент из двух вариантов (доступ / оплата) */
.ch-choice2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:4px}
.ch-choice2.locked{opacity:.7}
.ch-ch2{display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:12px 13px;border-radius:var(--r-md);
  background:var(--surface);border:1.5px solid var(--border);cursor:pointer;text-align:left;transition:all .18s;color:var(--text)}
.ch-ch2:hover:not(:disabled){border-color:var(--lime-dim)}
.ch-ch2.on{border-color:var(--lime);background:var(--raised);box-shadow:0 0 0 3px rgba(154,255,0,.1)}
.ch-ch2:disabled{cursor:not-allowed}
.ch-ch2 svg.i{width:20px;height:20px;color:var(--lime);margin-bottom:4px}
.ch-ch2 b{font-size:13.5px;font-weight:800}
.ch-ch2 small{color:var(--dim);font-size:10.5px;line-height:1.3}

/* бейджи на обложке канала */
.ch-cv-badges{display:flex;flex-wrap:wrap;gap:5px;justify-content:center;margin-top:9px}
.ch-cv-badges:empty{display:none}
.ch-cv-badges .ch-tag{box-shadow:0 2px 8px rgba(0,0,0,.35)}

/* свотч «без фона» */
.ch-sw.ch-sw-none{background:var(--surface);border:2px dashed var(--border);display:flex;align-items:center;justify-content:center}
.ch-sw.ch-sw-none svg.i{width:20px;height:20px;color:var(--dim)}
.ch-sw.ch-sw-none.on{border-color:var(--lime)}
.ch-sw.ch-sw-none.on svg.i{color:var(--lime)}

/* фон-«обои» за постами канала */
.ch-feed{border-radius:var(--r-md);padding:12px 12px 2px;margin-top:2px}
.ch-feed .ch-post{box-shadow:0 4px 14px rgba(0,0,0,.18)}

/* метка источника-канала в общей ленте (ядро) */
.ch-src-chip{display:inline-flex!important;align-items:center;gap:4px;background:var(--lime-dim)!important;color:var(--accent)!important;font-size:9px!important}
.ch-src-chip svg.i{width:11px;height:11px}
.ava.ch-feed-ava svg.i{width:22px;height:22px;color:#0a0a0a}

/* ===== Telegram-grade управление: сгруппированные списки-настройки ===== */
/* карточка-группа: несколько строк с внутренними разделителями (как настройки Telegram/iOS) */
.ch-list{background:var(--surface);border:1px solid var(--border);border-radius:var(--r-md);overflow:hidden;margin-bottom:6px}
.ch-lf{font-size:11.5px;color:var(--dim);line-height:1.5;padding:8px 6px 2px;margin-bottom:16px}
/* строка списка (переход/тумблер/копи) */
.ch-row{display:flex;align-items:center;gap:13px;width:100%;padding:13px 14px;background:transparent;border:none;
  border-top:1px solid var(--border);text-align:left;cursor:pointer;color:var(--text);transition:background .14s;-webkit-tap-highlight-color:transparent}
.ch-row:first-child{border-top:none}
.ch-row:hover{background:var(--raised)}
.ch-row:active{background:var(--raised)}
.ch-row .ch-row-ic{width:32px;height:32px;border-radius:9px;background:var(--raised);color:var(--lime);
  display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:background .14s}
.ch-row:hover .ch-row-ic{background:var(--lime-dim)}
.ch-row .ch-row-ic svg.i{width:18px;height:18px}
.ch-row .ch-row-ic.danger{color:var(--danger);background:rgba(212,58,58,.1)}
.ch-row .ch-row-main{flex:1;min-width:0}
.ch-row .ch-row-main b{font-size:14px;font-weight:600;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-row .ch-row-main small{color:var(--dim);font-size:11.5px;display:block;margin-top:1px;line-height:1.35;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-row.danger .ch-row-main b{color:var(--danger)}
.ch-row .ch-row-val{color:var(--dim);font-size:12.5px;font-weight:600;flex-shrink:0;display:flex;align-items:center;gap:5px;
  max-width:54%;justify-content:flex-end}
.ch-row .ch-row-val .ch-rv-t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ch-row .ch-row-val .ch-rv-t.lime{color:var(--lime)}
.ch-row .ch-row-val svg.i{width:16px;height:16px;flex-shrink:0;color:var(--dim)}
.ch-row .switch{flex-shrink:0;margin-left:0}

/* ряд быстрых действий (шапка канала / управление): иконка сверху, подпись снизу */
.ch-actrow{display:flex;gap:9px;margin-bottom:14px}
.ch-act{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:11px 6px;
  border-radius:var(--r-md);background:var(--surface);border:1px solid var(--border);color:var(--text);
  cursor:pointer;transition:all .16s;-webkit-tap-highlight-color:transparent}
.ch-act:hover{border-color:var(--lime-dim);background:var(--raised)}
.ch-act:active{transform:scale(.97)}
.ch-act svg.i{width:21px;height:21px;color:var(--lime)}
.ch-act span{font-size:11.5px;font-weight:600;line-height:1;white-space:nowrap}
.ch-act.on{border-color:var(--lime);background:var(--lime-dim)}
.ch-act.on svg.i{color:var(--accent)}

/* URL-подпись в строке-ссылке (полная ширина, лайм) */
.ch-row .ch-row-main small.ch-url{color:var(--lime);font-weight:600;font-size:12px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* ===== комментарии под постами канала (живые: пишем, лайкаем, сохраняются) ===== */
.ch-comments{margin-top:11px;border-top:1px solid var(--border);padding-top:11px;animation:chFade .28s both}
.ch-cmt-list{display:flex;flex-direction:column;gap:11px;margin-bottom:11px}
.ch-cmt-list:empty{margin-bottom:0}
.ch-cmt{display:flex;gap:9px;align-items:flex-start}
.ch-cmt-av{width:30px;height:30px;border-radius:10px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  font:800 12px/1 var(--font-display);background:var(--av-g,linear-gradient(135deg,#141414,#2a2a2a));color:var(--av-c,#0a0a0a)}
/* Светлая тема: процедурные аватары не должны быть чёрными кляксами на белых карточках.
   Фото-аватары задают inline background-image (перебивает CSS без !important) → их не трогаем. */
:root[data-theme="light"] .ch-av,
:root[data-theme="light"] .ch-appear-prev .ch-ap-ava,
:root[data-theme="light"] .ch-cmt-av{
  background:var(--av-gl,var(--av-g,linear-gradient(135deg,#e9f5d2,#cfe9a4)));
  color:var(--av-cl,var(--av-c,#2e4d00))}
.ch-cmt-b{flex:1;min-width:0}
.ch-cmt-top{display:flex;align-items:baseline;gap:7px}
.ch-cmt-top b{font-size:12.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.ch-cmt-top small{color:var(--dim);font-size:10.5px;flex-shrink:0}
.ch-cmt-txt{font-size:12.5px;line-height:1.5;color:var(--text);margin-top:2px;word-break:break-word;overflow-wrap:anywhere}
.ch-cmt-like{flex-shrink:0;display:inline-flex;align-items:center;gap:3px;color:var(--dim);font-size:11px;font-weight:700;
  padding:2px;transition:color .16s}
.ch-cmt-like:hover{color:var(--lime)}
.ch-cmt-like.on{color:var(--lime)}
.ch-cmt-like svg.i{width:14px;height:14px}
.ch-cmt-empty{color:var(--dim);font-size:12px;padding:1px 0 5px}
.ch-cmt-form{display:flex;gap:8px;align-items:center}
.ch-cmt-input{flex:1;min-width:0;background:var(--raised);border:1px solid var(--border);border-radius:99px;color:var(--text);
  font:400 13px/1.3 var(--font-body);padding:9px 14px;outline:none;transition:border-color .16s}
.ch-cmt-input:focus{border-color:var(--lime)}
.ch-cmt-input::placeholder{color:var(--dim)}
.ch-cmt-send{flex-shrink:0;width:38px;height:38px;border-radius:50%;background:var(--lime);color:#0a0a0a;
  display:flex;align-items:center;justify-content:center;cursor:pointer;transition:transform .14s}
.ch-cmt-send:hover{transform:scale(1.06)}
.ch-cmt-send:active{transform:scale(.94)}
.ch-cmt-send svg.i{width:18px;height:18px}

/* ===== закреплённый пост (закреп, как в Telegram) ===== */
.ch-post.pinned{border-color:var(--lime-dim);
  background:linear-gradient(180deg,rgba(154,255,0,.07),var(--surface));box-shadow:0 4px 16px rgba(154,255,0,.08)}
.ch-pin-lab{display:flex;align-items:center;gap:6px;margin-bottom:9px;padding-bottom:9px;border-bottom:1px solid var(--border);
  font:800 10px/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--lime)}
.ch-pin-lab svg.i{width:14px;height:14px;color:var(--lime);flex-shrink:0}
.ch-pin-lab span{flex:1;min-width:0}
.ch-pin-off{flex-shrink:0;color:var(--dim);font:700 11px/1 var(--font-body);letter-spacing:.02em;text-transform:none;
  padding:4px 9px;border-radius:20px;background:var(--raised);transition:color .16s,background .16s;-webkit-tap-highlight-color:transparent}
.ch-pin-off:hover{color:var(--lime);background:var(--lime-dim)}
/* кнопка «Закрепить» в ряду действий поста (наследует стиль .ch-post-acts button) */
.ch-post-acts .ch-pin-btn span{font-size:12px}
@media(max-width:400px){.ch-post-acts .ch-pin-btn span{display:none}}

/* ===== админ-строка с переходом к правам ===== */
.ch-member.ch-member-tap{cursor:pointer;transition:background .14s;border-radius:10px;-webkit-tap-highlight-color:transparent}
.ch-member.ch-member-tap:hover{background:var(--raised)}
.ch-member.ch-member-tap:active{transform:scale(.995)}
.ch-member .ch-m-chev{color:var(--dim);flex-shrink:0;display:inline-flex;align-items:center}
.ch-member .ch-m-chev svg.i{width:17px;height:17px}
.ch-member.ch-member-tap:hover .ch-m-chev{color:var(--lime)}

/* адаптив десктоп */
@media(min-width:900px){
  .ch-kpi{grid-template-columns:repeat(4,1fr)}
  .ch-type-grid{grid-template-columns:1fr}
}

/* ===== 29.07: расширенный мастер создания и каталог платного контента ===== */
/* аватар-пикер (создание) */
.ch-avatar-row{display:flex;gap:12px;align-items:center;margin:6px 0 14px}
.ch-avatar-prev{width:74px;height:74px;border-radius:22px;flex-shrink:0;display:flex;align-items:center;justify-content:center;
  font:800 26px/1 var(--font-display);color:var(--lime);overflow:hidden;
  background:var(--raised);border:1px solid var(--border);box-shadow:0 6px 18px rgba(0,0,0,.28)}
.ch-avatar-prev svg.i{width:32px;height:32px}
.ch-avatar-actions{display:flex;gap:8px;flex:1;min-width:0}
.ch-cover-actions{display:flex;gap:8px;margin:8px 0 10px}
.ch-mt-6{margin-top:6px}
/* PRO-тег */
.ch-pro-tag{display:inline-block;font:800 9px/1 var(--font-body);letter-spacing:.14em;color:#0a0a0a;
  background:var(--lime);padding:3px 6px;border-radius:6px;vertical-align:1px;text-transform:uppercase}
/* чек-строка (галочка + подпись) */
.ch-check-row{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border-radius:14px;
  background:var(--surface);border:1px solid var(--border);margin:10px 0;cursor:pointer;transition:border-color .16s}
.ch-check-row input{accent-color:var(--lime);width:20px;height:20px;flex-shrink:0;margin-top:2px}
.ch-check-row span{display:flex;flex-direction:column;gap:2px;font:600 14px/1.3 var(--font-body);color:var(--text)}
.ch-check-row span small{font:500 12px/1.35 var(--font-body);color:var(--dim)}
.ch-check-row:hover{border-color:var(--lime-dim)}
.ch-check-row input:disabled + span{opacity:.55;cursor:not-allowed}

/* чип «Каталог» первым в списке папок чатов */
.ch-cat-open-chip{display:inline-flex;align-items:center;gap:6px;flex-shrink:0;
  font:800 12px/1 var(--font-body);letter-spacing:.02em;padding:8px 12px;border-radius:99px;
  background:linear-gradient(135deg,#9AFF00 0%,#c8ff5e 100%);color:#0a0a0a;border:none;
  box-shadow:0 6px 16px rgba(154,255,0,.28);margin-right:6px;-webkit-tap-highlight-color:transparent}
.ch-cat-open-chip:hover{filter:brightness(1.05)}
.ch-cat-open-chip:active{transform:scale(.97)}
.ch-cat-open-chip svg.i{width:14px;height:14px;color:#0a0a0a}

/* каталог: фильтры */
.ch-cat-hint{font:600 13px/1.45 var(--font-body);color:var(--dim);background:var(--raised);
  padding:12px 14px;border-radius:14px;border:1px solid var(--border);margin:0 0 14px;
  display:flex;gap:9px;align-items:flex-start}
.ch-cat-hint svg.i{width:17px;height:17px;color:var(--lime);flex-shrink:0;margin-top:1px}
.ch-cat-filter{display:flex;flex-direction:column;gap:6px;margin-bottom:14px}
.ch-cat-lab{font:700 10px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--dim);margin-top:6px}
.ch-cat-chips{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}
.ch-cat-chips::-webkit-scrollbar{display:none}
.ch-cat-chip{flex-shrink:0;font:600 12px/1 var(--font-body);padding:8px 12px;border-radius:99px;
  background:var(--surface);border:1px solid var(--border);color:var(--text);
  cursor:pointer;transition:background .14s,color .14s,border-color .14s;-webkit-tap-highlight-color:transparent;white-space:nowrap}
.ch-cat-chip:hover{border-color:var(--lime-dim);color:var(--lime)}
.ch-cat-chip.on{background:var(--lime);color:#0a0a0a;border-color:var(--lime);font-weight:800}
.ch-cat-count{font:600 12px/1 var(--font-body);color:var(--dim);margin:4px 0 8px}

/* каталог: сетка карточек 2xN */
.ch-catx-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
@media(max-width:360px){.ch-catx-grid{grid-template-columns:1fr}}
@media(min-width:720px){.ch-catx-grid{grid-template-columns:repeat(3,1fr)}}
.ch-catx-card{display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--border);
  border-radius:16px;overflow:hidden;text-align:left;cursor:pointer;transition:transform .16s,border-color .16s,box-shadow .16s;
  -webkit-tap-highlight-color:transparent}
.ch-catx-card:hover{border-color:var(--lime-dim);transform:translateY(-2px);box-shadow:0 10px 26px rgba(0,0,0,.24)}
.ch-catx-card:active{transform:scale(.99)}
.ch-catx-hero{position:relative;aspect-ratio:16/10;padding:10px;display:flex;flex-direction:column;justify-content:space-between}
.ch-catx-kind{align-self:flex-start;display:inline-flex;align-items:center;gap:5px;
  font:800 10px/1 var(--font-body);letter-spacing:.06em;text-transform:uppercase;color:#fff;
  padding:5px 8px;border-radius:99px;background:rgba(0,0,0,.55);backdrop-filter:blur(6px)}
.ch-catx-kind svg.i{width:12px;height:12px}
.ch-catx-price{align-self:flex-end;font:800 13px/1 var(--font-body);color:#0a0a0a;background:var(--lime);
  padding:6px 10px;border-radius:99px;box-shadow:0 4px 12px rgba(154,255,0,.25)}
.ch-catx-price.free{background:rgba(255,255,255,.9);color:#0a0a0a}
.ch-catx-body{padding:11px 12px 13px}
.ch-catx-name{font:800 14px/1.25 var(--font-display);color:var(--text);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:4px}
.ch-catx-sub{font:500 11px/1.35 var(--font-body);color:var(--dim);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-bottom:8px}
.ch-catx-meta{display:flex;gap:12px;align-items:center;color:var(--dim);
  font:700 11px/1 var(--font-body)}
.ch-catx-meta span{display:inline-flex;align-items:center;gap:3px}
.ch-catx-meta svg.i{width:12px;height:12px}
.ch-catx-star{color:#ffc522}
.ch-catx-star svg.i{color:#ffc522}

/* ===== module: ui-chrome ===== */
/* ============================================================
   UI-CHROME · глобальный хром и премиум-полировка
   Владелец: base.html + этот модуль. Грузится последним в ORDER,
   чтобы аккуратно унифицировать глобальные элементы поверх ядра.
   НЕ трогает: composer/.msgs/#msgMenu/#callScreen/#storyViewer,
   .post-карточки и чипы ленты, экраны игр/кошелька/академии/биржи.
   ============================================================ */

/* ---------- SAFE-AREA: все fullscreen-вьюхи не заезжают под чёлку ---------- */
/* --oko-sa* приходят из base.html (инсеты Telegram-фуллскрина). Вне TG они
   не заданы → max() падает на env(safe-area-*). Fixed-оверлеи живут ВНЕ #app,
   поэтому пэддинг #app из tg-webapp их не защищает — защищаем здесь. */
/* базовые классы шапок — единый безопасный отступ сверху */
.sv-head,
.ep-head,
.search-head{
  padding-top:max(env(safe-area-inset-top),var(--oko-sat,0px),14px);
}
/* вьюхи-модули, у которых своя шапка без safe-area */
#hqEmbed .hq-emb-head,
#regView .ep-head,
#legalView .lg-tabs{
  padding-top:max(env(safe-area-inset-top),var(--oko-sat,0px),12px);
}
/* контейнеры-вьюхи: нижний safe-area, чтобы контент не прятался за home-bar */
#searchView .sv-body,
#notifsView .sv-body,
#adminView .sv-body,
#systemView .sv-body{
  padding-bottom:max(calc(30px + env(safe-area-inset-bottom)),calc(30px + var(--oko-sab,0px)));
}
/* звонок — тоже вне #app, верх/низ под инсеты TG */
#callScreen{
  padding-top:max(calc(60px + env(safe-area-inset-top)),calc(50px + var(--oko-sat,0px)));
  padding-bottom:max(calc(40px + env(safe-area-inset-bottom)),calc(34px + var(--oko-sab,0px)));
}

/* ---------- ПУСТОЕ ПОЛЕ ВНИЗУ: дыхание контента + safe-area ---------- */
main>.screen>.pad{
  padding-bottom:calc(22px + env(safe-area-inset-bottom));
}
/* лента и списки без .pad — небольшой хвост снизу под home-bar */
#feedList,
#chatList{
  padding-bottom:env(safe-area-inset-bottom);
}

/* ============ НИЖНЯЯ НАВИГАЦИЯ: индикатор + плавное переключение ============ */
nav#tabs{position:relative}
nav#tabs>button{position:relative;transition:color .22s ease;overflow:visible}
nav#tabs>button svg.i{transition:transform .28s cubic-bezier(.34,1.4,.5,1),filter .22s}
/* верхний лайм-индикатор активной вкладки (мобайл) */
nav#tabs>button::before{
  content:'';position:absolute;top:0;left:50%;
  width:24px;height:3px;border-radius:0 0 3px 3px;background:var(--lime);
  transform:translateX(-50%) scaleX(0);transform-origin:center;
  transition:transform .3s cubic-bezier(.34,1.4,.5,1),opacity .25s;
  opacity:0;box-shadow:0 0 9px rgba(154,255,0,.55);
}
nav#tabs>button.active::before{transform:translateX(-50%) scaleX(1);opacity:1}
nav#tabs>button.active svg.i{transform:translateY(-1px) scale(1.1);filter:drop-shadow(0 0 6px rgba(154,255,0,.5))}
nav#tabs>button:active svg.i{transform:scale(.88)}
:root[data-theme="light"] nav#tabs>button.active svg.i{filter:none}
:root[data-theme="light"] nav#tabs>button::before{box-shadow:0 0 6px rgba(110,200,0,.4)}
/* десктоп: индикатор слева, вертикальный (сайдбар) */
@media(min-width:900px){
  nav#tabs>button::before{
    top:50%;left:0;width:3px;height:26px;border-radius:0 3px 3px 0;
    transform:translateY(-50%) scaleY(0);
  }
  nav#tabs>button.active::before{transform:translateY(-50%) scaleY(1)}
}
@media(prefers-reduced-motion:reduce){
  nav#tabs>button svg.i,nav#tabs>button::before{transition:none}
}

/* ============ КНОПКИ: единые состояния/тени/градиент лайма ============ */
.btn{
  border-radius:var(--r-md);
  transition:transform .12s ease,box-shadow .22s ease,filter .22s ease,background .2s;
  box-shadow:0 6px 18px rgba(154,255,0,.16);
  /* если текст всё-таки не влезает — многоточие вместо жёсткого обреза */
  text-overflow:ellipsis;
  min-width:0;
}
.btn:hover{box-shadow:0 8px 24px rgba(154,255,0,.26);filter:brightness(1.04)}
.btn:active{transform:scale(.97);box-shadow:0 3px 10px rgba(154,255,0,.2)}
.btn.ghost{box-shadow:none;transition:transform .12s ease,background .2s,border-color .2s,color .2s}
.btn.ghost:hover{background:var(--lime-dim);border-color:var(--accent)}
.btn.ghost:active{transform:scale(.97)}
.btn[disabled],.btn:disabled{opacity:.5;pointer-events:none;box-shadow:none;filter:grayscale(.3)}
:root[data-theme="light"] .btn{box-shadow:0 5px 14px rgba(110,200,0,.22)}
:root[data-theme="light"] .btn:hover{box-shadow:0 7px 20px rgba(110,200,0,.32)}

/* ============ ЧИПЫ: аккуратный лайм-градиент и рамка ============ */
.chip{
  border:1px solid transparent;line-height:1.5;
  background:linear-gradient(135deg,rgba(154,255,0,.18),rgba(154,255,0,.08));
  transition:background .2s,border-color .2s,color .2s;
}
:root[data-theme="light"] .chip{
  background:linear-gradient(135deg,rgba(110,200,0,.16),rgba(110,200,0,.07));
  border-color:rgba(110,200,0,.18);
}
.chip.on{background:var(--lime);border-color:var(--lime);color:#000}

/* ============ КАРТОЧКИ: единый радиус, мягкая тень, живой ховер ============ */
.card{
  transition:border-color .22s ease,box-shadow .22s ease;
  box-shadow:0 1px 0 rgba(255,255,255,.015) inset,0 8px 22px rgba(0,0,0,.22);
}
:root[data-theme="light"] .card{box-shadow:0 6px 16px rgba(40,60,15,.06)}
.card:hover{border-color:color-mix(in srgb,var(--border) 55%,var(--accent))}

/* ============ СТРОКИ ПРОФИЛЯ: ховер/актив как у нативных списков ============ */
.prow{border-radius:12px;padding:14px 12px;margin:0 -8px;transition:background .18s,transform .1s}
.prow:hover{background:var(--lime-dim)}
.prow:active{transform:scale(.99);background:var(--lime-dim)}
.prow .chev svg.i{transition:transform .2s}
.prow:hover .chev svg.i{transform:translateX(3px);color:var(--accent)}

/* ============ АВАТАРЫ: тонкое лайм-кольцо на брендовых ============ */
.ava.lime{box-shadow:0 0 0 1px rgba(154,255,0,.3),0 4px 12px rgba(154,255,0,.14)}
:root[data-theme="light"] .ava.lime{box-shadow:0 0 0 1px rgba(110,200,0,.28)}

/* ============ SHEET: чуть премиальнее ручка и подложка ============ */
/* Тень ТОЛЬКО у открытого листа. Закрытый лист припаркован на 12px ниже вьюпорта
   (translateY(105%)), и его «верхняя» тень (offset -Ypx, blur 40-50) раньше
   протекала вверх на нижнюю навигацию — это и была та самая «тень снизу»
   в ОБЕИХ темах. Гейтим по .open — закрытый лист больше ничего не рисует. */
.sheet.open{box-shadow:0 -18px 50px rgba(0,0,0,.5)}
:root[data-theme="light"] .sheet.open{box-shadow:0 -14px 40px rgba(40,60,15,.14)}
.sheet::before{transition:background .2s}
.sheet-overlay{backdrop-filter:blur(2px)}
.sheet-item{border-radius:10px;transition:background .16s}
.sheet-item:hover{background:var(--lime-dim)}

/* ============ СТАТ-КАРТОЧКИ: единый ховер и лёгкий glow цифры ============ */
.stat{transition:border-color .22s,transform .14s}
.stat:hover{border-color:color-mix(in srgb,var(--border) 50%,var(--accent))}
.stat .v{text-shadow:0 0 18px rgba(154,255,0,.18)}
:root[data-theme="light"] .stat .v{text-shadow:none}

/* ============ SVC-плитки хаба: мягкий подъём + блик ============ */
.svc-ic{transition:transform .15s cubic-bezier(.34,1.4,.5,1),box-shadow .22s}
.svc:hover .svc-ic{transform:translateY(-2px);box-shadow:0 12px 26px rgba(0,0,0,.5)}
:root[data-theme="light"] .svc:hover .svc-ic{box-shadow:0 8px 20px rgba(60,90,20,.16)}

/* ============ MA-HERO: медленный дрейф сетки + пульс glow ============ */
#screen-mini .ma-hero{background-size:28px 28px,28px 28px,auto,auto;animation:uicHeroGrid 22s linear infinite}
@keyframes uicHeroGrid{to{background-position:28px 28px,28px 28px,0 0,0 0}}
#screen-mini .ma-hero-logo{animation:uicHeroGlow 5s ease-in-out infinite}
@keyframes uicHeroGlow{
  0%,100%{filter:drop-shadow(0 0 12px rgba(154,255,0,.4));opacity:.85}
  50%{filter:drop-shadow(0 0 22px rgba(154,255,0,.7));opacity:1}
}
/* svc-grid: очень лёгкий каскад появления при открытии хаба */
#screen-mini .svc-grid .svc{animation:uicSvcIn .45s cubic-bezier(.3,1,.4,1) both}
#screen-mini .svc-grid .svc:nth-child(1){animation-delay:.02s}
#screen-mini .svc-grid .svc:nth-child(2){animation-delay:.05s}
#screen-mini .svc-grid .svc:nth-child(3){animation-delay:.08s}
#screen-mini .svc-grid .svc:nth-child(4){animation-delay:.11s}
#screen-mini .svc-grid .svc:nth-child(5){animation-delay:.14s}
#screen-mini .svc-grid .svc:nth-child(6){animation-delay:.17s}
#screen-mini .svc-grid .svc:nth-child(7){animation-delay:.2s}
#screen-mini .svc-grid .svc:nth-child(8){animation-delay:.23s}
@keyframes uicSvcIn{from{opacity:0;transform:translateY(10px) scale(.96)}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:reduce){
  #screen-mini .ma-hero,#screen-mini .ma-hero-logo,#screen-mini .svc-grid .svc{animation:none}
}

/* ============ ВХОД: премиум-акцент онбординг-точек и splash-глаза ============ */
#onboard .ob-dots span.on{box-shadow:0 0 10px rgba(154,255,0,.6)}
#splash .eye{position:relative}
#splash .eye::after{
  content:'';position:absolute;inset:-18%;border-radius:50%;
  background:radial-gradient(circle,rgba(154,255,0,.25),transparent 62%);
  animation:uicSplashHalo 2.4s ease-in-out infinite;pointer-events:none;
}
@keyframes uicSplashHalo{0%,100%{opacity:.4;transform:scale(.9)}50%{opacity:.9;transform:scale(1.08)}}
@media(prefers-reduced-motion:reduce){#splash .eye::after{animation:none}}

/* ============================================================
   АДАПТИВ: TG / телефон / планшет / ПК / ультраширокий
   Контейнеры центрируются, ничего не растягивается и не обрезается.
   ============================================================ */

/* ---------- ПК ≥900px: единая контент-колонка (лента/хаб/профиль/кошелёк/
   игры/академия/реклама и т.д. центрируются, не растягиваются на ширь) ---------- */
@media(min-width:900px){
  /* все экраны с оболочкой .pad -> одна согласованная колонка по центру */
  main>.screen>.pad{
    max-width:900px;margin-inline:auto;width:100%;
    padding-left:26px;padding-right:26px;
  }
  /* лента уже центрируется своим #screen-feed{max-width:820px}; выравниваем
     её ширину под общий ритм колонки */
  #screen-feed{max-width:900px}
  /* fixed-панели капнуты на 1280 (base.html). Их ВНУТРЕННИЙ контент —
     форм-центрируем, чтобы поля/списки не были на всю ширь монитора */
  .ep-body>*,
  #systemView .sv-body>*,
  #searchView .sv-body>*,
  #notifsView .sv-body>*{
    max-width:640px;margin-inline:auto;
  }
  /* поиск/уведомления/система: сама шапка тоже по центру колонки */
  #searchView .search-head,
  #systemView .sv-head,
  #notifsView .sv-head{padding-left:max(18px,calc((100% - 640px)/2));padding-right:max(18px,calc((100% - 640px)/2))}
  /* админка — дашборд, ей нужна ширина: колонку не сужаем, лишь центрируем */
  #adminView .sv-body{max-width:1040px;margin-inline:auto;width:100%}
  /* HOVER: карточки мини-аппов заметнее приподнимаются на ПК (тач их не трогает) */
  .ma-card:hover{transform:translateY(-2px)}
}

/* десктоп двухколоночный чат: не даём разговору расплываться слишком широко */
@media(min-width:900px){
  #conv .msgs{width:100%;max-width:900px;margin-inline:auto}
}

/* ---------- ПЛАНШЕТ 700–1100 в портрете: аккуратная ширина колонки ---------- */
@media(min-width:700px) and (max-width:899px){
  main>.screen>.pad{max-width:720px;margin-inline:auto;width:100%}
  #screen-feed{max-width:720px;margin-inline:auto;width:100%}
}

/* ---------- LANDSCAPE на телефоне: safe-area слева/справа (чёлка сбоку) ---------- */
@media(max-width:899px) and (orientation:landscape){
  header{
    padding-left:max(16px,env(safe-area-inset-left),var(--oko-sal,0px));
    padding-right:max(16px,env(safe-area-inset-right),var(--oko-sar,0px));
  }
  main>.screen>.pad{
    padding-left:max(18px,env(safe-area-inset-left),var(--oko-sal,0px));
    padding-right:max(18px,env(safe-area-inset-right),var(--oko-sar,0px));
  }
  /* нижнюю навигацию в ландшафте прижимаем компактнее по высоте */
  nav#tabs>button{padding-top:7px;padding-bottom:6px}
}

/* ---------- УЗКИЕ ЭКРАНЫ ≤360px: убрать риск переполнения/обрезки ---------- */
@media(max-width:360px){
  .pad{padding:14px}
  header{padding-left:12px;padding-right:12px;gap:8px}
  nav#tabs>button{font-size:9.8px;padding-left:2px;padding-right:2px}
  /* хаб-сетка сервисов: 4 колонки на 360 не жмут подписи */
  .svc-grid{gap:12px 6px}
  .svc-label{font-size:10px}
}

/* ---------- SHEET: на широких экранах не гигантский, по центру (уже 480),
   на узких — во всю ширину с боковым зазором; высота под landscape ---------- */
.sheet{max-width:min(480px,calc(100vw - 20px))}
@media(max-height:520px){
  .sheet{max-height:92dvh}
  .sheet .stickers-grid,.stickers-grid{max-height:44vh}
}

/* ---------- УЛЬТРАШИРОКИЙ >1280: закрытые slide-in панели капнуты на 1280 и
   центрированы (base.html), поэтому translateX(100%) не убирает их полностью —
   на ширине >1280 остаётся тонкая полоска справа. Прячем гарантированно. ---------- */
@media(min-width:1281px){
  #editProfile:not(.open),
  #systemView:not(.open),
  #searchView:not(.open),
  #notifsView:not(.open),
  #adminView:not(.open),
  #regView:not(.open),
  #legalView:not(.open),
  #psView:not(.open),
  #st2View:not(.open),
  #chView:not(.open){transform:translateX(100vw)}
}

/* ---------- ГЛОБАЛЬНО: ничего не выпирает по горизонтали ---------- */
img,video,canvas,svg{max-width:100%}
.pad,.card,.sheet{overflow-wrap:anywhere}

/* ============================================================
   UI-CHROME · FLAGSHIP-ПОЛИРОВКА ХАБА (super-app home) + splash
   Только #screen-mini (мой хиро/плитки) и #splash. Все движения —
   GPU/transform. Пауза: html.oko-scrolling (перф-слой) + .uic-hero-off
   (хиро ушёл из вьюпорта, IntersectionObserver в script.js) + reduced-motion.
   ============================================================ */

/* ---------- ХИРО: диагональный блик-«свет» плавно скользит (WOW #1) ---------- */
/* ::before свободен (base занимает только .ma-hero::after). z-index:1 — под текстом
   (.ma-hero-txt z2), но над сеткой; screen-blend + низкая альфа не мешают читаемости. */
#screen-mini .ma-hero::before{
  content:'';position:absolute;top:-45%;left:0;width:40%;height:190%;z-index:1;
  pointer-events:none;will-change:transform;
  background:linear-gradient(105deg,transparent,rgba(154,255,0,.10) 42%,rgba(255,255,255,.16) 50%,rgba(154,255,0,.10) 58%,transparent);
  mix-blend-mode:screen;transform:translateX(-160%) rotate(9deg);
  animation:uicHeroSheen 7.5s cubic-bezier(.5,0,.3,1) infinite;
}
@keyframes uicHeroSheen{
  0%{transform:translateX(-160%) rotate(9deg)}
  48%,100%{transform:translateX(360%) rotate(9deg)}
}

/* ---------- ХИРО: параллакс-слои (WOW #2, управляется script.js) ---------- */
/* JS кладёт --uic-lx/--uic-ly (глаз) и --uic-tx/--uic-ty (текст). Трансформ
   аддитивен к позиции base (глаз позиционируется right/top; текст position:relative).
   Свечение глаза в base анимирует только filter/opacity — конфликта нет. */
#screen-mini .ma-hero-logo{
  transform:translate(var(--uic-lx,0px),var(--uic-ly,0px));
  transition:transform .35s cubic-bezier(.2,.8,.2,1);
}
#screen-mini .ma-hero-txt{
  transform:translate(var(--uic-tx,0px),var(--uic-ty,0px));
  transition:transform .35s cubic-bezier(.2,.8,.2,1);
}
/* хиро ушёл из вьюпорта или идёт скролл → замораживаем всё движение хиро */
#screen-mini .ma-hero.uic-hero-off::before,
html.oko-scrolling #screen-mini .ma-hero::before{animation-play-state:paused}

/* ---------- ХИРО: баланс-чип премиальнее (сам чип принадлежит core-ext,
   здесь только контекст хиро) ---------- */
#screen-mini .ma-hero .balance-chip{
  margin-top:11px;padding:7px 14px;
  background:linear-gradient(135deg,rgba(154,255,0,.20),rgba(154,255,0,.08));
  border:1px solid rgba(154,255,0,.28);
  box-shadow:0 4px 16px rgba(0,0,0,.35),0 0 0 3px rgba(154,255,0,.05);
  backdrop-filter:blur(3px);transition:transform .14s ease,box-shadow .2s ease;
}
#screen-mini .ma-hero .balance-chip:hover{transform:translateY(-1px);box-shadow:0 6px 20px rgba(154,255,0,.22)}
#screen-mini .ma-hero .balance-chip:active{transform:scale(.97)}

/* ---------- ПЛИТКИ СЕРВИСОВ: чётче, глубже, живой ховер ---------- */
/* тёмная: убираем «мутность», добавляем rim-light сверху и чистый градиент */
#screen-mini .svc-ic{
  background:linear-gradient(158deg,#1d3510 0%,#0b1205 76%);
  border-color:rgba(154,255,0,.15);
  box-shadow:0 10px 22px rgba(0,0,0,.5),0 1px 0 rgba(154,255,0,.12) inset;
}
#screen-mini .svc-ic::before{background:radial-gradient(circle at 50% 20%,rgba(154,255,0,.24),transparent 68%)}
#screen-mini .svc:hover .svc-ic{
  transform:translateY(-3px);
  box-shadow:0 16px 30px rgba(0,0,0,.55),0 0 0 1px rgba(154,255,0,.42),0 6px 22px rgba(154,255,0,.20);
}
#screen-mini .svc:active .svc-ic{transform:scale(.93)}
/* светлая: аккуратная глубина вместо плоской заливки */
:root[data-theme="light"] #screen-mini .svc-ic{
  background:linear-gradient(158deg,#ecfcd6,#d7f2b2);
  border-color:rgba(110,200,0,.30);
  box-shadow:0 6px 16px rgba(60,90,20,.12),0 1px 0 rgba(255,255,255,.65) inset;
}
:root[data-theme="light"] #screen-mini .svc:hover .svc-ic{
  transform:translateY(-3px);
  box-shadow:0 12px 24px rgba(60,90,20,.18),0 0 0 1px rgba(110,200,0,.4);
}
/* ПОДПИСИ: максимум 2 строки, аккуратный перенос, без обрезки букв и переполнения */
#screen-mini .svc-label{
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;
  overflow:hidden;hyphens:auto;
}

/* ---------- SPLASH: добавляем расходящееся кольцо к halo (тактичный reveal) ---------- */
/* base: #splash .eye — filter+splashBlink; ui-chrome ::after — halo; ::before свободен */
#splash .eye::before{
  content:'';position:absolute;inset:-8%;border-radius:50%;
  border:1.5px solid rgba(154,255,0,.5);pointer-events:none;will-change:transform,opacity;
  animation:uicSplashRing 2.6s ease-out infinite;animation-delay:.4s;
}
@keyframes uicSplashRing{
  0%{transform:scale(.7);opacity:0}
  18%{opacity:.75}
  70%,100%{transform:scale(1.55);opacity:0}
}

/* ---------- reduced-motion: гасим всё добавленное движение ---------- */
@media(prefers-reduced-motion:reduce){
  #screen-mini .ma-hero::before{animation:none;opacity:.5}
  #screen-mini .ma-hero-logo,#screen-mini .ma-hero-txt{transition:none;transform:none}
  #splash .eye::before{animation:none;opacity:0}
}

/* ============================================================
   UI-CHROME · ДЕСКТОП-ПОЛИРОВКА ОВЕРЛЕЙ-ПАНЕЛЕЙ (только ПК)
   Аудит на ПК: панели Поиск / Уведомления / Система на широких
   экранах выглядели «пустотой» — тонкая колонка 640 в чёрной панели
   1280 с большими боковыми и вертикальными провалами; края шапки и
   списка чуть расходились. Здесь всё лечим, НЕ трогая мобайл: каждое
   правило строго внутри @media(min-width:900px) / (min-width:1200px).
   Функциональность не меняется — только раскладка/CSS. Класс uic-qa
   на #searchView ставит ui-chrome/script.js (пустой запрос = быстрый
   доступ). Перф-слой не задет: без анимаций на скролле, лёгкие тени.
   ============================================================ */

/* ---------- ПОИСК ≥900: единая колонка + карточная сетка быстрого доступа ---------- */
@media(min-width:900px){
  /* и поле-шапка, и тело поиска делят ОДНИ левый/правый края (колонка 720).
     Переопределяет общий cap 640 из блока выше (тот же/выше приоритет + позже в файле) */
  #searchView .sv-body>*{max-width:720px}
  #searchView .search-head{
    padding-left:max(18px,calc((100% - 720px)/2));
    padding-right:max(18px,calc((100% - 720px)/2));
  }
  /* быстрый доступ (пустой запрос) → карточная сетка, привязанная к ВЕРХУ:
     заполняет колонку с воздухом, не висит в центре чёрной пустоты.
     Центрируем сетку ПЭДДИНГОМ (не max-width+margin-auto: у flex-элемента,
     ставшего grid, авто-margin по кроссоси отключает stretch и колонка
     схлопывается до содержимого). Формула паддинга = формула шапки → края
     сетки и поля поиска совпадают в пиксель. */
  #searchView.uic-qa .sv-body{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:14px;
    padding-left:max(18px,calc((100% - 720px)/2));
    padding-right:max(18px,calc((100% - 720px)/2));
    align-content:start;
  }
  /* в режиме сетки снимаем общий cap 640/центрирование у прямых детей */
  #searchView.uic-qa .sv-body>*{max-width:none;margin:0}
  /* заголовок группы — во всю строку сетки */
  #searchView.uic-qa .sv-body .nt-group{grid-column:1 / -1;margin:2px 0 2px 2px}
  /* элементы быстрого доступа → брендовые карточки (вертикальная раскладка) */
  #searchView.uic-qa .sv-body .nt-item{
    flex-direction:column;align-items:flex-start;gap:14px;
    padding:20px 18px;
    border:1px solid var(--border);border-radius:var(--r-md);
    background:linear-gradient(158deg,color-mix(in srgb,var(--surface) 88%,transparent),transparent);
    transition:border-color .2s ease,transform .14s ease,box-shadow .22s ease;
  }
  #searchView.uic-qa .sv-body .nt-item:hover{
    border-color:color-mix(in srgb,var(--border) 45%,var(--accent));
    transform:translateY(-2px);
    box-shadow:0 12px 26px rgba(0,0,0,.28);
  }
  #searchView.uic-qa .sv-body .nt-item:active{transform:translateY(0) scale(.99)}
  :root[data-theme="light"] #searchView.uic-qa .sv-body .nt-item:hover{box-shadow:0 10px 22px rgba(60,90,20,.12)}
  /* иконка крупнее и в лайм-подсветке — карточка читается как «сервис» */
  #searchView.uic-qa .sv-body .nt-item .nt-ic{
    width:46px;height:46px;border-radius:14px;
    background:linear-gradient(158deg,rgba(154,255,0,.16),rgba(154,255,0,.04));
    border-color:rgba(154,255,0,.22);color:var(--accent);
  }
  :root[data-theme="light"] #searchView.uic-qa .sv-body .nt-item .nt-ic{
    background:linear-gradient(158deg,rgba(110,200,0,.14),rgba(110,200,0,.04));
    border-color:rgba(110,200,0,.24);
  }
  #searchView.uic-qa .sv-body .nt-item .nt-b span{font-size:15px;font-weight:600}
}

/* ---------- УВЕДОМЛЕНИЯ / СИСТЕМА ≥1200: шире колонка + края шапки=список ---------- */
@media(min-width:1200px){
  /* колонка чтения 800 вместо 640 — меньше боковых провалов на ≥1280 */
  #systemView .sv-body>*,
  #notifsView .sv-body>*{max-width:800px}
  /* шапка («Прочитать» и т.п.) центрируется по ТОЙ ЖЕ колонке 800 — един. края */
  #systemView .sv-head,
  #notifsView .sv-head{
    padding-left:max(18px,calc((100% - 800px)/2));
    padding-right:max(18px,calc((100% - 800px)/2));
  }
  /* поиск на больших мониторах: колонка ~880, быстрый доступ в 3 колонки */
  #searchView .sv-body>*{max-width:880px}
  #searchView .search-head{
    padding-left:max(18px,calc((100% - 880px)/2));
    padding-right:max(18px,calc((100% - 880px)/2));
  }
  #searchView.uic-qa .sv-body{
    grid-template-columns:repeat(3,minmax(0,1fr));
    padding-left:max(18px,calc((100% - 880px)/2));
    padding-right:max(18px,calc((100% - 880px)/2));
  }
}

/* ===== module: wow-eye ===== */
/* wow-eye ОТКЛЮЧЁН по правке Даниэля от 29.07:
   canvas-фолбэк рисовал упрощённый круг-глаз с зрачком, что после
   загрузки выглядело как «капля». Теперь на экране входа показываем
   мастер-PNG oko-logo-master.png (эталон бренда с запечённым halo,
   тот же файл на договорах и КП). Скрытие .auth-logo убрано. */
#we-wrap{display:none!important}

/* ===== module: wow-motion ===== */
/* ==========================================================================
   wow-motion — финальный вау-слой OKO: премиальная типографика, брендовый
   моушен, микро-интеракции и ровное лаймовое свечение. Грузится последним,
   поэтому аккуратно переопределяет глобальное. Обе темы. prefers-reduced-motion.
   Префикс собственных классов/анимаций: wm* / .wm-*
   ========================================================================== */

:root{
  --wm-ease:cubic-bezier(.22,1,.36,1);      /* мягкий «дорогой» out */
  --wm-ease-io:cubic-bezier(.16,1,.3,1);
  --wm-spring:cubic-bezier(.34,1.56,.64,1); /* лёгкий overshoot для press */
  --wm-glow:0 0 22px rgba(154,255,0,.30);
  --wm-glow-soft:0 6px 20px rgba(154,255,0,.16);
}

/* =========================================================================
   1. ТИПОГРАФИКА — «дорого», без изменения layout
   Правим только рендер/трекинг/межстрочные/вес/цвет на существующих классах.
   ========================================================================= */
body{
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  text-rendering:optimizeLegibility;
  font-feature-settings:"kern" 1,"liga" 1;
  letter-spacing:.003em;
}
/* Bebas-заголовки: чуть плотнее по вертикали + выверенный трекинг = designed look */
h1,h2,h3,.display{
  letter-spacing:.055em;
  line-height:.98;
  font-feature-settings:"kern" 1;
}
.section-h{
  font-size:25px;
  letter-spacing:.06em;
  line-height:1.02;
}
/* Лого в шапке — ровное свечение только в тёмной теме */
header .logo{ text-shadow:0 0 16px rgba(154,255,0,.28); }
:root[data-theme="light"] header .logo{ text-shadow:none; }

/* Крупные цифры-акценты (счётчики/статы) — премиальный лаймовый ореол в тёмной */
.stat .v{ letter-spacing:.01em; text-shadow:0 0 20px rgba(154,255,0,.22); }
:root[data-theme="light"] .stat .v{ text-shadow:none; }

/* Читабельный body-текст в описаниях/подписях */
.dim,.svc-note,.stat .l,.sheet-item small{ line-height:1.5; }
.stat .l{ letter-spacing:.11em; }

/* Кнопки/чипы — ровный трекинг для «набора», без ломки размеров */
.btn{ letter-spacing:.015em; }
.chip{ letter-spacing:.07em; }

/* =========================================================================
   2. МИКРО-ИНТЕРАКЦИИ — pressed / hover / плавные переходы (обе темы)
   Работают всегда (не завязаны на wm-on), т.к. не создают «прыжков».
   ========================================================================= */
.btn{ transition:transform .14s var(--wm-spring), box-shadow .28s ease, filter .2s ease; }
.btn:active{ transform:scale(.965); }
/* Первичная CTA — чуть более «дорогой» тактильный отклик (только transform, без сдвига layout) */
.btn:not(.ghost):not(.sm):active{ transform:scale(.955) translateY(1px); }

/* Лаймовый фокус-ринг на полях ввода — box-shadow, поэтому БЕЗ сдвига layout. Обе темы. */
input:focus-visible,textarea:focus-visible,select:focus-visible,[contenteditable="true"]:focus-visible{
  outline:none;
  box-shadow:0 0 0 2px var(--bg), 0 0 0 3px var(--accent), 0 0 14px rgba(154,255,0,.24);
  border-color:var(--accent);
}
:root[data-theme="light"] input:focus-visible,
:root[data-theme="light"] textarea:focus-visible,
:root[data-theme="light"] select:focus-visible,
:root[data-theme="light"] [contenteditable="true"]:focus-visible{
  box-shadow:0 0 0 2px var(--bg), 0 0 0 3px var(--accent), 0 0 12px rgba(110,200,0,.20);
}

/* Стат-цифры (для count-up) — моноширинные цифры, чтобы ширина не «прыгала» при счёте */
.pay-sum,.stat .v,.pstat .v,.ch-stat .v,.pw-live-cell .v,.adm-kpi b,.gm-prz-stat b{
  font-variant-numeric:tabular-nums;
  font-feature-settings:"tnum" 1,"kern" 1;
}

/* Ровное лаймовое свечение на первичной CTA (не ghost, не мелкой) */
.btn:not(.ghost):not(.sm){ box-shadow:var(--wm-glow-soft); }
:root[data-theme="light"] .btn:not(.ghost):not(.sm){ box-shadow:0 6px 16px rgba(110,200,0,.20); }

.chip{ transition:transform .14s var(--wm-spring), background .2s ease, color .2s ease; }
.chip:active{ transform:scale(.93); }

.prow{ transition:background .2s ease, transform .14s ease; border-radius:12px; }
.prow:active{ background:var(--lime-dim); transform:scale(.99); }

.sheet-item{ transition:background .18s ease; border-radius:10px; }
.sheet-item:active{ background:var(--lime-dim); }

.card{ transition:transform .2s var(--wm-ease), box-shadow .28s ease, border-color .25s ease; }

/* Тайлы мини-аппов: press уже есть в ядре — добавим свечение */
.svc-ic{ transition:transform .18s var(--wm-spring), box-shadow .28s ease; }

/* Нижняя навигация — плавность + микро-press */
nav#tabs>button{ transition:color .2s ease, transform .14s var(--wm-spring); position:relative; }
nav#tabs>button:active{ transform:scale(.9); }
nav#tabs>button.active svg.i{ filter:drop-shadow(0 0 7px rgba(154,255,0,.55)); }
:root[data-theme="light"] nav#tabs>button.active svg.i{ filter:drop-shadow(0 0 5px rgba(83,168,0,.45)); }

/* Активный таб — ровный лаймовый индикатор (мобайл: сверху) */
nav#tabs>button.active::before{
  content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);
  width:24px;height:2px;border-radius:2px;background:var(--lime);
  box-shadow:0 0 8px var(--lime);
}
/* Десктоп: навигация — левый рельс, индикатор слева */
@media(min-width:900px){
  nav#tabs>button.active::before{
    top:50%;left:0;transform:translateY(-50%);
    width:3px;height:22px;
  }
}

/* Hover — только на устройствах с реальным ховером (ПК), не ломает тач */
@media(hover:hover){
  .btn:not(.ghost):hover{ box-shadow:var(--wm-glow); transform:translateY(-1px); }
  .btn.ghost:hover{ box-shadow:0 0 0 1px var(--accent), 0 0 16px rgba(154,255,0,.20); }
  .svc:hover .svc-ic{ transform:translateY(-3px) scale(1.03); box-shadow:0 14px 28px rgba(0,0,0,.5), 0 0 18px rgba(154,255,0,.18); }
  :root[data-theme="light"] .svc:hover .svc-ic{ box-shadow:0 10px 22px rgba(60,90,20,.16); }
  .card:hover{ border-color:rgba(154,255,0,.22); box-shadow:0 10px 30px rgba(0,0,0,.28); }
  :root[data-theme="light"] .card:hover{ border-color:rgba(110,200,0,.4); box-shadow:0 10px 24px rgba(60,90,20,.10); }
  .prow:hover{ background:var(--lime-dim); }
  .chip:hover{ background:var(--lime); color:#000; }
  .theme-btn:hover{ transform:rotate(-12deg); }
  nav#tabs>button:hover{ color:var(--accent); }
}

/* =========================================================================
   3. АКЦЕНТНЫЕ ПОВЕРХНОСТИ — «горячий» тариф, живой лаймовый ореол
   ========================================================================= */
.plan.hot{ box-shadow:0 0 0 1px var(--accent), 0 12px 34px rgba(154,255,0,.12); }
:root[data-theme="light"] .plan.hot{ box-shadow:0 0 0 1px var(--accent), 0 10px 26px rgba(110,200,0,.14); }

/* =========================================================================
   4. МОУШЕН ПОЯВЛЕНИЯ (reveal) — включается ТОЛЬКО когда JS добавил html.wm-on
   и НЕ при reduced-motion. Без JS/при reduced-motion — контент виден сразу
   (ничего не прячем «навсегда»).
   ========================================================================= */
/* БЕЗОПАСНО: контент НИКОГДА не прячется (opacity всегда 1). Reveal — только лёгкий
   доводочный сдвиг, который не может оставить блок невидимым (убрало «пустой кошелёк»). */
html.wm-on .wm-r{
  opacity:1;                              /* контент ВСЕГДА виден — не прячем никогда */
  transform:translateY(8px) scale(.994);  /* доводочный сдвиг + едва заметный масштаб */
}
html.wm-on .wm-r.wm-in{
  transform:none;
  transition:transform .52s var(--wm-ease-io);
  transition-delay:var(--wm-d,0ms);
}

/* Плавный вход экрана при переключении табов (тонко, opacity+микросдвиг) */
html.wm-on .screen.active{ animation:wmScreenIn .34s var(--wm-ease-io) both; }
@keyframes wmScreenIn{
  from{ opacity:.35; transform:translateY(7px) scale(.997); }
  to{ opacity:1; transform:none; }
}

/* Мягкая пульсация ровного свечения — только на «горячем» тарифе, деликатно */
html.wm-on .plan.hot{ animation:wmHotPulse 3.6s var(--wm-ease) infinite; }
@keyframes wmHotPulse{
  0%,100%{ box-shadow:0 0 0 1px var(--accent), 0 12px 34px rgba(154,255,0,.10); }
  50%{ box-shadow:0 0 0 1px var(--accent), 0 12px 40px rgba(154,255,0,.22); }
}
:root[data-theme="light"] html.wm-on .plan.hot{ animation:none; }

/* =========================================================================
   5. RESPECT prefers-reduced-motion — глушим весь собственный моушен
   (html.wm-on JS не добавляет при reduced, но подстрахуемся и здесь).
   ========================================================================= */
@media(prefers-reduced-motion:reduce){
  html.wm-on .wm-r{ opacity:1 !important; transform:none !important; transition:none !important; }
  html.wm-on .screen.active{ animation:none !important; }
  html.wm-on .plan.hot{ animation:none !important; }
  .btn,.chip,.prow,.card,.svc-ic,nav#tabs>button{ transition:none !important; }
}

/* =========================================================================
   6. PERF-СЛОЙ (борьба с лагами) — глушим декоративные @keyframes там, где они
   не нужны, освобождая компоновщик под плавный скролл и отклик интерфейса.
   Это НЕ трогает transitions (микро-press/hover остаются) — только бесконечные
   анимации, которые крутятся вхолостую и жрут GPU/CPU.
   ========================================================================= */
/* a) Экраны не в фокусе не анимируются вовсе (даже если не display:none). */
.screen:not(.active) *{ animation-play-state:paused !important; }
/* b) Во время активного скролла ставим на паузу все бесконечные анимации,
      это главный источник «дёрганого» скролла на слабых телефонах. Класс
      снимается через ~160 мс после остановки скролла (JS ниже). */
html.oko-scrolling *{ animation-play-state:paused !important; }
/* c) Когда вкладка/мини-апп в фоне, тоже пауза (не греем телефон впустую). */
html.oko-hidden *{ animation-play-state:paused !important; }

/* =========================================================================
   7. SKELETON-ЗАГРУЗКА (Facebook-style shimmer)
   Пульсирующие серо-лаймовые прямоугольники под ленту/чаты/списки. Работают
   и без wm-on (класс наносится приложением/шаблоном). Reduced-motion гасит.
   Использование: <div class="wm-sk wm-sk-line"></div>, .wm-sk-avatar, .wm-sk-thumb,
   .wm-sk-chip. Ширину/высоту можно менять на элементе.
   ========================================================================= */
.wm-sk{
  position:relative; overflow:hidden;
  background:rgba(255,255,255,.045);
  border:1px solid var(--border,rgba(255,255,255,.06));
  border-radius:10px; color:transparent;
  min-height:14px;
  isolation:isolate;
}
.wm-sk::after{
  content:''; position:absolute; inset:0;
  background:linear-gradient(90deg,
    transparent 0%,
    rgba(255,255,255,.055) 42%,
    rgba(154,255,0,.14) 50%,
    rgba(255,255,255,.055) 58%,
    transparent 100%);
  transform:translateX(-100%);
  animation:wmSkShimmer 1.4s var(--wm-ease-io) infinite;
  z-index:1; pointer-events:none;
}
:root[data-theme="light"] .wm-sk{ background:#eef1ec; border-color:rgba(0,0,0,.05); }
:root[data-theme="light"] .wm-sk::after{
  background:linear-gradient(90deg,
    transparent 0%,
    rgba(0,0,0,.035) 42%,
    rgba(110,200,0,.14) 50%,
    rgba(0,0,0,.035) 58%,
    transparent 100%);
}
@keyframes wmSkShimmer{ to{ transform:translateX(100%); } }

/* Шейпы под типовые места */
.wm-sk.wm-sk-line{ height:12px; border-radius:6px; margin:6px 0; }
.wm-sk.wm-sk-line.wm-sk-lg{ height:16px; }
.wm-sk.wm-sk-line.wm-sk-sm{ height:9px; width:58%; }
.wm-sk.wm-sk-line.wm-sk-title{ height:18px; width:72%; border-radius:8px; }
.wm-sk.wm-sk-avatar{ width:44px; height:44px; border-radius:50%; }
.wm-sk.wm-sk-thumb{ height:160px; border-radius:14px; }
.wm-sk.wm-sk-chip{ display:inline-block; height:26px; width:68px; border-radius:99px; margin:0 6px 6px 0; }
.wm-sk.wm-sk-block{ height:88px; border-radius:14px; }
/* Готовый контейнер под ряд ленты */
.wm-sk-row{ display:flex; gap:12px; align-items:flex-start; padding:14px; border:1px solid var(--border,rgba(255,255,255,.06)); border-radius:14px; background:var(--surface,transparent); margin:0 0 12px; }
.wm-sk-row .wm-sk-col{ flex:1; min-width:0; }

/* =========================================================================
   8. RIPPLE, лаймовая волна из точки клика на кнопках/чипах/тайлах/сит-итемах/табах
   Спан вставляется JS-ом (wow-motion/script.js) в момент pointerdown.
   ========================================================================= */
.btn, .chip, .svc-ic, .sheet-item, .prow, nav#tabs>button{ position:relative; overflow:hidden; }
.wm-ripple{
  position:absolute; pointer-events:none; z-index:0;
  width:14px; height:14px; margin:-7px 0 0 -7px;
  border-radius:50%;
  background:radial-gradient(circle,
    rgba(154,255,0,.55) 0%,
    rgba(154,255,0,.28) 40%,
    rgba(154,255,0,0) 72%);
  transform:scale(1); opacity:.85;
  animation:wmRipple .58s var(--wm-ease-io) forwards;
  mix-blend-mode:screen;
}
.btn.ghost .wm-ripple, .btn.sm .wm-ripple,
.sheet-item .wm-ripple, .prow .wm-ripple, nav#tabs>button .wm-ripple{
  background:radial-gradient(circle,
    rgba(154,255,0,.42) 0%,
    rgba(154,255,0,.18) 50%,
    rgba(154,255,0,0) 76%);
}
:root[data-theme="light"] .wm-ripple{
  background:radial-gradient(circle,
    rgba(110,200,0,.55) 0%,
    rgba(110,200,0,.25) 45%,
    rgba(110,200,0,0) 72%);
  mix-blend-mode:multiply;
}
/* Контент кнопки поверх волны */
.btn>*, .chip>*, .sheet-item>*, .prow>*, nav#tabs>button>*{ position:relative; z-index:1; }
@keyframes wmRipple{
  from{ transform:scale(1); opacity:.75; }
  to  { transform:scale(28); opacity:0; }
}

/* =========================================================================
   9. TOAST, bouncy slide-in снизу вместо fade
   Оверрайдит переходы у #toast (создаётся в ядре). Не меняет разметку.
   ========================================================================= */
#toast{
  transform:translate(-50%, 34px) scale(.9) !important;
  transition:opacity .22s ease-out, transform .44s cubic-bezier(.34,1.56,.64,1) !important;
  will-change:transform, opacity;
}
#toast.show{
  transform:translate(-50%, 0) scale(1) !important;
}

/* =========================================================================
   10. SCROLL-SHADOW, шапка получает тень когда контент под ней прокручивается
   Основной скроллер приложения, main. Класс wm-scrolled ставит JS ниже.
   ========================================================================= */
main{ transition:box-shadow .26s ease; }
main.wm-scrolled{
  box-shadow: inset 0 10px 14px -10px rgba(0,0,0,.55);
}
:root[data-theme="light"] main.wm-scrolled{
  box-shadow: inset 0 10px 14px -10px rgba(50,80,10,.18);
}
/* Также подсвечиваем sticky-поиск в списках */
.st2-search{ transition:box-shadow .22s ease, border-color .22s ease; }
.st2-search.wm-scrolled{
  box-shadow:0 8px 18px -10px rgba(0,0,0,.55), 0 0 0 1px rgba(154,255,0,.14);
}
:root[data-theme="light"] .st2-search.wm-scrolled{
  box-shadow:0 6px 14px -8px rgba(60,90,20,.18), 0 0 0 1px rgba(110,200,0,.18);
}

/* =========================================================================
   11. МАГНИТНЫЙ ПУЗЫРЬ, активная вкладка в bottom-nav получает мягкий овал
   позади иконки. Работает вместе с существующей полоской-индикатором сверху.
   ========================================================================= */
nav#tabs>button svg.i{ transition:transform .34s var(--wm-spring); }
nav#tabs>button::after{
  content:''; position:absolute;
  top:6px; left:50%;
  width:44px; height:30px; border-radius:16px;
  transform:translateX(-50%) scale(.55);
  background:radial-gradient(ellipse at center,
    rgba(154,255,0,.32) 0%,
    rgba(154,255,0,.14) 55%,
    rgba(154,255,0,0) 82%);
  opacity:0; pointer-events:none; z-index:0;
  transition:opacity .28s var(--wm-ease-io), transform .38s var(--wm-spring);
}
nav#tabs>button.active::after{
  opacity:1;
  transform:translateX(-50%) scale(1);
}
nav#tabs>button.active svg.i{
  transform:translateY(-1px) scale(1.08);
}
:root[data-theme="light"] nav#tabs>button::after{
  background:radial-gradient(ellipse at center,
    rgba(110,200,0,.28) 0%,
    rgba(110,200,0,.12) 55%,
    rgba(110,200,0,0) 82%);
}
/* Десктоп, вертикальный рельс: пузырёк слева от иконки */
@media(min-width:900px){
  nav#tabs>button::after{
    top:50%; left:46%;
    transform:translate(-50%,-50%) scale(.55);
    width:52px; height:36px; border-radius:18px;
  }
  nav#tabs>button.active::after{
    transform:translate(-50%,-50%) scale(1);
  }
}

/* =========================================================================
   12. RESPECT prefers-reduced-motion для новых слоёв
   ========================================================================= */
@media(prefers-reduced-motion:reduce){
  .wm-sk::after{ animation:none !important; }
  .wm-ripple{ animation:none !important; opacity:0 !important; }
  #toast{ transition:opacity .18s ease !important; transform:translate(-50%,0) !important; }
  main{ transition:none !important; }
  nav#tabs>button::after,
  nav#tabs>button svg.i{ transition:none !important; }
}

/* =========================================================================
   13. SPLASH-SHOT — стартовое раскрытие «глаза OKO» при загрузке приложения.
   Полноэкранный оверлей с двумя веками, лаймовым иридом и halo-пульсом.
   Снимается через событие oko:app-ready (JS через ~400 мс после DOMContentLoaded).
   ========================================================================= */
#wm-splash{
  position:fixed; inset:0; z-index:99999;
  background:radial-gradient(circle at center, #0d0d0d 0%, #000 72%);
  display:flex; align-items:center; justify-content:center;
  opacity:1; pointer-events:none;
  transition:opacity .42s ease-out;
}
#wm-splash.wm-gone{ opacity:0; }
#wm-splash-halo{
  position:absolute; width:520px; height:520px; border-radius:50%;
  background:radial-gradient(circle,
    rgba(154,255,0,.36) 0%,
    rgba(154,255,0,.14) 40%,
    rgba(154,255,0,0)   65%);
  transform:scale(.2); opacity:0;
  animation:wmSplashHalo 1200ms cubic-bezier(.16,1,.3,1) both;
  pointer-events:none; will-change:transform,opacity;
}
@keyframes wmSplashHalo{
  0%  { transform:scale(.15); opacity:0; }
  35% { opacity:.95; }
  100%{ transform:scale(2.2); opacity:0; }
}
#wm-splash-eye{
  width:188px; height:94px; overflow:visible;
  transform:scale(.4); opacity:0;
  animation:wmSplashEye 780ms cubic-bezier(.16,1,.3,1) 40ms both;
  filter:drop-shadow(0 0 22px rgba(154,255,0,.55));
  will-change:transform,opacity;
}
@keyframes wmSplashEye{
  0%  { transform:scale(.4); opacity:0; }
  25% { opacity:1; }
  70% { transform:scale(1.06); }
  100%{ transform:scale(1); opacity:1; }
}
.wm-splash-lid{
  fill:#000;
  transform-origin:100px 50px;
  animation:wmSplashLid 620ms cubic-bezier(.5,0,.2,1) 200ms both;
  will-change:transform;
}
.wm-splash-lid.wm-splash-lid-bot{ animation-name:wmSplashLidBot; }
@keyframes wmSplashLid   { from{ transform:translateY(0);   } to{ transform:translateY(-52px); } }
@keyframes wmSplashLidBot{ from{ transform:translateY(0);   } to{ transform:translateY( 52px); } }
.wm-splash-iris{
  transform-origin:100px 50px;
  animation:wmSplashIris 500ms cubic-bezier(.16,1,.3,1) 340ms both;
}
@keyframes wmSplashIris{ from{ transform:scale(.2); } to{ transform:scale(1); } }
.wm-splash-word{
  position:absolute; bottom:32%;
  font-family:var(--font-display,'Bebas Neue'),sans-serif;
  color:var(--accent,#9AFF00);
  font-size:22px; letter-spacing:.32em; opacity:0;
  animation:wmSplashWord 480ms ease-out 460ms both;
  text-shadow:0 0 12px rgba(154,255,0,.5);
}
@keyframes wmSplashWord{ from{ opacity:0; transform:translateY(4px); } to{ opacity:1; transform:none; } }

/* =========================================================================
   14. TAB-SWITCH — направленная слайд-анимация нового экрана + клон-оверлей
   уходящего экрана. Клон-оверлей ставит JS перед сменой .active класса,
   direction (right/left) вычисляется по индексу таба.
   ========================================================================= */
.wm-tab-overlay{
  position:fixed; overflow:hidden; pointer-events:none;
  z-index:5; contain:strict; will-change:transform,opacity;
}
.wm-tab-overlay > *{
  display:block !important; height:100%; transform:translate3d(0,0,0);
}
html.wm-on .screen.active.wm-tab-in-right{
  animation:wmTabInRight .24s cubic-bezier(.16,1,.3,1) both;
}
html.wm-on .screen.active.wm-tab-in-left{
  animation:wmTabInLeft  .24s cubic-bezier(.16,1,.3,1) both;
}
@keyframes wmTabInRight{ from{ opacity:.25; transform:translate3d(10%,0,0); } to{ opacity:1; transform:none; } }
@keyframes wmTabInLeft { from{ opacity:.25; transform:translate3d(-10%,0,0); } to{ opacity:1; transform:none; } }

/* =========================================================================
   15. LONG-PRESS RIPPLE — большая лаймовая волна из точки касания при удержании.
   Ставится JS-ом через 320 мс держания. Отличается от короткого ripple большим
   финальным масштабом и более долгой anim.
   ========================================================================= */
.wm-lpress{
  position:absolute; pointer-events:none; z-index:0;
  width:18px; height:18px; margin:-9px 0 0 -9px; border-radius:50%;
  background:radial-gradient(circle,
    rgba(154,255,0,.72) 0%,
    rgba(154,255,0,.30) 45%,
    rgba(154,255,0,0)   80%);
  transform:scale(1); mix-blend-mode:screen;
  animation:wmLPress 720ms cubic-bezier(.16,1,.3,1) forwards;
  will-change:transform,opacity;
}
:root[data-theme="light"] .wm-lpress{
  background:radial-gradient(circle,
    rgba(110,200,0,.72) 0%,
    rgba(110,200,0,.30) 45%,
    rgba(110,200,0,0)   80%);
  mix-blend-mode:multiply;
}
@keyframes wmLPress{
  from{ transform:scale(1);  opacity:.9; }
  to  { transform:scale(46); opacity:0;  }
}

/* =========================================================================
   16. SUCCESS-CHECK OVERLAY — окно с рисующейся лаймовой галочкой + backdrop-blur
   сцены. Вызов: window.okoWow.showCheck('Готово').
   ========================================================================= */
#wm-check{
  position:fixed; inset:0; z-index:99998;
  display:flex; align-items:center; justify-content:center;
  background:rgba(0,0,0,.32);
  -webkit-backdrop-filter:blur(10px) saturate(1.1);
          backdrop-filter:blur(10px) saturate(1.1);
  opacity:0; pointer-events:none;
  transition:opacity .18s ease;
}
#wm-check.wm-show{ opacity:1; }
.wm-check-box{
  display:flex; flex-direction:column; align-items:center; gap:14px;
  padding:26px 34px 22px; min-width:180px;
  background:rgba(20,20,20,.78);
  border:1px solid rgba(154,255,0,.28); border-radius:22px;
  box-shadow:0 24px 60px rgba(0,0,0,.55), 0 0 42px rgba(154,255,0,.14);
  transform:scale(.6); opacity:0;
  animation:wmCheckPop .5s cubic-bezier(.34,1.56,.64,1) forwards;
  will-change:transform,opacity;
}
:root[data-theme="light"] .wm-check-box{
  background:rgba(255,255,255,.92); border-color:rgba(110,200,0,.35);
  box-shadow:0 24px 48px rgba(60,90,20,.18), 0 0 36px rgba(110,200,0,.16);
}
@keyframes wmCheckPop{
  0%  { transform:scale(.6);  opacity:0; }
  60% { transform:scale(1.06);opacity:1; }
  100%{ transform:scale(1);   opacity:1; }
}
.wm-check-svg{ width:80px; height:80px; overflow:visible; }
.wm-check-circle{
  fill:none; stroke:#9AFF00; stroke-width:5; stroke-linecap:round;
  stroke-dasharray:220; stroke-dashoffset:220;
  animation:wmCheckDraw .48s cubic-bezier(.5,0,.3,1) forwards;
}
.wm-check-tick{
  fill:none; stroke:#9AFF00; stroke-width:7;
  stroke-linecap:round; stroke-linejoin:round;
  stroke-dasharray:60; stroke-dashoffset:60;
  animation:wmCheckDraw .32s cubic-bezier(.4,0,.2,1) forwards .3s;
  filter:drop-shadow(0 0 6px rgba(154,255,0,.5));
}
@keyframes wmCheckDraw{ to{ stroke-dashoffset:0; } }
.wm-check-text{
  color:#fff; font-family:var(--font-display,'Bebas Neue'),sans-serif;
  font-size:22px; letter-spacing:.08em; text-align:center;
  animation:wmShakeSoft .5s cubic-bezier(.4,0,.6,1) .32s;
}
:root[data-theme="light"] .wm-check-text{ color:#0d0d0d; }
@keyframes wmShakeSoft{
  0%,100%{ transform:translateX(0); }
  30%{ transform:translateX(-2px); }
  60%{ transform:translateX(2px); }
}

/* =========================================================================
   17. ERROR-SHAKE — okoWow.shake(el).
   ========================================================================= */
@keyframes wmShake{
  0%,100%{ transform:translateX(0); }
  20%,60%{ transform:translateX(-6px); }
  40%,80%{ transform:translateX(6px);  }
}
.wm-shake{
  animation:wmShake .25s cubic-bezier(.4,0,.6,1) both;
  will-change:transform;
}

/* =========================================================================
   18. CONFETTI-CANVAS — okoWow.confetti(x, y). Canvas оверлей поверх всего.
   ========================================================================= */
#wm-confetti-canvas{
  position:fixed; inset:0; pointer-events:none;
  z-index:99997; width:100%; height:100%;
}

/* =========================================================================
   19. SKELETON-SHIMMER — универсальный .wow-skel (алиас-класс, дополняет .wm-sk).
   Линейный градиент лайм-цветов бренда сдвигается по X.
   ========================================================================= */
.wow-skel{
  position:relative; overflow:hidden;
  background:linear-gradient(90deg,
    rgba(255,255,255,.045) 0%,
    rgba(255,255,255,.09)  38%,
    rgba(154,255,0,.14)    50%,
    rgba(255,255,255,.09)  62%,
    rgba(255,255,255,.045) 100%);
  background-size:220% 100%;
  animation:wmSkelSlide 1.4s ease-in-out infinite;
  border-radius:10px; color:transparent; min-height:14px;
  border:1px solid rgba(255,255,255,.05);
  will-change:background-position;
}
:root[data-theme="light"] .wow-skel{
  background:linear-gradient(90deg,
    #eef1ec 0%, #f4f6f0 38%, rgba(154,255,0,.22) 50%, #f4f6f0 62%, #eef1ec 100%);
  background-size:220% 100%;
  border-color:rgba(0,0,0,.05);
}
@keyframes wmSkelSlide{
  from{ background-position:220% 0; }
  to  { background-position:-120% 0; }
}

/* =========================================================================
   20. PAGE-PARALLAX — фоновое лайм-glow смещается медленнее контента.
   Класс на элементе + JS выставляет CSS-var --wm-par-y.
   ========================================================================= */
.wow-parallax{
  will-change:transform;
  transform:translate3d(0, var(--wm-par-y, 0px), 0);
  transition:none;
}

/* =========================================================================
   21. HAPTIC-HINT — короткий scale(.97) → scale(1) 80ms при тапе на .btn, .svc,
   .chip. Класс .wm-pop ставит JS на pointerdown, снимает по animationend.
   ========================================================================= */
.wm-pop{
  animation:wmPop 80ms cubic-bezier(.34,1.56,.64,1);
  transform-origin:center;
}
@keyframes wmPop{
  0%  { transform:scale(.97); }
  100%{ transform:scale(1);   }
}

/* =========================================================================
   22. NUMBER COUNT-UP — .wow-count[data-to="1234"] моноширинные цифры,
   чтобы ширина не «прыгала» на промежуточных значениях.
   ========================================================================= */
.wow-count{
  font-variant-numeric:tabular-nums;
  font-feature-settings:"tnum" 1,"kern" 1;
}

/* =========================================================================
   23. RESPECT prefers-reduced-motion — гасим весь новый моушен-слой.
   ========================================================================= */
@media(prefers-reduced-motion:reduce){
  #wm-splash{ display:none !important; }
  #wm-splash-halo,#wm-splash-eye,
  .wm-splash-lid,.wm-splash-iris,.wm-splash-word{ animation:none !important; }
  html.wm-on .screen.active.wm-tab-in-right,
  html.wm-on .screen.active.wm-tab-in-left{ animation:none !important; }
  .wm-lpress{ animation:none !important; opacity:0 !important; }
  .wm-check-box,.wm-check-circle,.wm-check-tick,.wm-check-text{ animation:none !important; transform:none !important; stroke-dashoffset:0 !important; }
  .wm-shake{ animation:none !important; }
  .wow-skel{ animation:none !important; }
  .wow-parallax{ transform:none !important; }
  .wm-pop{ animation:none !important; }
}

/* ===== module: viral ===== */
/* ================= VIRAL — общий share-слой (префикс vr-)
   Тёмная и светлая темы. Никаких эмодзи. Только SVG-иконки бренда. */

/* ---------- Sheet-контейнеры ---------- */
.vr-share-view, .vr-reels-view, .vr-weekly-view, .vr-refsq-view{
  display:flex; flex-direction:column; gap:12px;
}
.vr-share-view h3, .vr-reels-view h3, .vr-weekly-view h3, .vr-refsq-view h3{
  margin:0; font-family:'Bebas Neue', sans-serif; letter-spacing:.02em;
  font-size:22px; line-height:1.05;
}
.vr-share-view .sub, .vr-reels-view .sub, .vr-weekly-view .sub, .vr-refsq-view .sub{
  color:var(--dim); font-size:12.5px; margin-top:-6px;
}

/* ---------- Canvas-превью ---------- */
.vr-preview-wrap{
  border-radius:16px; overflow:hidden; background:#0a0a0a;
  border:1px solid var(--border); position:relative;
  display:flex; align-items:center; justify-content:center;
  min-height:240px; max-height:56vh;
}
.vr-preview-wrap canvas, .vr-preview-wrap img{
  display:block; max-width:100%; max-height:56vh; height:auto; width:auto;
  border-radius:14px; box-shadow:0 12px 32px rgba(0,0,0,.35);
}
.vr-preview-hint{
  color:var(--dim); font-size:11.5px; text-align:center; margin:2px 0 0;
}

/* ---------- 4 share-кнопки ---------- */
.vr-share-grid{
  display:grid; grid-template-columns:repeat(4,1fr); gap:8px; margin-top:2px;
}
.vr-share-btn{
  display:flex; flex-direction:column; align-items:center; gap:6px;
  padding:12px 6px 10px; border-radius:14px; cursor:pointer;
  background:var(--raised); border:1px solid var(--border);
  color:var(--fg); font-size:11.5px; font-weight:700;
  transition:transform .15s ease, background .15s ease, border-color .15s ease;
  font-family:inherit;
}
.vr-share-btn:hover{ transform:translateY(-1px); border-color:var(--accent); }
.vr-share-btn:active{ transform:translateY(0); }
.vr-share-btn .ico{
  width:36px; height:36px; border-radius:50%;
  display:flex; align-items:center; justify-content:center;
  background:var(--lime-dim); color:var(--accent);
}
.vr-share-btn .i{ width:18px; height:18px; }
.vr-share-btn.story .ico{ background:linear-gradient(135deg,#f58529,#dd2a7b 45%,#8134af 90%); color:#fff; }
.vr-share-btn.tg .ico{ background:#26a5e4; color:#fff; }
.vr-share-btn.vk .ico{ background:#07f; color:#fff; }
.vr-share-btn.tt .ico{ background:#000; color:#fff; border:1px solid #333; }
.vr-share-btn.wa .ico{ background:#25d366; color:#fff; }
.vr-share-btn.copy .ico{ background:var(--raised); color:var(--fg); border:1px solid var(--border); }

/* ---------- Native-Share кнопка сверху ---------- */
.vr-native-btn{
  display:flex; align-items:center; justify-content:center; gap:8px;
  width:100%; padding:12px 14px; border-radius:12px; cursor:pointer;
  background:var(--accent); color:#000; border:0;
  font-weight:800; font-size:14px; font-family:inherit;
  letter-spacing:.01em;
}
.vr-native-btn .i{ width:16px; height:16px; }
.vr-native-btn:disabled{ opacity:.5; cursor:default; }

/* ---------- Плашки: nudge (после урока / вс 20:00) ---------- */
.vr-nudge{
  position:fixed; left:50%; top:8px; transform:translate(-50%,-120%);
  z-index:2200; width:min(96vw, 460px);
  background:var(--surface); border:1px solid var(--border); border-radius:14px;
  box-shadow:0 12px 32px rgba(0,0,0,.35);
  display:grid; grid-template-columns:36px 1fr auto 24px;
  gap:8px; align-items:center; padding:10px 10px 10px 10px;
  transition:transform .38s cubic-bezier(.2,.9,.35,1.2), opacity .3s;
  opacity:0; pointer-events:none;
}
.vr-nudge.on{ transform:translate(-50%, calc(env(safe-area-inset-top,0px) + 8px)); opacity:1; pointer-events:auto; }
.vr-nudge.weekly .vr-nudge-ico{ background:linear-gradient(135deg,#f58529,#dd2a7b 55%,#8134af); color:#fff; }
.vr-nudge-ico{
  width:36px; height:36px; border-radius:11px;
  display:flex; align-items:center; justify-content:center;
  background:var(--lime-dim); color:var(--accent);
}
.vr-nudge-ico .i{ width:18px; height:18px; }
.vr-nudge-body{ min-width:0; }
.vr-nudge-t{ font-weight:800; font-size:13px; line-height:1.15; }
.vr-nudge-s{ color:var(--dim); font-size:11.5px; margin-top:2px; }
.vr-nudge-cta{
  background:var(--accent); color:#000; border:0; border-radius:9px;
  padding:7px 12px; font-weight:800; font-size:12px; cursor:pointer;
  font-family:inherit;
}
.vr-nudge-x{
  background:none; border:0; color:var(--dim); font-size:20px;
  line-height:1; cursor:pointer; padding:0 4px;
}

/* ---------- Публичный профиль /u/@username ---------- */
.vr-public{
  position:fixed; inset:0; z-index:2500;
  background:var(--bg); color:var(--fg);
  display:none; overflow-y:auto; overflow-x:hidden;
  -webkit-overflow-scrolling:touch;
}
.vr-public.open{ display:block; }
.vr-public-inner{
  max-width:520px; margin:0 auto;
  padding:calc(env(safe-area-inset-top,0px) + 16px) 16px calc(env(safe-area-inset-bottom,0px) + 24px);
}
.vr-pu-top{
  display:flex; align-items:center; gap:10px; margin-bottom:12px;
}
.vr-pu-logo{
  display:flex; align-items:center; gap:8px; font-family:'Bebas Neue', sans-serif;
  font-size:22px; letter-spacing:.08em; color:var(--fg); text-decoration:none;
}
.vr-pu-logo .i{ width:22px; height:22px; color:var(--accent); }
.vr-pu-actions{ margin-left:auto; display:flex; gap:8px; }
.vr-pu-actions button, .vr-pu-actions a{
  background:var(--raised); border:1px solid var(--border);
  color:var(--fg); border-radius:10px; padding:8px 12px;
  font-weight:700; font-size:12.5px; cursor:pointer; font-family:inherit;
  text-decoration:none; display:inline-flex; align-items:center; gap:6px;
}
.vr-pu-actions .primary{ background:var(--accent); color:#000; border-color:var(--accent); }
.vr-pu-actions .i{ width:14px; height:14px; }

.vr-pu-hero{
  background:linear-gradient(135deg,rgba(154,255,0,.18),rgba(0,0,0,0) 55%),
             var(--surface);
  border:1px solid var(--border); border-radius:22px;
  padding:22px 20px 20px; margin-bottom:12px; overflow:hidden;
  position:relative;
}
.vr-pu-hero::before{
  content:''; position:absolute; right:-40px; top:-40px;
  width:160px; height:160px; border-radius:50%;
  background:radial-gradient(circle at 30% 30%, rgba(154,255,0,.25), transparent 65%);
  filter:blur(2px);
}
.vr-pu-ava{
  width:88px; height:88px; border-radius:26px;
  background:var(--raised); border:2px solid var(--accent);
  display:flex; align-items:center; justify-content:center;
  font-family:'Bebas Neue', sans-serif; font-size:44px; letter-spacing:.02em;
  color:var(--accent);
  margin:0 auto 12px; background-size:cover; background-position:center;
  box-shadow:0 6px 22px rgba(154,255,0,.28);
}
.vr-pu-name{ font-family:'Bebas Neue', sans-serif; font-size:30px; letter-spacing:.03em; text-align:center; line-height:1; }
.vr-pu-nick{ color:var(--dim); text-align:center; font-size:13px; margin-top:6px; font-weight:600; }
.vr-pu-bio{ color:var(--fg); font-size:13.5px; line-height:1.4; text-align:center; margin:10px 8px 0; opacity:.9; }
.vr-pu-chips{ display:flex; flex-wrap:wrap; gap:6px; justify-content:center; margin-top:12px; }
.vr-pu-chip{
  background:var(--raised); border:1px solid var(--border); color:var(--fg);
  padding:5px 10px; border-radius:999px; font-size:11.5px; font-weight:700;
  display:inline-flex; align-items:center; gap:5px;
}
.vr-pu-chip.gold{ background:var(--lime-dim); color:var(--accent); border-color:var(--accent); }
.vr-pu-chip .i{ width:12px; height:12px; }

.vr-pu-stats{
  display:grid; grid-template-columns:repeat(4,1fr); gap:6px; margin:14px 0 0;
}
.vr-pu-stat{
  background:var(--raised); border:1px solid var(--border);
  border-radius:12px; padding:10px 4px; text-align:center;
}
.vr-pu-stat .v{ font-family:'Bebas Neue', sans-serif; font-size:22px; letter-spacing:.02em; color:var(--fg); line-height:1; }
.vr-pu-stat .v.lime{ color:var(--accent); }
.vr-pu-stat .l{ font-size:10px; color:var(--dim); margin-top:4px; font-weight:600; text-transform:uppercase; letter-spacing:.05em; }

.vr-pu-cta{
  display:grid; grid-template-columns:1fr auto auto; gap:8px; margin-top:14px;
}
.vr-pu-cta .btn-primary{
  background:var(--accent); color:#000; border:0; border-radius:12px;
  padding:12px; font-weight:800; font-size:14px; cursor:pointer; font-family:inherit;
  display:flex; align-items:center; justify-content:center; gap:8px;
}
.vr-pu-cta .btn-ghost{
  background:var(--raised); color:var(--fg); border:1px solid var(--border);
  border-radius:12px; padding:12px; cursor:pointer; font-family:inherit;
  display:flex; align-items:center; justify-content:center;
}
.vr-pu-cta .btn-ghost .i, .vr-pu-cta .btn-primary .i{ width:16px; height:16px; }

/* Разделы */
.vr-pu-section{
  background:var(--surface); border:1px solid var(--border);
  border-radius:16px; padding:14px; margin-bottom:12px;
}
.vr-pu-section h3{
  margin:0 0 10px; font-family:'Bebas Neue', sans-serif;
  font-size:18px; letter-spacing:.03em; display:flex; align-items:baseline; gap:8px;
}
.vr-pu-section h3 .badge{
  font-size:11px; letter-spacing:.05em; color:var(--accent);
  background:var(--lime-dim); padding:2px 8px; border-radius:999px; font-family:inherit; font-weight:700;
}
.vr-pu-soc{
  display:grid; grid-template-columns:repeat(auto-fill, minmax(140px,1fr));
  gap:8px;
}
.vr-pu-soc a{
  display:flex; align-items:center; gap:10px; padding:10px;
  background:var(--raised); border:1px solid var(--border);
  border-radius:12px; text-decoration:none; color:var(--fg);
  font-weight:700; font-size:12.5px;
}
.vr-pu-soc a .ico{
  width:32px; height:32px; border-radius:9px;
  display:flex; align-items:center; justify-content:center;
  background:var(--accent); color:#000;
}
.vr-pu-soc a .ico .i{ width:16px; height:16px; }
.vr-pu-soc a .lbl{ min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }

.vr-pu-cert{
  display:flex; align-items:center; gap:10px; padding:10px;
  background:var(--raised); border:1px solid var(--border); border-radius:12px;
  margin-bottom:6px;
}
.vr-pu-cert .seal{
  width:38px; height:38px; border-radius:50%;
  background:linear-gradient(135deg,#c0c0c0 30%,#e6e6e6 70%);
  color:#333; display:flex; align-items:center; justify-content:center;
  font-family:'Bebas Neue', sans-serif; font-size:11px; letter-spacing:.05em;
  border:2px solid var(--accent); flex:0 0 auto;
}
.vr-pu-cert .t{ font-weight:700; font-size:13px; line-height:1.15; min-width:0; }
.vr-pu-cert .s{ color:var(--dim); font-size:11.5px; margin-top:2px; }
.vr-pu-cert .info{ min-width:0; flex:1 1 auto; }

.vr-pu-chan{
  display:flex; align-items:center; gap:10px; padding:10px;
  background:var(--raised); border:1px solid var(--border); border-radius:12px;
  margin-bottom:6px;
}
.vr-pu-chan .a{
  width:36px; height:36px; border-radius:11px;
  display:flex; align-items:center; justify-content:center;
  background:var(--lime-dim); color:var(--accent);
  font-family:'Bebas Neue', sans-serif; font-size:18px;
  flex:0 0 auto;
}
.vr-pu-chan .t{ font-weight:700; font-size:13px; line-height:1.15; }
.vr-pu-chan .s{ color:var(--dim); font-size:11.5px; margin-top:2px; }
.vr-pu-chan .info{ flex:1 1 auto; min-width:0; }
.vr-pu-chan .k{ font-family:'Bebas Neue', sans-serif; font-size:15px; color:var(--fg); letter-spacing:.02em; }

.vr-pu-ref{
  display:flex; align-items:center; gap:10px; padding:14px;
  background:linear-gradient(135deg, rgba(154,255,0,.12), var(--raised) 60%);
  border:1px solid var(--accent); border-radius:14px;
}
.vr-pu-ref .ico{
  width:40px; height:40px; border-radius:12px; background:var(--accent); color:#000;
  display:flex; align-items:center; justify-content:center; flex:0 0 auto;
}
.vr-pu-ref .ico .i{ width:20px; height:20px; }
.vr-pu-ref .info{ flex:1 1 auto; min-width:0; }
.vr-pu-ref .t{ font-weight:800; font-size:13.5px; line-height:1.15; }
.vr-pu-ref .s{ color:var(--dim); font-size:11.5px; margin-top:3px; }
.vr-pu-ref button{
  background:#000; color:var(--accent); border:1px solid var(--accent);
  border-radius:10px; padding:8px 14px; font-weight:800; font-size:12.5px;
  cursor:pointer; font-family:inherit; flex:0 0 auto;
}

.vr-pu-foot{
  color:var(--dim); font-size:11px; text-align:center; padding:20px 4px 8px;
  line-height:1.5;
}
.vr-pu-foot a{ color:var(--dim); text-decoration:underline; }

/* ---------- Weekly Story slide (preview) ---------- */
.vr-weekly-metrics{
  display:grid; grid-template-columns:repeat(2,1fr); gap:8px;
}
.vr-weekly-metric{
  background:var(--raised); border:1px solid var(--border); border-radius:12px;
  padding:10px 12px;
}
.vr-weekly-metric .l{ color:var(--dim); font-size:11px; text-transform:uppercase; letter-spacing:.06em; font-weight:700; }
.vr-weekly-metric .v{ font-family:'Bebas Neue', sans-serif; font-size:24px; letter-spacing:.02em; margin-top:4px; }
.vr-weekly-metric .v.lime{ color:var(--accent); }

/* ---------- Refsquared (партнёрка: +3/+10) ---------- */
.vr-refsq-progress{
  background:var(--raised); border:1px solid var(--border); border-radius:14px;
  padding:14px; margin-bottom:8px;
}
.vr-refsq-row{
  display:flex; align-items:center; justify-content:space-between; gap:10px;
  margin-bottom:8px;
}
.vr-refsq-row .lbl{ font-weight:700; font-size:13px; }
.vr-refsq-row .n{ font-family:'Bebas Neue', sans-serif; font-size:22px; letter-spacing:.02em; color:var(--accent); }
.vr-refsq-bar{
  height:8px; border-radius:99px; background:var(--border); overflow:hidden; margin-top:6px;
}
.vr-refsq-bar > i{
  display:block; height:100%; background:linear-gradient(90deg, var(--accent), #b8ff42);
  border-radius:99px; transition:width .6s cubic-bezier(.2,.9,.4,1);
}
.vr-refsq-goal{
  display:flex; gap:10px; padding:12px; border-radius:14px;
  background:var(--surface); border:1px solid var(--border); margin-bottom:8px;
}
.vr-refsq-goal .badge{
  width:44px; height:44px; border-radius:12px;
  background:var(--lime-dim); color:var(--accent);
  display:flex; align-items:center; justify-content:center;
  font-family:'Bebas Neue', sans-serif; font-size:20px; letter-spacing:.02em;
  flex:0 0 auto;
}
.vr-refsq-goal.done .badge{ background:var(--accent); color:#000; }
.vr-refsq-goal .t{ font-weight:800; font-size:13.5px; line-height:1.2; }
.vr-refsq-goal .s{ color:var(--dim); font-size:11.5px; margin-top:3px; }
.vr-refsq-goal.done{ border-color:var(--accent); }

/* ---------- Serial badge (мессия шеринга) ---------- */
.vr-serial{
  display:inline-flex; align-items:center; gap:6px;
  padding:5px 10px; border-radius:999px;
  background:linear-gradient(135deg, #ffd11a, #ff7a00);
  color:#000; font-weight:800; font-size:11.5px;
  border:1px solid rgba(0,0,0,.25);
  box-shadow:0 4px 12px rgba(255,140,0,.35);
}
.vr-serial .i{ width:12px; height:12px; }

/* ---------- Share-кнопка в постах ленты (доп. полировка) ---------- */
.vr-post-share-btn{ display:inline-flex; align-items:center; gap:4px; }

/* ---------- Партнёрка: карточка refsquared, если ppRoot существует ---------- */
#vrRefSquaredCard{
  padding:16px; border-radius:16px; background:var(--surface);
  border:1px solid var(--border); margin-top:12px;
  display:flex; flex-direction:column; gap:10px;
}
#vrRefSquaredCard .h{ display:flex; justify-content:space-between; align-items:baseline; }
#vrRefSquaredCard .h .lb{ font-family:'Bebas Neue', sans-serif; font-size:19px; letter-spacing:.03em; }
#vrRefSquaredCard .h .chip{
  background:var(--lime-dim); color:var(--accent); border-radius:999px;
  padding:3px 10px; font-size:11px; font-weight:800;
}
#vrRefSquaredCard button{
  background:var(--raised); color:var(--fg); border:1px solid var(--border);
  border-radius:10px; padding:9px; font-weight:700; font-size:12px;
  cursor:pointer; font-family:inherit;
}

/* ---------- Игры: кнопка share моей позиции ---------- */
.vr-lb-share{
  margin:8px 12px 12px; width:calc(100% - 24px);
  padding:10px; border-radius:12px;
  background:var(--accent); color:#000; border:0;
  font-weight:800; font-size:13px; cursor:pointer; font-family:inherit;
  display:inline-flex; align-items:center; justify-content:center; gap:8px;
}
.vr-lb-share .i{ width:14px; height:14px; }

/* ---------- Reels-scene карточки (внутри reels-sheet) ---------- */
.vr-reels-scenes{ display:flex; flex-direction:column; gap:8px; }
.vr-reels-scene{
  background:var(--raised); border:1px solid var(--border); border-radius:12px;
  padding:10px 12px;
}
.vr-reels-scene .n{
  display:inline-block; font-family:'Bebas Neue', sans-serif;
  font-size:13px; letter-spacing:.05em; color:var(--accent);
}
.vr-reels-scene .q{ font-size:13px; margin-top:4px; font-weight:600; line-height:1.35; }

/* ---------- Мелочи для светлой темы ---------- */
:root[data-theme="light"] .vr-preview-wrap{ background:#111; }
@media (prefers-color-scheme: light){
  :root:not([data-theme="dark"]) .vr-preview-wrap{ background:#111; }
}
